/* History event log for per-turn recording.
 * 68k CODE_054 FUN_000020e2 has 12 event types (cases 0-11):
 * 0=new turn, 1=city captured/razed/abandoned, 2=hero appeared,
 * 3=hero killed, 4=player eliminated, 5=army destroyed/defeated,
 * 6=ruin searched, 7=diplomacy change, 8=alliance, 9=war, 10=peace, 11=separator */
#define MAX_HISTORY_EVENTS 100
#define HIST_EVT_NEWTURN    0   /* new turn / round marker */
#define HIST_EVT_CAPTURE    1   /* city captured, razed, or abandoned */
#define HIST_EVT_HERO_APP   2   /* hero appeared (hired) */
#define HIST_EVT_HERO_KILL  3   /* hero killed in combat */
#define HIST_EVT_ELIMINATE   4   /* player eliminated */
#define HIST_EVT_BATTLE     5   /* army destroyed/defeated in battle */
#define HIST_EVT_SEARCH     6   /* ruin/temple/library searched */
#define HIST_EVT_DIPLOMACY  7   /* diplomacy change (generic) */
#define HIST_EVT_ALLIANCE   8   /* alliance formed */
#define HIST_EVT_WAR        9   /* war declared */
#define HIST_EVT_PEACE     10   /* peace declared */
#define HIST_EVT_SEPARATOR 11   /* separator/blank line */
/* Legacy aliases for existing RecordEvent calls */
#define HIST_EVT_PRODUCED   2   /* mapped to hero_appeared (closest match) */
#define HIST_EVT_HERO       2   /* mapped to hero_appeared */
#define HIST_EVT_DEFEAT     4   /* mapped to eliminate */

/* Diplomacy state values for bits 2-3 of diplomacy byte (68k CODE_052/117)
 * Byte layout: bits 0-1=displayed, 2-3=current state, 4=notify, 5=direction, 6-7=previous */
#define DIPLO_PEACE    0  /* at peace: no fighting at all */
#define DIPLO_HOSTILE  1  /* hostile: armies in the open may be attacked, cities not */
#define DIPLO_WAR      2  /* at war: anything goes */
#define DIPLO_GET_STATE(b)       (((b) >> 2) & 3)
#define DIPLO_SET_STATE(b, s)    (((b) & 0xF3) | (((s) & 3) << 2))
static struct {
    short turn;
    short eventType;
    short player;     /* 0-7 */
    char  text[40];
} sHistoryEvents[MAX_HISTORY_EVENTS];
static short sHistoryCount = 0;

/* Per-turn gold tracking for gold chart (up to 200 turns) */
#define MAX_HIST_TURNS 200
static short sGoldHistory[8][MAX_HIST_TURNS];
static short sCityHistory[8][MAX_HIST_TURNS];
static short sHistoryTurnCount = 0;

static void RecordEvent(short turn, short type, short player, const char *text)
{
    short i;
    if (sHistoryCount >= MAX_HISTORY_EVENTS) {
        /* Shift oldest events out */
        for (i = 0; i < MAX_HISTORY_EVENTS - 1; i++)
            sHistoryEvents[i] = sHistoryEvents[i + 1];
        sHistoryCount = MAX_HISTORY_EVENTS - 1;
    }
    sHistoryEvents[sHistoryCount].turn = turn;
    sHistoryEvents[sHistoryCount].eventType = type;
    sHistoryEvents[sHistoryCount].player = player;
    for (i = 0; i < 39 && text[i] != 0; i++)
        sHistoryEvents[sHistoryCount].text[i] = text[i];
    sHistoryEvents[sHistoryCount].text[i] = 0;
    sHistoryCount++;
}

/* Record per-turn gold and city snapshots */
static void RecordTurnSnapshot(void)
{
    unsigned char *gs;
    short p, ci;
    short cityCount;
    if (*gGameState == 0 || sHistoryTurnCount >= MAX_HIST_TURNS) return;
    gs = (unsigned char *)*gGameState;
    cityCount = sCityCount;
    if (cityCount > 139) cityCount = 139;

    for (p = 0; p < 8; p++) {
        short pCities = 0;
        sGoldHistory[p][sHistoryTurnCount] = *(short *)(gs + 0x186 + p * 0x14);
        for (ci = 0; ci < cityCount; ci++) {
            unsigned char *city = sCityData +ci * 0x20;
            if (*(short *)(city + 0x04) == p) pCities++;
        }
        sCityHistory[p][sHistoryTurnCount] = pCities;
    }
    sHistoryTurnCount++;
}

/* Fog of war visibility bitmaps: per-player explored + current visibility.
 * Explored = seen at least once (dimmed). Visible = currently within sight range.
 * Map is 112x156 = 17472 tiles. Each bit = 1 tile. ~2184 bytes per player. */
#define FOG_MAP_W 112
#define FOG_MAP_H 156
#define FOG_BYTES_PER_PLAYER ((FOG_MAP_W * FOG_MAP_H + 7) / 8)
/* 68k fog reveal: asymmetric [-2,+3] in both axes (6 tiles, not 7) */
#define FOG_SIGHT_MIN -2  /* tiles visible in negative direction */
#define FOG_SIGHT_MAX  3  /* tiles visible in positive direction */

static unsigned char sFogExplored[8][FOG_BYTES_PER_PLAYER];  /* ever seen */
static unsigned char sFogVisible[8][FOG_BYTES_PER_PLAYER];   /* currently visible */

/* Forward declaration — needed by FogUpdatePlayer before main forward decl block */
static short GetEffectiveUnitClass(short armyIdx);

/* Check if any unit in army is naval (68k: _DAT_00028864[unitType*6] != 0).
 * Used for fog reveal radius — naval armies get 5x5 instead of 3x3. */
static Boolean ArmyIsNaval(short armyIdx)
{
    unsigned char *gs, *army;
    short slot, ut;
    if (*gGameState == 0 || !sUnitTypesLoaded) return false;
    gs = (unsigned char *)*gGameState;
    army = ARMY_REC(armyIdx);
    for (slot = 0; slot < 4; slot++) {
        ut = (short)(unsigned char)army[0x16 + slot];
        if (ut == 0xFF || ut >= MAX_UNIT_TYPES) continue;
        if (sUnitTypeTable[ut * UNIT_TYPE_ENTRY + UTE_STAT_NAVAL] >= 1) return true;
    }
    return false;
}

static void FogSetBit(unsigned char *map, short x, short y)
{
    long idx;
    if (x < 0 || x >= FOG_MAP_W || y < 0 || y >= FOG_MAP_H) return;
    idx = (long)y * FOG_MAP_W + x;
    map[idx >> 3] |= (1 << (idx & 7));
}

static Boolean FogGetBit(unsigned char *map, short x, short y)
{
    long idx;
    if (x < 0 || x >= FOG_MAP_W || y < 0 || y >= FOG_MAP_H) return false;
    idx = (long)y * FOG_MAP_W + x;
    return (map[idx >> 3] & (1 << (idx & 7))) != 0;
}

/* Reveal area around a point for a given player — city vision [-2,+3] (6x6)
 * 68k CODE_067 FUN_00002ab4: cities get full asymmetric vision range */
static void FogReveal(short player, short cx, short cy)
{
    short dx, dy;
    if (player < 0 || player > 7) return;
    for (dy = FOG_SIGHT_MIN; dy <= FOG_SIGHT_MAX; dy++) {
        for (dx = FOG_SIGHT_MIN; dx <= FOG_SIGHT_MAX; dx++) {
            FogSetBit(sFogExplored[player], cx + dx, cy + dy);
            FogSetBit(sFogVisible[player], cx + dx, cy + dy);
        }
    }
}

/* Forward declare GetTerrainType (defined later, needed for city tile check) */
static short GetTerrainType(short mapX, short mapY);

/* Reveal area around a unit — radius depends on movement mode (PPC FUN_1000931c,
 * 68k CODE_067 FUN_00002c20): a FLYING stack (mode 2: 0 naval, 1 ground, 2
 * flying - PPC FUN_10041de8 / 68k CODE_042) or a city tile: [-2,+2] (5x5);
 * ground and naval stacks: [-1,+1] (3x3). */
static void FogRevealUnit(short player, short cx, short cy, Boolean isFlying)
{
    short dx, dy, rMin, rMax;
    Boolean extended;
    if (player < 0 || player > 7) return;
    extended = isFlying;
    if (!extended) {
        short tt = GetTerrainType(cx, cy);
        if (tt == 10) extended = true;  /* city tile → 5x5 */
    }
    rMin = extended ? -2 : -1;
    rMax = extended ?  2 :  1;
    for (dy = rMin; dy <= rMax; dy++) {
        for (dx = rMin; dx <= rMax; dx++) {
            FogSetBit(sFogExplored[player], cx + dx, cy + dy);
            FogSetBit(sFogVisible[player], cx + dx, cy + dy);
        }
    }
}

/* Update fog of war for a player: clear visible, then reveal around armies/cities */
static void FogUpdatePlayer(short player)
{
    unsigned char *gs;
    short i;
    if (*gGameState == 0 || player < 0 || player > 7) return;
    gs = (unsigned char *)*gGameState;

    /* Clear current visibility */
    for (i = 0; i < FOG_BYTES_PER_PLAYER; i++)
        sFogVisible[player][i] = 0;

    /* 68k CODE_067 FUN_00002ab4: cities do NOT provide vision.
     * Only armies reveal fog. Removed fabricated city vision loop.
     *
     * Reveal around owned armies (68k CODE_067 FUN_00002ab4):
     * At turn start, ALL armies get the full [-2,+3] (6x6) sight range,
     * same as cities.  The smaller [-1,+1] / [-2,+2] radius (FUN_00002c20)
     * is only used for incremental reveals during movement. */
    {
        short armyCount = *(short *)(gs + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            if ((short)(unsigned char)army[0x15] == player && *(short *)(army + 0x00) >= 0) {   /* not in transit */
                FogReveal(player, *(short *)(army + 0x00), *(short *)(army + 0x02));
            }
        }
    }
}

