/* ===================================================================
 * CenterViewportOn — Center the map viewport on a given tile coordinate.
 * =================================================================== */
static void CenterViewportOn(short tx, short ty)
{
    /* Map area of the map window; before it exists, the size it will have
     * (window content minus the 15px scroll bars, see window creation). */
    long viewW = qd.screenBits.bounds.right - 223 - 10 - SCROLLBAR_W;
    long viewH = qd.screenBits.bounds.bottom - 3 - 40 - SCROLLBAR_H;
    long px, py, maxX, maxY;
    if (*gMainGameWindow != 0) {
        Rect p = ((WindowPtr)*gMainGameWindow)->portRect;
        viewW = p.right - p.left - SCROLLBAR_W;
        viewH = p.bottom - p.top - SCROLLBAR_H;
    }
    /* Measured on the original (Erythea, Mirea 86,8 -> origin 3072,0):
     * the tile's centre goes to the middle of the view, clamped to the map. */
    px = (long)tx * TERRAIN_TILE_W + TERRAIN_TILE_W / 2 - viewW / 2;
    py = (long)ty * TERRAIN_TILE_H + TERRAIN_TILE_H / 2 - viewH / 2;
    maxX = (long)sMapWidth  * TERRAIN_TILE_W - viewW;
    maxY = (long)sMapHeight * TERRAIN_TILE_H - viewH;
    if (px > maxX) px = maxX;
    if (py > maxY) py = maxY;
    if (px < 0) px = 0;
    if (py < 0) py = 0;
    sViewportX = (short)(px / TERRAIN_TILE_W);  sViewPixX = (short)(px % TERRAIN_TILE_W);
    sViewportY = (short)(py / TERRAIN_TILE_H);  sViewPixY = (short)(py % TERRAIN_TILE_H);
}

/* RevealTile — PPC FUN_100836dc / 68k CODE_067 FUN_00000340 (TMapView), run
 * when a stack is selected and after it moves.  Keeps a box of up to 280px
 * centred on the tile inside the view: if the box is already visible nothing
 * scrolls; if the tile itself is off screen the view centres on it; otherwise
 * it scrolls the minimum (MacApp TScroller::RevealRect) to show the box. */
static void RevealTile(short tx, short ty)
{
    long viewW, viewH, vl, vt, bw, bh, bl, bt, tl, tt, maxX, maxY;
    Rect p;
    if (*gMainGameWindow == 0) { CenterViewportOn(tx, ty); return; }
    p = ((WindowPtr)*gMainGameWindow)->portRect;
    viewW = p.right - p.left - SCROLLBAR_W;
    viewH = p.bottom - p.top - SCROLLBAR_H;
    vl = (long)sViewportX * TERRAIN_TILE_W + sViewPixX;
    vt = (long)sViewportY * TERRAIN_TILE_H + sViewPixY;
    bw = viewW < 280 ? viewW : 280;
    bh = viewH < 280 ? viewH : 280;
    tl = (long)tx * TERRAIN_TILE_W;  tt = (long)ty * TERRAIN_TILE_H;
    bl = tl + (TERRAIN_TILE_W - bw) / 2;
    bt = tt + (TERRAIN_TILE_H - bh) / 2;
    if (bl >= vl && bt >= vt && bl + bw <= vl + viewW && bt + bh <= vt + viewH)
        return;                                         /* box already visible */
    if (!(tl >= vl && tt >= vt && tl + TERRAIN_TILE_W <= vl + viewW &&
          tt + TERRAIN_TILE_H <= vt + viewH)) {
        vl = tl + (TERRAIN_TILE_W - viewW) / 2;         /* tile off screen: centre */
        vt = tt + (TERRAIN_TILE_H - viewH) / 2;
    } else {
        long d;
        d = bl + bw - (vl + viewW);                     /* RevealRect, per axis */
        if (d < 1) { d = bl + bw - bw - vl; if (d > 0) d = 0; }
        vl += d;
        d = bt + bh - (vt + viewH);
        if (d < 1) { d = bt + bh - bh - vt; if (d > 0) d = 0; }
        vt += d;
    }
    maxX = (long)sMapWidth  * TERRAIN_TILE_W - viewW;
    maxY = (long)sMapHeight * TERRAIN_TILE_H - viewH;
    if (vl > maxX) vl = maxX;
    if (vt > maxY) vt = maxY;
    if (vl < 0) vl = 0;
    if (vt < 0) vt = 0;
    sViewportX = (short)(vl / TERRAIN_TILE_W);  sViewPixX = (short)(vl % TERRAIN_TILE_W);
    sViewportY = (short)(vt / TERRAIN_TILE_H);  sViewPixY = (short)(vt % TERRAIN_TILE_H);
}

/* A player's capital: pstat+0x0E/0x10 (written by GameInit), else the SCN
 * bytes pstat[3]/pstat[5]. */
static void GetCapitalXY(short player, short *x, short *y)
{
    unsigned char *pstat = (unsigned char *)*gGameState + 0x186 + player * 0x14;
    *x = *(short *)(pstat + 0x0E);
    *y = *(short *)(pstat + 0x10);
    if (*x == 0 && *y == 0) {
        *x = (short)pstat[3];
        *y = (short)pstat[5];
    }
}

/* FUN_1003956c's "far" test: no living side's capital within Euclid
 * distance 14 (FUN_1000a884, truncated) of the site */
static Boolean SiteFarFromCapitals(const unsigned char *site)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short pl, sx = *(short *)(site + 0x00), sy = *(short *)(site + 0x02);
    for (pl = 0; pl < 8; pl++) {
        short cx, cy;
        long dx, dy, d2, r = 0;
        if (*(short *)(gs + 0x138 + pl * 2) == 0) continue;
        GetCapitalXY(pl, &cx, &cy);
        dx = cx - sx; dy = cy - sy; d2 = dx * dx + dy * dy;
        while ((r + 1) * (r + 1) <= d2) r++;
        if (r < 15) return false;
    }
    return true;
}

/* PPC FUN_10039ec8(p): the site tiles as player p sees them - a temple is
 * tile 11, a site that is not hidden tile 12 (the ruin), a hidden site tile
 * 10, or with quests on tile 9 (plain land, terrain type 7, so it can be
 * neither seen nor searched) while p does not know it (known mask). */
static void SiteTilesFor(short p)
{
    unsigned char *gs = (unsigned char *)*gGameState, *md;
    short ci, cc = sCityCount > 139 ? 139 : sCityCount;
    if (gs == NULL || *gMapTiles == 0 || p < 0 || p > 7) return;
    md = (unsigned char *)*gMapTiles;
    for (ci = 0; ci < cc; ci++) {
        unsigned char *site = sCityData + ci * 0x20;
        short x = *(short *)(site + 0x00), y = *(short *)(site + 0x02);
        unsigned char tile;
        if (site[0x17] < 2 || x < 0 || y < 0 || x >= sMapWidth || y >= sMapHeight) continue;
        if (site[0x17] == 2) tile = 11;
        else if (!SITE_HARD(site)) tile = 12;
        else if (!(SITE_KNOWN(site) & (1 << p)) && *(short *)(gs + 0x11e) != 0) tile = 9;
        else tile = 10;
        md[y * 0xE0 + x * 2] = tile;
    }
}

/* ===================================================================
 * CenterViewportOnPlayer — Center the map viewport on a player's capital
 *
 * Finds the current player (gs+0x110) and centers the viewport on their
 * capital city. Falls back to first owned army if no capital found.
 * Must be called after GameInit AND after ShowGameSetup changes the player.
 * =================================================================== */
static void CenterViewportOnPlayer(void)
{
    unsigned char *gs;
    short currentPlayer, i;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;

    currentPlayer = *(short *)(gs + 0x110);
    if (currentPlayer < 0 || currentPlayer >= MAX_FACTIONS) {
        sViewportX = 0; sViewportY = 0;
        return;
    }

    /* Try capital city first (68k: verify capital still owned by player) */
    {
        unsigned char *pstat = gs + 0x186 + currentPlayer * 0x14;
        /* Read from pstat+0x0E/0x10 (68k start_x/start_y, written by GameInit
         * capital coord loop). If zero (loop hasn't run), fall back to raw SCN
         * byte values at pstat[3]=capX and pstat[5]=capY. */
        short capX = *(short *)(pstat + 0x0E);
        short capY = *(short *)(pstat + 0x10);

        if (capX == 0 && capY == 0) {
            capX = (short)(unsigned char)pstat[3];
            capY = (short)(unsigned char)pstat[5];
        }

        if (capX > 0 || capY > 0) {
            short cci, ccc = sCityCount;
            if (ccc > 139) ccc = 139;
            for (cci = 0; cci < ccc; cci++) {
                unsigned char *city = sCityData +cci * 0x20;
                if (*(short *)(city + 0x00) == capX &&
                    *(short *)(city + 0x02) == capY) {
                    /* Accept if owned by current player OR still neutral
                     * (happens on first call during GameInit before ownership
                     * is assigned). Direct capital coord match is sufficient. */
                    CenterViewportOn(capX, capY);
                    return;
                }
            }
            /* Capital coords are valid but city not in array yet — use coords directly */
            if (capX >= 0 && capX < sMapWidth && capY >= 0 && capY < sMapHeight) {
                CenterViewportOn(capX, capY);
                return;
            }
        }
    }

    /* Fallback: find first army belonging to this player */
    {
        short armyCount = *(short *)(gs + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;  /* sanity cap */
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            if ((short)(unsigned char)army[0x15] == currentPlayer) {
                CenterViewportOn(*(short *)(army + 0x00), *(short *)(army + 0x02));
                return;
            }
        }
    }

    sViewportX = 0;
    sViewportY = 0;
    sViewPixX = sViewPixY = 0;
}


/* A city changes hands without a fight (quick start hand-out, resignation):
 * the record's owner, the 2x2 tiles' owner nibble, production and vectoring
 * cleared, vectors aimed at it dropped (PPC FUN_1004f438). */
static void AssignCityOwner(short ci, short owner)
{
    unsigned char *city;
    short cx, cy, dx, dy, cc = sCityCount;
    if (ci < 0 || ci >= cc || ci >= 139) return;
    city = sCityData + ci * 0x20;
    cx = *(short *)(city + 0x00);
    cy = *(short *)(city + 0x02);
    *(short *)(city + 0x04) = owner;
    if (*gMapTiles != 0) {
        unsigned char *md = (unsigned char *)*gMapTiles;
        for (dy = 0; dy < 2; dy++)
            for (dx = 0; dx < 2; dx++) {
                short tx = cx + dx, ty = cy + dy;
                if (tx >= 0 && tx < sMapWidth && ty >= 0 && ty < sMapHeight) {
                    unsigned short off = ty * 0xE0 + tx * 2;
                    md[off + 1] = (unsigned char)((md[off + 1] & 0xF0) | (owner & 0x0F));
                }
            }
    }
    if (*gExtState != 0) {
        unsigned char *ext = (unsigned char *)*gExtState;
        unsigned char *extCity = ext + 0x24c + ci * 0x5c;
        short cj;
        *(short *)(extCity + 0x02) = -1;   /* nothing in production */
        *(short *)(extCity + 0x58) = 0;
        *(short *)(extCity + 0x3e) = -1;   /* no vectoring */
        if (cc > 139) cc = 139;
        for (cj = 0; cj < cc; cj++)
            if (*(short *)(ext + 0x24c + cj * 0x5c + 0x3e) == ci)
                *(short *)(ext + 0x24c + cj * 0x5c + 0x3e) = -1;
    }
}

/* PPC FUN_1001e794 (68k CODE_117 FUN_00000db4): the city's best production
 * slot under weight set `set` (data+0xadd0/0xade0/0xadf0, 8 shorts each):
 *   str' = min(str + (gs+0xF0[current side] ? 2 : 0), 9), +2 more when the
 *          type's flag-table byte +5 (army-set stat 15) is 1;
 *   turns' = turns+1 when str' < 3 (not for set 6), capped at 10;
 *   score = sW[set]*str' + tW[set]*(10 - turns') + mW[set]*move/2
 * over the city's OWN slot values (city+0x161a types, +0x161e turns, +0x1622
 * strength, +0x1626 moves), which at new game are the army set's stats after
 * FUN_1003b9f8's sort and jitter.  Set 4 also needs the flying flag (stat
 * 16).  Slots 3..0 with a strict '>' (ties keep the later slot).  -1: none. */
static short BestCitySlotTypeW(short ci, short set)
{
    static const short kMoveW[8] = {0, 1, 1, 1, 1, 1, 10, 0};
    static const short kStrW[8]  = {0, 4, 10, 10, 10, 10, 1, 0};
    static const short kTurnW[8] = {0, 10, 10, 5, 5, 5, 10, 0};
    unsigned char *gs, *ec;
    short s, best = 0, unitType = -1, cur;
    Boolean tech;
    if (*gGameState == 0 || *gExtState == 0) return -1;
    if (ci < 0 || ci >= sCityCount || ci >= 139 || set < 0 || set > 7) return -1;
    gs = (unsigned char *)*gGameState;
    ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
    cur = *(short *)(gs + 0x110) & 7;
    tech = *(short *)(gs + 0xf0 + cur * 2) != 0;
    for (s = 3; s >= 0; s--) {
        short pt = *(short *)(ec + 0x06 + s * 2);
        short turns, str, move, score;
        if (pt < 0 || pt >= MAX_UNIT_TYPES) continue;
        turns = (short)(signed char)ec[0x40 + s];
        str   = (short)(signed char)ec[0x44 + s] + (tech ? 2 : 0);
        move  = (short)(signed char)ec[0x48 + s];
        if (str > 9) str = 9;
        if (sUnitTypesLoaded && pt < sUnitTypeCount && (UnitStatLE(pt, 15) & 0xFF) == 1) str += 2;
        if (set != 6 && str < 3) turns++;
        if (turns > 10) turns = 10;
        if (set == 4 && !(sUnitTypesLoaded && pt < sUnitTypeCount && (UnitStatLE(pt, 16) & 0xFF) != 0)) continue;
        score = (short)(str * kStrW[set] + kTurnW[set] * (10 - turns) + (move * kMoveW[set]) / 2);
        if (score > best) { best = score; unitType = pt; }
    }
    return unitType;
}

/* One army record of `count` (1..4) units of `type` for `owner` on the
 * city's anchor tile (68k FUN_00000be0 via func_0x4948). */
static void SpawnCityUnits(short ci, short owner, short type, short count, Boolean fortified)
{
    unsigned char *gs, *a, *city;
    short n, k, mv = 10, hp = 3;
    if (*gGameState == 0 || ci < 0 || ci >= sCityCount) return;
    gs = (unsigned char *)*gGameState;
    n = *(short *)(gs + 0x1602);
    if (n < 0 || n >= MAX_ARMIES) return;
    if (count < 1) count = 1;
    if (count > 4) count = 4;
    city = sCityData + ci * 0x20;
    if (sUnitTypesLoaded && type >= 0 && type < sUnitTypeCount) {
        short m = GetUnitTypeStat(type, 3), h = GetUnitTypeStat(type, 0);
        if (m > 0 && m <= 99) mv = m;
        if (h > 0) hp = h;
    }
    a = ARMY_REC(n);
    for (k = 0; k < 0x42; k++) a[k] = 0;
    *(short *)(a + 0x00) = *(short *)(city + 0x00);
    *(short *)(a + 0x02) = *(short *)(city + 0x02);
    a[0x15] = (unsigned char)owner;
    a[0x2f] = (unsigned char)owner;
    a[0x14] = (sUnitTypesLoaded && type >= 0 && type < sUnitTypeCount) ?
              sUnitTypeTable[type * UNIT_TYPE_ENTRY] : (unsigned char)type;
    for (k = 0; k < 4; k++) {
        if (k < count) {
            a[0x16 + k] = (unsigned char)type;
            a[0x1a + k] = (unsigned char)mv;
            a[0x1e + k] = (unsigned char)hp;
        } else a[0x16 + k] = 0xFF;
    }
    RecalcArmyStrength(a);
    if (fortified) { a[0x2e] = 20; a[0x2d] = 3; }
    else a[0x2e] = (owner >= 0 && owner < 8) ? 0 : (unsigned char)mv;   /* FUN_1002cae8: 0 until the turn-1 reset */
    *(short *)(gs + 0x1602) = n + 1;
}

/* ===================================================================
 * GameInit — Initialize game state after loading SCN data
 *
 * Reconstructed from FUN_1003c368 (GameInit, 1232 bytes).
 * Sets up turn counter, player alive flags, diplomacy, viewport,
 * city ownership, and army positions.
 * =================================================================== */
static void GameInit(void)
{
    unsigned char *gs;
    unsigned char *ext;
    short i, j;

    if (*gGameState == 0)
        return;

    gs  = (unsigned char *)*gGameState;
    ext = (*gExtState != 0) ? (unsigned char *)*gExtState : NULL;
    AIResetAll();                       /* the computer players start afresh */
    PathCacheClear();                   /* (the original clears it only at start-up, save and load) */

    /* --- Per-player Standard names (SCN+0xCE9 + i*0x1D: name[20], type 8,
     * value 0; e.g. Isles "White Standard", others "Knight Standard").  gs
     * is a raw SCN copy here; read it before the item records at gs+0xD12
     * (which overlap it) are built.  Random maps have no SCN block. --- */
    for (i = 0; i < 8; i++) {
        const unsigned char *src = gs + 0xCE9 + i * 0x1D;
        Boolean ok = !sRandomMap && src[0] >= 'A' && src[0] <= 'Z';
        for (j = 0; ok && j < 20 && src[j]; j++)
            if (src[j] < 0x20 || src[j] > 0x7E) ok = false;
        if (ok) {
            for (j = 0; j < 19 && src[j]; j++) sStandardNames[i][j] = (char)src[j];
            sStandardNames[i][j] = 0;
        } else {
            static const char kStd[] = "Knight Standard";
            for (j = 0; kStd[j]; j++) sStandardNames[i][j] = kStd[j];
            sStandardNames[i][j] = 0;
        }
    }

    /* --- The guardians (names and strengths, see sGuardName); a random map
     * keeps the standard table (Troll 5 ... Ghost 7) --- */
    {
        static const char *const kGName[10] = {"", "Troll", "Giant", "Wolf", "Goblin", "Dragon",
                                                "Demon", "Devil", "Wizard", "Ghost"};
        static const short kGStr[10] = {0, 5, 7, 4, 3, 8, 8, 8, 8, 7};
        short g;
        for (g = 0; g < 10; g++) {
            if (!sRandomMap) {
                for (j = 0; j < 15; j++) sGuardName[g][j] = (char)gs[0xF67 + g * 0x10 + j];
                sGuardName[g][15] = 0;
                sGuardStr[g] = (short)(gs[0x1007 + g * 2] | (gs[0x1008 + g * 2] << 8));
            } else {
                for (j = 0; kGName[g][j]; j++) sGuardName[g][j] = kGName[g][j];
                sGuardName[g][j] = 0;
                sGuardStr[g] = kGStr[g];
            }
        }
    }

    /* --- Basic game state fields (68k CODE_117 FUN_00001ab6) --- */

    /* Current turn = 1 */
    *(short *)(gs + 0x136) = 1;

    /* Game started flag = 0 (not started yet, becomes 1 after first move) */
    *(short *)(gs + 0x15e) = 0;

    /* Clear resource/intro flags (68k: gs+0x118=0, gs+0x158=0) */
    *(short *)(gs + 0x118) = 0;
    *(short *)(gs + 0x158) = 0;

    /* Map dimensions — write to game state so other code can read them */
    *(short *)(gs + 0x17a) = sMapHeight;
    *(short *)(gs + 0x17c) = sMapWidth;

    /* Viewport scroll: start at 0,0 */
    *(short *)(gs + 0x176) = 0;  /* scroll_y */
    *(short *)(gs + 0x178) = 0;  /* scroll_x */

    /* Max army slots (68k: starts at 10, grows as armies are created) */
    *(short *)(gs + 0x182) = 100;

    /* --- Player alive flags --- */
    /* Read from player_type array at 0xD0. If type != 0xFF, player is alive */
    {
        short factionCount = 8;   /* gs+0x100..0x10F are the advisor's bytes (original layout) */

        for (i = 0; i < 8; i++) {
            /* A faction participates only if its slot has a REAL name. The SCN
             * stores the literal "Not Used" for unused slots (verified: Tutoria
             * SCN 10000 = Knights, "Not Used" x6, Darklords). factionCount is just
             * the highest named slot+1, so unused middle slots fall inside it —
             * without this check they were marked alive and got starting armies at
             * junk capital coords (the phantom armies floating in the sea). The
             * original keys participation off the capital, then overwrites dead
             * slots' names with "Not Used" + colour 3 (68k CODE_116:177-191). */
            unsigned char *fname = gs + i * 0x14;
            Boolean realFaction = (i < factionCount) && (fname[0] != 0) &&
                !(fname[0]=='N' && fname[1]=='o' && fname[2]=='t' && fname[3]==' ' &&
                  fname[4]=='U' && fname[5]=='s' && fname[6]=='e' && fname[7]=='d');
            if (realFaction) {
                *(short *)(gs + 0x138 + i * 2) = 1;  /* alive */
                *(short *)(gs + 0x148 + i * 2) = 1;  /* secondary alive flag */
            } else {
                *(short *)(gs + 0x138 + i * 2) = 0;  /* not in this scenario */
                *(short *)(gs + 0x148 + i * 2) = 0;
                *(short *)(gs + 0xc0 + i * 2) = 3;   /* grey (68k CODE_116: colour 3) */
            }
        }
    }

    /* 68k CODE_117 FUN_00001ab6: validate each player's capital coords.
     * If a player has no valid capital (Y < 0 or not matching any city),
     * mark as eliminated and AI-controlled. Prevents crashes with
     * malformed scenarios that define faction slots without real cities. */
    for (i = 0; i < 8; i++) {
        if (*(short *)(gs + 0x138 + i * 2) != 0) {
            short capY = (short)(unsigned char)gs[0x186 + i * 0x14 + 5];
            if (capY <= 0 || capY >= sMapHeight) {
                *(short *)(gs + 0xd0 + i * 2) = 1;     /* force AI */
                *(short *)(gs + 0x138 + i * 2) = 0;     /* eliminated */
            }
        }
    }

    /* --- Turn order: default sequential --- */
    for (i = 0; i < 8; i++) {
        *(short *)(gs + 0x164 + i * 2) = i;
    }

    /* --- Hero hire scores and tracking (68k CODE_117 FUN_00000a8e) --- */
    /* 68k randomizes hero hire scores with func_0x00002ad0(8) (random 0-7).
     * This affects hero availability timing per-player. */
    {
        unsigned short rSeed = (unsigned short)TickCount();
        for (i = 0; i < 8; i++) {
            rSeed = rSeed * 25173 + 13849;  /* simple LCG */
            *(short *)(gs + 0x1122 + i * 2) = (short)(rSeed % 8);
            *(short *)(gs + 0x1132 + i * 2) = (short)0xFFFF; /* tracking: -1 sentinel */
        }
    }

    /* --- Per-player gold initialization (68k CODE_117 FUN_00001ab6) --- */
    /* 68k preserves SCN scenario gold at gs+0x186+i*0x14 for alive players.
     * Only zero gold for eliminated players. */
    /* Scenario gold is a little-endian short at SCN+0x185+p*0x14, one byte
     * before gs+0x186 (same shift as the city block): Erythea 200, 75, 150,
     * 45, 125, 95, 35, 80; Hadesha P0 f4 01 = 500. Production setting costs
     * nothing (stat[4] is the price of buying a new unit type into a slot). */
    for (i = 0; i < 8; i++) {
        if (!sRandomMap) {
            short g = (short)((unsigned char)gs[0x185 + i * 0x14] |
                              ((unsigned char)gs[0x186 + i * 0x14] << 8));
            *(short *)(gs + 0x186 + i * 0x14) = g;
        }
        if (*(short *)(gs + 0x138 + i * 2) == 0) {
            *(short *)(gs + 0x186 + i * 0x14) = 0;    /* no gold for eliminated */
        }
    }


    /* --- Rebuild city records from valid SCN data at gs+0x157D ---
     * IMPORTANT: This MUST run before diplomacy init, because the diplomacy
     * table at gs+0x1582 (64 bytes) extends to gs+0x15C1, overlapping the
     * SCN city compact records starting at gs+0x157D. ---
     * For loaded scenarios: the raw gs+0x812 records are MacApp-serialized objects
     * with garbage X/Y. Valid city data lives at gs+0x157D (stride 0x41).
     * For random maps: gs+0x812 already has valid city data written by
     * GenerateRandomMap, and gs+0x157D now overlaps with army records.
     * Skip this rebuild for random maps to avoid overwriting correct data. */
    if (!sRandomMap) {
        /* Read player capital coordinates from raw SCN player stat blocks.
         * pstat = gs+0x186+p*0x14. Capital X is a BYTE at pstat[3] (low byte
         * of the BE short at pstat+0x02), Y at pstat[5] (low byte of pstat+0x04).
         * Write them immediately to pstat+0x0E/0x10 (68k start_x/start_y) so
         * army creation and CenterViewportOnPlayer always find valid coords there,
         * regardless of whether the capital coord writing loop below succeeds. */
        short capX[8], capY[8];
        for (i = 0; i < 8; i++) {
            unsigned char *pstat = gs + 0x186 + i * 0x14;
            capX[i] = (short)(unsigned char)pstat[3];
            capY[i] = (short)(unsigned char)pstat[5];
            *(short *)(pstat + 0x0E) = capX[i];
            *(short *)(pstat + 0x10) = capY[i];
        }
        /* DEBUG: store P0 capital coords */
        sDbgCapX0 = capX[0]; sDbgCapY0 = capY[0];

        /* SCN city block: LE short count at gs+0x157B, then 0x41-byte records
         * from gs+0x157D (verified on all 6 scenarios: Erythea=80, Tutoria=6).
         * Reading from gs+0x15BE skipped record 0 (Kuuria / Skullcrag). The
         * coordinate scan below stays as a guard against a bad count. */
        short scnCityCount = (short)((unsigned char)gs[0x157B] |
                                     ((unsigned short)(unsigned char)gs[0x157C] << 8));
        if (scnCityCount < 0 || scnCityCount > 99) scnCityCount = 99;
        short cityCount = 0;
        for (i = 0; i < scnCityCount; i++) {
            unsigned char *src = gs + 0x157D + i * 0x41;
            short cx = (short)((unsigned char)src[0] | ((unsigned short)(unsigned char)src[1] << 8));
            short cy = (short)((unsigned char)src[2] | ((unsigned short)(unsigned char)src[3] << 8));
            if ((cx == 0 && cy == 0) || cx >= 112 || cy >= 156) break;
            cityCount++;
        }
        sCityCount = cityCount;
        /* DEBUG */
        sDbgCityCount = cityCount;
        if (cityCount > 0) {
            unsigned char *s0 = gs + 0x157D;
            sDbgCity0X = (short)((unsigned char)s0[0] | ((unsigned short)(unsigned char)s0[1] << 8));
            sDbgCity0Y = (short)((unsigned char)s0[2] | ((unsigned short)(unsigned char)s0[3] << 8));
        }

        /* Rebuild sCityData entries from the valid 0x41-byte city records.
         * Our runtime 0x20-byte layout:
         *   +0x00: X (short, native BE)
         *   +0x02: Y (short, native BE)
         *   +0x04: owner (short; 0-7 = player, 0x0F = neutral)
         *   +0x06: defense (short)
         *   +0x0C..+0x13: production type slots (4 shorts; -1 = empty)
         *   +0x17: site type (0 = city; non-zero = ruin/temple) */
        for (i = 0; i < cityCount; i++) {
            unsigned char *src  = gs + 0x157D + i * 0x41;
            unsigned char *city = sCityData + i * 0x20;
            short cx = (short)((unsigned char)src[0] | ((unsigned short)(unsigned char)src[1] << 8));
            short cy = (short)((unsigned char)src[2] | ((unsigned short)(unsigned char)src[3] << 8));

            /* Determine owner: player if capital, else neutral */
            short owner = 0x0F;
            for (j = 0; j < 8; j++) {
                if (cx == capX[j] && cy == capY[j]) { owner = j; break; }
            }

            /* Clear the 0x20-byte record first */
            for (j = 0; j < 0x20; j++) city[j] = 0;

            *(short *)(city + 0x00) = cx;
            *(short *)(city + 0x02) = cy;
            *(short *)(city + 0x04) = owner;
            *(short *)(city + 0x06) = (short)(unsigned char)src[0x14];  /* defense */

            /* Production capability: read from SCN compact record +0x16..+0x19.
             * Each byte is a unit type index (0-28) or 0xFF (empty slot).
             * 68k CODE_117 FUN_00002118 strips Catapults (type 5) from every
             * city at game start and compacts the list (confirmed in an original
             * Erythea save: Mirea 01 04 05 0a -> 01 04 0a ff). The slot's SCN
             * build turns (+0x1A), strength (+0x1E) and movement (+0x22) travel
             * with it for the starting-army choice below. */
            {
                short n = 0;
                for (j = 0; j < 4; j++) {
                    *(short *)(city + 0x0C + j * 2) = -1;
                    sScnSlotStats[i][j][0] = sScnSlotStats[i][j][1] = sScnSlotStats[i][j][2] = 0;
                }
                for (j = 0; j < 4; j++) {
                    unsigned char pt = src[0x16 + j];
                    if (pt == 0xFF || pt == 5) continue;
                    *(short *)(city + 0x0C + n * 2) = (short)pt;
                    sScnSlotStats[i][n][0] = src[0x1A + j];
                    sScnSlotStats[i][n][1] = src[0x1E + j];
                    sScnSlotStats[i][n][2] = src[0x22 + j];
                    n++;
                }
            }

            /* Income: SCN compact record +0x2A */
            *(short *)(city + 0x08) = (short)(unsigned char)src[0x2A];

            city[0x17] = 0;  /* site type: 0 = playable city */

            /* the record's name (16 bytes at +0x04) is the city's name */
            if (i < 99) {
                for (j = 0; j < 16 && src[0x04 + j] != 0; j++) sScnCityNames[i][j] = (char)src[0x04 + j];
                sScnCityNames[i][j] = 0;
                sScnCityNamesValid = true;
            }

            /* City name: the SCN record's C string at +0x04 (16 bytes,
             * "White College", "Caldera").  The original's city window 'name'
             * (View 3300, TSunkenText) shows this field; the CTY text is only
             * the Info pane's description ("The city of Caldera...").  The
             * CTY-derived guess that LoadCityNames made is replaced here. */
            if (i < 99) {
                short q = 0;
                while (q < 16 && q < MAX_CITY_NAME - 1 && src[0x04 + q] != 0) {
                    sCityNames[i][q] = (char)src[0x04 + q];
                    q++;
                }
                sCityNames[i][q] = 0;
                if (sCityNameCount < i + 1) sCityNameCount = i + 1;
            }
        }
        /* DEBUG: count non-neutral cities */
        {
            short oc = 0;
            for (i = 0; i < cityCount; i++) {
                if (*(short *)(sCityData +i * 0x20 + 0x04) != 0x0F) oc++;
            }
            sDbgOwnedCount = oc;
        }

        /* --- Load ruins/temples from gs+0x811 records (stride 0x1F = 31 bytes) ---
         * Record layout (verified by hex dump analysis):
         *   +0x00: X (byte), +0x01: 0x00, +0x02: Y (byte), +0x03: 0x00
         *   +0x04: name (20 bytes), +0x18: site_type (1=temple, 2=ruin)
         * Stop when site_type == 0 (sentinel = city record, not a ruin).
         * Site type mapping: 1→2(temple), 2→3(sage), 3→4(ruin), 4→3(library),
         *   5→5(searchable), 6→3(library) */
        {
            static const unsigned char gsTypeMap[7] = {0, 2, 3, 4, 3, 5, 3};
            short ri;
            for (ri = 0; ri < 40 && cityCount < 139; ri++) {
                unsigned char *rec = gs + 0x811 + ri * 0x1F;
                short rx = (short)rec[0x00];
                short ry = (short)rec[0x02];
                unsigned char gsType = rec[0x18];
                unsigned char sType;

                /* Stop on sentinel (type=0 means city, not ruin/temple) */
                if (gsType == 0) break;
                /* Validate coordinates */
                if (rx <= 0 || ry <= 0 || rx >= sMapWidth || ry >= sMapHeight) continue;

                /* Map gs site type to runtime sType */
                if (gsType >= 1 && gsType <= 6)
                    sType = gsTypeMap[gsType];
                else
                    sType = 4; /* default to ruin */

                {
                    unsigned char *ruin = sCityData + cityCount * 0x20;
                    short si;
                    for (si = 0; si < 0x20; si++) ruin[si] = 0;
                    *(short *)(ruin + 0x00) = rx;
                    *(short *)(ruin + 0x02) = ry;
                    *(short *)(ruin + 0x04) = (short)0xFF;  /* no owner */
                    ruin[0x17] = sType;
                    cityCount++;
                }
            }
            sCityCount = cityCount;
        }
    }

    /* --- Initialize diplomacy table (0x1582, 8x8 matrix of BYTES) --- */
    /* 68k CODE_117 FUN_00000ad2: each entry is 1 byte with bitfields:
     *   Bits 2-3: diplomatic state (extracted as (byte>>2)&3: 0=peace, 2=war)
     *   Bit 3 (0x08): war flag
     *   Bit 4 (0x10): diplomatic change notification
     *   Bit 5 (0x20): direction of change
     * Table is 64 bytes: 8 rows x 8 cols x 1 byte per entry.
     * Default: 0x00 (at peace, all flags clear).
     * NOTE: This MUST run after city rebuild, because the 64-byte range
     * gs+0x1582..0x15C1 overlaps the city compact records at gs+0x157D. */
    for (i = 0; i < 8; i++) {
        for (j = 0; j < 8; j++) {
            *(gs + 0x1582 + i * 8 + j) = 0x00;
        }
    }

    /* --- Initialize extended state (cities) --- */
    if (ext != NULL) {
        short cityCount = 0;

        /* Parse city data from SCN. Cities are at gs+0x0812, each 0x20 bytes.
         * City count at gs+0x0810. */
        cityCount = sCityCount;
        if (cityCount < 0) cityCount = 0;
        if (cityCount > 139) cityCount = 139;

        *(short *)(ext + 0x24a) = cityCount;

        /* City record layout (rebuilt from valid SCN city data):
         *   +0x00: city_x (short)
         *   +0x02: city_y (short)
         *   +0x04: owner (short; 0-7 = player, 0x0F = neutral)
         *   +0x06: defense (short)
         *   +0x0C-0x13: production capability (4 shorts)
         *   +0x17: site type (0 = city, non-zero = ruin/temple)
         */
        for (i = 0; i < cityCount; i++) {
            unsigned char *city = sCityData +i * 0x20;
            unsigned char *extCity = ext + 0x24c + i * 0x5c;
            short siteType = (short)(unsigned char)city[0x17];

            /* Mark city as active */
            *(short *)(extCity + 0x00) = 1;

            /* Default: produce nothing (-1) for non-cities */
            *(short *)(extCity + 0x02) = -1;
            *(short *)(extCity + 0x04) = -1;  /* garrison_army = none */

            /* Initialize production capability slots from SCN city data.
             * SCN city record +0x0C-+0x15: up to 5 producible unit type indices.
             * Each is a short; -1 (0xFFFF) = empty slot. */
            for (j = 0; j < 4; j++) {
                short pType = *(short *)(city + 0x0C + j * 2);
                *(short *)(extCity + 0x06 + j * 2) = pType;
            }

            /* 68k CODE_072: sort production slots ascending by unit cost.
             * Empty slots (-1) sort to the end. Simple insertion sort. */
            { short a2, b2;
              for (a2 = 1; a2 < 4; a2++) {
                  short keyType = *(short *)(extCity + 0x06 + a2 * 2);
                  short keyCost = (keyType >= 0) ? UnitStatLE(keyType, 4) : 9999;
                  b2 = a2 - 1;
                  while (b2 >= 0) {
                      short bType = *(short *)(extCity + 0x06 + b2 * 2);
                      short bCost = (bType >= 0) ? UnitStatLE(bType, 4) : 9999;
                      if (bCost <= keyCost) break;
                      *(short *)(extCity + 0x06 + (b2 + 1) * 2) = bType;
                      b2--;
                  }
                  *(short *)(extCity + 0x06 + (b2 + 1) * 2) = keyType;
              }
            }

            /* Initialize build queue to empty */
            for (j = 0; j < 12; j++)
                *(short *)(extCity + 0x0e + j * 2) = -1;

            /* Initialize vectoring targets to -1 (no vectoring) */
            for (j = 0; j < 4; j++)
                *(short *)(extCity + 0x3e + j * 2) = -1;

            /* +0x50: the attacked-by mask (the original's city+0x30, one bit
             * per attacking player, cleared only here; FUN_1002d93c) */
            extCity[0x50] = 0;

            /* Cities start idle: on the original's turn 1 Mirea shows
             * "Current: -" (the AI sets production for its own idle cities). */
            *(short *)(extCity + 0x02) = -1;
            *(short *)(extCity + 0x58) = (siteType == 0) ? -1 : 0;

            /* 68k CODE_072: city defense from production slot count, not SCN value */
            if (siteType == 0) {
                *(short *)(city + 0x06) = CalcCityDefense(extCity);
            }

            /* Detect port cities: check 8 neighbors for water terrain (type 2=Water or 9=Sea).
             * Sets CITY_FLAG_PORT (0x08) at extCity+0x5A. */
            {
                short cx = *(short *)(city + 0x00);
                short cy = *(short *)(city + 0x02);
                short flags = 0;
                if (siteType < 2 && *gMapTiles != 0 && *gGameState != 0) {
                    unsigned char *md = (unsigned char *)*gMapTiles;
                    unsigned char *sd = (unsigned char *)*gGameState;
                    static const short dx8[8] = {-1, 0, 1, -1, 1, -1, 0, 1};
                    static const short dy8[8] = {-1,-1,-1,  0, 0,  1, 1, 1};
                    short ni;
                    for (ni = 0; ni < 8; ni++) {
                        short nx = cx + dx8[ni];
                        short ny = cy + dy8[ni];
                        if (nx >= 0 && nx < sMapWidth && ny >= 0 && ny < sMapHeight) {
                            unsigned char tIdx = md[ny * 0xE0 + nx * 2];
                            short tType = (short)(unsigned char)sd[tIdx + TERRAIN_TYPE_OFS];
                            if (tType == 2 || tType == 9) {
                                flags |= 0x08;  /* port */
                                break;
                            }
                        }
                    }
                }
                *(short *)(extCity + 0x5A) = flags;

                /* Filter out naval units from non-port cities (68k production filter).
                 * Sets naval production slots to -1 so they don't appear anywhere. */
                if (!(flags & 0x08) && sUnitTypesLoaded) {
                    short ps;
                    for (ps = 0; ps < 4; ps++) {
                        short pt = *(short *)(extCity + 0x06 + ps * 2);
                        if (pt >= 0 && pt < MAX_UNIT_TYPES &&
                            sUnitTypeTable[pt * UNIT_TYPE_ENTRY + UTE_STAT_NAVAL] >= 1) {
                            *(short *)(extCity + 0x06 + ps * 2) = -1;
                        }
                    }
                }
            }
        }

        /* army_state moved to sArmyState. ext+0x11e/0x182/0x1e6 were
         * write-only and a 1000-wide write would run into the city records. */
        for (i = 0; i < MAX_ARMIES; i++) sArmyState[i] = 0;
    }

    /* --- Write per-player capital coordinates to stats block --- */
    /* Scan city records to find each player's capital (first city they own).
     * Per-player stats at gs + 0x186 + p*0x14:
     *   +0x04: capital_x, +0x06: capital_y
     *   +0x0E: start_x,   +0x10: start_y   */
    {
        short cityCount = sCityCount;
        if (cityCount > 139) cityCount = 139;
        for (i = 0; i < 8; i++) {
            unsigned char *pstat = gs + 0x186 + i * 0x14;
            Boolean foundCap = false;
            for (j = 0; j < cityCount && !foundCap; j++) {
                unsigned char *city = sCityData +j * 0x20;
                short cOwner = *(short *)(city + 0x04);
                short sType  = (short)(unsigned char)city[0x17];
                if (cOwner == i && sType == 0) {  /* city owned by player i */
                    short capX = *(short *)(city + 0x00);
                    short capY = *(short *)(city + 0x02);
                    *(short *)(pstat + 0x04) = capX;  /* capital_x */
                    *(short *)(pstat + 0x06) = capY;  /* capital_y */
                    *(short *)(pstat + 0x0E) = capX;  /* start_x */
                    *(short *)(pstat + 0x10) = capY;  /* start_y */
                    foundCap = true;
                }
            }
        }
    }

    /* --- Validate player capitals (68k CODE_117 FUN_00001ab6 step 2) --- */
    /* If a player has no capital city, mark them as eliminated.
     * This prevents orphaned players with no home base. */
    {
        short factionCount = 8;
        for (i = 0; i < factionCount; i++) {
            unsigned char *pstat = gs + 0x186 + i * 0x14;
            short capX = *(short *)(pstat + 0x04);
            short capY = *(short *)(pstat + 0x06);
            if (capX == 0 && capY == 0) {
                /* No capital found — check if player has any cities at all */
                short cityCount = sCityCount;
                Boolean hasCity = false;
                if (cityCount > 139) cityCount = 139;
                for (j = 0; j < cityCount; j++) {
                    unsigned char *site = sCityData +j * 0x20;
                    if (*(short *)(site + 0x04) == i &&
                        (unsigned char)site[0x17] == 0) {
                        hasCity = true;
                        break;
                    }
                }
                if (!hasCity) {
                    *(short *)(gs + 0x138 + i * 2) = 0;  /* eliminate */
                    *(short *)(gs + 0x148 + i * 2) = 0;
                    *(short *)(gs + 0xd0 + i * 2) = 1;   /* force to AI */
                }
            }
        }
    }

    /* --- Initialize army records --- */
    /* The raw gs+0x1602/0x1604 area overlaps with the city compact records at
     * gs+0x157D that we read for city initialization. The "army count" value
     * read from gs+0x1602 is garbage (it's city name bytes, not a real count).
     * We reset the army count to 0 and build all armies from scratch:
     *   1. Neutral garrison armies are created by the loop below.
     *   2. Player starting armies are created after the garrison loop.
     * This matches the 68k initialization which also builds armies
     * programmatically (CODE_116 FUN_0000000c, CODE_117 FUN_00001ecc). */
    {
        /* Clear the out-of-gs army table. Do not wipe gs+0x1604. */
        for (i = 0; i < MAX_ARMIES; i++) {
            unsigned char *army = ARMY_REC(i);
            short z;
            for (z = 0; z < 0x42; z++) army[z] = 0;
            sArmyState[i] = 0;
        }
        /* Reset army count to 0; garrison/player army loops will set it */
        *(short *)(gs + 0x1602) = 0;
    }

    /* --- The fight order (gs+0x60C, 29 bytes per side, lower fights first):
     * the original's FUN_1005668c loads the SCN one byte later than the
     * remake's raw copy, so its gs+0x60C holds SCN+0x60B (every shipped
     * scenario: 8 3 1 6 12 28 5 11 ... in all nine rows).  Shift it into
     * place; rows 0-7 and the first 28 bytes of row 8 (the remake keeps the
     * terrain table at SCN+0x710, row 8's last byte in the original).  A
     * random map, or a row that is no permutation of 0..28, gets 0..28. --- */
    {
        short pi, ut;
        Boolean ok = !sRandomMap;
        for (pi = 0; pi < 9 && ok; pi++) {
            unsigned long seen = 0;
            short nb = (pi == 8) ? 28 : 29;
            for (ut = 0; ut < nb; ut++) {
                unsigned char v = gs[0x60B + pi * 0x1D + ut];
                if (v > 28 || (seen & (1UL << v))) { ok = false; break; }
                seen |= 1UL << v;
            }
        }
        for (pi = 8; pi >= 0; pi--) {          /* backwards: the copy overlaps */
            short nb = (pi == 8) ? 28 : 29;
            for (ut = nb - 1; ut >= 0; ut--)
                gs[0x60C + pi * 0x1D + ut] = ok ? gs[0x60B + pi * 0x1D + ut] : (unsigned char)ut;
        }
    }

    /* --- Initialize movement cost table (9 terrain x 29 units) --- */
    /* Copy from gs+0x60C (where SCN data lives) into sMoveCostTable,
     * then fill defaults if empty. This must happen BEFORE fight order
     * init in BeginGame() which overwrites gs+0x60C.
     * Layout: sMoveCostTable[terrainType * 29 + unitType] = cost (0=impassable) */
    {
        /* gs+0x60C is the per-player fight-order table (Erythea: the same
         * 29-byte permutation 8 times), NOT movement costs; copying it gave
         * the hero 8 MP per road tile. Always use the defaults until the
         * original's table is known (road/city measured at 1 MP). */
        Boolean tableEmpty = true;
        for (i = 0; i < 9 * 29; i++) sMoveCostTable[i] = 0;
        if (tableEmpty) {
            /* Fill with defaults: land costs by terrain
             * 68k types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
             *            5=Hills, 6=Mountains, 7=Plains, 8=Marsh */
            static const unsigned char defaultCosts[9] = {
                1,  /* 0 road: 1 MP (cheapest terrain) */
                1,  /* 1 bridge: 1 MP */
                0,  /* 2 water: impassable for land (naval gets 2) */
                2,  /* 3 shore: 2 MP */
                3,  /* 4 forest: 3 MP */
                3,  /* 5 hills: 3 MP */
                6,  /* 6 mountains: 6 MP (most units can't) */
                2,  /* 7 plains: 2 MP */
                4,  /* 8 marsh/swamp: 4 MP */
            };
            short ut, tt;
            for (ut = 0; ut < 29; ut++) {
                short isNaval = 0;
                /* Check if this unit type is naval (stat[19] in DAT) */
                if (sUnitTypesLoaded && ut < sUnitTypeCount) {
                    unsigned char *ute = sUnitTypeTable + ut * UNIT_TYPE_ENTRY;
                    if (ute[UTE_STAT_NAVAL] >= 1) isNaval = 1;
                }
                for (tt = 0; tt < 9; tt++) {
                    if (isNaval) {
                        /* Naval: can traverse water and shore, not land */
                        if (tt == 2)      sMoveCostTable[tt * 29 + ut] = 2;  /* water */
                        else if (tt == 3) sMoveCostTable[tt * 29 + ut] = 2;  /* shore */
                        else              sMoveCostTable[tt * 29 + ut] = 0;  /* land: impassable */
                    } else {
                        sMoveCostTable[tt * 29 + ut] = defaultCosts[tt];
                        /* Mountains: impassable for most except heroes */
                        if (tt == 6 && ut != 0x1C) sMoveCostTable[tt * 29 + ut] = 0;
                    }
                }
            }
        }
    }

    /* (The ruins and items, the Quick Start handout, the slot jitter, the
     * computer sides' zones and the starting armies are dealt at Begin Game,
     * in the original's order: BeginNewGame below.) */
    /* (No per-army stat variance: FUN_1003b9f8 jitters the CITY SLOTS only,
     * which JitterCitySlotStats ports; the remake's old per-army pass changed
     * starting units' strength, moves and a[0x22] - now the unit's upkeep -
     * and consumed Random() calls the original does not make.) */

    /* NOTE: Unit slot sort by fight priority (FUN_100496c8) is NOT done here
     * because gs+0x60C still contains movement costs at this point (fight order
     * is initialized later in game setup). The combat code at line ~11063
     * already sorts slots before each battle. */

    /* --- Center viewport on current player's capital city --- */
    CenterViewportOnPlayer();

    /* --- Clear fog and defended bits on map tiles and road data (68k CODE_117 step 23) ---
     * Map tile byte 1: clear bit 5 (visibility), clear bit 4 (army present)
     * Road data: clear bit 6 (city-defended) for each tile */
    if (*gMapTiles != 0) {
        unsigned char *mapData = (unsigned char *)*gMapTiles;
        unsigned char *roadData = (*gRoadData != 0) ? (unsigned char *)*gRoadData : NULL;
        short mx, my;
        for (my = 0; my < 156 && my < sMapHeight; my++) {
            for (mx = 0; mx < 112 && mx < sMapWidth; mx++) {
                unsigned short off = my * 0xE0 + mx * 2;
                mapData[off + 1] &= 0xCF;  /* clear bits 4+5 (army present + visibility) */
                if (roadData)
                    roadData[my * 0x70 + mx] &= 0xBF;  /* clear bit 6 (city-defended) */
            }
        }
    }

    /* --- Stamp city/site terrain indices into map tiles (68k CODE_128 FUN_000003ae) ---
     * Cities overwrite the terrain index (byte 0) in a 2x2 area with special values:
     *   0x0B = capital, 0x0A = player city, 0x0C = neutral city, 0x09 = ruin/site
     * Also write owner into byte 1 low nibble. */
    if (*gMapTiles != 0) {
        unsigned char *mapData = (unsigned char *)*gMapTiles;
        short siteCount = sCityCount;
        if (siteCount > 139) siteCount = 139;

        for (i = 0; i < siteCount; i++) {
            unsigned char *site = sCityData +i * 0x20;
            short sx = *(short *)(site + 0x00);
            short sy = *(short *)(site + 0x02);
            short sOwner = *(short *)(site + 0x04);
            short sType = (short)(unsigned char)site[0x17];
            unsigned char terrIdx;
            unsigned char ownerNibble;
            Boolean isCapital = false;

            /* Check if this city is a player's capital (matches pstat capital coords) */
            if (sType == 0 && sOwner >= 0 && sOwner < 8) {
                unsigned char *pstat = gs + 0x186 + sOwner * 0x14;
                short capX = *(short *)(pstat + 0x04);
                short capY = *(short *)(pstat + 0x06);
                if (capX == sx && capY == sy) isCapital = true;
            }

            /* Determine terrain index for this site type */
            if (isCapital)        terrIdx = 0x0B;  /* capital */
            else if (sType == 0)  terrIdx = (sOwner >= 0 && sOwner < 8) ? 0x0A : 0x0C;  /* city: player=0A, neutral=0C */
            else                  terrIdx = 0x09;   /* ruin/temple/library */

            ownerNibble = (sOwner >= 0 && sOwner < 8) ? (unsigned char)sOwner : 0x0F;

            /* Stamp tile area: cities are 2x2, ruins/temples are 1x1 */
            {
                short dx, dy;
                short stampW = (sType < 2) ? 2 : 1;
                short stampH = (sType < 2) ? 2 : 1;
                for (dy = 0; dy < stampH; dy++) {
                    for (dx = 0; dx < stampW; dx++) {
                        short tx = sx + dx;
                        short ty = sy + dy;
                        if (tx >= 0 && tx < sMapWidth && ty >= 0 && ty < sMapHeight) {
                            unsigned short off = ty * 0xE0 + tx * 2;
                            /* Terrain byte left alone: the scenario's city tiles
                             * (Erythea 96/97/112/113) are already type 10 (City),
                             * and the original's minimap draws them (validated
                             * pixel-exact); the old stamp made them Ruin/Marsh. */
                            (void)terrIdx;
                            mapData[off + 1] = (mapData[off + 1] & 0xF0) | (ownerNibble & 0x0F);
                        }
                    }
                }
            }
        }
    }

    /* The original never alters the army set's table: FUN_1003b9f8 gives each
     * CITY SLOT its type's stats and jitters THOSE at new game
     * (JitterCitySlotStats, run from FinalizeCitySlots once the table is in;
     * the city window and the produced units read the slot). */
    sCitySlotStatsPending = true;
    sNewGamePending = true;     /* BeginNewGame deals the rest after Begin Game */
    if (sUnitTypesLoaded && sUnitTypeCount > 0) {
        BlockMoveData(sUnitTypeTableBase, sUnitTypeTable,
                      (long)sUnitTypeCount * UNIT_TYPE_ENTRY);
    }
    /* --- Initialize fog of war --- */
    {
        short p;
        for (p = 0; p < 8; p++) {
            for (i = 0; i < FOG_BYTES_PER_PLAYER; i++) {
                sFogExplored[p][i] = 0;
                sFogVisible[p][i] = 0;
            }
        }
        /* Reveal initial positions for all players */
        for (p = 0; p < 8; p++) {
            if (*(short *)(gs + 0x138 + p * 2) != 0) {
                FogUpdatePlayer(p);
            }
        }
    }
}


/* ===================================================================
 * BeginNewGame — the original's new-game deal after Begin Game (PPC 1.0.7
 * FUN_1003e13c, PPC_0002.c:3974): FUN_1003c838 (the turn order, 20 swaps
 * with Random Turns) -> FUN_1003d4dc (the first living side in that order
 * moves first) -> FUN_1003c368: FUN_1003956c (ruins, items) ->
 * FUN_1003c068 (capitals, Quick Start handout, FUN_1003b9f8 slot jitter) ->
 * FUN_10025f2c -> FUN_1001db60 (the computer sides' zones) ->
 * FUN_1002cbbc (starting armies) -> notoriety Dice(1,8,0) per side (+400
 * for a human under "I am the Greatest").  Every roll in this order.  Runs
 * once the army set's table is in (the slot stats need it).
 * =================================================================== */
static short AIDist(short x1, short y1, short x2, short y2);
static void AISetupZones(void);
static short PathCityIndexAt(short x, short y);

static void BeginNewGame(void)
{
    unsigned char *gs;
    short i, j;

    if (!sNewGamePending || *gGameState == 0) return;
    sNewGamePending = false;
    gs = (unsigned char *)*gGameState;

    /* --- FUN_1003c838: the turn order --- */
    for (i = 0; i < 8; i++) *(short *)(gs + 0x164 + i * 2) = i;
    if (*(short *)(gs + 0x122) != 0) {
        short sw;
        for (sw = 0; sw < 20; sw++) {
            short a = Dice(1, 8, -1);
            short b = Dice(1, 8, -1);
            short tmp = *(short *)(gs + 0x164 + b * 2);
            *(short *)(gs + 0x164 + b * 2) = *(short *)(gs + 0x164 + a * 2);
            *(short *)(gs + 0x164 + a * 2) = tmp;
        }
    }
    *(short *)(gs + 0x174) = 0;
    *(short *)(gs + 0x118) = 0;

    /* --- FUN_1003d4dc: the first living side in the order moves first --- */
    for (i = 0; i < 8; i++) {
        short p = *(short *)(gs + 0x164 + *(short *)(gs + 0x174) * 2);
        *(short *)(gs + 0x110) = p;
        *(short *)(gs + 0x174) += 1;
        if (*(short *)(gs + 0x174) > 7) *(short *)(gs + 0x118) = 1;
        if (*(short *)(gs + 0x138 + p * 2) != 0) break;
    }

    /* --- Ruins, temples and items (PPC 1.0.7 FUN_1003956c with FUN_10038fb8
     * and FUN_10039180, PPC_0002.c:817-1225).  Every count is based on ALL
     * sites, temples included (the original's gs+0x810):
     *   - p = sites*2/10;
     *   - FUN_10038fb8: sites*3/10 random non-temple sites are HIDDEN
     *     (site+0x1C, Dice(1,sites,-1) until a free one); with quests on a
     *     hidden site starts unknown to everyone (known mask site+0x12 = 0,
     *     else 0xFF; set again at BeginGame with the final options);
     *   - FUN_10039180(p): item records 8..21 are unique picks from the item
     *     list (Dice(1,list,-1)), special ones (movement, flying, command > 1,
     *     standard) for records 8..8+p-1, plain ones after;
     *   - k = min(2d3+1, p); N = min(22, sites/3 + 1d5-3 + 8); records 8..N-1
     *     below 8+k or from 8+p on hide in a random unused site whose hidden
     *     flag matches the item's specialness (a draw that does not match
     *     costs a roll but no try); after 100 counted tries the record stays
     *     out of the game; every other record is out (status 0);
     *   - the other sites: hidden -> allies/allies/gold (1d3), else near
     *     (Euclid < 15 from a living side's capital) sage/gold/allies (1d3)
     *     or far sage/gold/allies/sage/gold (1d5);
     *   - allies sites draw an army type by rank (FUN_10038d8c's lists:
     *     hidden 1d4 of the 4 strongest, far 1d3 of the next 3, near 1d2 of
     *     a list holding the weakest twice; resolved at search time because
     *     the army set is not loaded yet), every other non-temple site has a
     *     guardian 1d9.
     * Site record use: +0x0C kind, +0x0E ally rank, +0x10 item record,
     * +0x12 known mask, +0x1A guardian, +0x1C hidden, +0x1D searchable,
     * +0x1E visited bits. */
    {
        short siteCount = sCityCount;
        short siteIdx[140];
        unsigned char used[140];
        short nSites = 0, pick8[GAME_ITEM_COUNT];
        short p, nHidden, nItems, k, s;
        if (siteCount > 139) siteCount = 139;

        for (i = 0; i < siteCount; i++) {
            unsigned char *site = sCityData + i * 0x20;
            short sType = (short)(unsigned char)site[0x17];
            if (sType < 2) continue;
            for (j = 0x0C; j < 0x14; j++) site[j] = 0;
            SITE_KIND(site) = (sType == 2) ? SITE_TEMPLE : SITE_EMPTY;
            SITE_ITEM(site) = 0xFF;
            SITE_GUARDIAN(site) = 0;
            SITE_HARD(site) = 0;
            SITE_KNOWN(site) = 0xFF;
            site[0x1D] = 0;                              /* not searchable */
            site[0x1E] = (sType == 2) ? 0xFF : 0x00;     /* visited bits */
            used[nSites] = (sType == 2) ? 1 : 0;
            siteIdx[nSites++] = i;
        }
        p = (short)(nSites * 2 / 10);

        /* FUN_10038fb8: hidden sites */
        nHidden = (short)(nSites * 3 / 10);
        for (k = 0; k < nHidden; k++) {
            unsigned char *site;
            short guard = 0;
            do {
                site = sCityData + siteIdx[Dice(1, nSites, -1)] * 0x20;
            } while ((site[0x17] == 2 || SITE_HARD(site)) && ++guard < 10000);
            SITE_HARD(site) = 1;
            if (sOptQuests) SITE_KNOWN(site) = 0;
        }

        /* FUN_10039180(p): item records 0-7 Standards, 8-21 unique picks */
        for (s = 0; s < GAME_ITEM_COUNT; s++) {
            unsigned char *ir = gs + 0xD12 + s * 0x1E;
            for (j = 0; j < 0x1E; j++) ir[j] = 0;
            ITEM_STATUS(ir) = ITEM_ST_NONE;
            ITEM_CARRIER(ir) = -1;
            pick8[s] = -1;
        }
        for (s = 0; s < 8; s++) {
            unsigned char *ir = gs + 0xD12 + s * 0x1E;
            for (j = 0; j < 19 && sStandardNames[s][j]; j++) ir[j] = (unsigned char)sStandardNames[s][j];
            ir[0x14] = ITEM_TYPE_FLAT_PLUS;
            ir[0x15] = 0;
        }
        for (s = 8; s < GAME_ITEM_COUNT; s++) {
            unsigned char *ir = gs + 0xD12 + s * 0x1E;
            short c = 0, q, guard = 0;
            Boolean ok = false;
            while (!ok && ++guard < 20000) {
                Boolean sp;
                c = Dice(1, sItemPoolCount, -1);   /* FUN_1005f230(1, local_644, -1) */
                ok = true;
                for (q = 0; q < s; q++) if (pick8[q] == c) ok = false;
                if (!ok) continue;
                sp = IsSpecialItemTV(sItemTable[c].type, sItemTable[c].value);
                ok = (s < p + 8) ? sp : !sp;
            }
            pick8[s] = c;
            for (j = 0; j < 19 && sItemTable[c].name[j]; j++)
                ir[j] = (unsigned char)sItemTable[c].name[j];
            ir[0x14] = (unsigned char)sItemTable[c].type;
            ir[0x15] = (unsigned char)sItemTable[c].value;
        }

        /* item placement */
        k = Dice(2, 3, 1);
        if (k > p) k = p;
        nItems = (short)(nSites / 3 + Dice(1, 5, -3) + 8);
        if (nItems > GAME_ITEM_COUNT) nItems = GAME_ITEM_COUNT;
        for (s = 8; s < nItems && nSites > 0; s++) {
            unsigned char *ir = gs + 0xD12 + s * 0x1E;
            short special = IsSpecialItemTV(ir[0x14], ir[0x15]) ? 1 : 0;
            short tries = 0, si = 0;
            Boolean found = false;
            if (!(s < k + 8 || s >= p + 8)) continue;          /* status 0 */
            {
                short spins = 0;
                do {
                    si = Dice(1, nSites, -1);
                    /* FUN_1003956c: a draw that fails the special<->hidden
                     * test costs the roll and is not counted.  After 100
                     * matching draws the item stays unplaced (status 0) and
                     * its carrier is that site. */
                    if ((SITE_HARD(sCityData + siteIdx[si] * 0x20) ? 1 : 0) == special) {
                        if (!used[si]) { used[si] = 1; found = true; }
                        if (++tries > 100) {
                            ITEM_CARRIER(ir) = siteIdx[si];
                            found = false;
                            break;
                        }
                    }
                    if (++spins > 100000) break;   /* no matching site: do not hang */
                } while (!found);
            }
            if (found) {
                unsigned char *site = sCityData + siteIdx[si] * 0x20;
                ITEM_STATUS(ir) = ITEM_ST_RUIN;
                ITEM_CARRIER(ir) = siteIdx[si];
                *(short *)(ir + 0x1A) = *(short *)(site + 0x00);
                *(short *)(ir + 0x1C) = *(short *)(site + 0x02);
                SITE_KIND(site) = SITE_ITEM_KIND;
                SITE_ITEM(site) = (unsigned char)s;
            }
        }

        /* fixed rewards for the remaining sites */
        for (s = 0; s < nSites; s++) {
            unsigned char *site = sCityData + siteIdx[s] * 0x20;
            if (used[s]) continue;
            if (!SITE_HARD(site)) {
                if (SiteFarFromCapitals(site)) {
                    static const unsigned char kFar[5] =
                        {SITE_SAGE, SITE_GOLD, SITE_ALLIES, SITE_SAGE, SITE_GOLD};
                    SITE_KIND(site) = kFar[Dice(1, 5, -1)];
                } else {
                    static const unsigned char kNear[3] = {SITE_SAGE, SITE_GOLD, SITE_ALLIES};
                    SITE_KIND(site) = kNear[Dice(1, 3, -1)];
                }
            } else {
                static const unsigned char kHard[3] = {SITE_ALLIES, SITE_ALLIES, SITE_GOLD};
                SITE_KIND(site) = kHard[Dice(1, 3, -1)];
            }
            used[s] = 1;
        }

        /* guardians and ally ranks */
        for (s = 0; s < nSites; s++) {
            unsigned char *site = sCityData + siteIdx[s] * 0x20;
            if (site[0x17] == 2) continue;                       /* temple: none */
            if (SITE_KIND(site) == SITE_ALLIES) {
                if (!SITE_HARD(site)) {
                    if (SiteFarFromCapitals(site)) SITE_ALLY_RANK(site) = (unsigned char)(3 + Dice(1, 3, 0));
                    else { (void)Dice(1, 2, -1); SITE_ALLY_RANK(site) = 0xFF; }
                } else
                    SITE_ALLY_RANK(site) = (unsigned char)Dice(1, 4, -1);
            } else
                SITE_GUARDIAN(site) = (unsigned char)Dice(1, 9, 0);
            site[0x1D] = 1;                                   /* searchable */
        }
    }

    /* --- PPC FUN_1003c068: sides 7..0, each side's capital city
     * (FUN_1002be50 at its start coordinates) takes its owner - neutral for
     * a side not in play.  Then, with Quick Start (gs+0x128), the neutral
     * cities are handed out round-robin from the LOWEST living side: each
     * takes the neutral city nearest to where it stands (FUN_1002bf64:
     * FUN_1000a884's truncated Euclid, the first index on ties), then
     * Dice(1,10,-1) < 5 sends it back to its capital, else it stands at the
     * city it took.  Last, FUN_1003b9f8: the slots' sort, stats and jitter
     * (FinalizeCitySlots). --- */
    {
        short fromX[8], fromY[8], p, side = -1, cc = sCityCount;
        if (cc > 139) cc = 139;
        for (p = 7; p >= 0; p--) {
            short ci;
            GetCapitalXY(p, &fromX[p], &fromY[p]);
            ci = PathCityIndexAt(fromX[p], fromY[p]);
            if (ci < 0) continue;
            if (*(short *)(gs + 0x138 + p * 2) == 0) {
                if (*(short *)(sCityData + ci * 0x20 + 0x04) != 0x0F) AssignCityOwner(ci, 0x0F);
            } else {
                if (*(short *)(sCityData + ci * 0x20 + 0x04) != p) AssignCityOwner(ci, p);
                side = p;
            }
        }
        if (side != -1 && sOptQuickStart) {
            short guard = 0;
            for (;;) {
                short best = -1, bestD = 1000, ci;
                for (ci = 0; ci < cc; ci++) {
                    unsigned char *city = sCityData + ci * 0x20;
                    short d;
                    if (city[0x17] >= 2 || *(short *)(city + 0x04) != 0x0F) continue;
                    d = AIDist(fromX[side], fromY[side], *(short *)(city + 0x00), *(short *)(city + 0x02));
                    if (d < bestD) { bestD = d; best = ci; }
                }
                if (best < 0 || ++guard > 200) break;
                AssignCityOwner(best, side);
                if (Dice(1, 10, -1) < 5) {
                    GetCapitalXY(side, &fromX[side], &fromY[side]);
                } else {
                    fromX[side] = *(short *)(sCityData + best * 0x20 + 0x00);
                    fromY[side] = *(short *)(sCityData + best * 0x20 + 0x02);
                }
                do { side = (short)((side + 1) % 8); } while (*(short *)(gs + 0x138 + side * 2) == 0);
            }
        }
    }
    FinalizeCitySlots();   /* FUN_1003b9f8 (sCitySlotStatsPending: sort, base stats, jitter) */

    /* --- FUN_10025f2c -> FUN_1001db60: the computer sides' zones --- */
    AISetupZones();

    /* --- Starting armies and garrisons: PPC FUN_1002cbbc (68k CODE_117
     * FUN_00000be0).  Scenarios carry no army data.  One pass over the
     * cities from the LAST to the first:
     *   neutral city: gs+0x11a (Neutral Cities) 0 -> the standard 0x0B
     *     garrison, no roll; else k = Dice(1,4,ns-2) capped at 3;
     *   owned city: k = 3;
     *   then n = Dice(1,4,0) units with Quick Start (gs+0x128), else 1, each
     *   the city's best slot under weight set {1,6,2,3}[k] (FUN_1001e794,
     *   BestCitySlotTypeW; 3 = 10*str + 5*(10-turns) + move/2, verified 8/8
     *   on an original Erythea turn-1 save); no scoring slot -> the 0x0B
     *   garrison (owner 0x0F) instead.
     * Slot strength, moves and upkeep, plus the gs+0xF0 +2 (cap 9), are
     * applied afterwards by StartingUnitsFromSlots.  The stat-15 +2 is only
     * in the chooser's score (BestCitySlotTypeW / FUN_1001e794). */
    {
        static const short kWeightSet[4] = {1, 6, 2, 3};
        short cc = sCityCount, ci;
        if (cc > 139) cc = 139;
        for (ci = cc - 1; ci >= 0 && *(short *)(gs + 0x1602) < MAX_ARMIES; ci--) {
            unsigned char *city = sCityData + ci * 0x20;
            short o = *(short *)(city + 0x04), k = 3, n, t = -1, a, na;
            Boolean garrison = false, occupied = false;
            if (city[0x17] != 0) continue;
            na = *(short *)(gs + 0x1602);
            for (a = 0; a < na; a++) {      /* (guard: a re-run GameInit) */
                unsigned char *ar = ARMY_REC(a);
                if (*(short *)(ar + 0) == *(short *)(city + 0) && *(short *)(ar + 2) == *(short *)(city + 2)) {
                    occupied = true; break;
                }
            }
            if (occupied) continue;
            if (o >= 0 && o < 8 && *(short *)(gs + 0x138 + o * 2) == 0) {
                AssignCityOwner(ci, 0x0F);   /* FUN_1003c068: a side not in play */
                o = 0x0F;
            }
            if (o < 0 || o >= 8) {
                o = 0x0F;
                if (sNeutralCities == 0) garrison = true;
                else if (sNeutralCities > 0) {
                    k = Dice(1, 4, (short)(sNeutralCities - 2));
                    if (k > 3) k = 3;
                }
            }
            if (!garrison) {
                n = sOptQuickStart ? Dice(1, 4, 0) : 1;
                t = (k >= 0 && k < 4) ? BestCitySlotTypeW(ci, kWeightSet[k]) : -1;
                if (t < 0) garrison = true;
                else SpawnCityUnits(ci, o, t, n, o == 0x0F);
            }
            if (garrison)
                SpawnCityUnits(ci, 0x0F, 0x0B, 1, true);   /* FUN_10021434: standard garrison */
        }
    }

    StartingUnitsFromSlots();   /* FUN_1004a5f0: the slot's strength, moves and upkeep */

    /* --- Stamp army owners into map tiles (68k CODE_117 FUN_0000035c) ---
     * Write army owner into the tile byte 1 low nibble and set army-present bit. */
    if (*gMapTiles != 0) {
        unsigned char *mapData = (unsigned char *)*gMapTiles;
        short armyCount = *(short *)(gs + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;

        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            short ax = *(short *)(army + 0x00);
            short ay = *(short *)(army + 0x02);
            short aOwner = (short)(unsigned char)army[0x15];

            if (army[0x16] == 0xFF) continue;  /* empty slot */
            if (ax < 0 || ay < 0 || ax >= sMapWidth || ay >= sMapHeight) continue;

            {
                unsigned short off = ay * 0xE0 + ax * 2;
                unsigned char ownerNib = (aOwner < 8) ? aOwner : 0x0F;
                mapData[off + 1] = (mapData[off + 1] & 0xE0) | 0x10 | (ownerNib & 0x0F);
                /* bit 4 = army present, bits 0-3 = owner */
            }
        }
    }


    /* --- the fog: every living side sees round its units --- */
    {
        short p;
        for (p = 0; p < 8; p++)
            for (i = 0; i < FOG_BYTES_PER_PLAYER; i++) { sFogExplored[p][i] = 0; sFogVisible[p][i] = 0; }
        for (p = 0; p < 8; p++)
            if (*(short *)(gs + 0x138 + p * 2) != 0) FogUpdatePlayer(p);
    }

    /* --- FUN_1003c368: notoriety, Dice(1,8,0) per side, +400 for a human
     * side under "I am the Greatest" (gs+0x116) --- */
    for (i = 0; i < 8; i++) {
        *(short *)(gs + 0x1122 + i * 2) = Dice(1, 8, 0);
        if (*(short *)(gs + 0x116) != 0 && *(short *)(gs + 0xd0 + i * 2) == 0)
            *(short *)(gs + 0x1122 + i * 2) += 400;
        *(short *)(gs + 0x1132 + i * 2) = (short)0xFFFF;
    }
    (void)j;
    CenterViewportOnPlayer();
    SiteTilesFor(*(short *)(gs + 0x110));   /* FUN_10039ec8 */
}


/* ===================================================================
 * TryLoadScenario — Open a file and load MAP resource directly
 * =================================================================== */
/* CTY 10000 (city names + descriptions) and SPC 10000 (site descriptions)
 * from the scenario file, which must be the current resource file. */
static void LoadCityNames(void)
{
    sCityNameCount = 0;
    /* Load CTY resource (city names + descriptions) and SPC resource (site descriptions) */
    /* Format: #NNN|Line1 of text|Line2|Line3|\r\n
     * Lines are word-wrapped segments joined with a space for the full description.
     * City name is extracted from the first segment before " is " or the first "|". */
    {
        short resPass;
        for (resPass = 0; resPass < 2; resPass++) {
            ResType rType = (resPass == 0) ? 'CTY ' : 'SPC ';
            Handle hdl = Get1Resource(rType, 10000);
            if (hdl == NULL) continue;
            {
                long sz = GetHandleSize(hdl);
                char *buf;
                long p = 0;
                short idx = 0;
                short maxIdx = 99;
                HLock(hdl);
                buf = (char *)*hdl;

                while (p < sz && idx < maxIdx) {
                    long lineStart;
                    short ni;
                    char *name = (resPass == 0) ? sCityNames[idx] : NULL;
                    char *desc = (resPass == 0) ? sCityDescs[idx] : sSiteDescs[idx];
                    short di;

                    /* Find '#' */
                    while (p < sz && buf[p] != '#') p++;
                    if (p >= sz) break;
                    p++;  /* skip '#' */

                    /* Skip NNN */
                    while (p < sz && buf[p] >= '0' && buf[p] <= '9') p++;

                    /* Skip '|' */
                    if (p < sz && buf[p] == '|') p++;

                    lineStart = p;

                    /* --- Extract name (CTY only) from first segment --- */
                    if (name != NULL) {
                        ni = 0;
                        while (p < sz && buf[p] != '|' &&
                               buf[p] != '\r' && buf[p] != '\n') {
                            if (p + 4 < sz &&
                                buf[p] == ' ' && buf[p+1] == 'i' &&
                                buf[p+2] == 's' && buf[p+3] == ' ') {
                                break;
                            }
                            if (p + 2 < sz && buf[p] == ',' && buf[p+1] == ' ') {
                                break;
                            }
                            if (ni < MAX_CITY_NAME - 1)
                                name[ni++] = buf[p];
                            p++;
                        }
                        name[ni] = '\0';
                    }

                    /* --- Extract full description by joining all |-separated segments --- */
                    p = lineStart;
                    di = 0;
                    while (p < sz && buf[p] != '\r' && buf[p] != '\n') {
                        if (buf[p] == '|') {
                            /* keep the '|' line breaks: the city window's Info pane
                             * shows the segments verbatim, one per line */
                            if (resPass == 0) {
                                if (di > 0 && di < MAX_CITY_DESC - 1) desc[di++] = '|';
                            } else if (di > 0 && desc[di - 1] != ' ' && di < MAX_CITY_DESC - 1)
                                desc[di++] = ' ';
                            p++;
                        } else {
                            if (di < MAX_CITY_DESC - 1)
                                desc[di++] = buf[p];
                            p++;
                        }
                    }
                    /* Trim trailing space / separators */
                    while (di > 0 && (desc[di - 1] == ' ' || desc[di - 1] == '|')) di--;
                    desc[di] = '\0';

                    if (resPass == 0) sCityNameCount++;
                    idx++;

                    /* Skip to next line */
                    while (p < sz && buf[p] != '\n') p++;
                }

                HUnlock(hdl);
                ReleaseResource(hdl);
            }
        }
    }

    /* The original names a city by the SCN city record's name (city+0x04
     * in its gs+0x1604 array: "Dark College", "Crater"), never by the CTY
     * description text ("The dark College is ...", "This city was built").
     * Where GameInit kept the SCN names they replace the parsed ones. */
    if (sScnCityNamesValid) {
        short ci, k;
        for (ci = 0; ci < 99; ci++) {
            if (sScnCityNames[ci][0] == 0) continue;
            for (k = 0; k < 16 && sScnCityNames[ci][k]; k++) sCityNames[ci][k] = sScnCityNames[ci][k];
            sCityNames[ci][k] = 0;
            if (ci >= sCityNameCount) sCityNameCount = ci + 1;
        }
    }
}

static void TryLoadScenario(void)
{
    StandardFileReply reply;
    short             refNum;
    Handle            mapHdl;

    /* Let user pick any file */
    StandardGetFile(NULL, -1, NULL, &reply);

    if (!reply.sfGood)
        return;

    /* Open the file's resource fork */
    refNum = FSpOpenResFile(&reply.sfFile, fsRdPerm);
    if (refNum == -1)
        return;

    UseResFile(refNum);

    /* Try to load MAP resource (type 'MAP ', ID 10000) */
    mapHdl = Get1Resource('MAP ', 10000);
    if (mapHdl != NULL) {
        long mapSize = GetHandleSize(mapHdl);

        HLock(mapHdl);

        /* Allocate map buffer if DoPostCreate didn't */
        if (*gMapTiles == 0) {
            *gMapTiles = (int)NewPtr(0x8880);
        }

        if (*gMapTiles != 0) {
            /* Copy MAP data - clamp to buffer size */
            long copySize = mapSize;
            if (copySize > 0x8880) copySize = 0x8880;
            BlockMoveData(*mapHdl, (void *)*gMapTiles, copySize);

            sMapLoaded = true;
            sRandomMap = false;
            /* Standard map: 112 wide x 156 tall */
            sMapWidth  = 112;
            sMapHeight = (short)(copySize / (112 * 2));
            if (sMapHeight > 156) sMapHeight = 156;
        }

        HUnlock(mapHdl);
        ReleaseResource(mapHdl);
    }

    /* Also try to load SCN resource into game state */
    {
        Handle scnHdl = Get1Resource('SCN ', 10000);
        if (scnHdl != NULL) {
            long scnSize = GetHandleSize(scnHdl);
            HLock(scnHdl);

            if (*gGameState == 0) {
                *gGameState = (int)NewPtrClear(0x2FCC);
            } else {
                /* Zero-fill existing buffer to prevent stale data */
                BlockZero((void *)*gGameState, 0x2FCC);
            }
            if (*gGameState != 0) {
                long copySize = scnSize;
                if (copySize > 0x2FCC) copySize = 0x2FCC;
                BlockMoveData(*scnHdl, (void *)*gGameState, copySize);
            }
            HUnlock(scnHdl);
            ReleaseResource(scnHdl);
        }
    }

    /* Load RD (road overlay) resource */
    {
        Handle rdHdl = Get1Resource('RD  ', 10000);
        if (rdHdl != NULL) {
            long rdSize = GetHandleSize(rdHdl);
            HLock(rdHdl);

            if (*gRoadData == 0) {
                *gRoadData = (pint)NewPtrClear(0x4440);
            }
            if (*gRoadData != 0) {
                long copySize = rdSize;
                if (copySize > 0x4440) copySize = 0x4440;
                BlockMoveData(*rdHdl, (void *)*gRoadData, copySize);
            }
            HUnlock(rdHdl);
            ReleaseResource(rdHdl);
        }
    }

    LoadCityNames();

    /* Load SGN resource (scenario-defined map signposts) */
    /* Format: 2-byte LE count, then count*104-byte entries.
     * Each entry: x(2,LE) y(2,LE) text1 at entry+4, text2 at entry+54 (continuation). */
    {
        Handle sgnHdl = Get1Resource('SGN ', 10000);
        sSgnSignpostCount = 0;
        if (sgnHdl != NULL) {
            long sgnSz = GetHandleSize(sgnHdl);
            char *sgnBuf;
            short sgnCount, n;
            HLock(sgnHdl);
            sgnBuf = (char *)*sgnHdl;
            if (sgnSz >= 2) {
                sgnCount = (short)((unsigned char)sgnBuf[0] |
                                   ((unsigned char)sgnBuf[1] << 8));
                for (n = 0; n < sgnCount && sSgnSignpostCount < MAX_SGN_SIGNPOSTS; n++) {
                    long eoff = 2 + (long)n * 104;
                    short ex, ey, di;
                    long t1len = 0, t2len = 0;
                    char last_c;
                    if (eoff + 104 > sgnSz) break;
                    ex = (short)((unsigned char)sgnBuf[eoff] |
                                 ((unsigned char)sgnBuf[eoff+1] << 8));
                    ey = (short)((unsigned char)sgnBuf[eoff+2] |
                                 ((unsigned char)sgnBuf[eoff+3] << 8));
                    /* Text chunk 1 at entry+4 */
                    while (eoff + 4 + t1len < eoff + 54) {
                        unsigned char c = (unsigned char)sgnBuf[eoff + 4 + t1len];
                        if (c == 0 || c < 32 || c >= 127) break;
                        t1len++;
                    }
                    if (t1len == 0) continue;
                    /* Text chunk 2 at entry+54 (if chunk1 not sentence-complete) */
                    while (eoff + 54 + t2len < eoff + 104) {
                        unsigned char c = (unsigned char)sgnBuf[eoff + 54 + t2len];
                        if (c == 0 || c < 32 || c >= 127) break;
                        t2len++;
                    }
                    /* Build combined text */
                    sSgnSignposts[sSgnSignpostCount].x = ex;
                    sSgnSignposts[sSgnSignpostCount].y = ey;
                    di = (short)(t1len > 31 ? 31 : t1len);
                    BlockMoveData(sgnBuf + eoff + 4,
                                  sSgnSignposts[sSgnSignpostCount].text, di);
                    /* Append chunk2 if chunk1 doesn't end with sentence-ending punctuation */
                    last_c = sSgnSignposts[sSgnSignpostCount].text[di - 1];
                    if (t2len > 0 && di < 31 &&
                        last_c != '!' && last_c != '.' && last_c != '?') {
                        sSgnSignposts[sSgnSignpostCount].text[di++] = ' ';
                        if (di < 31) {
                            short copy_len = (short)(t2len > (31 - di) ? (31 - di) : t2len);
                            BlockMoveData(sgnBuf + eoff + 54,
                                          sSgnSignposts[sSgnSignpostCount].text + di,
                                          copy_len);
                            di += copy_len;
                        }
                    }
                    sSgnSignposts[sSgnSignpostCount].text[di] = '\0';
                    sSgnSignposts[sSgnSignpostCount].active = true;
                    sSgnSignpostCount++;
                }
            }
            HUnlock(sgnHdl);
            ReleaseResource(sgnHdl);
        }
    }

    LoadScenarioItemPool();   /* FUN_10039180: the scenario's ITM 10000 */
    CloseResFile(refNum);

    /* Allocate extended state if needed (cities, per-army arrays) */
    if (*gExtState == 0) {
        /* Size: 0x24C header + 40 cities * 0x5C + per-army arrays */
        *gExtState = (int)NewPtrClear(0x4000);
    }

    /* Run game initialization on loaded data */
    if (sMapLoaded && *gGameState != 0) {
        GameInit();
    }

    /* Update main window title with scenario name */
    if (sMapLoaded && *gMainGameWindow != 0) {
        Str255 title;
        unsigned char *src = reply.sfFile.name;
        short len = src[0];
        short i;

        /* Build title: "Warlords II — [scenario name]" */
        title[0] = 0;
        BlockMoveData("\pWarlords II", title, 12);
        if (len > 0 && title[0] + 3 + len <= 255) {
            title[++title[0]] = ' ';
            title[++title[0]] = '-';
            title[++title[0]] = ' ';
            for (i = 1; i <= len; i++)
                title[++title[0]] = src[i];
        }
        (void)title;
        /* a new game is a new MacApp document: "untitled" until it is saved */
        SetWTitle((WindowPtr)*gMainGameWindow, "\puntitled");
        sSaveFileValid = false;
    }

    /* Force redraw of all windows */
    if (sMapLoaded) {
        if (*gMainGameWindow != 0)
            InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        if (*gOverviewWindow != 0)
            InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
    }
}


/* ===================================================================
 * LoadTerrainSprites — Load terrain sprite sheets from Terrain folder
 *
 * Opens the resource fork of "Terrain:Grasslands" and loads PICT
 * resources 30000-30009 into offscreen GWorlds for sprite blitting.
 * =================================================================== */
static GWorldPtr LoadPICTIntoGWorld(short pictID)
{
    PicHandle  pic;
    GWorldPtr  gw = NULL;
    OSErr      err;

    pic = (PicHandle)Get1Resource('PICT', pictID);
    if (pic == NULL)
        return NULL;

    {
        Rect     picRect = (**pic).picFrame;
        short    w = picRect.right - picRect.left;
        short    h = picRect.bottom - picRect.top;
        Rect     bounds;
        CGrafPtr savedPort;
        GDHandle savedDevice;

        SetRect(&bounds, 0, 0, w, h);
        err = NewGWorld(&gw, 0, &bounds, NULL, NULL, 0);
        if (err == noErr && gw != NULL) {
            GetGWorld(&savedPort, &savedDevice);
            SetGWorld(gw, NULL);
            LockPixels(GetGWorldPixMap(gw));
            EraseRect(&bounds);
            DrawPicture(pic, &bounds);
            UnlockPixels(GetGWorldPixMap(gw));
            SetGWorld(savedPort, savedDevice);
        }
    }
    ReleaseResource((Handle)pic);
    return gw;
}


/* ===================================================================
 * DrawMarbleBackground — tile PICT 1001 "MARBLE" into a rect
 *
 * Works in the current GWorld/port.  Falls back to solid gray if
 * the marble GWorld hasn't been loaded yet.
 * =================================================================== */
static void DrawMarbleBackground(Rect *r)
{
    if (sMarbleGW != NULL) {
        PixMapHandle mPix = GetGWorldPixMap(sMarbleGW);
        CGrafPtr curGW;
        GDHandle curGD;
        BitMap *dstBits;
        Rect mBounds;
        short mx, my, mw, mh;

        GetGWorld(&curGW, &curGD);
        dstBits = (BitMap *)*GetGWorldPixMap(curGW);
        LockPixels(mPix);
        mBounds = (**mPix).bounds;
        mw = mBounds.right - mBounds.left;
        mh = mBounds.bottom - mBounds.top;
        if (mw < 1) mw = 1;
        if (mh < 1) mh = 1;
        for (my = r->top; my < r->bottom; my += mh) {
            for (mx = r->left; mx < r->right; mx += mw) {
                Rect srcR, dstR;
                short dw = mw, dh = mh;
                if (mx + dw > r->right) dw = r->right - mx;
                if (my + dh > r->bottom) dh = r->bottom - my;
                SetRect(&srcR, 0, 0, dw, dh);
                SetRect(&dstR, mx, my, mx + dw, my + dh);
                CopyBits((BitMap *)*mPix,
                         dstBits,
                         &srcR, &dstR, srcCopy, NULL);
            }
        }
        UnlockPixels(mPix);
    } else {
        RGBColor gray = {0x5555, 0x5555, 0x5555};
        RGBForeColor(&gray);
        PaintRect(r);
    }
}


static void LoadTerrainSprites(void)
{
    FSSpec terrainSpec;
    OSErr  err;
    short  oldResFile;

    if (sTerrainLoaded)
        return;

    {
        short vRefNum;
        long dirID;
        err = HGetVol(NULL, &vRefNum, &dirID);
        if (err != noErr) return;
        err = FSMakeFSSpec(vRefNum, dirID, "\p:Terrain:Grasslands", &terrainSpec);
    }
    if (err != noErr)
        return;

    oldResFile = CurResFile();
    sTerrainResFile = FSpOpenResFile(&terrainSpec, fsRdPerm);
    if (sTerrainResFile == -1) {
        UseResFile(oldResFile);
        return;
    }
    UseResFile(sTerrainResFile);

    /* Load terrain tile sheets (640x240 each, 16x6 grid of 40x40 tiles) */
    sTerrainGW  = LoadPICTIntoGWorld(30022);  /* tiles 0-95 */
    sTerrainGW2 = LoadPICTIntoGWorld(30023);  /* tiles 96-191 */

    /* Load road sprite sheet at screen depth (same as all other sprite sheets). */
    sRoadGW = LoadPICTIntoGWorld(30021);

    /* Sample background color from road sprite sheet pixel (0,0) for mode 36 rendering.
     * Matches the pattern used by army/city/shield sprites. */
    if (sRoadGW != NULL && !sRoadBgColorValid) {
        CGrafPtr savedPort;
        GDHandle savedDev;
        GetGWorld(&savedPort, &savedDev);
        SetGWorld(sRoadGW, NULL);
        GetCPixel(0, 0, &sRoadBgColor);
        SetGWorld(savedPort, savedDev);
        sRoadBgColorValid = true;
    }

    /* Hero name lists (HERONAM0-7): DAT 30010+player, "#0 name" (male) or
     * "#1 name" (female) per line. */
    {
        short hp;
        for (hp = 0; hp < 8; hp++) {
            Handle h = GetResource('DAT ', 30010 + hp);
            if (sHeroNameDat[hp] != NULL) { DisposeHandle(sHeroNameDat[hp]); sHeroNameDat[hp] = NULL; }
            if (h != NULL) { DetachResource(h); sHeroNameDat[hp] = h; }
        }
    }

    /* Load MAPCOLOR data (DAT 30020) for minimap per-tile colors */
    {
        Handle mapColorH = GetResource('DAT ', 30020);
        if (mapColorH != NULL) {
            Size datLen = GetHandleSize(mapColorH);
            short copyLen = (datLen > MAPCOLOR_SIZE) ? MAPCOLOR_SIZE : (short)datLen;
            HLock(mapColorH);
            BlockMoveData(*mapColorH, sMapColor, copyLen);
            BlockMoveData(*mapColorH, sMapColorFull, datLen > 1200 ? 1200 : datLen);
            sMapColorFullLoaded = (datLen >= 1200);
            sOverviewBaseFor = NULL;                 /* rebuild the overview */
            HUnlock(mapColorH);
            ReleaseResource(mapColorH);
            sMapColorLoaded = true;
        }
    }

    /* Load shield sprite sheets from terrain file while it's the active resource.
     * Terrain file has NO cicn shield icons — only PICT sprite sheets.
     * Must load here (not in LoadShieldIcons) because Get1Resource only
     * searches the current resource file. */
    if (sShieldBigGW == NULL)
        sShieldBigGW = LoadPICTIntoGWorld(30011);
    if (sShieldSmallGW == NULL)
        sShieldSmallGW = LoadPICTIntoGWorld(30024);
    if (sMasterSpriteGW == NULL)
        sMasterSpriteGW = LoadPICTIntoGWorld(30010);

    /* Sample PICT 30024 background for DrawMapShield transparent blit.
     * (310,26) is in a gap region of PICT 30024 between sprite areas. */
    if (sShieldSmallGW != NULL) {
        CGrafPtr sp; GDHandle sd;
        Rect gwBounds;
        GetGWorld(&sp, &sd);
        SetGWorld(sShieldSmallGW, NULL);
        LockPixels(GetGWorldPixMap(sShieldSmallGW));
        gwBounds = (**GetGWorldPixMap(sShieldSmallGW)).bounds;
        if (gwBounds.right > 310 && gwBounds.bottom > 26)
            GetCPixel(310, 26, &sShieldSheetBgColor);
        else
            GetCPixel(0, 0, &sShieldSheetBgColor);
        UnlockPixels(GetGWorldPixMap(sShieldSmallGW));
        SetGWorld(sp, sd);
    }

    /* PICT 30010 background: light grey (239,239,239) surrounding sprite areas */
    sMasterSpriteBgColor.red   = 0xEFEF;
    sMasterSpriteBgColor.green = 0xEFEF;
    sMasterSpriteBgColor.blue  = 0xEFEF;

    UseResFile(oldResFile);
    sTerrainLoaded = (sTerrainGW != NULL);
}


/* ===================================================================
 * ScanArmySets — Find available army sets in the Armies folder
 *
 * Checks for known army set files (from NAME resources 2000-2002)
 * and records which ones exist. Called once at startup.
 * =================================================================== */
static void ScanArmySets(void)
{
    short vRefNum;
    long dirID;
    OSErr err;
    CInfoPBRec cipb;
    Str255 name;
    FSSpec armiesDir;
    short armiesDirID;

    sArmySetCount = 0;

    /* First entry is always "Default" (uses colored army markers) */
    {
        const char *def = "Default";
        short n;
        for (n = 0; def[n]; n++)
            sArmySetNames[0][n] = def[n];
        sArmySetNames[0][n] = 0;
        sArmySetCount = 1;
    }

    /* Find the Armies folder relative to the app's directory */
    err = HGetVol(NULL, &vRefNum, &dirID);
    if (err != noErr) { sSelectedArmySet = 0; return; }

    err = FSMakeFSSpec(vRefNum, dirID, "\p:Armies:", &armiesDir);
    if (err != noErr) { sSelectedArmySet = 0; return; }

    /* Get dirID of the Armies folder */
    BlockZero(&cipb, sizeof(cipb));
    cipb.dirInfo.ioNamePtr = armiesDir.name;
    cipb.dirInfo.ioVRefNum = armiesDir.vRefNum;
    cipb.dirInfo.ioDrDirID = armiesDir.parID;
    err = PBGetCatInfoSync(&cipb);
    if (err != noErr || !(cipb.dirInfo.ioFlAttrib & 0x10)) {
        sSelectedArmySet = 0;
        return;
    }
    armiesDirID = cipb.dirInfo.ioDrDirID;

    /* Iterate files in the Armies folder */
    {
        short idx = 1;
        while (sArmySetCount < MAX_ARMY_SETS) {
            BlockZero(&cipb, sizeof(cipb));
            cipb.hFileInfo.ioNamePtr = name;
            cipb.hFileInfo.ioVRefNum = vRefNum;
            cipb.hFileInfo.ioDirID = armiesDirID;
            cipb.hFileInfo.ioFDirIndex = idx++;
            err = PBGetCatInfoSync(&cipb);
            if (err != noErr) break;
            /* Skip directories and "Icon\r" files */
            if (cipb.hFileInfo.ioFlAttrib & 0x10) continue;
            if (name[1] == 'I' && name[2] == 'c' && name[3] == 'o' && name[4] == 'n') continue;
            /* Add to list */
            {
                short n;
                for (n = 0; n < name[0] && n < 31; n++)
                    sArmySetNames[sArmySetCount][n] = name[n + 1];
                sArmySetNames[sArmySetCount][n] = 0;
                sArmySetCount++;
            }
        }
    }

    sSelectedArmySet = 0;
}

/* ===================================================================
 * LoadArmySprites — Load army sprite sheets from Armies folder
 *
 * Opens the selected army set's resource fork and loads
 * PICT 20000-20009 into offscreen GWorlds.
 * =================================================================== */
/* Starting armies and garrisons are created by GameInit at scenario load,
 * before the army set (chosen in Game Setup) is loaded, so their units got
 * placeholder stats (10 MP). Give every unit its type's movement/strength
 * once the table exists (the original copies them from the city slot,
 * whose stats are the type's with a small random adjustment). */
/* FinalizeCitySlots — GameInit runs from the scenario picker before the army
 * set's unit table is loaded, so its slot sort (68k CODE_072: ascending by
 * stat 2) and the non-port naval filter saw no stats. Redo both once the
 * table is in (Myre: Scouts, Light Inf. - pillage takes Light Inf., 25 gp). */
static void FinalizeCitySlots(void)
{
    unsigned char *ext;
    short ci, cc = sCityCount;
    if (*gExtState == 0 || !sUnitTypesLoaded) return;
    ext = (unsigned char *)*gExtState;
    if (cc > 99) cc = 99;
    for (ci = 0; ci < cc; ci++) {
        unsigned char *city = sCityData + ci * 0x20;
        unsigned char *ec = ext + 0x24c + ci * 0x5c;
        short t[4], n = 0, k, j;
        Boolean port = (*(short *)(ec + 0x5A) & 0x08) != 0;
        if (city[0x17] >= 2) continue;
        for (k = 0; k < 4; k++) {
            short pt = *(short *)(ec + 0x06 + k * 2);
            if (pt < 0 || pt >= MAX_UNIT_TYPES) continue;
            if (!port && sUnitTypeTable[pt * UNIT_TYPE_ENTRY + UTE_STAT_NAVAL] >= 1) continue;
            t[n++] = pt;
        }
        for (k = 1; k < n; k++) {                    /* stable, ascending by |stat 4| (FUN_100496c8) */
            short key = t[k], kc = UnitStatLE(key, 4);
            if (kc < 0) kc = -kc;
            for (j = k - 1; j >= 0 && (UnitStatLE(t[j], 4) < 0 ? -UnitStatLE(t[j], 4) : UnitStatLE(t[j], 4)) > kc; j--) t[j + 1] = t[j];
            t[j + 1] = key;
        }
        {   /* the slot stats travel with their types (FUN_100496c8 moves all
             * five fields) */
            unsigned char keep[4][4];
            short old[4], q;
            for (k = 0; k < 4; k++) {
                old[k] = *(short *)(ec + 0x06 + k * 2);
                keep[k][0] = ec[0x40 + k]; keep[k][1] = ec[0x44 + k];
                keep[k][2] = ec[0x48 + k]; keep[k][3] = ec[0x4C + k];
            }
            for (k = 0; k < 4; k++) {
                *(short *)(ec + 0x06 + k * 2) = (k < n) ? t[k] : -1;
                ec[0x40 + k] = ec[0x44 + k] = ec[0x48 + k] = ec[0x4C + k] = 0;
                if (k >= n) continue;
                for (q = 0; q < 4; q++) if (old[q] == t[k]) break;
                if (q < 4) {
                    ec[0x40 + k] = keep[q][0]; ec[0x44 + k] = keep[q][1];
                    ec[0x48 + k] = keep[q][2]; ec[0x4C + k] = keep[q][3];
                }
            }
        }
    }
    if (sCitySlotStatsPending) {
        sCitySlotStatsPending = false;
        InitCitySlotStatsBase();
        JitterCitySlotStats();
        StartingUnitsFromSlots();
    }
}

/* ===================================================================
 * Per-city production slot stats - the original's city record +0x1A..+0x29
 * (per slot: turns, strength, movement, cost), kept here in the ext city
 * record at +0x40 turns[4], +0x44 strength[4], +0x48 moves[4], +0x4C cost[4]
 * (signed), parallel to the slot types at +0x06.  FUN_1003b9f8 fills them
 * from the army set at new game and jitters them (JitterCitySlotStats);
 * FUN_10049aec (Build Production) writes the plain type stats into the slot
 * it buys; FUN_1000ba58 shows them in the city window; FUN_1004a5f0 gives a
 * produced unit the slot's strength and moves.
 * =================================================================== */
static short CitySlotOf(short ci, short t)
{
    unsigned char *ec;
    short k;
    if (*gExtState == 0 || ci < 0 || ci >= sCityCount || ci >= 139 || t < 0) return -1;
    ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
    for (k = 0; k < 4; k++) if (*(short *)(ec + 0x06 + k * 2) == t) return k;
    return -1;
}

static void SetCitySlotBase(short ci, short k, short t)
{
    unsigned char *ec;
    if (*gExtState == 0 || ci < 0 || ci >= 139 || k < 0 || k > 3) return;
    ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
    if (t < 0 || t >= MAX_UNIT_TYPES || !sUnitTypesLoaded) {
        ec[0x40 + k] = ec[0x44 + k] = ec[0x48 + k] = ec[0x4C + k] = 0;
        return;
    }
    ec[0x44 + k] = (unsigned char)UnitStatLE(t, 0);   /* strength */
    ec[0x40 + k] = (unsigned char)UnitStatLE(t, 1);   /* turns */
    ec[0x4C + k] = (unsigned char)UnitStatLE(t, 2);   /* cost (upkeep) */
    ec[0x48 + k] = (unsigned char)UnitStatLE(t, 3);   /* moves */
}

static void InitCitySlotStatsBase(void)
{
    short ci, k, cc = sCityCount;
    if (*gExtState == 0) return;
    if (cc > 139) cc = 139;
    for (ci = 0; ci < cc; ci++) {
        unsigned char *ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
        for (k = 0; k < 4; k++) SetCitySlotBase(ci, k, *(short *)(ec + 0x06 + k * 2));
    }
}

/* FUN_1003b9f8, the new-game pass over every filled slot (R = 1d100):
 *   R < 10: strength +1 (cap 9) when R < 60, else -1 (floor 1)
 *   R < 20: R' < 10 moves +4, < 60 +2, < 95 -2 (floor 2), else -4 (floor 2)
 *   moves below 6 become 6
 *   R < 10: cost -cost/4 when R < 60, else +cost/4   (signed-char maths)
 *   R < 10: turns -1 (floor 1) when R < 60, else +1 */
#define SLOT_D100() Dice(1, 100, 0)   /* FUN_1003b9f8: FUN_1005f230(1,100,0) */
static void JitterCitySlotStats(void)
{
    short ci, k, cc = sCityCount;
    if (*gExtState == 0 || !sUnitTypesLoaded) return;
    if (cc > 139) cc = 139;
    for (ci = 0; ci < cc; ci++) {
        unsigned char *ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
        if (sCityData[ci * 0x20 + 0x17] >= 2) continue;
        for (k = 0; k < 4; k++) {
            short v;
            if (*(short *)(ec + 0x06 + k * 2) < 0) break;
            if (SLOT_D100() < 10) {
                v = (short)ec[0x44 + k];
                if (SLOT_D100() < 60) { v++; if (v > 9) v = 9; }
                else { v--; if (v < 2) v = 1; }
                ec[0x44 + k] = (unsigned char)v;
            }
            if (SLOT_D100() < 20) {
                short r = SLOT_D100();
                v = (short)ec[0x48 + k];
                if (r < 10) v += 4;
                else if (r < 60) v += 2;
                else if (r < 95) { v -= 2; if (v < 3) v = 2; }
                else { v -= 4; if (v < 3) v = 2; }
                ec[0x48 + k] = (unsigned char)v;
            }
            if ((short)ec[0x48 + k] < 6) ec[0x48 + k] = 6;
            if (SLOT_D100() < 10) {
                signed char c = (signed char)ec[0x4C + k];
                if (SLOT_D100() < 60) c = (signed char)(c - c / 4);
                else c = (signed char)(c + c / 4);
                ec[0x4C + k] = (unsigned char)c;
            }
            if (SLOT_D100() < 10) {
                v = (short)ec[0x40 + k];
                if (SLOT_D100() < 60) { v--; if (v < 2) v = 1; }
                else v++;
                ec[0x40 + k] = (unsigned char)v;
            }
        }
    }
}

/* which: 0 strength, 1 turns, 2 cost, 3 moves - the city's own slot value,
 * else (type not in a slot, slot unfilled) the army set's. */
static short CitySlotStat(short ci, short t, short which)
{
    short k;
    if (sCitySlotStatsPending && sUnitTypesLoaded) FinalizeCitySlots();   /* a game begun before the table was in */
    k = CitySlotOf(ci, t);
    if (k >= 0 && !sCitySlotStatsPending) {
        unsigned char *ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
        if (ec[0x44 + k] != 0 || ec[0x48 + k] != 0) {
            switch (which) {
                case 0: return (short)ec[0x44 + k];
                case 1: return (short)ec[0x40 + k];
                case 2: return (short)(signed char)ec[0x4C + k];
                case 3: return (short)ec[0x48 + k];
            }
        }
    }
    return GetUnitTypeStat(t, which);
}

/* a[0x22+k]: the unit's upkeep, a signed char (the original's unit +0xB).
 * PPC FUN_1004a5f0 sets it to the producing city's slot cost / 2, toward
 * zero; heroes, allies and every other unit get 0. */
#define A_UPKEEP 0x22
static unsigned char SlotUpkeep(short ci, short t)
{
    signed char c = (signed char)CitySlotStat(ci, t, 2);
    return (unsigned char)(signed char)(c / 2);
}

/* The starting units were made by FUN_1004a5f0 from their city (FUN_1002cbbc
 * -> FUN_1002cae8; the capitals' too): the slot's strength (+2, cap 9, with
 * the CURRENT player's tech flag gs+0xf0), the slot's moves and the slot
 * upkeep.  The remake makes them before the slots get their new-game stats,
 * so they take them here, once the slots are final.  (Average neutrals'
 * strength-1 type-0x0B garrison unit is made directly, not by a5f0.) */
static void StartingUnitsFromSlots(void)
{
    unsigned char *gs;
    short n, i, k, cc = sCityCount, ci;
    Boolean tech;
    if (*gGameState == 0 || *gExtState == 0 || !sUnitTypesLoaded) return;
    gs = (unsigned char *)*gGameState;
    tech = *(short *)(gs + 0xf0 + (*(short *)(gs + 0x110) & 7) * 2) != 0;
    n = *(short *)(gs + 0x1602);
    if (n > MAX_ARMIES) n = MAX_ARMIES;
    if (cc > 139) cc = 139;
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        short ax = *(short *)(a + 0), ay = *(short *)(a + 2);
        if (a[0x16] == 0xFF) continue;
        if (a[0x15] == 0x0F && *(short *)(gs + 0x11a) == 0) continue;
        for (ci = 0; ci < cc; ci++) {
            unsigned char *c = sCityData + ci * 0x20;
            short x0 = *(short *)(c + 0), y0 = *(short *)(c + 2);
            if (c[0x17] >= 2) continue;
            if (ax >= x0 && ax <= x0 + 1 && ay >= y0 && ay <= y0 + 1) break;
        }
        if (ci >= cc) continue;
        for (k = 0; k < 4; k++) {
            short t = (short)(unsigned char)a[0x16 + k], str, mv;
            if (t == 0xFF || t == 0x1C || t >= sUnitTypeCount) continue;
            str = CitySlotStat(ci, t, 0);
            if (tech) { str += 2; if (str > 9) str = 9; }
            mv = CitySlotStat(ci, t, 3);
            if (str > 0) a[0x1e + k] = (unsigned char)str;
            if (mv > 0) a[0x1a + k] = (unsigned char)mv;
            a[A_UPKEEP + k] = SlotUpkeep(ci, t);
        }
        RecalcArmyStrength(a);
    }
}

static void RefreshInitialArmyStats(void)
{
    unsigned char *gs;
    short n, i, k;
    if (*gGameState == 0 || !sUnitTypesLoaded) return;
    gs = (unsigned char *)*gGameState;
    n = *(short *)(gs + 0x1602);
    if (n > MAX_ARMIES) n = MAX_ARMIES;
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        short minMv = 255;
        if (a[0x16] == 0xFF) continue;
        for (k = 0; k < 4; k++) {
            short t = a[0x16 + k], mv, str;
            if (t == 0xFF || t >= sUnitTypeCount) continue;
            mv = GetUnitTypeStat(t, 3);
            str = GetUnitTypeStat(t, 0);
            if (mv > 0) a[0x1a + k] = (unsigned char)mv;
            if (str > 0) a[0x1e + k] = (unsigned char)str;
            if (a[0x1a + k] < minMv) minMv = a[0x1a + k];
        }
        a[0x14] = sUnitTypeTable[(unsigned char)a[0x16] * UNIT_TYPE_ENTRY];
        /* a side's starting units begin with 0 current moves (FUN_1002cae8);
         * their turn-1 reset gives the base.  Neutral garrisons keep theirs. */
        if (minMv < 255) a[0x2e] = (a[0x15] < 8) ? 0 : (unsigned char)minMv;
        RecalcArmyStrength(a);
    }
}

static void LoadArmySprites(void)
{
    FSSpec armySpec;
    OSErr  err;
    short  i;
    short  oldResFile;
    short  armyResFile;

    /* Free existing sprite sheets if reloading with a different set */
    if (sArmyLoaded) {
        for (i = 0; i < ARMY_SHEETS; i++) {
            if (sArmyGW[i] != NULL) {
                DisposeGWorld(sArmyGW[i]);
                sArmyGW[i] = NULL;
            }
        }
        sArmyLoaded = false;
    }
    if (sFlagsLoaded) {
        for (i = 0; i < 8; i++) {
            if (sFlagGW[i] != NULL) {
                DisposeGWorld(sFlagGW[i]);
                sFlagGW[i] = NULL;
            }
        }
        sFlagsLoaded = false;
    }

    for (i = 0; i < ARMY_SHEETS; i++)
        sArmyGW[i] = NULL;
    for (i = 0; i < 8; i++)
        sFlagGW[i] = NULL;

    /* "Default" (index 0) means no external army set — load army sprites
     * from the terrain resource file instead (PICTs 30000-30009).
     * Do NOT auto-select Spectremia or other army sets; scenarios use the
     * default terrain sprites with their own built-in unit types. */
    if (sSelectedArmySet == 0) {
        if (sTerrainResFile != -1) {
            short oldRes = CurResFile();
            UseResFile(sTerrainResFile);
            for (i = 0; i < ARMY_SHEETS; i++) {
                PicHandle pic = (PicHandle)Get1Resource('PICT', 30000 + i);
                if (pic == NULL) continue;
                {
                    Rect picRect = (**pic).picFrame;
                    short w = picRect.right - picRect.left;
                    short h = picRect.bottom - picRect.top;
                    Rect bounds;
                    CGrafPtr sp2; GDHandle sd2;
                    SetRect(&bounds, 0, 0, w, h);
                    if (NewGWorld(&sArmyGW[i], 0, &bounds, NULL, NULL, 0) == noErr && sArmyGW[i] != NULL) {
                        GetGWorld(&sp2, &sd2);
                        SetGWorld(sArmyGW[i], NULL);
                        LockPixels(GetGWorldPixMap(sArmyGW[i]));
                        EraseRect(&bounds);
                        DrawPicture(pic, &bounds);
                        GetCPixel(0, 0, &sArmyBgColor[i]);
                        UnlockPixels(GetGWorldPixMap(sArmyGW[i]));
                        SetGWorld(sp2, sd2);
                    }
                }
                ReleaseResource((Handle)pic);
            }
            /* Load unit type definitions from DAT 30000 in terrain file.
             * Same format as DAT 20000 in external army sets: 29 entries × 62 bytes.
             * Byte 0 = sprite index, bytes 2-21 = name, 0x16+ = stats. */
            {
                Handle datH = Get1Resource('DAT ', 30000);
                if (datH != NULL) {
                    long datSize = GetHandleSize(datH);
                    HLock(datH);
                    sUnitTypeCount = (short)(datSize / UNIT_TYPE_ENTRY);
                    if (sUnitTypeCount > MAX_UNIT_TYPES)
                        sUnitTypeCount = MAX_UNIT_TYPES;
                    BlockMoveData(*datH, sUnitTypeTable,
                                  (long)sUnitTypeCount * UNIT_TYPE_ENTRY);
                    IndexUnitTypesBySprite(sUnitTypeTable, sUnitTypeCount);
                    BlockMoveData(sUnitTypeTable, sUnitTypeTableBase,
                                  (long)sUnitTypeCount * UNIT_TYPE_ENTRY);
                    sUnitTypesLoaded = true;
                    HUnlock(datH);
                    ReleaseResource((Handle)datH);
                }
            }
            /* Load faction flag strips from PICT 30030-30037 in terrain file.
             * Each is 320x18 with repeating flag animation frames per faction. */
            {
                short fi;
                for (fi = 0; fi < 8; fi++) {
                    PicHandle fp = (PicHandle)Get1Resource('PICT', FLAG_PICT_BASE + fi);
                    if (fp == NULL) continue;
                    {
                        Rect fBounds;
                        CGrafPtr sp3; GDHandle sd3;
                        short fw = (**fp).picFrame.right - (**fp).picFrame.left;
                        short fh = (**fp).picFrame.bottom - (**fp).picFrame.top;
                        SetRect(&fBounds, 0, 0, fw, fh);
                        if (NewGWorld(&sFlagGW[fi], 0, &fBounds, NULL, NULL, 0) == noErr && sFlagGW[fi] != NULL) {
                            GetGWorld(&sp3, &sd3);
                            SetGWorld(sFlagGW[fi], NULL);
                            LockPixels(GetGWorldPixMap(sFlagGW[fi]));
                            EraseRect(&fBounds);
                            DrawPicture(fp, &fBounds);
                            if (fi == 0)
                                GetCPixel(0, 0, &sFlagBgColor);
                            UnlockPixels(GetGWorldPixMap(sFlagGW[fi]));
                            SetGWorld(sp3, sd3);
                        }
                    }
                    ReleaseResource((Handle)fp);
                }
                sFlagsLoaded = true;
            }
            UseResFile(oldRes);
        }
        sArmyLoaded = true;
        return;
    }

    /* Build path from selected army set name */
    {
        short vRefNum;
        long dirID;
        Str255 armyPath;
        short pLen = 0;
        const char *prefix = ":Armies:";
        const char *name = sArmySetNames[sSelectedArmySet];

        err = HGetVol(NULL, &vRefNum, &dirID);
        if (err != noErr) return;

        while (prefix[pLen]) { armyPath[1 + pLen] = prefix[pLen]; pLen++; }
        while (*name && pLen < 254) { armyPath[1 + pLen] = *name++; pLen++; }
        armyPath[0] = (unsigned char)pLen;
        err = FSMakeFSSpec(vRefNum, dirID, armyPath, &armySpec);
    }
    if (err != noErr)
        return;

    oldResFile = CurResFile();
    armyResFile = FSpOpenResFile(&armySpec, fsRdPerm);
    if (armyResFile == -1) {
        UseResFile(oldResFile);
        return;
    }

    UseResFile(armyResFile);

    for (i = 0; i < ARMY_SHEETS; i++) {
        PicHandle pic = (PicHandle)Get1Resource('PICT', ARMY_PICT_BASE + i);
        if (pic == NULL)
            continue;

        {
            Rect     picRect = (**pic).picFrame;
            short    w = picRect.right - picRect.left;
            short    h = picRect.bottom - picRect.top;
            Rect     bounds;
            CGrafPtr savedPort;
            GDHandle savedDevice;

            SetRect(&bounds, 0, 0, w, h);

            err = NewGWorld(&sArmyGW[i], 0, &bounds, NULL, NULL, 0);
            if (err == noErr && sArmyGW[i] != NULL) {
                GetGWorld(&savedPort, &savedDevice);
                SetGWorld(sArmyGW[i], NULL);
                LockPixels(GetGWorldPixMap(sArmyGW[i]));
                EraseRect(&bounds);
                DrawPicture(pic, &bounds);
                /* Sample pixel (0,0) — the sprite sheet background color.
                 * Store it so we can set destination bg before mode 36 CopyBits. */
                GetCPixel(0, 0, &sArmyBgColor[i]);
                UnlockPixels(GetGWorldPixMap(sArmyGW[i]));
                SetGWorld(savedPort, savedDevice);
            }
        }
        ReleaseResource((Handle)pic);
    }

    /* Load unit type definitions from DAT 20000.
     * 29 entries × 62 bytes, big-endian shorts throughout. */
    {
        Handle datH = Get1Resource('DAT ', 20000);
        if (datH != NULL) {
            long datSize = GetHandleSize(datH);
            HLock(datH);
            sUnitTypeCount = (short)(datSize / UNIT_TYPE_ENTRY);
            if (sUnitTypeCount > MAX_UNIT_TYPES)
                sUnitTypeCount = MAX_UNIT_TYPES;
            BlockMoveData(*datH, sUnitTypeTable,
                          (long)sUnitTypeCount * UNIT_TYPE_ENTRY);
            IndexUnitTypesBySprite(sUnitTypeTable, sUnitTypeCount);
            /* Save original stats for per-game variance restoration */
            BlockMoveData(sUnitTypeTable, sUnitTypeTableBase,
                          (long)sUnitTypeCount * UNIT_TYPE_ENTRY);
            sUnitTypesLoaded = true;
            HUnlock(datH);
            ReleaseResource(datH);
        }
    }

    CloseResFile(armyResFile);

    /* Load faction flag strips from terrain file PICT 30030-30037.
     * Flags are always from terrain, independent of selected army set. */
    if (sTerrainResFile != -1 && !sFlagsLoaded) {
        short fi;
        UseResFile(sTerrainResFile);
        for (fi = 0; fi < 8; fi++) {
            PicHandle fp = (PicHandle)Get1Resource('PICT', FLAG_PICT_BASE + fi);
            if (fp == NULL) continue;
            {
                Rect fBounds;
                CGrafPtr sp3; GDHandle sd3;
                short fw = (**fp).picFrame.right - (**fp).picFrame.left;
                short fh = (**fp).picFrame.bottom - (**fp).picFrame.top;
                SetRect(&fBounds, 0, 0, fw, fh);
                if (NewGWorld(&sFlagGW[fi], 0, &fBounds, NULL, NULL, 0) == noErr && sFlagGW[fi] != NULL) {
                    GetGWorld(&sp3, &sd3);
                    SetGWorld(sFlagGW[fi], NULL);
                    LockPixels(GetGWorldPixMap(sFlagGW[fi]));
                    EraseRect(&fBounds);
                    DrawPicture(fp, &fBounds);
                    if (fi == 0)
                        GetCPixel(0, 0, &sFlagBgColor);
                    UnlockPixels(GetGWorldPixMap(sFlagGW[fi]));
                    SetGWorld(sp3, sd3);
                }
            }
            ReleaseResource((Handle)fp);
        }
        sFlagsLoaded = true;
    }

    UseResFile(oldResFile);
    sArmyLoaded = true;
}


/* ===================================================================
 * LoadCitySprites — Load city sprite sheet from Cities folder
 *
 * Opens "Cities:Spectremia Cities" resource fork and loads
 * PICT 25000 (640x240) into an offscreen GWorld.
 * =================================================================== */
static void LoadCitySprites(void)
{
    FSSpec citySpec;
    OSErr  err;
    short  oldResFile;
    short  cityResFile;

    if (sCityLoaded)
        return;

    {
        short vRefNum;
        long dirID;
        err = HGetVol(NULL, &vRefNum, &dirID);
        if (err != noErr) return;
        err = FSMakeFSSpec(vRefNum, dirID, "\p:Cities:Spectremia Cities", &citySpec);
    }
    if (err != noErr)
        return;

    oldResFile = CurResFile();
    cityResFile = FSpOpenResFile(&citySpec, fsRdPerm);
    if (cityResFile == -1) {
        UseResFile(oldResFile);
        return;
    }
    UseResFile(cityResFile);

    sCityGW = LoadPICTIntoGWorld(CITY_PICT_ID);

    /* Sample city sprite background color for transparent-mode CopyBits.
     * Mode 36 compares against the DESTINATION port's RGBBackColor,
     * so we store the color and set it on the window before blitting. */
    if (sCityGW != NULL) {
        CGrafPtr sp;
        GDHandle sd;
        GetGWorld(&sp, &sd);
        SetGWorld(sCityGW, NULL);
        LockPixels(GetGWorldPixMap(sCityGW));
        GetCPixel(0, 0, &sCityBgColor);
        UnlockPixels(GetGWorldPixMap(sCityGW));
        SetGWorld(sp, sd);
    }

    CloseResFile(cityResFile);
    UseResFile(oldResFile);
    sCityLoaded = (sCityGW != NULL);
}

/* ===================================================================
 * LoadShieldIcons — Load shield cicn/PICT from Elemental Shields file
 *
 * Opens ":Shields:Elemental Shields" resource file at runtime to load
 * cicn 30600-30607 (one per faction, 39x36 pixels each) plus
 * PICT 15009 (big shield sprite sheet, 288x59) and PICT 15010
 * (small shield sprite sheet, 368x64).
 * Falls back to terrain-file cicns (already in sShieldIcons[]).
 * =================================================================== */
static void LoadShieldIcons(void)
{
    short i;

    /* Dispose existing cicn icons (these are per-shield-set) */
    for (i = 0; i < MAX_FACTIONS; i++) {
        if (sShieldIcons[i] != NULL) {
            DisposeCIcon(sShieldIcons[i]);
            sShieldIcons[i] = NULL;
        }
    }

    /* Only dispose sprite sheet GWorlds when switching to external shield set.
     * For default armies, keep the terrain-loaded PICTs 30011/30024. */
    if (sSelectedArmySet > 0) {
        if (sShieldBigGW != NULL) {
            DisposeGWorld(sShieldBigGW);
            sShieldBigGW = NULL;
        }
        if (sShieldSmallGW != NULL) {
            DisposeGWorld(sShieldSmallGW);
            sShieldSmallGW = NULL;
        }
        if (sMasterSpriteGW != NULL) {
            DisposeGWorld(sMasterSpriteGW);
            sMasterSpriteGW = NULL;
        }
    }

    /* If a non-default army set is selected, try matching shield set file.
     * Army set "Spectremia Armies" → Shields "Elemental Shields", etc.
     * Convention: look for any file in :Shields: folder. */
    if (sSelectedArmySet > 0) {
        short vRefNum;
        long dirID;
        OSErr err = HGetVol(NULL, &vRefNum, &dirID);
        if (err == noErr) {
            /* Try to open a shield file from the Shields folder.
             * Scan the folder and open the first non-Icon file found. */
            FSSpec shieldsDir;
            err = FSMakeFSSpec(vRefNum, dirID, "\p:Shields:", &shieldsDir);
            if (err == noErr) {
                CInfoPBRec cipb;
                Str255 name;
                short shieldsDirID;
                BlockZero(&cipb, sizeof(cipb));
                cipb.dirInfo.ioNamePtr = shieldsDir.name;
                cipb.dirInfo.ioVRefNum = shieldsDir.vRefNum;
                cipb.dirInfo.ioDrDirID = shieldsDir.parID;
                err = PBGetCatInfoSync(&cipb);
                if (err == noErr && (cipb.dirInfo.ioFlAttrib & 0x10)) {
                    short oldResFile = CurResFile();
                    short shieldResFile;
                    shieldsDirID = cipb.dirInfo.ioDrDirID;
                    /* Find matching shield file by iterating */
                    {
                        short idx = 1;
                        while (1) {
                            FSSpec shSpec;
                            BlockZero(&cipb, sizeof(cipb));
                            cipb.hFileInfo.ioNamePtr = name;
                            cipb.hFileInfo.ioVRefNum = vRefNum;
                            cipb.hFileInfo.ioDirID = shieldsDirID;
                            cipb.hFileInfo.ioFDirIndex = idx++;
                            err = PBGetCatInfoSync(&cipb);
                            if (err != noErr) break;
                            if (cipb.hFileInfo.ioFlAttrib & 0x10) continue;
                            if (name[1] == 'I' && name[2] == 'c' && name[3] == 'o' && name[4] == 'n') continue;
                            /* Open this shield file */
                            err = FSMakeFSSpec(vRefNum, shieldsDirID, name, &shSpec);
                            if (err != noErr) continue;
                            shieldResFile = FSpOpenResFile(&shSpec, fsRdPerm);
                            if (shieldResFile != -1) {
                                UseResFile(shieldResFile);
                                for (i = 0; i < MAX_FACTIONS; i++) {
                                    CIconHandle sh = GetCIcon(30600 + i);
                                    if (sh != NULL)
                                        sShieldIcons[i] = sh;
                                }
                                if (sShieldBigGW == NULL)
                                    sShieldBigGW = LoadPICTIntoGWorld(15009);
                                /* Don't load PICT 15010 — its layout (46px columns)
                                 * differs from terrain PICT 30024 (26px columns).
                                 * cicn icons are used for drawing instead. */
                                UseResFile(oldResFile);
                                /* Don't close — icons reference the file */
                            }
                            break;  /* use first matching file */
                        }
                    }
                }
            }
        }
    }

    /* Default: load PICT 30011 (big capital banners) and PICT 30024 (dialog+map shields)
     * from the terrain resource file. The terrain file has NO cicn shield icons —
     * default army shields are ONLY in these PICT sprite sheets.
     * External shield sets (Spectremia etc.) use PICT 15009/15010 + cicn 30600-30607. */
    if (sShieldBigGW == NULL && sTerrainResFile != -1) {
        short oldRes = CurResFile();
        UseResFile(sTerrainResFile);
        sShieldBigGW = LoadPICTIntoGWorld(30011);
        if (sShieldSmallGW == NULL)
            sShieldSmallGW = LoadPICTIntoGWorld(30024);
        UseResFile(oldRes);
    }
    /* Final fallback to main app resources */
    if (sShieldBigGW == NULL)
        sShieldBigGW = LoadPICTIntoGWorld(15009);
    if (sShieldSmallGW == NULL)
        sShieldSmallGW = LoadPICTIntoGWorld(15010);

    /* Note: shields are drawn with srcCopy from the sprite sheet.
     * Transparent mode (36) is unreliable in SheepShaver. */

    sShieldsLoaded = true;
}

/* Big shield sprite sheet layout (PICT 15009 "BELEMENT"):
 * 288x59 pixels, 8 columns (one per faction), 2 rows.
 * Row 0 (y=0..28): shields with "CAPITAL" text banner.
 * Row 1 (y=29..58): plain shields without text.
 * Each column is 36px wide (288/8). */
#define BIG_SHIELD_W   36
#define BIG_SHIELD_H   30  /* height of one row */
#define BIG_SHIELD_ROW1 29 /* y-offset of row 1 (plain shields) */

/* ===================================================================
 * DrawBigShield — Draw a faction shield from the big sprite sheet
 *
 * Draws faction factionIdx's plain shield (row 1) from sShieldBigGW
 * into dstRect. Falls back to PlotCIcon of the cicn if no PICT loaded.
 * =================================================================== */
static void DrawBigShield(short factionIdx, const Rect *dstRect)
{
    GrafPtr curPort;

    if (factionIdx < 0 || factionIdx >= MAX_FACTIONS) return;

    GetPort(&curPort);

    if (sShieldBigGW != NULL) {
        PixMapHandle pm = GetGWorldPixMap(sShieldBigGW);
        Rect srcR;
        SetRect(&srcR,
                factionIdx * BIG_SHIELD_W, BIG_SHIELD_ROW1,
                factionIdx * BIG_SHIELD_W + BIG_SHIELD_W,
                BIG_SHIELD_ROW1 + BIG_SHIELD_H);
        if (LockPixels(pm)) {
            CopyBits((BitMap *)*pm,
                     &curPort->portBits,
                     &srcR, dstRect, srcCopy, NULL);
            UnlockPixels(pm);
        }
    } else if (sShieldIcons[factionIdx] != NULL) {
        PlotCIcon(dstRect, sShieldIcons[factionIdx]);
    }
}

/* ===================================================================
 * DrawShieldIcon — Draw a faction shield from either cicn or sprite sheet
 *
 * Uses PlotCIcon if a cicn handle exists (external shield sets like
 * Spectremia have cicn 30600-30607). For default armies (no cicn),
 * blits from PICT 30024 top row (dialog shields) with srcCopy.
 * =================================================================== */
static void DrawShieldIcon(short factionIdx, const Rect *dstRect)
{
    if (factionIdx < 0 || factionIdx >= MAX_FACTIONS) return;

    /* External shield sets provide cicn — use those (handles transparency via mask) */
    if (sShieldIcons[factionIdx] != NULL) {
        PlotCIcon(dstRect, sShieldIcons[factionIdx]);
        return;
    }

    /* Default armies: blit from PICT 30024 top row.
     * Use transparent mode (36) so background pixels are skipped. */
    if (sShieldSmallGW != NULL) {
        GrafPtr curPort;
        PixMapHandle pm = GetGWorldPixMap(sShieldSmallGW);
        Rect srcR;
        RGBColor savedBg;

        GetPort(&curPort);
        SetRect(&srcR,
                factionIdx * SMALL_SHIELD_W, 0,
                factionIdx * SMALL_SHIELD_W + SMALL_SHIELD_W,
                SMALL_SHIELD_H);

        if (LockPixels(pm)) {
            GetBackColor(&savedBg);
            RGBBackColor(&sShieldSheetBgColor);
            CopyBits((BitMap *)*pm,
                     &curPort->portBits,
                     &srcR, dstRect, 36, NULL);
            RGBBackColor(&savedBg);
            UnlockPixels(pm);
        }
    }
}

/* ===================================================================
 * DrawMapShield — Draw a faction shield with swords from sprite sheet
 *
 * Uses PICT 30024 bottom row (map shields with crossed swords) for
 * default armies. Falls back to DrawShieldIcon for external sets.
 * =================================================================== */
static void DrawMapShield(short factionIdx, const Rect *dstRect)
{
    if (factionIdx < 0 || factionIdx >= MAX_FACTIONS) return;

    /* External shield sets: use cicn */
    if (sShieldIcons[factionIdx] != NULL) {
        PlotCIcon(dstRect, sShieldIcons[factionIdx]);
        return;
    }

    /* Default armies: blit from PICT 30024 row 0 (map shields).
     * 68k CODE_067 case 3: srcRect = {0, owner*26, 27, owner*26+26}.
     * Use transparent mode (36) matching 68k's mode 0x10024. */
    if (sShieldSmallGW != NULL) {
        GrafPtr curPort;
        PixMapHandle pm = GetGWorldPixMap(sShieldSmallGW);
        Rect srcR;
        RGBColor savedBg;

        GetPort(&curPort);
        SetRect(&srcR,
                factionIdx * SMALL_SHIELD_W, 0,
                factionIdx * SMALL_SHIELD_W + SMALL_SHIELD_W,
                SMALL_SHIELD_H);

        if (LockPixels(pm)) {
            GetBackColor(&savedBg);
            RGBBackColor(&sShieldSheetBgColor);
            CopyBits((BitMap *)*pm,
                     &curPort->portBits,
                     &srcR, dstRect, 36, NULL);
            RGBBackColor(&savedBg);
            UnlockPixels(pm);
        }
    }
}

/* ===================================================================
 * DrawSmallShieldIcon — Draw a tiny shield for bottom bar / lists
 *
 * 68k CODE_067 case 2: srcRect = {0, owner*13+208, 15, owner*13+221}.
 * Uses the small icon region of PICT 30024 (13x15 at x=208).
 * =================================================================== */
static void DrawSmallShieldIcon(short factionIdx, const Rect *dstRect)
{
    if (factionIdx < 0 || factionIdx >= MAX_FACTIONS) return;

    if (sShieldIcons[factionIdx] != NULL) {
        PlotCIcon(dstRect, sShieldIcons[factionIdx]);
        return;
    }

    /* Default armies: read 11x14 faction shields from PICT 30010 master sprite sheet.
     * Pixel-scan confirmed layout: 2 columns x 4 rows.
     *   Left column  (x=112..122): factions 0-3 top-to-bottom, row stride 14px, y=94
     *   Right column (x=128..138): factions 4-7 top-to-bottom, row stride 14px, y=94
     * Background: light grey (0xEFEF, 0xEFEF, 0xEFEF). */
    if (sMasterSpriteGW != NULL) {
        GrafPtr curPort;
        PixMapHandle pm = GetGWorldPixMap(sMasterSpriteGW);
        Rect srcR;
        RGBColor savedBg;
        short col = factionIdx / 4;   /* 0 for factions 0-3, 1 for factions 4-7 */
        short row = factionIdx % 4;

        GetPort(&curPort);
        SetRect(&srcR,
                112 + col * 16,      94 + row * 14,
                112 + col * 16 + 11, 94 + row * 14 + 14);

        if (LockPixels(pm)) {
            GetBackColor(&savedBg);
            RGBBackColor(&sMasterSpriteBgColor);
            CopyBits((BitMap *)*pm,
                     &curPort->portBits,
                     &srcR, dstRect, 36, NULL);
            RGBBackColor(&savedBg);
            UnlockPixels(pm);
        }
    }
}

