/* Game palette (pltt 1000). Verified on the oracle: every colour on the
 * original's 8-bit screen is a pltt 1000 entry (after the display gamma) while
 * the remake was on the system CLUT, so PICTs, marble and UI greys all came out
 * different. Like the original (SetPalette in its code), windows get the palette
 * through the Palette Manager, which switches the device CLUT *and* has the Finder
 * redraw the desktop/icons in the nearest colours. Offscreen GWorlds created
 * before any window is active use sGameCTab explicitly instead of the device. */
static PaletteHandle sGamePal = NULL;
static WindowPtr     sSplashWin = NULL;     /* start-up splash; closed before the scenario picker */
static unsigned long sSplashStart = 0;
static CTabHandle    sGameCTab = NULL;

static void InstallGamePalette(void)
{
    if (sGamePal != NULL) return;
    sGamePal = GetNewPalette(1000);
    if (sGamePal == NULL) return;
    sGameCTab = (CTabHandle)NewHandle(sizeof(ColorTable));
    if (sGameCTab != NULL) Palette2CTab(sGamePal, sGameCTab);
}

static void ApplyGamePalette(WindowPtr w)
{
    if (sGamePal == NULL || w == NULL) return;
    SetPalette(w, sGamePal, true);
    ActivatePalette(w);
}

/* ===================================================================
 * RemapShieldColors — Remap cicn CLUTs to nearest game palette entries
 *
 * At screen depths > 8-bit, PlotCIcon uses raw cicn CLUT colors directly.
 * At 8-bit, it maps them to the nearest device CLUT entry (from pltt 1000).
 * To get the authentic 256-color look at any depth, we modify each shield
 * icon's embedded CLUT entries to be the nearest pltt 1000 palette color.
 * =================================================================== */
static void RemapShieldColors(void)
{
    PaletteHandle gamePal;
    short         numPalColors, i, j, k;
    RGBColor      palColors[256];

    gamePal = GetNewPalette(1000);
    if (gamePal == NULL) return;

    numPalColors = (**gamePal).pmEntries;
    if (numPalColors <= 0) return;
    if (numPalColors > 256) numPalColors = 256;

    /* Cache palette colors */
    for (i = 0; i < numPalColors; i++)
        GetEntryColor(gamePal, i, &palColors[i]);

    /* Remap each shield icon's CLUT to nearest palette colors */
    for (i = 0; i < MAX_FACTIONS; i++) {
        CTabHandle ctab;
        short      numEntries;

        if (sShieldIcons[i] == NULL) continue;

        ctab = (**sShieldIcons[i]).iconPMap.pmTable;
        if (ctab == NULL) continue;

        numEntries = (**ctab).ctSize + 1;

        for (j = 0; j < numEntries; j++) {
            RGBColor orig = (**ctab).ctTable[j].rgb;
            long     bestDist = 0x7FFFFFFF;
            short    bestIdx = 0;

            /* Find nearest palette color (Euclidean distance in RGB) */
            for (k = 0; k < numPalColors; k++) {
                long dr = ((long)(orig.red   >> 8) - (long)(palColors[k].red   >> 8));
                long dg = ((long)(orig.green >> 8) - (long)(palColors[k].green >> 8));
                long db = ((long)(orig.blue  >> 8) - (long)(palColors[k].blue  >> 8));
                long dist = dr*dr + dg*dg + db*db;
                if (dist < bestDist) {
                    bestDist = dist;
                    bestIdx = k;
                }
            }

            /* Replace CLUT entry with nearest palette color */
            (**ctab).ctTable[j].rgb = palColors[bestIdx];
        }

        /* Bump ctSeed so QuickDraw knows the table changed */
        (**ctab).ctSeed = GetCTSeed();
    }
}


/* ===================================================================
 * LoadButtonIcons — Load info panel button cicn resources
 *
 * Loads control panel icons: cicn 1000-1005 (commands), cicn 1011-1019
 * (scroll arrows), cicn 1020 (diplomacy), cicn 2000-2025 (shortcuts).
 * =================================================================== */
static void LoadButtonIcons(void)
{
    short i;

    if (sCtrlIconsLoaded)
        return;

    /* Command buttons: cicn 1000-1005 */
    for (i = 0; i < NUM_CMD_ICONS; i++)
        sCmdIcons[i] = GetCIcon(1000 + i);

    /* Scroll arrows: cicn 1011-1019 (3x3 directional pad) */
    for (i = 0; i < NUM_SCROLL_ICONS; i++)
        sScrollIcons[i] = GetCIcon(1011 + i);

    /* Diplomacy icon */
    sDiplomIcon = GetCIcon(1020);
    sSwordsIcon = GetCIcon(1007);

    /* Shortcut icons (26 total, only 4 displayed at a time) */
    for (i = 0; i < NUM_SHORTCUT_ICONS; i++)
        sShortcutIcons[i] = GetCIcon(2000 + i);

    sCtrlIconsLoaded = true;
}

static void LoadDialogIcons(void)
{
    short i;

    if (sDialogIconsLoaded) return;

    /* City dialog tab icons: cicn 3300-3303 */
    for (i = 0; i < 4; i++)
        sCityTabIcons[i] = GetCIcon(3300 + i);

    /* Stack info unit type icons: cicn 3500-3507 */
    for (i = 0; i < 8; i++)
        sStackTypeIcons[i] = GetCIcon(3500 + i);

    /* Diplomacy state icons: cicn 4300-4302 (war/peace/allied) */
    for (i = 0; i < 3; i++)
        sDiploStateIcons[i] = GetCIcon(4300 + i);

    /* Ruin status icons: cicn 3700 (unsearched), 3701 (searched) */
    for (i = 0; i < 2; i++)
        sRuinIcons[i] = GetCIcon(3700 + i);

    sDialogIconsLoaded = true;
}


/* ===================================================================
 * ScanForScenarios — Find scenario files in the app's directory
 *
 * Scans for files that have a resource fork containing SCN resources.
 * Populates sScenarioNames[] and sScenarioSpecs[].
 * =================================================================== */
static void ScanForScenarios(void)
{
    CInfoPBRec  cpb;
    Str255      name;
    short       vRefNum;
    long        dirID;
    short       idx;
    OSErr       err;

    sScenarioCount = 0;

    /* Get the app's default directory */
    err = HGetVol(NULL, &vRefNum, &dirID);
    if (err != noErr)
        return;

    /* Iterate files in the directory */
    for (idx = 1; sScenarioCount < MAX_SCENARIOS; idx++) {
        cpb.hFileInfo.ioNamePtr = name;
        cpb.hFileInfo.ioVRefNum = vRefNum;
        cpb.hFileInfo.ioDirID = dirID;
        cpb.hFileInfo.ioFDirIndex = idx;

        err = PBGetCatInfoSync(&cpb);
        if (err != noErr)
            break;

        /* Skip directories */
        if (cpb.hFileInfo.ioFlAttrib & 0x10)
            continue;

        /* Skip the app itself and known non-scenario files */
        if (name[0] > 0 && name[1] == '.') continue; /* hidden files */

        /* Check if file has a resource fork with SCN resource */
        {
            FSSpec fileSpec;
            short  refNum;

            err = FSMakeFSSpec(vRefNum, dirID, name, &fileSpec);
            if (err != noErr) continue;

            refNum = FSpOpenResFile(&fileSpec, fsRdPerm);
            if (refNum == -1) continue;

            UseResFile(refNum);
            {
                Handle scnHdl = Get1Resource('SCN ', 10000);
                if (scnHdl != NULL) {
                    /* Also check for MAP resource to distinguish scenarios from other files */
                    Handle mapHdl = Get1Resource('MAP ', 10000);
                    if (mapHdl != NULL) {
                        /* This is a valid scenario/save file */
                        BlockMoveData(name, sScenarioNames[sScenarioCount], name[0] + 1);
                        sScenarioSpecs[sScenarioCount] = fileSpec;
                        sScenarioCount++;
                        ReleaseResource(mapHdl);
                    }
                    ReleaseResource(scnHdl);
                }
            }
            CloseResFile(refNum);
        }
    }

    /* The original lists scenarios alphabetically regardless of directory
     * order (which differs on non-HFS volumes such as The Outside World). */
    {
        short x, y;
        for (x = 1; x < sScenarioCount; x++) {
            for (y = x; y > 0 && RelString(sScenarioNames[y - 1], sScenarioNames[y], false, true) > 0; y--) {
                Str255 tn; FSSpec ts;
                BlockMoveData(sScenarioNames[y], tn, sizeof(Str255));
                BlockMoveData(sScenarioNames[y - 1], sScenarioNames[y], sizeof(Str255));
                BlockMoveData(tn, sScenarioNames[y - 1], sizeof(Str255));
                ts = sScenarioSpecs[y]; sScenarioSpecs[y] = sScenarioSpecs[y - 1]; sScenarioSpecs[y - 1] = ts;
            }
        }
    }
}


/* ===================================================================
 * GenerateRandomMap — Procedurally generate a playable random map
 *
 * Loads a template SCN from the first available scenario (for terrain
 * properties and unit definitions), then generates terrain, places
 * cities, and initializes the game state.
 *
 * Algorithm:
 *   1. Fill with ocean
 *   2. Place seed points and grow landmasses outward
 *   3. Add terrain variety (forest, mountain, hills, swamp)
 *   4. Add shore transition tiles
 *   5. Place 8 faction starting cities + neutral cities
 *   6. Initialize game state and call GameInit()
 * =================================================================== */

/* Terrain type codes for working buffer */
#define TT_WATER  0
#define TT_GRASS  1
#define TT_FOREST 2
#define TT_MTN    3
#define TT_HILL   4
#define TT_SWAMP  5

/* Tile indices for Grasslands terrain set (from MAPCOLOR analysis) */
#define RTILE_WATER  20   /* deep ocean (color 6) */
#define RTILE_SHORE  16   /* shore (color 5) */
#define RTILE_GRASS   0   /* grassland (color 10) */
#define RTILE_FOREST 65   /* forest (color 11) */
#define RTILE_MTN    80   /* mountain (color 3) */
#define RTILE_HILL  132   /* hills (color 13) */
#define RTILE_SWAMP  13   /* swamp (color 16) */

static Boolean GenerateRandomMap(WindowPtr scenWin,
                                  short barLeft, short barRight,
                                  short barTop, short barH)
{
    unsigned char *gs, *map;
    unsigned char *terrain;  /* working buffer: terrain types per tile */
    short x, y, i, pass;
    short numSeeds;
    short cityCount = 0;

    if (*gGameState == 0 || *gMapTiles == 0) return false;
    gs  = (unsigned char *)*gGameState;
    map = (unsigned char *)*gMapTiles;

    /* Allocate working terrain type buffer (112*156 = 17,472 bytes) */
    terrain = (unsigned char *)NewPtrClear(112 * 156);
    if (terrain == NULL) return false;

    /* --- Phase 1: Load template SCN for terrain properties --- */
    if (sScenarioCount > 0) {
        short refNum = FSpOpenResFile(&sScenarioSpecs[0], fsRdPerm);
        if (refNum != -1) {
            Handle scnHdl;
            UseResFile(refNum);
            scnHdl = Get1Resource('SCN ', 10000);
            if (scnHdl != NULL) {
                long scnSize = GetHandleSize(scnHdl);
                HLock(scnHdl);
                if (scnSize > 0x2FCC) scnSize = 0x2FCC;
                BlockMoveData(*scnHdl, gs, scnSize);
                HUnlock(scnHdl);
                ReleaseResource(scnHdl);
            }
            CloseResFile(refNum);
        }
    }

    /* Progress: 20% */
    {
        Rect fillR;
        RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
        short fillW = (barRight - barLeft - 2) * 20 / 100;
        SetPort(scenWin);
        SetRect(&fillR, barLeft + 1, barTop + 1,
                barLeft + 1 + fillW, barTop + barH - 1);
        RGBForeColor(&barFg);
        PaintRect(&fillR);
    }

    /* --- Phase 2: Generate terrain --- */

    /* Place 4-6 landmass seeds */
    numSeeds = 4 + Dice(1, 3, -1);
    for (i = 0; i < numSeeds; i++) {
        short sx = 15 + Dice(1, 82, -1);
        short sy = 15 + Dice(1, 126, -1);
        short dx, dy;
        /* Create initial 7x7 land patch */
        for (dy = -3; dy <= 3; dy++) {
            for (dx = -3; dx <= 3; dx++) {
                short nx = sx + dx, ny = sy + dy;
                if (nx >= 1 && nx < 111 && ny >= 1 && ny < 155)
                    terrain[ny * 112 + nx] = TT_GRASS;
            }
        }
    }

    /* Grow land from seeds: 8 expansion passes with decreasing probability */
    for (pass = 0; pass < 8; pass++) {
        for (y = 1; y < 155; y++) {
            for (x = 1; x < 111; x++) {
                if (terrain[y * 112 + x] == TT_GRASS) {
                    short prob = 45 - pass * 3;  /* 45% → 24% */
                    /* Try to expand in each cardinal direction */
                    if (terrain[(y-1)*112+x] == TT_WATER &&
                        Dice(1, 100, -1) < prob)
                        terrain[(y-1)*112+x] = TT_GRASS;
                    if (terrain[(y+1)*112+x] == TT_WATER &&
                        Dice(1, 100, -1) < prob)
                        terrain[(y+1)*112+x] = TT_GRASS;
                    if (terrain[y*112+x-1] == TT_WATER &&
                        Dice(1, 100, -1) < prob)
                        terrain[y*112+x-1] = TT_GRASS;
                    if (terrain[y*112+x+1] == TT_WATER &&
                        Dice(1, 100, -1) < prob)
                        terrain[y*112+x+1] = TT_GRASS;
                }
            }
        }
    }

    /* Progress: 40% */
    {
        Rect fillR;
        RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
        short fillW = (barRight - barLeft - 2) * 40 / 100;
        SetPort(scenWin);
        SetRect(&fillR, barLeft + 1, barTop + 1,
                barLeft + 1 + fillW, barTop + barH - 1);
        RGBForeColor(&barFg);
        PaintRect(&fillR);
    }

    /* Add terrain variety using clustered features */

    /* Mountain chains: 3-5 chains of 8-20 tiles each */
    {
        short numChains = 3 + Dice(1, 3, -1);
        short ch;
        for (ch = 0; ch < numChains; ch++) {
            short cx, cy, len, step;
            short dx, dy;
            /* Pick random starting point on land */
            cx = 10 + Dice(1, 92, -1);
            cy = 10 + Dice(1, 136, -1);
            len = 8 + Dice(1, 13, -1);
            /* Pick direction */
            dx = Dice(1, 3, -1) - 1;  /* -1, 0, 1 */
            dy = Dice(1, 3, -1) - 1;
            if (dx == 0 && dy == 0) dx = 1;

            for (step = 0; step < len; step++) {
                if (cx >= 1 && cx < 111 && cy >= 1 && cy < 155 &&
                    terrain[cy * 112 + cx] == TT_GRASS) {
                    terrain[cy * 112 + cx] = TT_MTN;
                    /* Add hills on sides of mountain chain */
                    if (cx > 1 && terrain[cy * 112 + cx - 1] == TT_GRASS &&
                        Dice(1, 100, -1) < 50)
                        terrain[cy * 112 + cx - 1] = TT_HILL;
                    if (cx < 110 && terrain[cy * 112 + cx + 1] == TT_GRASS &&
                        Dice(1, 100, -1) < 50)
                        terrain[cy * 112 + cx + 1] = TT_HILL;
                    if (cy > 1 && terrain[(cy-1) * 112 + cx] == TT_GRASS &&
                        Dice(1, 100, -1) < 40)
                        terrain[(cy-1) * 112 + cx] = TT_HILL;
                    if (cy < 154 && terrain[(cy+1) * 112 + cx] == TT_GRASS &&
                        Dice(1, 100, -1) < 40)
                        terrain[(cy+1) * 112 + cx] = TT_HILL;
                }
                cx += dx;
                cy += dy;
                /* Meander: 25% chance to shift direction */
                if (Dice(1, 4, -1) == 0) {
                    dx += Dice(1, 3, -1) - 1;
                    dy += Dice(1, 3, -1) - 1;
                    if (dx < -1) dx = -1;
                    if (dx > 1) dx = 1;
                    if (dy < -1) dy = -1;
                    if (dy > 1) dy = 1;
                    if (dx == 0 && dy == 0) dx = 1;
                }
            }
        }
    }

    /* Forest clusters: 8-12 forest seed points, each grows into a cluster */
    {
        short numForests = 8 + Dice(1, 5, -1);
        short fi;
        for (fi = 0; fi < numForests; fi++) {
            short fx = 5 + Dice(1, 102, -1);
            short fy = 5 + Dice(1, 146, -1);
            short radius = 3 + Dice(1, 5, -1);
            short fdx, fdy;

            for (fdy = -radius; fdy <= radius; fdy++) {
                for (fdx = -radius; fdx <= radius; fdx++) {
                    short nx = fx + fdx, ny = fy + fdy;
                    if (nx >= 0 && nx < 112 && ny >= 0 && ny < 156 &&
                        terrain[ny * 112 + nx] == TT_GRASS) {
                        /* Higher probability near center */
                        short dist = (fdx < 0 ? -fdx : fdx) + (fdy < 0 ? -fdy : fdy);
                        short prob = 80 - dist * 12;
                        if (prob > 0 && Dice(1, 100, -1) < prob)
                            terrain[ny * 112 + nx] = TT_FOREST;
                    }
                }
            }
        }
    }

    /* Swamp patches: 2-4 swamp areas near water */
    {
        short numSwamps = 2 + Dice(1, 3, -1);
        short si;
        for (si = 0; si < numSwamps; si++) {
            /* Find a land tile near water */
            short attempts = 0;
            while (attempts < 200) {
                short sx = 5 + Dice(1, 102, -1);
                short sy = 5 + Dice(1, 146, -1);
                if (terrain[sy * 112 + sx] == TT_GRASS &&
                    ((sx > 0 && terrain[sy*112+sx-1] == TT_WATER) ||
                     (sx < 111 && terrain[sy*112+sx+1] == TT_WATER) ||
                     (sy > 0 && terrain[(sy-1)*112+sx] == TT_WATER) ||
                     (sy < 155 && terrain[(sy+1)*112+sx] == TT_WATER))) {
                    /* Place 3x3 to 5x5 swamp patch */
                    short r = 1 + Dice(1, 2, -1);
                    short sdx, sdy;
                    for (sdy = -r; sdy <= r; sdy++) {
                        for (sdx = -r; sdx <= r; sdx++) {
                            short nx = sx + sdx, ny = sy + sdy;
                            if (nx >= 0 && nx < 112 && ny >= 0 && ny < 156 &&
                                terrain[ny * 112 + nx] == TT_GRASS &&
                                Dice(1, 100, -1) < 70)
                                terrain[ny * 112 + nx] = TT_SWAMP;
                        }
                    }
                    break;
                }
                attempts++;
            }
        }
    }

    /* Convert terrain types to tile indices and write to map buffer */
    {
        static const short typeToTile[] = {
            RTILE_WATER, RTILE_GRASS, RTILE_FOREST,
            RTILE_MTN, RTILE_HILL, RTILE_SWAMP
        };
        for (y = 0; y < 156; y++) {
            for (x = 0; x < 112; x++) {
                unsigned char *tile = map + y * 0xE0 + x * 2;
                short tt = terrain[y * 112 + x];

                if (tt == TT_WATER) {
                    /* Shore: water tile adjacent to any land */
                    Boolean nearLand = false;
                    if (x > 0 && terrain[y*112+x-1] != TT_WATER) nearLand = true;
                    if (x < 111 && terrain[y*112+x+1] != TT_WATER) nearLand = true;
                    if (y > 0 && terrain[(y-1)*112+x] != TT_WATER) nearLand = true;
                    if (y < 155 && terrain[(y+1)*112+x] != TT_WATER) nearLand = true;
                    tile[0] = nearLand ? RTILE_SHORE : RTILE_WATER;
                } else {
                    /* Add slight variety with adjacent tile indices */
                    short base = typeToTile[tt];
                    short var = Dice(1, 3, -1);
                    tile[0] = base + var;
                }
                tile[1] = 0;
            }
        }
    }

    /* Progress: 60% */
    {
        Rect fillR;
        RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
        short fillW = (barRight - barLeft - 2) * 60 / 100;
        SetPort(scenWin);
        SetRect(&fillR, barLeft + 1, barTop + 1,
                barLeft + 1 + fillW, barTop + barH - 1);
        RGBForeColor(&barFg);
        PaintRect(&fillR);
    }

    /* --- Phase 3: Place cities --- */
    {
        short factionCount = 8;
        /* 68k CODE_020: neutral count from config, typical 10-15 */
        short neutralCount = 10 + Dice(1, 6, -1);
        short totalCities;

        totalCities = factionCount + neutralCount;
        if (totalCities > 139) totalCities = 139;

        /* Place faction starting cities in quadrants */
        for (i = 0; i < factionCount && cityCount < 40; i++) {
            short attempts = 0;
            while (attempts < 2000) {
                /* Quadrant layout: 4 columns x 2 rows */
                short qx = (i % 4) * 28 + 5;
                short qy = (i / 4) * 78 + 5;
                short cx = qx + Dice(1, 22, -1);
                short cy = qy + Dice(1, 68, -1);

                if (cx >= 2 && cx < 110 && cy >= 2 && cy < 154 &&
                    terrain[cy * 112 + cx] != TT_WATER &&
                    terrain[cy * 112 + cx] != TT_MTN) {
                    unsigned char *city = sCityData +cityCount * 0x20;
                    *(short *)(city + 0x00) = cx;
                    *(short *)(city + 0x02) = cy;
                    *(short *)(city + 0x04) = i;
                    *(short *)(city + 0x06) = 3;   /* defense */
                    *(short *)(city + 0x08) = 4;   /* income */
                    *(short *)(city + 0x0A) = cityCount;
                    city[0x17] = 0;   /* site_type = city */
                    /* Ensure grass under city */
                    terrain[cy * 112 + cx] = TT_GRASS;
                    {
                        unsigned char *t = map + cy * 0xE0 + cx * 2;
                        t[0] = RTILE_GRASS;
                    }
                    cityCount++;
                    break;
                }
                attempts++;
            }
        }

        /* Place neutral cities */
        for (i = 0; i < neutralCount && cityCount < 40; i++) {
            short attempts = 0;
            while (attempts < 500) {
                short cx = 3 + Dice(1, 106, -1);
                short cy = 3 + Dice(1, 150, -1);
                short j;
                Boolean tooClose = false;

                if (terrain[cy * 112 + cx] == TT_WATER ||
                    terrain[cy * 112 + cx] == TT_MTN) {
                    attempts++;
                    continue;
                }

                /* Check minimum distance from existing cities */
                for (j = 0; j < cityCount; j++) {
                    short ox = *(short *)(sCityData +j * 0x20);
                    short oy = *(short *)(sCityData +j * 0x20 + 0x02);
                    short dx = cx - ox, dy = cy - oy;
                    if (dx < 0) dx = -dx;
                    if (dy < 0) dy = -dy;
                    if (dx < 5 && dy < 5) { tooClose = true; break; }
                }

                if (!tooClose) {
                    unsigned char *city = sCityData +cityCount * 0x20;
                    *(short *)(city + 0x00) = cx;
                    *(short *)(city + 0x02) = cy;
                    *(short *)(city + 0x04) = (short)0xFF;  /* neutral */
                    *(short *)(city + 0x06) = 2;   /* defense */
                    *(short *)(city + 0x08) = 3;   /* income */
                    *(short *)(city + 0x0A) = cityCount;
                    city[0x17] = 0;   /* site_type = city */
                    cityCount++;
                    break;
                }
                attempts++;
            }
        }

        /* Place ruins on land (site_type at offset 0x17, active at 0x1D) */
        {
            /* 68k CODE_020: fill remaining slots with ruins (up to 40 total sites) */
            short ruinCount = 40 - cityCount;
            short ri;
            for (ri = 0; ri < ruinCount && cityCount < 40; ri++) {
                short attempts = 0;
                while (attempts < 300) {
                    short rx = 5 + Dice(1, 102, -1);
                    short ry = 5 + Dice(1, 146, -1);
                    short j;
                    Boolean tooClose = false;

                    if (terrain[ry * 112 + rx] == TT_WATER ||
                        terrain[ry * 112 + rx] == TT_MTN) {
                        attempts++;
                        continue;
                    }

                    /* Check minimum distance from all existing sites */
                    for (j = 0; j < cityCount; j++) {
                        short ox = *(short *)(sCityData +j * 0x20);
                        short oy = *(short *)(sCityData +j * 0x20 + 0x02);
                        short dx = rx - ox, dy = ry - oy;
                        if (dx < 0) dx = -dx;
                        if (dy < 0) dy = -dy;
                        if (dx < 3 && dy < 3) { tooClose = true; break; }
                    }

                    if (!tooClose) {
                        unsigned char *ruin = sCityData +cityCount * 0x20;
                        /* 68k CODE_020: site types 2-5 (item, defended, gold, ally) */
                        static const unsigned char siteTypes[] = {2, 3, 4, 5};
                        *(short *)(ruin + 0x00) = rx;
                        *(short *)(ruin + 0x02) = ry;
                        *(short *)(ruin + 0x04) = (short)0xFF;  /* no owner */
                        ruin[0x17] = siteTypes[Dice(1, 4, -1)];
                        ruin[0x1C] = (unsigned char)Dice(1, 2, -1);  /* richness */
                        ruin[0x1D] = 1;  /* active/searchable */
                        cityCount++;
                        break;
                    }
                    attempts++;
                }
            }
        }

        sCityCount = cityCount;
    }

    /* Progress: 80% */
    {
        Rect fillR;
        RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
        short fillW = (barRight - barLeft - 2) * 80 / 100;
        SetPort(scenWin);
        SetRect(&fillR, barLeft + 1, barTop + 1,
                barLeft + 1 + fillW, barTop + barH - 1);
        RGBForeColor(&barFg);
        PaintRect(&fillR);
    }

    /* --- Phase 3b: Generate road network between cities --- */
    {
        short siteCount = sCityCount;
        unsigned char *roadBuf;

        /* Allocate road data buffer (clear if reusing from previous game) */
        if (*gRoadData == 0)
            *gRoadData = (pint)NewPtrClear(0x4440);
        else {
            short z;
            unsigned char *rd = (unsigned char *)*gRoadData;
            for (z = 0; z < 0x4440; z++) rd[z] = 0;
        }

        roadBuf = (*gRoadData != 0) ? (unsigned char *)*gRoadData : NULL;

        if (roadBuf != NULL && siteCount > 1) {
            short ci, cj;

            /* Connect each city to its 2 nearest neighbors via road */
            for (ci = 0; ci < siteCount; ci++) {
                unsigned char *siteA = sCityData +ci * 0x20;
                short ax = *(short *)(siteA + 0x00);
                short ay = *(short *)(siteA + 0x02);
                short bestDist[2] = {30000, 30000};
                short bestIdx[2]  = {-1, -1};

                /* Only connect cities (site_type=0), not ruins */
                if (siteA[0x17] != 0) continue;

                /* Find 2 nearest other cities */
                for (cj = 0; cj < siteCount; cj++) {
                    unsigned char *siteB = sCityData +cj * 0x20;
                    short dx, dy, dist;
                    if (cj == ci || siteB[0x17] != 0) continue;
                    dx = *(short *)(siteB + 0x00) - ax;
                    dy = *(short *)(siteB + 0x02) - ay;
                    if (dx < 0) dx = -dx;
                    if (dy < 0) dy = -dy;
                    dist = dx + dy;  /* Manhattan distance */
                    if (dist < bestDist[0]) {
                        bestDist[1] = bestDist[0]; bestIdx[1] = bestIdx[0];
                        bestDist[0] = dist; bestIdx[0] = cj;
                    } else if (dist < bestDist[1]) {
                        bestDist[1] = dist; bestIdx[1] = cj;
                    }
                }

                /* Draw road from cityA to each nearest neighbor */
                for (cj = 0; cj < 2; cj++) {
                    short bx, by, rx, ry;
                    if (bestIdx[cj] < 0) continue;
                    bx = *(short *)(sCityData +bestIdx[cj] * 0x20 + 0x00);
                    by = *(short *)(sCityData +bestIdx[cj] * 0x20 + 0x02);

                    /* Walk from A to B using Manhattan path (horizontal then vertical)
                     * so every road tile has at least one cardinal neighbor for autotile. */
                    rx = ax; ry = ay;
                    /* Horizontal leg first */
                    while (rx != bx) {
                        if (rx >= 0 && rx < 112 && ry >= 0 && ry < 156) {
                            if (terrain[ry * 112 + rx] != TT_WATER)
                                roadBuf[ry * 112 + rx] = 1;
                        }
                        if (rx < bx) rx++; else rx--;
                    }
                    /* Vertical leg */
                    while (ry != by) {
                        if (rx >= 0 && rx < 112 && ry >= 0 && ry < 156) {
                            if (terrain[ry * 112 + rx] != TT_WATER)
                                roadBuf[ry * 112 + rx] = 1;
                        }
                        if (ry < by) ry++; else ry--;
                    }
                    /* Mark destination */
                    if (bx >= 0 && bx < 112 && by >= 0 && by < 156)
                        roadBuf[by * 112 + bx] = 1;
                }
            }
        }

        /* --- Autotile pass: convert boolean road flags to proper tile indices ---
         * For each road tile, check 4 cardinal neighbors to build a 4-bit mask:
         *   bit0=N, bit1=E, bit2=S, bit3=W
         * Then look up the correct RD value (1-17) from the autotile table.
         * Confirmed from original SCN resource dumps (Erythea et al.):
         *   1=E+W horiz, 2=N+S vert, 3=crossroad, 4-7=T-junctions,
         *   8-11=corners, 12-15=dead-ends, 16-17=variants */
        if (roadBuf != NULL) {
            /* Autotile lookup: index by 4-bit neighbor mask (N=1,E=2,S=4,W=8) */
            static const unsigned char kAutoTile[16] = {
                /*  0=none  */ 1,   /*  1=N     */ 15,
                /*  2=E     */ 14,  /*  3=N+E   */ 10,
                /*  4=S     */ 13,  /*  5=N+S   */ 2,
                /*  6=E+S   */ 11,  /*  7=N+E+S */ 7,
                /*  8=W     */ 12,  /*  9=N+W   */ 9,
                /* 10=E+W   */ 1,   /* 11=N+E+W */ 6,
                /* 12=S+W   */ 8,   /* 13=N+S+W */ 5,
                /* 14=E+S+W */ 4,   /* 15=all   */ 3
            };
            short rx, ry;
            for (ry = 0; ry < 156; ry++) {
                for (rx = 0; rx < 112; rx++) {
                    short idx = ry * 112 + rx;
                    unsigned char mask;
                    if (roadBuf[idx] == 0) continue;
                    mask = 0;
                    if (ry > 0   && roadBuf[(ry-1) * 112 + rx] != 0) mask |= 1; /* N */
                    if (rx < 111 && roadBuf[ry * 112 + rx + 1]  != 0) mask |= 2; /* E */
                    if (ry < 155 && roadBuf[(ry+1) * 112 + rx] != 0) mask |= 4; /* S */
                    if (rx > 0   && roadBuf[ry * 112 + rx - 1]  != 0) mask |= 8; /* W */
                    roadBuf[idx] = kAutoTile[mask];
                }
            }
        }
    }

    /* --- Phase 4: Initialize game state --- */
    /* Faction name pool from DAT 1010 "RANDOM": 8 slots x 5 variants each.
     * Original game picks one variant randomly per slot. */
    {
        static const char *factionNamePool[8][5] = {
            {"White Knights", "Guardians",   "Argentia",     "Knights Arcana", "Chivalria"},
            {"Dragonlords",  "Mountainmen",  "Frost Giants", "Ice Jarls",      "Storm Kings"},
            {"Gnomes",       "Dark Dwarves", "Dwarrows",     "Khazarak",       "Rockfiends"},
            {"Goblins",      "Ymorgians",    "Balad Naran",  "Ogre Lords",     "Kobolds"},
            {"Eldakkar",     "Forestfolk",   "Treelords",    "Light Elves",    "Dark Elves"},
            {"Emphidians",   "Ilish Empire", "Mathreans",    "Demonlords",     "Serricea"},
            {"Wild Men",     "Frost Tribe",  "Barbarians",   "Oinland",        "Horse Kings"},
            {"Zhoragh",      "Black Hand",   "Deathmaster",  "Lich-King",      "Dark Knights"}
        };
        short nameVariant = Dice(1, 5, -1);
        for (i = 0; i < 8; i++) {
            short j;
            unsigned char *name = gs + i * 20;
            const char *src = factionNamePool[i][nameVariant];
            for (j = 0; src[j] != 0 && j < 19; j++)
                name[j] = src[j];
            name[j] = 0;
        }
    }

    for (i = 0; i < 16; i++) gs[0x100 + i] = 0;   /* advisor state (FUN_10092c5c) */
    for (i = 0; i < 8; i++)
        *(short *)(gs + 0xd0 + i * 2) = (i == 0) ? 0 : 1;  /* human + 7 AI */
    *(short *)(gs + 0x110) = 0;        /* current player */
    *(short *)(gs + 0x114) = 7;        /* difficulty = Lord */
    /* Create one starting army per faction at their starting city */
    {
        short armyIdx = 0;

        for (i = 0; i < 8 && i < cityCount && armyIdx < MAX_ARMIES; i++) {
            unsigned char *city = sCityData +i * 0x20;
            unsigned char *army = ARMY_REC(armyIdx);
            short cx = *(short *)(city + 0x00);
            short cy = *(short *)(city + 0x02);
            short j;

            /* Position at the city */
            *(short *)(army + 0x00) = cx;
            *(short *)(army + 0x02) = cy;

            /* Name: "1st <faction>" derived from game state faction name */
            {
                const char *prefix = "1st ";
                unsigned char *facName = gs + i * 20;
                short p;
                for (p = 0; prefix[p] && p < 15; p++)
                    army[0x04 + p] = prefix[p];
                for (j = 0; facName[j] != 0 && p + j < 15; j++)
                    army[0x04 + p + j] = facName[j];
                army[0x04 + p + j] = 0;
            }

            /* Sprite from lead unit type, owner */
            army[0x15] = i;   /* owner = faction index */

            /* 4 mixed units matching original Warlords II starting army */
            army[0x16] = 11;    /* unit_types[0] = type 11 */
            army[0x17] = 2;     /* unit_types[1] = type 2 */
            army[0x18] = 1;     /* unit_types[2] = Heavy Infantry */
            army[0x19] = 8;     /* unit_types[3] = type 8 */

            /* Sprite from lead unit type (type 11) via unit type table */
            if (sUnitTypesLoaded && 11 < sUnitTypeCount) {
                unsigned char *ute = sUnitTypeTable + 11 * UNIT_TYPE_ENTRY;
                army[0x14] = ute[0x00];
            } else {
                army[0x14] = 11;  /* fallback: use type index as sprite */
            }

            /* Movement points */
            army[0x1a] = 10;  army[0x1b] = 10;
            army[0x1c] = 8;   army[0x1d] = 6;

            /* Hit points */
            army[0x1e] = 5;   army[0x1f] = 5;
            army[0x20] = 4;   army[0x21] = 6;

            /* Bonus and experience = 0 (already zeroed) */

            /* Strength display = SUM(HP * 2) = (5+5+4+6)*2 = 40 */
            RecalcArmyStrength(army);

            /* Active unit type */
            army[0x2c] = 11;  /* type 11 */

            /* Origin player */
            army[0x2f] = i;

            /* No orders */
            *(short *)(army + 0x32) = 0;
            *(short *)(army + 0x34) = 0;
            *(short *)(army + 0x36) = 0;

            /* Hero items = 0 */
            *(short *)(army + 0x3a) = 0;
            *(short *)(army + 0x3c) = 0;
            *(short *)(army + 0x3e) = 0;
            *(short *)(army + 0x40) = 0;

            armyIdx++;
        }
        /* Create neutral garrison armies at every non-capital city */
        /* Vary composition based on city index to match original Warlords II */
        for (i = 8; i < cityCount && armyIdx < MAX_ARMIES; i++) {
            unsigned char *city = sCityData +i * 0x20;
            short sType = (short)(unsigned char)city[0x17];
            short cx, cy;
            unsigned char *army;
            short j2;

            /* Skip ruins and non-city sites (types 2-6) */
            if (sType >= 2 && sType <= 6) continue;

            cx = *(short *)(city + 0x00);
            cy = *(short *)(city + 0x02);

            army = ARMY_REC(armyIdx);
            for (j2 = 0; j2 < 0x42; j2++) army[j2] = 0;

            *(short *)(army + 0x00) = cx;
            *(short *)(army + 0x02) = cy;
            army[0x15] = 0x0F;   /* neutral owner */
            army[0x2d] = 3;      /* fortified */
            army[0x2f] = 0x0F;   /* origin = neutral */

            if ((i % 2) == 0) {
                /* Setup A (even cities): stronger garrison, strength 22 */
                army[0x16] = 11;     /* unit_types[0] = type 11 */
                army[0x17] = 2;      /* unit_types[1] = type 2 */
                army[0x18] = 7;      /* unit_types[2] = type 7 */
                army[0x19] = 0xFF;   /* slot 3 empty */
                army[0x1a] = 10;     /* movement[0] */
                army[0x1b] = 10;     /* movement[1] */
                army[0x1c] = 8;      /* movement[2] */
                army[0x1d] = 0;      /* movement[3] */
                army[0x1e] = 5;      /* HP[0] */
                army[0x1f] = 5;      /* HP[1] */
                army[0x20] = 4;      /* HP[2] */
                army[0x21] = 0;      /* HP[3] */
                RecalcArmyStrength(army);  /* (5+5+4)*2 = 28 */
            } else {
                /* Setup B (odd cities): single Heavy Infantry */
                army[0x16] = 1;      /* unit_types[0] = Heavy Infantry */
                army[0x17] = 0xFF;   /* slot 1 empty */
                army[0x18] = 0xFF;   /* slot 2 empty */
                army[0x19] = 0xFF;   /* slot 3 empty */
                army[0x1a] = 8;      /* movement[0] */
                army[0x1b] = 0;      /* movement[1] */
                army[0x1c] = 0;      /* movement[2] */
                army[0x1d] = 0;      /* movement[3] */
                army[0x1e] = 4;      /* HP[0] */
                army[0x1f] = 0;      /* HP[1] */
                army[0x20] = 0;      /* HP[2] */
                army[0x21] = 0;      /* HP[3] */
                RecalcArmyStrength(army);  /* 4*2 = 8 */
            }

            /* Set sprite from lead unit type */
            {
                short leadType = (short)(unsigned char)army[0x16];
                if (sUnitTypesLoaded && leadType < sUnitTypeCount) {
                    unsigned char *ute = sUnitTypeTable + leadType * UNIT_TYPE_ENTRY;
                    army[0x14] = ute[0x00];
                } else {
                    army[0x14] = (unsigned char)leadType;
                }
            }

            armyIdx++;
        }

        *(short *)(gs + 0x1602) = armyIdx;
    }

    /* Set starting gold for all 8 factions */
    for (i = 0; i < 8; i++)
        *(short *)(gs + 0x186 + i * 0x14) = 100;

    /* gs+0x12E is the tutorial flag (68k: gates the tutorial screens and the
     * CODE_104 hero-vs-neutral protection), not hero generation. */
    *(short *)(gs + 0x12e) = 0;

    sMapLoaded = true;
    sRandomMap = true;
    sMapWidth = 112;
    sMapHeight = 156;

    /* Allocate extended state if needed */
    if (*gExtState == 0)
        *gExtState = (pint)NewPtrClear(0x4000);

    GameInit();

    /* Progress: 100% */
    {
        Rect fillR;
        RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
        short fillW = (barRight - barLeft - 2);
        SetPort(scenWin);
        SetRect(&fillR, barLeft + 1, barTop + 1,
                barLeft + 1 + fillW, barTop + barH - 1);
        RGBForeColor(&barFg);
        PaintRect(&fillR);
    }

    /* Brief delay at 100% */
    {
        unsigned long endTick = TickCount() + 30;
        while (TickCount() < endTick) { /* busy-wait */ }
    }

    sViewportX = 0;
    sViewportY = 0;

    DisposePtr((Ptr)terrain);
    return true;
}


/* View/button title from STR# 'id', 1-based like the original's MacApp views
 * (GetCachedString is 0-based and only covers the cached lists). */
static ConstStr255Param ViewString(Str255 buf, short id, short idx, ConstStr255Param fallback)
{
    GetIndString(buf, id, idx);
    return buf[0] ? buf : fallback;
}

static void DrawEmbossedStringIn(ConstStr255Param s, short x, short baseline, const RGBColor *fg,
                                 unsigned short darkV, unsigned short lightV);

/* MacApp T3DButton, pixel-exact from the original (Game Setup / picker),
 * drawn over the whole view rect (L,T)-(R,B):
 *   black outline with cut corners: rows T and B-1 span L+3..R-4, the next
 *   rows in have L+1..L+2 / R-3..R-2, then L+1 / R-2, sides at L and R-1;
 *   face 0xBBBB; white highlight on row T+2 and column L+2; shadows 0x7777
 *   (column R-3, row B-3) and 0x5555 (column R-2, row B-2); 0x8888 where the
 *   highlight meets the shadow; label Chicago 12 black over a 0xDDDD emboss. */
/* The cut-corner outline shared by enabled (black) and disabled (0x5555)
 * T3D buttons. */
static void FrameT3DOutline(short L, short T, short R, short B)
{
    MoveTo(L + 3, T); LineTo(R - 4, T);           MoveTo(L + 3, B - 1); LineTo(R - 4, B - 1);
    MoveTo(L + 1, T + 1); LineTo(L + 2, T + 1);   MoveTo(R - 3, T + 1); LineTo(R - 2, T + 1);
    MoveTo(L + 1, B - 2); LineTo(L + 2, B - 2);   MoveTo(R - 3, B - 2); LineTo(R - 2, B - 2);
    MoveTo(L + 1, T + 2); LineTo(L + 1, T + 2);   MoveTo(R - 2, T + 2); LineTo(R - 2, T + 2);
    MoveTo(L + 1, B - 3); LineTo(L + 1, B - 3);   MoveTo(R - 2, B - 3); LineTo(R - 2, B - 3);
    MoveTo(L, T + 3); LineTo(L, B - 4);           MoveTo(R - 1, T + 3); LineTo(R - 1, B - 4);
}

/* Disabled T3D button / icon button: 0x5555 outline, flat 0xCCCC face. */
static void DrawT3DDisabledFace(const Rect *r)
{
    RGBColor face = {0xCCCC, 0xCCCC, 0xCCCC}, out = {0x5555, 0x5555, 0x5555};
    Rect f;
    SetRect(&f, r->left + 1, r->top + 1, r->right - 1, r->bottom - 1);
    RGBForeColor(&face); PaintRect(&f);
    RGBForeColor(&out);
    FrameT3DOutline(r->left, r->top, r->right, r->bottom);
}

static void DrawT3DBevel(const Rect *r);
static void DrawT3DButton(const Rect *r, ConstStr255Param label)
{
    RGBColor black = {0, 0, 0};
    short w;
    DrawT3DBevel(r);

    {   /* TxSt 1002 names Chicago explicitly; on 8.5+ font 0 is Charcoal */
        short fnum;
        GetFNum("\pChicago", &fnum);
        TextFont(fnum); TextSize(12); TextFace(0);
    }
    w = StringWidth(label);
    {   /* MacApp centres Chicago 12 in the view: baseline top+13 for the
         * 20- and 21-high buttons (picker / Game Setup, measured) */
        short x = (r->left + r->right - w + 1) / 2 - 1;   /* measured (picker, Game Setup, city Done) */
        DrawEmbossedStringIn(label, x, (r->top + r->bottom) / 2 + 3, &black, 0x8888, 0xDDDD);
    }
}

static void DrawT3DBevel(const Rect *r)
{
    RGBColor face = {0xBBBB, 0xBBBB, 0xBBBB}, white = {0xFFFF, 0xFFFF, 0xFFFF};
    RGBColor sh1 = {0x7777, 0x7777, 0x7777}, sh2 = {0x5555, 0x5555, 0x5555};
    RGBColor mid = {0x8888, 0x8888, 0x8888}, black = {0, 0, 0};
    short L = r->left, T = r->top, R = r->right, B = r->bottom;
    Rect f;

    SetRect(&f, L + 1, T + 1, R - 1, B - 1);
    RGBForeColor(&face); PaintRect(&f);
    RGBForeColor(&black);
    FrameT3DOutline(L, T, R, B);
    RGBForeColor(&white);
    MoveTo(L + 2, T + 2); LineTo(R - 4, T + 2);   MoveTo(L + 2, T + 3); LineTo(L + 2, B - 4);
    RGBForeColor(&sh1);
    MoveTo(L + 3, B - 3); LineTo(R - 4, B - 3);   MoveTo(R - 3, T + 3); LineTo(R - 3, B - 4);
    MoveTo(R - 4, B - 4); LineTo(R - 4, B - 4);
    RGBForeColor(&sh2);
    MoveTo(L + 3, B - 2); LineTo(R - 4, B - 2);   MoveTo(R - 2, T + 3); LineTo(R - 2, B - 4);
    MoveTo(R - 3, B - 3); LineTo(R - 3, B - 3);
    RGBForeColor(&mid);
    MoveTo(R - 3, T + 2); LineTo(R - 3, T + 2);   MoveTo(R - 4, T + 3); LineTo(R - 4, T + 3);
    MoveTo(L + 3, B - 4); LineTo(L + 3, B - 4);   MoveTo(L + 2, B - 3); LineTo(L + 2, B - 3);
    RGBForeColor(&black);
}

/* Draw text in a MacApp static-text view rect with the view's justification
 * (1 = centre, -1 = right, -2 = left), baseline at top + font ascent. */
static void DrawViewText(const Rect *r, ConstStr255Param s, short just)
{
    FontInfo fi;
    short w = StringWidth(s), x;
    GetFontInfo(&fi);
    if (just == 1)       x = (r->left + r->right - w + 1) / 2;   /* MacApp rounds up (picker 'Name') */
    else if (just == -1) x = r->right - w;
    else                 x = r->left + 1;                           /* measured (picker 'Ruins') */
    MoveTo(x, r->top + fi.ascent);
    DrawString(s);
}

/* ===================================================================
 * Tutorial screens (68k CODE_062 "a1Tutorial").
 *
 * A scenario whose SCN has the tutorial flag at gs+0x12E (only Tutoria) shows
 * its named 'GFX ' scripts at fixed moments; gs+0x134 holds a bit per screen
 * already shown (same bits as the 68k: THERO 0x01, TPROD 0x02, TSELECT 0x04,
 * TMOVE 0x08, TFIGHT 0x10, TPROD2 0x20, TTURN2 0x40, TSEARCH 0x80; TWARLORD
 * and TENDTURN have none). Each script is drawn in View 1030: a 366x352
 * window on WDEF 128 variant 7 (procID 0x0807, which adds the drop shadow),
 * marble edge PICTs 1004/1005/1006/1008 around PICT 1001, the script area at
 * (7,7) and a "Done" T3DButton. Script commands (CODE_062 FUN_000002f4):
 *   #H / #T          foreground = palette entry 0xE0, background = 0xF9
 *   #Fnnn            foreground = palette entry nnn
 *   #C(x,y)|text|    title, centred on x;  #L / #R: left / right aligned line
 *   #G(sx,sy,w,h)nnn(x,y)  transparent blit from the first army sheet
 *   #Bnnnnn(x,y)     cicn nnnnn (mouse pictures)
 *   #E               end
 * Coordinates are relative to the script area; y is the top of the text.
 * =================================================================== */
#define MAX_TUTORIAL_SCRIPTS 16
static Handle  sTutorialScripts[MAX_TUTORIAL_SCRIPTS];
static Str63   sTutorialNames[MAX_TUTORIAL_SCRIPTS];
static short   sTutorialCount = 0;

/* Called with the scenario's resource file current. */
static void LoadTutorialScripts(void)
{
    short n, i;
    for (i = 0; i < sTutorialCount; i++)
        if (sTutorialScripts[i] != NULL) DisposeHandle(sTutorialScripts[i]);
    sTutorialCount = 0;
    n = Count1Resources('GFX ');
    for (i = 1; i <= n && sTutorialCount < MAX_TUTORIAL_SCRIPTS; i++) {
        Handle h = Get1IndResource('GFX ', i);
        short id; ResType t;
        if (h == NULL) continue;
        GetResInfo(h, &id, &t, sTutorialNames[sTutorialCount]);
        DetachResource(h);
        sTutorialScripts[sTutorialCount++] = h;
    }
}

static Boolean TutorialActive(void)
{
    return *gGameState != 0 && *(short *)((unsigned char *)*gGameState + 0x12e) != 0;
}

static short ParseNum3(const char **p)
{
    const char *s = *p;
    short v = (s[0] - '0') * 100 + (s[1] - '0') * 10 + (s[2] - '0');
    *p = s + 3;
    return v;
}

/* "(xxx,yyy)" -> x, y */
static void ParsePoint(const char **p, short *x, short *y)
{
    (*p)++;  *x = ParseNum3(p);
    (*p)++;  *y = ParseNum3(p);
    (*p)++;
}

/* "|text|" -> Pascal string */
static void ParseText(const char **p, const char *end, Str255 out)
{
    const char *s = *p;
    short n = 0;
    while (s < end && *s != '|') s++;
    if (s < end) s++;
    while (s < end && *s != '|' && n < 255) out[++n] = *s++;
    if (s < end) s++;
    out[0] = (unsigned char)n;
    *p = s;
}

static void DrawTutorialScript(Handle script, short ox, short oy)
{
    const char *p, *end;
    RGBColor fg = {0xFFFF, 0xFFFF, 0xCCCC};
    RGBColor dark = {0x4444, 0x4444, 0x4444}, light = {0xAAAA, 0xAAAA, 0xAAAA};
    short illuria;
    char saved = HGetState(script);

    GetFNum("\pIlluria", &illuria);
    if (illuria == 0) illuria = 1602;
    HLock(script);
    p = *script;
    end = p + GetHandleSize(script);
    if (sGamePal != NULL) GetEntryColor(sGamePal, 0xE0, &fg);

    while (p < end) {
        char cmd;
        while (p < end && *p != '#') p++;
        if (p + 1 >= end) break;
        cmd = p[1];
        p += 2;
        if (cmd == 'E') break;
        if (cmd == 'H' || cmd == 'T') {
            if (sGamePal != NULL) GetEntryColor(sGamePal, 0xE0, &fg);
        } else if (cmd == 'F') {
            short idx = ParseNum3(&p);
            if (sGamePal != NULL && idx < 256) GetEntryColor(sGamePal, idx, &fg);
        } else if (cmd == 'C' || cmd == 'L' || cmd == 'R') {
            short x, y, w;
            FontInfo fi;
            Str255 text;
            ParsePoint(&p, &x, &y);
            ParseText(&p, end, text);
            TextFont(illuria);
            TextSize(cmd == 'C' ? 36 : 17);
            TextFace(0);
            GetFontInfo(&fi);
            w = StringWidth(text);
            if (cmd == 'C') x -= w / 2;
            else if (cmd == 'R') x -= w;
            /* Embossed like the original: 0xAAAA at (x+2,y+2), then 0x4444 at
             * (x,y) on top of it, then the script colour at (x+1,y+1). */
            RGBForeColor(&light);
            MoveTo(ox + x + 2, oy + y + fi.ascent + 2);
            DrawString(text);
            RGBForeColor(&dark);
            MoveTo(ox + x, oy + y + fi.ascent);
            DrawString(text);
            RGBForeColor(&fg);
            MoveTo(ox + x + 1, oy + y + fi.ascent + 1);
            DrawString(text);
        }
        else if (cmd == 'G') {
            /* #G(sx,sy,w,h)nnn(dx,dy): transparent blit (mode 0x24) from a sprite
             * sheet. nnn 100/101/102 pick shields/PICTS0/SCENERY0 (unused by the
             * shipped scripts); every other value is sheet 14, which on the Mac
             * holds the first army sheet (A0: the hero knight at (384,30) in
             * THERO matches the original pixel for pixel). */
            short sx, sy, w, h, sheet, dx, dy;
            p++; sx = ParseNum3(&p); p++; sy = ParseNum3(&p);
            p++; w = ParseNum3(&p);  p++; h = ParseNum3(&p); p++;
            sheet = ParseNum3(&p);
            ParsePoint(&p, &dx, &dy);
            if (sheet < 100 && sArmyGW[0] != NULL) {
                Rect src, dst;
                RGBColor key;
                GWorldPtr gw = sArmyGW[0];
                SetRect(&src, sx, sy, sx + w, sy + h);
                SetRect(&dst, ox + dx, oy + dy, ox + dx + w, oy + dy + h);
                key = sArmyBgColor[0];
                RGBBackColor(&key);
                CopyBits((BitMap *)*GetGWorldPixMap(gw), &qd.thePort->portBits,
                         &src, &dst, transparent, NULL);
                {
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    RGBBackColor(&white);
                }
            }
        } else if (cmd == 'B' || cmd == 'I') {
            /* #Bnnnnn(x,y): small picture (cicn nnnnn, the mouse drawings) */
            short id, x, y;
            CIconHandle ic;
            id = (short)((p[0]-'0') * 10000 + (p[1]-'0') * 1000 + (p[2]-'0') * 100 +
                         (p[3]-'0') * 10 + (p[4]-'0'));
            p += 5;
            ParsePoint(&p, &x, &y);
            ic = GetCIcon(id);
            if (ic != NULL) {
                Rect ir = (**ic).iconPMap.bounds;
                OffsetRect(&ir, ox + x - ir.left, oy + y - ir.top);
                PlotCIcon(&ir, ic);
                DisposeCIcon(ic);
            }
        }
    }
    HSetState(script, saved);
}

/* Show tutorial screen 'name' if the tutorial is active and its gs+0x134 bit
 * (0 = no bit, may repeat) is clear; modal until Done. Restores the port.
 * Returns true if it was shown (callers then redraw what was underneath). */
static Boolean ShowTutorialScreen(ConstStr255Param name, unsigned char bit)
{
    GrafPtr savedPort;
    unsigned char *gsp;
    WindowPtr win;
    Rect wr, r;
    short i, idx = -1, left, top, mbar = GetMBarHeight();
    Rect screen = qd.screenBits.bounds;
    Boolean done = false;
    unsigned long openTick;

    if (!TutorialActive()) return false;
    gsp = (unsigned char *)*gGameState;
    if (bit != 0 && (gsp[0x134] & bit)) return false;
    for (i = 0; i < sTutorialCount; i++)
        if (EqualString(sTutorialNames[i], name, false, true)) { idx = i; break; }
    if (idx < 0) return false;
    gsp[0x134] |= bit;
    GetPort(&savedPort);

    /* View 1030 placement (MacApp alert position, counting the 5px shadow):
     * centred horizontally, a third of the way down below the menu bar. */
    left = (screen.right - (366 + 5)) / 2;
    top  = mbar + (screen.bottom - mbar - (352 + 5)) / 3;
    SetRect(&wr, left, top, left + 366, top + 352);
    win = NewCWindow(NULL, &wr, "\p", true, 0x0807, (WindowPtr)-1L, false, 0);
    if (win == NULL) return false;
    {   /* MacApp windows take their WDEF colours from wctb 1000 */
        Handle wctb = GetResource('wctb', 1000);
        if (wctb != NULL) SetWinColor(win, (CTabHandle)wctb);
    }
    ApplyGamePalette(win);
    SetPort(win);
    /* Drop the key/click that opened us. A Return that confirmed the scenario
     * picker can still be held (and repeat) after the scenario has loaded, so
     * wait for Return/Enter to be released (max 2s) before flushing. */
    {
        unsigned long until = TickCount() + 120;
        unsigned char km[16];    /* KeyMap: bit (k & 7) of byte (k >> 3) */
        do {
            GetKeys(km);
        } while ((((km[0x24 >> 3] >> (0x24 & 7)) & 1) ||      /* Return */
                  ((km[0x4C >> 3] >> (0x4C & 7)) & 1)) &&     /* Enter */
                 TickCount() < until);
    }
    FlushEvents(keyDownMask | keyUpMask | autoKeyMask | mDownMask | mUpMask, 0);
    openTick = TickCount();

    while (!done) {
        EventRecord evt;
        Rect doneOuter, doneBtn;
        SetRect(&doneOuter, 279, 310, 351, 339);   /* View 1030 'done' (310,279) 29x72 */
        doneBtn = doneOuter;
        InsetRect(&doneBtn, 4, 4);

        if (WaitNextEvent(everyEvent, &evt, 30, NULL)) {
            if (evt.what == updateEvt && (WindowPtr)evt.message == win) {
                static const short edges[4][5] = {     /* pict, top, left, bottom, right */
                    {1004, 0, 0, 7, 366}, {1005, 7, 0, 352, 7},
                    {1006, 345, 0, 352, 366}, {1008, 0, 359, 352, 366} };
                BeginUpdate(win);
                SetRect(&r, 7, 7, 359, 345);
                {
                    PicHandle marble = GetPicture(1001);
                    Rect pf;
                    if (marble != NULL) {
                        ClipRect(&r);
                        pf = (**marble).picFrame;
                        OffsetRect(&pf, 7 - pf.left, 7 - pf.top);
                        DrawPicture(marble, &pf);
                    }
                }
                for (i = 0; i < 4; i++) {
                    PicHandle pic = GetPicture(edges[i][0]);
                    Rect pf, clip;
                    if (pic == NULL) continue;
                    SetRect(&clip, edges[i][2], edges[i][1], edges[i][4], edges[i][3]);
                    ClipRect(&clip);
                    pf = (**pic).picFrame;
                    OffsetRect(&pf, edges[i][2] - pf.left, edges[i][1] - pf.top);
                    DrawPicture(pic, &pf);
                }
                ClipRect(&win->portRect);
                DrawTutorialScript(sTutorialScripts[idx], 7, 7);
                {
                    RGBColor black = {0, 0, 0};
                    RGBForeColor(&black);
                    PenSize(3, 3);
                    FrameRoundRect(&doneOuter, 16, 16);
                    PenSize(1, 1);
                }
                {
                    Str255 title;
                    DrawT3DButton(&doneBtn, ViewString(title, 1000, 5, "\pDone"));  /* STR# 1000 #5 */
                }
                EndUpdate(win);
            } else if (evt.what == mouseDown) {
                Point pt = evt.where;
                WindowPtr hit;
                if (FindWindow(pt, &hit) == inContent && hit == win) {
                    GlobalToLocal(&pt);
                    if (PtInRect(pt, &doneOuter)) done = true;
                }
            } else if (evt.what == keyDown && TickCount() - openTick > 30) {
                /* A Return still held from the picker can arrive (or repeat)
                 * after the flush while the scenario was loading. */
                char key = evt.message & charCodeMask;
                if (key == 0x0D || key == 0x03 || key == 0x1B) done = true;
            }
        }
    }
    DisposeWindow(win);
    SetPort(savedPort);
    return true;
}

/* ===================================================================
 * ShowScenarioSelection — Display scenario choice dialog
 *
 * Shows a modal window with a list of available scenarios.
 * Returns true if the user selected a scenario and it was loaded.
 * =================================================================== */
static Boolean ShowScenarioSelection(void)
{
    WindowPtr  scenWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect, listRect;
    short      i;
    short      selectedIdx = 0;
    short      scrollOffset = 0;
    short      visibleItems;
    Boolean    done = false;
    Boolean    loaded = false;
    Boolean    useRandomMap = false;
    short      lineHeight = 18;   /* View 3000 'lstg' row height */
    ControlHandle vScroll = NULL;
    Rect       screenRect = qd.screenBits.bounds;

    if (sScenarioCount == 0) ScanForScenarios();   /* normally done during the splash */

    if (sScenarioCount == 0) {
        /* No scenarios found — fall back to StandardGetFile */
        return false;
    }

    /* Default selection: last scenario (Tutoria), matching the original. */
    selectedIdx = sScenarioCount - 1;

    /* View 3000: matches the original on 1024x768 pixel-for-pixel: 482x362
     * content at (271,213) inside plainDBox's 1px frame, PICT 3000 at the
     * content origin and the spare right/bottom pixels black. */
    {
        short mbar = GetMBarHeight();
        short top = mbar + (screenRect.bottom - mbar - 360) / 2;
        short left = (screenRect.right - 480) / 2;
        SetRect(&winRect, left - 1, top - 1, left + 481, top + 361);  /* (271,213) on 1024x768 */
    }

    scenWin = NewCWindow(NULL, &winRect, "\p", true,
                          plainDBox, (WindowPtr)-1L, false, 0);
    if (scenWin == NULL)
        return false;
    ApplyGamePalette(scenWin);

    SetPort(scenWin);

    /* View 3000 'vScr': standard scroll bar in the list frame (inactive when
     * every scenario fits, as in the original). */
    {
        Rect sr;
        SetRect(&sr, 170, 110, 186, 274);
        vScroll = NewControl(scenWin, &sr, "\p", true, 0, 0, 0, scrollBarProc, 0);
    }

    /* Create offscreen buffer for flicker-free drawing */
    {
        Rect obounds;
        SetRect(&obounds, 0, 0, 480, 360);
        NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
    }

    /* List rows area: View 3000 scroller (111,16) 162x154; 18px rows from y=111 */
    SetRect(&listRect, 16, 111, 170, 274);
    visibleItems = (listRect.bottom - listRect.top) / lineHeight;

    /* Drain pending events and ignore early keypresses */
    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        unsigned long startTick = TickCount();

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                SetRect(&r, 0, 0, 480, 360);

                /* Draw into offscreen buffer for flicker-free rendering */
                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* PICT 3000: scenario selection background (crystal ball + dragons) */
                {
                    PicHandle bgPict = GetPicture(3000);
                    if (bgPict != NULL) {
                        DrawPicture(bgPict, &r);
                    } else {
                        DrawMarbleBackground(&r);
                    }
                }

                /* List frame: T3DFrameAdorner around View 3000 (109,14) 166x173 —
                 * 0x4444/black on top-left, black/0xAAAA on bottom-right — white rows. */
                {
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF}, black = {0, 0, 0};
                    RGBColor dark = {0x4444, 0x4444, 0x4444}, light = {0xAAAA, 0xAAAA, 0xAAAA};
                    Rect fr;
                    SetRect(&fr, 15, 110, 186, 274);
                    RGBForeColor(&white); PaintRect(&fr);
                    RGBForeColor(&black); FrameRect(&fr);
                    RGBForeColor(&dark);
                    MoveTo(14, 274); LineTo(14, 109); LineTo(186, 109);
                    RGBForeColor(&light);
                    MoveTo(15, 274); LineTo(186, 274); LineTo(186, 110);
                }

                /* Rows: W2SC document icon (BNDL family 133) + name in the system
                 * font; selection painted in the original's 0xCCCC,0xCCCC,0xFFFF. */
                TextFont(0);
                TextSize(12);
                TextFace(0);
                for (i = 0; i < visibleItems && (i + scrollOffset) < sScenarioCount; i++) {
                    short itemIdx = i + scrollOffset;
                    short rowTop = listRect.top + i * lineHeight;
                    RGBColor black = {0, 0, 0};
                    Rect iconR;

                    SetRect(&iconR, 20, rowTop + 1, 36, rowTop + 17);
                    PlotIconID(&iconR, atNone, ttNone, 133);
                    RGBForeColor(&black);
                    MoveTo(37, rowTop + 13);
                    DrawString(sScenarioNames[itemIdx]);
                    if (itemIdx == selectedIdx) {
                        /* the selection is a hilite-mode inversion of the row drawn
                         * on white (the smoothed text keeps its white-blended
                         * fringe, as measured on the original) */
                        RGBColor hilite = {0xCCCC, 0xCCCC, 0xFFFF};
                        Rect selRect;
                        SetRect(&selRect, listRect.left, rowTop, listRect.right, rowTop + lineHeight);
                        *(RGBColor *)0x0DA0 = hilite;                 /* HiliteRGB */
                        LMSetHiliteMode(LMGetHiliteMode() & 0x7F);    /* clear hiliteBit */
                        InvertRect(&selRect);
                    }
                }

                /* Scenario info from SCEN resource — values drawn in crystal ball area.
                 * PICT 3000 already has the labels (Name, Description, Cities, Ruins, Players)
                 * so we only draw the actual data values here. */
                if (selectedIdx >= 0 && selectedIdx < sScenarioCount) {
                    RGBColor valueColor = {0xFFFF, 0xFFFF, 0xFFFF};
                    short refNum = FSpOpenResFile(&sScenarioSpecs[selectedIdx], fsRdPerm);
                    if (refNum != -1) {
                        Handle scenHdl;
                        UseResFile(refNum);
                        scenHdl = Get1Resource('SCEN', 10000);
                        if (scenHdl != NULL && GetHandleSize(scenHdl) >= 84) {
                            unsigned char *sc;
                            HLock(scenHdl);
                            sc = (unsigned char *)*scenHdl;
                            char nameBuf[21], descBuf[33];
                            short cities, ruins, players;
                            Str255 numStr;

                            BlockMoveData(sc, nameBuf, 20);
                            nameBuf[20] = 0;
                            BlockMoveData(sc + 28, descBuf, 32);
                            descBuf[32] = 0;
                            cities  = (short)sc[76];
                            ruins   = (short)sc[78];
                            players = (short)sc[80];

                            /* View 3000 static texts, all TxSt 1011: Illuria 17pt in
                             * (0x12B8,0x88A3,0xD000), each with its view's justification. */
                            {
                                RGBColor teal = {0x12B8, 0x88A3, 0xD000};
                                Str255 pStr;
                                short fnum, len = 0;
                                Rect vr;
                                GetFNum("\pIlluria", &fnum);
                                if (fnum == 0) fnum = 1602;
                                TextFont(fnum); TextSize(17); TextFace(0);
                                RGBForeColor(&teal);

                                while (len < 20 && nameBuf[len] != 0) len++;   /* SCEN title */
                                pStr[0] = (unsigned char)len; BlockMoveData(nameBuf, pStr + 1, len);
                                SetRect(&vr, 236, 55, 436, 72);  DrawViewText(&vr, pStr, 1);

                                len = 0;
                                while (len < 32 && descBuf[len] != 0) len++;
                                pStr[0] = (unsigned char)len; BlockMoveData(descBuf, pStr + 1, len);
                                SetRect(&vr, 200, 130, 472, 147); DrawViewText(&vr, pStr, 1);

                                NumToString((long)cities, numStr);
                                SetRect(&vr, 238, 189, 288, 206); DrawViewText(&vr, numStr, -1);
                                NumToString((long)ruins, numStr);
                                SetRect(&vr, 392, 189, 442, 206); DrawViewText(&vr, numStr, -2);
                                NumToString((long)players, numStr);
                                SetRect(&vr, 311, 209, 361, 226); DrawViewText(&vr, numStr, 1);
                            }

                            HUnlock(scenHdl);
                            ReleaseResource(scenHdl);
                        }
                        CloseResFile(refNum);
                    }
                }

                /* Buttons: View 3000 'Rand' (292,15) 20x172 and 'Star' (321,11) 28x180,
                 * whose 'outl' adorner is a 3px round-rect ring (TxSt 1001 colour) around a
                 * button inset 4px. */
                {
                    RGBColor ring = {0xC28E, 0x1999, 0x0000};   /* TxSt 1001 colour */
                    Rect randBtnRect, starRect, starBtn;
                    Str255 title;
                    SetRect(&randBtnRect, 15, 292, 187, 312);
                    DrawT3DButton(&randBtnRect, ViewString(title, 3000, 3, "\pUse Random Map\311"));  /* View 3000 Rand: STR# 3000 #3 */
                    SetRect(&starRect, 11, 321, 191, 349);
                    RGBForeColor(&ring);
                    PenSize(3, 3);
                    FrameRoundRect(&starRect, 16, 16);
                    PenSize(1, 1);
                    starBtn = starRect;
                    InsetRect(&starBtn, 4, 4);
                    DrawT3DButton(&starBtn, ViewString(title, 3000, 2, "\pUse Selected Scenario"));  /* View 3000 Star: STR# 3000 #2 */
                }

                /* Blit offscreen buffer to window */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(scenWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)scenWin)->portBits,
                             &r, &r, srcCopy, NULL);
                }
                {   /* spare right/bottom pixels of the 482x362 content */
                    RGBColor black = {0, 0, 0};
                    Rect edge;
                    RGBForeColor(&black);
                    SetRect(&edge, 480, 0, 482, 362); PaintRect(&edge);
                    SetRect(&edge, 0, 360, 482, 362); PaintRect(&edge);
                }

                if (vScroll != NULL) Draw1Control(vScroll);
                needsRedraw = false;
            }

            /* Wait for events — long sleep to avoid CPU spinning */
            WaitNextEvent(everyEvent, &evt, 30, NULL);

            if (evt.what == mouseDown) {
                WindowPtr clickWin;
                short partCode = FindWindow(evt.where, &clickWin);

                if (partCode == inMenuBar) {
                    long menuResult = MenuSelect(evt.where);
                    short menuID = (menuResult >> 16) & 0xFFFF;
                    short menuItem = menuResult & 0xFFFF;
                    if (menuID == 2 && menuItem == 9) {
                        /* File > Quit */
                        DisposeWindow(scenWin);
                        if (offscreen != NULL) DisposeGWorld(offscreen);
                        ExitToShell();
                    }
                    HiliteMenu(0);
                } else {
                Point localPt = evt.where;
                SetPort(scenWin);
                GlobalToLocal(&localPt);

                /* Check list click — single click to select, double-click to load */
                if (PtInRect(localPt, &listRect)) {
                    short clickedItem = (localPt.v - listRect.top) / lineHeight + scrollOffset;
                    if (clickedItem >= 0 && clickedItem < sScenarioCount) {
                        if (clickedItem == selectedIdx) {
                            /* Double-click (same item already selected): load it */
                            done = true;
                            loaded = true;
                        } else {
                            selectedIdx = clickedItem;
                            needsRedraw = true;
                        }
                    }
                }

                /* Check "Use Selected Scenario" button */
                {
                    Rect useBtnRect;
                    SetRect(&useBtnRect, 11, 321, 191, 349);
                    if (PtInRect(localPt, &useBtnRect)) {
                        done = true;
                        loaded = true;
                    }
                }

                /* Check "Use Random Map..." button */
                {
                    Rect randBtnRect;
                    SetRect(&randBtnRect, 15, 292, 187, 312);
                    if (PtInRect(localPt, &randBtnRect)) {
                        done = true;
                        loaded = true;
                        useRandomMap = true;
                    }
                }
                } /* end else (not inMenuBar) */
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;

                /* Cmd+Q = Quit */
                if ((evt.modifiers & cmdKey) && (key == 'q' || key == 'Q')) {
                    DisposeWindow(scenWin);
                    if (offscreen != NULL) DisposeGWorld(offscreen);
                    ExitToShell();
                }

                /* Ignore keypresses in the first second to avoid
                 * stale Return from the 256-color Alert */
                if ((TickCount() - startTick) < 60)
                    continue;
                if (key == 0x0D || key == 0x03) {
                    done = true;
                    loaded = true;
                }
                else if (key == 0x1B) {
                    done = true;
                }
                else if (key == 0x1E) {
                    if (selectedIdx > 0) { selectedIdx--; needsRedraw = true; }
                    if (selectedIdx < scrollOffset) scrollOffset = selectedIdx;
                }
                else if (key == 0x1F) {
                    if (selectedIdx < sScenarioCount - 1) { selectedIdx++; needsRedraw = true; }
                    if (selectedIdx >= scrollOffset + visibleItems)
                        scrollOffset = selectedIdx - visibleItems + 1;
                }
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    /* Progress bar dimensions (shared between drawing and resource loading blocks) */
    short barLeft = 155, barRight = 305, barTop = 200, barH = 16;

    /* No sound while a scenario loads: the original is silent from the picker
     * to "Let the war begin!" (recorded, sound_erythea). */

    /* Loading screen visuals commented out — keep code for later restoration.
     * Original uses 6 text labels + progress bar advancing 0%→20%→60%→100%. */
#if 0  /* Loading screen disabled */
    if (loaded && !useRandomMap && selectedIdx >= 0 && selectedIdx < sScenarioCount) {
        Rect r, barFrame, barFill;
        RGBColor gold     = {0xFFFF, 0xCCCC, 0x3333};
        RGBColor ltBlue   = {0xCCCC, 0xDDDD, 0xFFFF};
        RGBColor barBg    = {0x3333, 0x3333, 0x5555};
        RGBColor white    = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor framCol  = {0x8888, 0x8888, 0xAAAA};
        short pct;

        SetPort(scenWin);
        SetRect(&r, 0, 0, 480, 360);

        /* Draw loading screen background: PICT 1010 (parchment scroll) */
        {
            PicHandle loadBg = GetPicture(1010);
            if (loadBg != NULL) {
                Rect pf = (**loadBg).picFrame;
                Rect bgR;
                short pw = pf.right - pf.left;
                short ph = pf.bottom - pf.top;
                SetRect(&bgR, (480 - pw) / 2, (360 - ph) / 2,
                        (480 - pw) / 2 + pw, (360 - ph) / 2 + ph);
                DrawMarbleBackground(&r);
                DrawPicture(loadBg, &bgR);
            } else {
                DrawMarbleBackground(&r);
            }
        }

        /* Title: "Loading Scenario" */
        TextFont(2);
        TextSize(18);
        TextFace(bold);
        RGBForeColor(&gold);
        {
            short tw = StringWidth(GetCachedString(STR_MISC, 24, "\pLoading Scenario"));
            MoveTo((480 - tw) / 2, 100);
            DrawString(GetCachedString(STR_MISC, 24, "\pLoading Scenario"));
        }

        /* Scenario name */
        TextFont(3);
        TextSize(12);
        TextFace(italic);
        RGBForeColor(&ltBlue);
        {
            short nameW = StringWidth(sScenarioNames[selectedIdx]);
            MoveTo((480 - nameW) / 2, 130);
            DrawString(sScenarioNames[selectedIdx]);
        }

        /* Status text */
        TextFont(3);
        TextSize(10);
        TextFace(0);
        RGBForeColor(&ltBlue);
        MoveTo(barLeft, barTop - 6);
        DrawString(GetCachedString(STR_MISC, 25, "\pReading scenario data..."));

        /* Draw PICT 1011 as the loading bar background, same size as the bar */
        {
            PicHandle borderPict = GetPicture(1011);
            if (borderPict != NULL) {
                Rect barBgRect;
                SetRect(&barBgRect, barLeft, barTop, barRight, barTop + barH);
                DrawPicture(borderPict, &barBgRect);
                KillPicture(borderPict);
            }
        }

        /* Progress bar frame */
        SetRect(&barFrame, barLeft, barTop, barRight, barTop + barH);
        RGBForeColor(&framCol);
        FrameRect(&barFrame);

        /* Animate: 0% */
        pct = 0;
        {
            Str255 pctStr;
            short pctW;
            NumToString((long)pct, pctStr);
            pctStr[pctStr[0] + 1] = '%';
            pctStr[0]++;
            RGBForeColor(&white);
            TextFont(3); TextSize(10); TextFace(bold);
            pctW = StringWidth(pctStr);
            MoveTo((480 - pctW) / 2, barTop + barH + 16);
            DrawString(pctStr);
        }
    }
#endif

    /* Load the selected scenario with progress updates.
     * Original game: 0%→20% (read SCN), →60% (load MAP/RD), →100% (init). */
    if (loaded && !useRandomMap && selectedIdx >= 0 && selectedIdx < sScenarioCount) {
        short refNum = FSpOpenResFile(&sScenarioSpecs[selectedIdx], fsRdPerm);
        if (refNum != -1) {
            Handle mapHdl, scnHdl;
            UseResFile(refNum);
            LoadTutorialScripts();
            LoadCityNames();

#if 0  /* Progress bar 20% disabled */
            {
                SetPort(scenWin);
                {
                    Rect fillR;
                    RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
                    short fillW = (barRight - barLeft - 2) * 20 / 100;
                    SetRect(&fillR, barLeft + 1, barTop + 1, barLeft + 1 + fillW, barTop + barH - 1);
                    RGBForeColor(&barFg);
                    PaintRect(&fillR);
                }
            }
#endif

            scnHdl = Get1Resource('SCN ', 10000);
            if (scnHdl != NULL) {
                long scnSize = GetHandleSize(scnHdl);
                HLock(scnHdl);
                if (*gGameState != 0) {
                    long copySize = scnSize;
                    if (copySize > 0x2FCC) copySize = 0x2FCC;
                    BlockMoveData(*scnHdl, (void *)*gGameState, copySize);
                }
                HUnlock(scnHdl);
                ReleaseResource(scnHdl);
            }

#if 0  /* Progress bar 60% disabled */
            {
                SetPort(scenWin);
                {
                    Rect fillR;
                    RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
                    short fillW = (barRight - barLeft - 2) * 60 / 100;
                    SetRect(&fillR, barLeft + 1, barTop + 1, barLeft + 1 + fillW, barTop + barH - 1);
                    RGBForeColor(&barFg);
                    PaintRect(&fillR);
                }
            }
#endif

            mapHdl = Get1Resource('MAP ', 10000);
            if (mapHdl != NULL) {
                long mapSize = GetHandleSize(mapHdl);
                HLock(mapHdl);
                if (*gMapTiles != 0) {
                    long copySize = mapSize;
                    if (copySize > 0x8880) copySize = 0x8880;
                    BlockMoveData(*mapHdl, (void *)*gMapTiles, copySize);
                    sMapLoaded = true;
                    sRandomMap = false;
                    sMapWidth = 112;
                    sMapHeight = (short)(copySize / (112 * 2));
                    if (sMapHeight > 156) sMapHeight = 156;
                }
                HUnlock(mapHdl);
                ReleaseResource(mapHdl);
            }

            /* Load RD (road overlay) resource */
            {
                Handle rdHdl = Get1Resource('RD  ', 10000);
                if (rdHdl != NULL) {
                    long rdSize = GetHandleSize(rdHdl);
                    HLock(rdHdl);
                    if (*gRoadData == 0)
                        *gRoadData = (pint)NewPtrClear(0x4440);
                    if (*gRoadData != 0) {
                        long copySize = rdSize;
                        if (copySize > 0x4440) copySize = 0x4440;
                        BlockMoveData(*rdHdl, (void *)*gRoadData, copySize);
                    }
                    HUnlock(rdHdl);
                    ReleaseResource(rdHdl);
                }
            }

            LoadScenarioItemPool();   /* FUN_10039180: the scenario's ITM 10000 */
            CloseResFile(refNum);

            /* Allocate extended state and run game initialization.
             * Guard against a garbage (non-heap) pointer too, not just 0 — a
             * duplicate gExtState definition (main.c vs core/globals.c) can leave
             * *gExtState holding a low-memory junk value (~0x40810000) that is
             * nonzero, which would otherwise skip the alloc and make GameInit
             * write the ext city records through a wild pointer (crash #6). */
            if (*gExtState == 0 || (unsigned long)*gExtState >= 0x10000000)
                *gExtState = (pint)NewPtrClear(0x4000);
            if (sMapLoaded && *gGameState != 0)
                GameInit();

#if 0  /* Progress bar 100% + delay disabled */
            {
                SetPort(scenWin);
                {
                    Rect fillR;
                    RGBColor barFg = {0x4444, 0x8888, 0xFFFF};
                    short fillW = (barRight - barLeft - 2);
                    SetRect(&fillR, barLeft + 1, barTop + 1, barLeft + 1 + fillW, barTop + barH - 1);
                    RGBForeColor(&barFg);
                    PaintRect(&fillR);
                }
                {
                    Rect clearR;
                    RGBColor white  = {0xFFFF, 0xFFFF, 0xFFFF};
                    SetRect(&clearR, 0, barTop + barH + 2, 460, barTop + barH + 20);
                    DrawMarbleBackground(&clearR);
                    RGBForeColor(&white);
                    TextFont(3); TextSize(10); TextFace(bold);
                    {
                        short tw = StringWidth("\p100%");
                        MoveTo((460 - tw) / 2, barTop + barH + 16);
                        DrawString("\p100%");
                    }
                }
            }
            {
                unsigned long endTick = TickCount() + 30;
                while (TickCount() < endTick) { /* busy-wait */ }
            }
#endif

            /* Reset viewport and force redraw */
            sViewportX = 0;
            sViewportY = 0;
            if (*gMainGameWindow != 0)
                InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
            if (*gOverviewWindow != 0)
                InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
        }
    }

    /* --- Random map generation path --- */
    if (loaded && useRandomMap) {
        /* The original's random-map setup dialog (View 3010, not in the
         * remake) ends with the helmet saying 'vmoment' ("One moment...")
         * before the map is generated (PPC FUN_10088724 -> FUN_10092c5c(0)). */
        HelmetVoice(SND_VMOMENT);
        /* Generate the random map (no loading screen visuals) */
        GenerateRandomMap(scenWin, barLeft, barRight, barTop, barH);

        if (*gMainGameWindow != 0)
            InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        if (*gOverviewWindow != 0)
            InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
    }
#if 0  /* Random map loading screen disabled */
    if (loaded && useRandomMap) {
        Rect r, barFrame, barFill;
        RGBColor gold     = {0xFFFF, 0xCCCC, 0x3333};
        RGBColor ltBlue   = {0xCCCC, 0xDDDD, 0xFFFF};
        RGBColor barBg    = {0x3333, 0x3333, 0x5555};
        RGBColor white    = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor framCol  = {0x8888, 0x8888, 0xAAAA};

        SetPort(scenWin);
        SetRect(&r, 0, 0, 460, 340);
        DrawMarbleBackground(&r);
        TextFont(2); TextSize(18); TextFace(bold);
        RGBForeColor(&gold);
        {
            short tw = StringWidth(GetCachedString(STR_MISC, 26, "\pGenerating Random Map"));
            MoveTo((460 - tw) / 2, 100);
            DrawString(GetCachedString(STR_MISC, 26, "\pGenerating Random Map"));
        }
        TextFont(3); TextSize(10); TextFace(0);
        RGBForeColor(&ltBlue);
        MoveTo(barLeft, barTop - 6);
        DrawString(GetCachedString(STR_MISC, 27, "\pCreating terrain and placing cities..."));
        {
            PicHandle borderPict = GetPicture(1011);
            if (borderPict != NULL) {
                Rect barBgRect;
                SetRect(&barBgRect, barLeft, barTop, barRight, barTop + barH);
                DrawPicture(borderPict, &barBgRect);
                KillPicture(borderPict);
            }
        }
        SetRect(&barFrame, barLeft, barTop, barRight, barTop + barH);
        RGBForeColor(&framCol); FrameRect(&barFrame);
        {
            RGBForeColor(&white);
            TextFont(3); TextSize(10); TextFace(bold);
            { short tw2 = StringWidth("\p0%"); MoveTo((460 - tw2) / 2, barTop + barH + 16); DrawString("\p0%"); }
        }
        GenerateRandomMap(scenWin, barLeft, barRight, barTop, barH);
        {
            Rect clearR;
            SetRect(&clearR, 0, barTop + barH + 2, 460, barTop + barH + 20);
            DrawMarbleBackground(&clearR);
            RGBForeColor(&white);
            TextFont(3); TextSize(10); TextFace(bold);
            { short tw3 = StringWidth("\p100%"); MoveTo((460 - tw3) / 2, barTop + barH + 16); DrawString("\p100%"); }
        }
        { unsigned long endTick = TickCount() + 30; while (TickCount() < endTick) {} }
        if (*gMainGameWindow != 0) InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        if (*gOverviewWindow != 0) InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
    }
#endif

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeWindow(scenWin);
    return loaded;
}


/* ===================================================================
 * ApplyOptionsPreset — Set all options to match the selected preset
 *
 * 0=Beginner, 1=Intermediate, 2=Advanced
 * =================================================================== */
static void ApplyOptionsPreset(short preset)
{
    sOptionsPreset = preset;
    switch (preset) {
    case 0: /* Beginner */
        sNeutralCities   = 0;
        sRazingCities    = 0;
        sOptQuests       = false;
        sOptViewEnemies  = true;
        sOptHiddenMap    = false;
        sOptDiplomacy    = false;
        sOptViewProd     = true;
        sOptIntenseCombat = false;
        sOptMilAdvisor   = true;
        sOptQuickStart   = false;
        sOptRandomTurns  = false;
        break;
    case 1: /* Intermediate (read off the original's View 3021 list) */
        sNeutralCities   = 1;
        sRazingCities    = 1;
        sOptQuests       = true;
        sOptViewEnemies  = false;
        sOptHiddenMap    = false;
        sOptDiplomacy    = true;
        sOptViewProd     = true;
        sOptIntenseCombat = true;
        sOptMilAdvisor   = true;
        sOptQuickStart   = false;
        sOptRandomTurns  = false;
        break;
    case 2: /* Advanced (read off the original's View 3021 list) */
        sNeutralCities   = 2;
        sRazingCities    = 2;
        sOptQuests       = true;
        sOptViewEnemies  = false;
        sOptHiddenMap    = true;
        sOptDiplomacy    = true;
        sOptViewProd     = false;
        sOptIntenseCombat = true;
        sOptMilAdvisor   = true;
        sOptQuickStart   = false;
        sOptRandomTurns  = false;
        break;
    }
}

/* The preset the current options equal (0 Beginner, 1 Intermediate,
 * 2 Advanced) or -1 = "Custom": the original (FUN_10059d30) compares the
 * eleven option words against its preset table after every edit and shows
 * "Custom" in the popup and the name field when none matches. */
static short MatchingOptionsPreset(void)
{
    short bkPreset = sOptionsPreset, bkNeutral = sNeutralCities, bkRazing = sRazingCities;
    Boolean bkQ = sOptQuests, bkVE = sOptViewEnemies, bkH = sOptHiddenMap, bkD = sOptDiplomacy,
            bkVP = sOptViewProd, bkI = sOptIntenseCombat, bkM = sOptMilAdvisor,
            bkQS = sOptQuickStart, bkR = sOptRandomTurns;
    short p, match = -1;
    for (p = 0; p < 3 && match < 0; p++) {
        ApplyOptionsPreset(p);
        if (sNeutralCities == bkNeutral && sRazingCities == bkRazing && sOptQuests == bkQ &&
            sOptViewEnemies == bkVE && sOptHiddenMap == bkH && sOptDiplomacy == bkD &&
            sOptViewProd == bkVP && sOptIntenseCombat == bkI && sOptMilAdvisor == bkM &&
            sOptQuickStart == bkQS && sOptRandomTurns == bkR)
            match = p;
    }
    sOptionsPreset = bkPreset; sNeutralCities = bkNeutral; sRazingCities = bkRazing;
    sOptQuests = bkQ; sOptViewEnemies = bkVE; sOptHiddenMap = bkH; sOptDiplomacy = bkD;
    sOptViewProd = bkVP; sOptIntenseCombat = bkI; sOptMilAdvisor = bkM;
    sOptQuickStart = bkQS; sOptRandomTurns = bkR;
    return match;
}

/* The original's option words (FUN_1005a6ac copies the eleven-entry option
 * array into the game state at Begin Game; the Edit Options dialog
 * FUN_1008c8f8 fills the array):
 *   gs+0x11A neutral cities 0 Average / 1 Strong / 2 Active
 *   gs+0x11C diplomacy      gs+0x11E quests        gs+0x124 hidden map
 *   gs+0x12A view enemies   gs+0x132 = 1 when View Production is OFF
 *   gs+0x114 razing 0xF Always / 1 On Capture / 0 Never
 *   gs+0x126 intense combat gs+0x128 quick start   gs+0x12C military advisor
 *   gs+0x122 random turns   gs+0x116 "I am the Greatest" (FUN_1005aac8)
 *   gs+0x130 = 0 */
static void WriteOptionsToGameState(unsigned char *gs)
{
    static const short kRazeCode[3] = {0x0F, 1, 0};   /* Always, On Capture, Never */
    *(short *)(gs + 0x11a) = sNeutralCities;
    *(short *)(gs + 0x11c) = sOptDiplomacy ? 1 : 0;
    *(short *)(gs + 0x11e) = sOptQuests ? 1 : 0;
    *(short *)(gs + 0x124) = sOptHiddenMap ? 1 : 0;
    *(short *)(gs + 0x12a) = sOptViewEnemies ? 1 : 0;
    *(short *)(gs + 0x132) = sOptViewProd ? 0 : 1;
    *(short *)(gs + 0x114) = kRazeCode[(sRazingCities >= 0 && sRazingCities < 3) ? sRazingCities : 0];
    *(short *)(gs + 0x126) = sOptIntenseCombat ? 1 : 0;   /* the battle die (FUN_1002d654) */
    *(short *)(gs + 0x128) = sOptQuickStart ? 1 : 0;      /* quick start (FUN_1003b9f8) */
    *(short *)(gs + 0x12c) = sOptMilAdvisor ? 1 : 0;
    *(short *)(gs + 0x122) = sOptRandomTurns ? 1 : 0;
    *(short *)(gs + 0x116) = sIAmGreatest ? 1 : 0;
    *(short *)(gs + 0x130) = 0;
}

/* The Options popup (CMNU 70: Beginner, Intermediate, Advanced). While
 * the words match no preset the original appends a separator and a
 * "Custom" item and shows that one (seen on the original after editing
 * Quests on Beginner). */
static void SyncPresetMenu(MenuHandle m)
{
    short n = CountMItems(m), want = MatchingOptionsPreset() < 0 ? 5 : 3;
    while (n > want) { DeleteMenuItem(m, n); n--; }
    if (want == 5 && n == 3) { AppendMenu(m, "\p(-"); AppendMenu(m, "\pCustom"); }
}

static short PresetMenuItem(void)   /* the 1-based item shown / checked */
{
    short p = MatchingOptionsPreset();
    return p < 0 ? 5 : p + 1;
}


/* ===================================================================
 * CalcDifficultyRating — Returns difficulty percentage (0-100)
 *
 * Weighted sum of option values.
 * =================================================================== */
/* Options term of the 68k rating (CODE_057 FUN_0000482a): 3 x four option
 * flags, minus one, plus one, plus the neutral-cities code (gs+0x114:
 * 15 = +0, 1 = +3, 0 = +6), capped at 20. Default (Beginner) = -1.
 * PROVISIONAL: which remake options are the four x3 flags (gs+0x11A, 0x11C,
 * 0x11E, 0x124) and the -1/+1 ones (0x12A, 0x132) still has to be mapped
 * from View 3021; this mapping reproduces Beginner's -1. */
static short DifficultyOptionsTerm(void)
{
    /* PPC FUN_100584c8: 3 x (neutral code 0/1/2 + diplomacy + quests +
     * hidden map) - view enemies + (view production OFF), + 6 when razing
     * is Never (code 0), + 3 when On Capture (code 1), nothing for Always
     * (0xF); capped at 20. Beginner = -1 (Erythea opens at 79%). */
    short opt = 3 * (sNeutralCities + (sOptDiplomacy ? 1 : 0) + (sOptQuests ? 1 : 0) +
                     (sOptHiddenMap ? 1 : 0))
                - (sOptViewEnemies ? 1 : 0) + (sOptViewProd ? 0 : 1);
    if (sRazingCities == 1) opt += 3;          /* On Capture */
    else if (sRazingCities == 2) opt += 6;     /* Never */
    return opt > 19 ? 20 : opt;
}

/* Full 68k rating with every AI at 'skillLevel' (0 Knight, 1 Lord, 2 Warlord =
 * the gs+0xC0 level): each AI adds (level+1)*80/(count*3), >77 -> 80; with no
 * AI players the AI term is 80. Verified on the original: Erythea opens at 79%
 * (its SCN has no AI players yet), Knight 25%, Lord 52%. */
static short CalcDifficultyRating(short skillLevel)
{
    short ai = (short)(((long)(skillLevel + 1) * 80) / 3);
    if (ai > 77) ai = 80;
    return DifficultyOptionsTerm() + ai;
}

static short CalcDifficultyRatingNoAI(void)
{
    return DifficultyOptionsTerm() + 80;
}

/* The same rating over the per-side levels of View 3020: every computer
 * side adds (level+1)*80/(count*3); no computer side at all gives 80. */
static short CalcDifficultyRatingSides(void)
{
    long sum = 0;
    short i, n = 0, ai;
    for (i = 0; i < MAX_FACTIONS; i++)
        if (sFactionAI[i] >= 1 && sFactionAI[i] <= 3) { sum += (long)sFactionAI[i] * 80; n++; }
    ai = n ? (short)(sum / (n * 3)) : 80;
    if (ai > 77) ai = 80;
    return DifficultyOptionsTerm() + ai;
}


/* ===================================================================
 * MacApp "3D" look helpers (pixel-verified against the original on 8.6)
 * =================================================================== */

/* Embossed text: 0x4444 at (x,y), 0xAAAA at (x+2,y+2), colour at (x+1,y+1).
 * Used for cluster titles, radio/check labels and sunken texts. */
static void DrawEmbossedStringIn(ConstStr255Param s, short x, short baseline, const RGBColor *fg,
                                 unsigned short darkV, unsigned short lightV)
{
    RGBColor dark = {darkV, darkV, darkV}, light = {lightV, lightV, lightV};
    /* each shadow layer is smeared one pixel to the right (drawn twice, so the
     * advance widths stay plain); the face is plain -- measured on every
     * embossed label of the original */
    RGBForeColor(&light); MoveTo(x + 1, baseline + 2); DrawString(s);
                          MoveTo(x + 2, baseline + 2); DrawString(s);
    RGBForeColor(&dark);  MoveTo(x, baseline);         DrawString(s);
                          MoveTo(x + 1, baseline);     DrawString(s);
    RGBForeColor(fg);     MoveTo(x + 1, baseline + 1); DrawString(s);
}

/* Labels and sunken texts: dark 0x4444, light 0xAAAA. Other MacApp elements
 * use the same three layers with their own pair (cluster titles 0x5555/0xBBBB,
 * button labels 0x8888/0xDDDD), all measured on the original. */
static void DrawEmbossedString(ConstStr255Param s, short x, short baseline, const RGBColor *fg)
{
    DrawEmbossedStringIn(s, x, baseline, fg, 0x4444, 0xAAAA);
}

static short IlluriaFont(void)
{
    short f;
    GetFNum("\pIlluria", &f);
    return f ? f : 1602;
}

static short ChicagoFont(void)
{
    short f;
    GetFNum("\pChicago", &f);
    return f;
}

/* T3DCluster: 2px cream frame inset (8 top, 4 left, 2 right/bottom) from the
 * view rect, broken at the top by an embossed (0x5555/0xBBBB) cream Illuria 17
 * title drawn 16px in;
 * the line resumes 13px past the title's pen end (measured on all three
 * clusters of View 3024). */
static void DrawT3DClusterColor(const Rect *v, ConstStr255Param title, const RGBColor *col)
{
    Rect f;
    short tx, tw;
    FontInfo fi;

    SetRect(&f, v->left + 4, v->top + 8, v->right - 2, v->bottom - 2);
    TextFont(IlluriaFont()); TextSize(17); TextFace(0);
    GetFontInfo(&fi);
    tw = StringWidth(title);
    tx = f.left + 16;
    {
        RGBColor frame = *col;
        RGBForeColor(&frame);
    }
    PenSize(2, 2);
    MoveTo(f.left, f.top); LineTo(tx - 4, f.top);                 /* top, left of title */
    MoveTo(tx + tw + 13, f.top); LineTo(f.right - 2, f.top);      /* resumes 13px past the title */
    MoveTo(f.left, f.top); LineTo(f.left, f.bottom - 2);          /* left */
    MoveTo(f.left, f.bottom - 2); LineTo(f.right - 2, f.bottom - 2);  /* bottom */
    MoveTo(f.right - 2, f.top); LineTo(f.right - 2, f.bottom - 2);    /* right */
    PenSize(1, 1);
    {   /* the frame is embossed like the title (measured on Views 3024/3020):
         * 0x5555 outside top/left and inside bottom/right, 0xBBBB inside
         * top/left and outside bottom/right, broken under the title too */
        RGBColor dark = {0x5555, 0x5555, 0x5555}, light = {0xBBBB, 0xBBBB, 0xBBBB};
        RGBForeColor(&dark);
        MoveTo(f.left - 1, f.top - 1); LineTo(tx - 3, f.top - 1);
        MoveTo(tx + tw + 12, f.top - 1); LineTo(f.right - 1, f.top - 1);
        MoveTo(f.left - 1, f.top - 1); LineTo(f.left - 1, f.bottom - 1);
        MoveTo(f.left + 2, f.bottom - 3); LineTo(f.right - 3, f.bottom - 3);
        MoveTo(f.right - 3, f.top + 2); LineTo(f.right - 3, f.bottom - 3);
        RGBForeColor(&light);
        MoveTo(f.left + 2, f.top + 2); LineTo(tx - 2, f.top + 2);
        MoveTo(tx + tw + 13, f.top + 2); LineTo(f.right - 4, f.top + 2);
        MoveTo(f.left + 2, f.top + 2); LineTo(f.left + 2, f.bottom - 4);
        MoveTo(f.left, f.bottom); LineTo(f.right, f.bottom);
        MoveTo(f.right, f.top); LineTo(f.right, f.bottom);
    }
    DrawEmbossedStringIn(title, tx, v->top + fi.ascent, col, 0x5555, 0xBBBB);
}

/* The default cream cluster (View 3024); View 3020 frames each side's
 * cluster in the side's colour through DrawT3DClusterColor. */
static void DrawT3DCluster(const Rect *v, ConstStr255Param title)
{
    RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
    DrawT3DClusterColor(v, title, &cream);
}

/* Centred / left / right embossed text in a TSunkenText view rect. */
static void DrawSunkenTextColor(const Rect *v, ConstStr255Param s, short font, short size,
                                short just, const RGBColor *fg)
{
    FontInfo fi;
    short w, x;
    TextFont(font); TextSize(size); TextFace(0);
    GetFontInfo(&fi);
    w = StringWidth(s);
    x = (just == 1) ? (v->left + v->right - w + 1) / 2 : (just == -1 ? v->right - w : v->left);
    DrawEmbossedString(s, x, v->top + fi.ascent, fg);
}

static void DrawSunkenText(const Rect *v, ConstStr255Param s, short font, short size, short just)
{
    RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
    DrawSunkenTextColor(v, s, font, size, just, &cream);
}

