static void DrawPaletteArt(const short *art, short w, short h, short x, short y)
{
    short i, j;
    RGBColor c;
    for (j = 0; j < h; j++)
        for (i = 0; i < w; i++) {
            short idx = art[j * w + i];
            if (idx < 0 || sGamePal == NULL) continue;
            GetEntryColor(sGamePal, idx, &c);
            SetCPixel(x + i, y + j, &c);
        }
}

/* MacApp T3DCheckBox, measured on the original: 12x12 black square filled
 * 0xDDDD at (left+2,top+2), in a 1px bevel dark 0x5555 above/left and light
 * 0xBBBB below/right. */
static void DrawT3DCheckBox(short left, short top, Boolean on)
{
    RGBColor dark = {0x5555, 0x5555, 0x5555}, light = {0xBBBB, 0xBBBB, 0xBBBB};
    RGBColor fill = {0xDDDD, 0xDDDD, 0xDDDD}, black = {0, 0, 0};
    Rect b;
    RGBForeColor(&dark);
    MoveTo(left + 1, top + 14); LineTo(left + 1, top + 1); LineTo(left + 14, top + 1);
    RGBForeColor(&light);
    MoveTo(left + 2, top + 14); LineTo(left + 14, top + 14); LineTo(left + 14, top + 2);
    SetRect(&b, left + 2, top + 2, left + 14, top + 14);
    RGBForeColor(&black); FrameRect(&b);
    InsetRect(&b, 1, 1);
    RGBForeColor(&fill); PaintRect(&b);
    if (on) {   /* corner-to-corner X across the 10x10 interior (captured) */
        RGBForeColor(&black);
        MoveTo(b.left, b.top); LineTo(b.right - 1, b.bottom - 1);
        MoveTo(b.right - 1, b.top); LineTo(b.left, b.bottom - 1);
    }
}

#include "mac_ui_art.h"

/* T3DPopup: frame art from the original plus the current item in Chicago 12. */
static void DrawT3DPopup(short left, short top, ConstStr255Param item)
{
    short i, j;
    RGBColor c, black = {0, 0, 0};
    for (j = 0; j < POPUP_ART_H; j++)
        for (i = 0; i < POPUP_ART_W; i++) {
            if (sGamePal == NULL) break;
            GetEntryColor(sGamePal, kPopupArt[j][i], &c);
            SetCPixel(left + i, top + j, &c);
        }
    TextFont(0);   /* the system font: the original's popup label is smoothed and spaced like the list text */ TextSize(12); TextFace(0);
    RGBForeColor(&black);
    {   /* the original clips the item to the text area (cuts the 'g' tail) */
        Rect clip;
        RgnHandle saved = NewRgn();
        GetClip(saved);
        SetRect(&clip, left + 4, top + 3, left + 105, top + 15);
        ClipRect(&clip);
        MoveTo(left + 6, top + 13);
        DrawString(item);
        SetClip(saved);
        DisposeRgn(saved);
    }
}

static void DrawT3DRadio(short left, short top, Boolean on)
{
    DrawPaletteArt(on ? &kRadioOn[0][0] : &kRadioOff[0][0], 12, 12, left + 2, top + 2);
}

/* ===================================================================
 * ShowEditOptions — View 3021 "Game Options" (the original's Edit
 * Options dialog). 512x352 altDBoxProc window: PICT 1001 marble at
 * (7,7) inside the frame PICTs 1004 (top), 1005 (left), 1006 (bottom)
 * and 1008 (right), in MacApp's alert position (a third of the way
 * down; (253,150) on the original at 1024x768). Left column: the
 * setting list (Beginner / Intermediate / Advanced in a TScroller frame
 * measured on the original, 18px Chicago 12 rows, 0xDADAFF highlight),
 * Delete Setting, the name field (the setting's name, or "Custom" while
 * the words match no preset — then Create New Setting carries the
 * default ring instead of OK), Create New Setting, Cancel, OK. Right:
 * the 'affe' cluster (Neutral Cities / Razing Cities radios, Quests,
 * View Enemies, Hidden Map, Diplomacy, View Production) and the 'nota'
 * cluster (Intense Combat, Military Advisor, Quick Start, Random Turns).
 * Positions are the View record's (v,h); strings STR# 3021. OK keeps the
 * edited words (the popup then shows the matching preset or "Custom"),
 * Cancel restores them. Not implemented: saving / deleting named
 * settings ('new ' / 'dele' draw as on the original but do nothing).
 * =================================================================== */
#define GOPT_W 512
#define GOPT_H 352
static void DrawT3DButtonDisabled(const Rect *r, ConstStr255Param label);   /* defined with View 3020 below */
static void DrawDimLabel(ConstStr255Param s, short x, short baseline);
static Boolean SetupSlotUnused(char names[][FACTION_NAME_LEN + 1], short factionCount, short i);
static void ShowEditOptions(void)
{
    WindowPtr win;
    Rect wr, r;
    short i, result = -1, mbar = GetMBarHeight();
    Rect screen = qd.screenBits.bounds;
    ControlHandle vScroll;
    Str255 s;
    short   bkPreset = sOptionsPreset, bkNeutral = sNeutralCities, bkRazing = sRazingCities;
    Boolean bkQ = sOptQuests, bkVE = sOptViewEnemies, bkH = sOptHiddenMap, bkD = sOptDiplomacy,
            bkVP = sOptViewProd, bkI = sOptIntenseCombat, bkM = sOptMilAdvisor,
            bkQS = sOptQuickStart, bkR = sOptRandomTurns;
    static const short kNeutLbl[3] = {4, 5, 6};        /* Average, Strong, Active (neu1..neu3) */
    static const short kRazeLbl[3] = {8, 9, 10};       /* Always, On Capture, Never (raz3, raz2, raz1) */
    static const unsigned char *kPresetName[3] = {"\pBeginner", "\pIntermediate", "\pAdvanced"};
    struct { short v, h, str; Boolean *val; } checks[9];
    Rect listR, nameR, deleR, newR, cancR, okR, okBtn;

    /* 'affe' (73,194): ques (91,14) vene (112,14) hidd (133,14) dipl (91,150) vpro (112,150);
     * 'nota' (249,194): intn (22,14) mili (43,14) quic (22,150) rand (43,150) */
    checks[0].v = 73 + 91;   checks[0].h = 194 + 14;  checks[0].str = 3;  checks[0].val = &sOptQuests;
    checks[1].v = 73 + 112;  checks[1].h = 194 + 14;  checks[1].str = 12; checks[1].val = &sOptViewEnemies;
    checks[2].v = 73 + 133;  checks[2].h = 194 + 14;  checks[2].str = 13; checks[2].val = &sOptHiddenMap;
    checks[3].v = 73 + 91;   checks[3].h = 194 + 150; checks[3].str = 14; checks[3].val = &sOptDiplomacy;
    checks[4].v = 73 + 112;  checks[4].h = 194 + 150; checks[4].str = 15; checks[4].val = &sOptViewProd;
    checks[5].v = 249 + 22;  checks[5].h = 194 + 14;  checks[5].str = 18; checks[5].val = &sOptIntenseCombat;
    checks[6].v = 249 + 43;  checks[6].h = 194 + 14;  checks[6].str = 20; checks[6].val = &sOptMilAdvisor;
    checks[7].v = 249 + 22;  checks[7].h = 194 + 150; checks[7].str = 19; checks[7].val = &sOptQuickStart;
    checks[8].v = 249 + 43;  checks[8].h = 194 + 150; checks[8].str = 17; checks[8].val = &sOptRandomTurns;

    SetRect(&wr, (screen.right - (GOPT_W + 2)) / 2 - 2,
            mbar + (screen.bottom - mbar - (GOPT_H + 2)) / 3 - 1, 0, 0);
    wr.right = wr.left + GOPT_W; wr.bottom = wr.top + GOPT_H;
    win = NewCWindow(NULL, &wr, "\p", false, altDBoxProc, (WindowPtr)-1L, false, 0);
    if (win == NULL) return;
    ApplyGamePalette(win);
    SetPort(win);
    TextFont(ChicagoFont()); TextSize(12);

    SetRect(&listR, 20, 75, 158, 187);          /* 'Scrl' 112x138 at (75,20) */
    SetRect(&r, 158, 74, 174, 188);             /* 'vScr' 114x16, inactive */
    vScroll = NewControl(win, &r, "\p", true, 0, 0, 0, scrollBarProc, 0);
    SetRect(&nameR, 18, 233, 175, 255);         /* 'name' (233,18) 22x157 */
    SetRect(&deleR, 26, 200, 167, 220);         /* 'dele' (measured) */
    SetRect(&newR,  26, 267, 167, 287);         /* 'new ' (267,26) 20x141 */
    SetRect(&cancR, 26, 300, 90, 320);          /* 'canc' (300,26) 20x64 */
    SetRect(&okR,   99, 296, 171, 324);         /* 'ok  ' (296,99) 28x72 */
    okBtn = okR; InsetRect(&okBtn, 4, 4);

    ShowWindow(win);
    FlushEvents(everyEvent, 0);

    while (result < 0) {
        EventRecord evt;
        if (!WaitNextEvent(everyEvent, &evt, 30, NULL)) continue;
        if (evt.what == updateEvt && (WindowPtr)evt.message == win) {
            RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC}, hil = {0xDADA, 0xDADA, 0xFFFF};
            RGBColor g96 = {0x9696, 0x9696, 0x9696}, g88 = {0x8888, 0x8888, 0x8888};
            RGBColor g66 = {0x6666, 0x6666, 0x6666}, gC0 = {0xC0C0, 0xC0C0, 0xC0C0};
            short match = MatchingOptionsPreset();
            SetPort(win);
            BeginUpdate(win);
            {
                PicHandle p;
                RgnHandle saved = NewRgn();
                GetClip(saved);
                SetRect(&r, 7, 7, GOPT_W - 7, GOPT_H - 7); ClipRect(&r);
                p = GetPicture(1001);
                if (p != NULL) { Rect pf = (**p).picFrame; OffsetRect(&pf, 7 - pf.left, 7 - pf.top); DrawPicture(p, &pf); }
                SetClip(saved); DisposeRgn(saved);
                p = GetPicture(1004);
                if (p != NULL) { Rect pf = (**p).picFrame; OffsetRect(&pf, -pf.left, -pf.top); DrawPicture(p, &pf); }
                p = GetPicture(1005);
                if (p != NULL) { Rect pf = (**p).picFrame; OffsetRect(&pf, -pf.left, 7 - pf.top); DrawPicture(p, &pf); }
                p = GetPicture(1006);
                if (p != NULL) { Rect pf = (**p).picFrame; OffsetRect(&pf, -pf.left, GOPT_H - 7 - pf.top); DrawPicture(p, &pf); }
                p = GetPicture(1008);
                if (p != NULL) { Rect pf = (**p).picFrame; OffsetRect(&pf, GOPT_W - 7 - pf.left, -pf.top); DrawPicture(p, &pf); }
            }
            SetRect(&r, 7, 21, GOPT_W - 7, 61);
            DrawSunkenText(&r, ViewString(s, 3021, 11, "\pGame Options"), IlluriaFont(), 36, 1);

            /* the TScroller frame round the setting list */
            RGBForeColor(&g96); SetRect(&r, 14, 69, 179, 193); FrameRect(&r);
            RGBForeColor(&black); SetRect(&r, 15, 70, 178, 192); PenSize(2, 2); FrameRect(&r); PenSize(1, 1);
            RGBForeColor(&g88); MoveTo(17, 190); LineTo(17, 72); LineTo(176, 72);
            MoveTo(18, 190); LineTo(176, 190); LineTo(176, 73);
            RGBForeColor(&g66); MoveTo(18, 189); LineTo(18, 73); LineTo(175, 73);
            RGBForeColor(&gC0); MoveTo(19, 189); LineTo(175, 189); LineTo(175, 74);
            RGBForeColor(&black); SetRect(&r, 19, 74, 175, 189); FrameRect(&r);
            RGBForeColor(&white); PaintRect(&listR);
            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            for (i = 0; i < 3; i++) {
                SetRect(&r, listR.left, listR.top + 18 * i, listR.right, listR.top + 18 * i + 18);
                if (i == match) { RGBForeColor(&hil); PaintRect(&r); }
                RGBForeColor(&black);
                MoveTo(listR.left + 3, listR.top + 18 * i + 13);
                DrawString(kPresetName[i]);
            }
            DrawControls(win);

            DrawT3DButtonDisabled(&deleR, ViewString(s, 3021, 23, "\pDelete Setting"));
            /* the name field: sunken 1px bevel round a black-framed white box */
            RGBForeColor(&g66);
            MoveTo(nameR.left, nameR.bottom - 2); LineTo(nameR.left, nameR.top); LineTo(nameR.right - 2, nameR.top);
            RGBForeColor(&gC0);
            MoveTo(nameR.left + 1, nameR.bottom - 1); LineTo(nameR.right - 1, nameR.bottom - 1); LineTo(nameR.right - 1, nameR.top + 1);
            SetRect(&r, nameR.left + 1, nameR.top + 1, nameR.right - 1, nameR.bottom - 1);
            RGBForeColor(&black); FrameRect(&r);
            InsetRect(&r, 1, 1); RGBForeColor(&white); PaintRect(&r);
            RGBForeColor(&black); TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            MoveTo(r.left + 3, r.top + 13);
            DrawString(match >= 0 ? kPresetName[match] : (ConstStr255Param)"\pCustom");
            DrawT3DButton(&newR, ViewString(s, 3021, 24, "\pCreate New Setting"));

            SetRect(&r, 194, 73, 194 + 301, 73 + 162);                 /* 'affe' */
            DrawT3DCluster(&r, ViewString(s, 3021, 2, "\pAffecting Difficulty"));
            SetRect(&r, 194, 249, 194 + 301, 249 + 72);                /* 'nota' */
            DrawT3DCluster(&r, ViewString(s, 3021, 16, "\pNot Affecting Difficulty"));
            SetRect(&r, 194 + 14, 73 + 21, 194 + 14 + 95, 73 + 21 + 16);
            DrawSunkenText(&r, ViewString(s, 3021, 1, "\pNeutral Cities"), ChicagoFont(), 12, 0);
            SetRect(&r, 194 + 150, 73 + 21, 194 + 150 + 95, 73 + 21 + 16);
            DrawSunkenText(&r, ViewString(s, 3021, 7, "\pRazing Cities"), ChicagoFont(), 12, 0);
            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            for (i = 0; i < 3; i++) {   /* 'neut' (36,24) / 'razi' (36,160) in 'affe', radios (1+17i, 1) */
                DrawT3DRadio(194 + 24 + 1, 73 + 36 + 1 + 17 * i, i == sNeutralCities);
                DrawEmbossedString(ViewString(s, 3021, kNeutLbl[i], "\p"), 194 + 24 + 1 + 17,
                                   73 + 36 + 1 + 17 * i + 11, &cream);
                DrawT3DRadio(194 + 160 + 1, 73 + 36 + 1 + 17 * i, i == sRazingCities);
                DrawEmbossedString(ViewString(s, 3021, kRazeLbl[i], "\p"), 194 + 160 + 1 + 17,
                                   73 + 36 + 1 + 17 * i + 11, &cream);
            }
            for (i = 0; i < 9; i++) {
                DrawT3DCheckBox(checks[i].h, checks[i].v, *checks[i].val);
                DrawEmbossedString(ViewString(s, 3021, checks[i].str, "\p"), checks[i].h + 17,
                                   checks[i].v + 11, &cream);
            }

            DrawT3DButton(&cancR, ViewString(s, 3010, 2, "\pCancel"));
            RGBForeColor(&black);
            PenSize(3, 3);
            if (match >= 0) FrameRoundRect(&okR, 16, 16);
            else { r = newR; InsetRect(&r, -4, -4); FrameRoundRect(&r, 16, 16); }
            PenSize(1, 1);
            DrawT3DButton(&okBtn, ViewString(s, 3010, 1, "\pOK"));
            EndUpdate(win);
        } else if (evt.what == mouseDown) {
            WindowPtr hit;
            Point pt = evt.where;
            Rect rr;
            if (FindWindow(pt, &hit) != inContent || hit != win) continue;
            GlobalToLocal(&pt);
            for (i = 0; i < 3; i++) {
                SetRect(&rr, listR.left, listR.top + 18 * i, listR.right, listR.top + 18 * i + 18);
                if (PtInRect(pt, &rr)) { ApplyOptionsPreset(i); InvalRect(&win->portRect); }
                SetRect(&rr, 194 + 24 + 1, 73 + 36 + 1 + 17 * i, 194 + 24 + 1 + 120, 73 + 36 + 1 + 17 * i + 16);
                if (PtInRect(pt, &rr)) { sNeutralCities = i; InvalRect(&win->portRect); }
                SetRect(&rr, 194 + 160 + 1, 73 + 36 + 1 + 17 * i, 194 + 160 + 1 + 120, 73 + 36 + 1 + 17 * i + 16);
                if (PtInRect(pt, &rr)) { sRazingCities = i; InvalRect(&win->portRect); }
            }
            for (i = 0; i < 9; i++) {
                SetRect(&rr, checks[i].h, checks[i].v, checks[i].h + 130, checks[i].v + 16);
                if (PtInRect(pt, &rr)) { *checks[i].val = !*checks[i].val; InvalRect(&win->portRect); }
            }
            if (PtInRect(pt, &okR)) result = 1;
            else if (PtInRect(pt, &cancR)) result = 0;
        } else if (evt.what == keyDown) {
            char key = evt.message & charCodeMask;
            if (key == 0x0D || key == 0x03) result = 1;
            else if (key == 0x1B) result = 0;
        }
    }

    if (result == 1) {
        /* OK: the popup follows the edited words (a preset, or "Custom") */
        sOptionsPreset = MatchingOptionsPreset();
    } else {
        sOptionsPreset = bkPreset; sNeutralCities = bkNeutral; sRazingCities = bkRazing;
        sOptQuests = bkQ; sOptViewEnemies = bkVE; sOptHiddenMap = bkH; sOptDiplomacy = bkD;
        sOptViewProd = bkVP; sOptIntenseCombat = bkI; sOptMilAdvisor = bkM;
        sOptQuickStart = bkQS; sOptRandomTurns = bkR;
    }
    DisposeControl(vScroll);
    DisposeWindow(win);
}


/* ===================================================================
 * RunEasyGameSetup — View 3024 "Easy game setup" (the original's default
 * Game Setup). 353x286 altDBoxProc window centred below the menu bar.
 * Radios, checkbox and popup are real Control Manager controls: on 8.6 the
 * original's T3D controls are the Appearance (Platinum) CDEFs with labels
 * drawn embossed by MacApp. Returns 0 = Begin Game, 1 = More Choices,
 * 2 = cancelled (Escape).
 * =================================================================== */
#define EASY_W 353
#define EASY_H 286
static short RunEasyGameSetup(char names[][FACTION_NAME_LEN + 1], short factionCount,
                              short *side, short *skill, Boolean aiPreset)
{
    WindowPtr win;
    Rect wr, r;
    short i, result = -1, mbar = GetMBarHeight();
    Rect screen = qd.screenBits.bounds;
    MenuHandle presetMenu;
    Rect editR, moreR, goR, goBtn, popR;
    Str255 s;
    static const short compStr[3] = {13, 14, 5};   /* STR# 3020: Knight, Lord, Warlord */
    /* The rating counts the game state's AI players: none until a side /
     * level radio is clicked, but Fewer Choices comes back with the sides
     * assigned (the original shows 25% then, verified on Isles of Sorcery). */
    Boolean aiAssigned = aiPreset;

    /* MacApp centres the window including altDBoxProc's 2px shadow */
    SetRect(&wr, (screen.right - (EASY_W + 2)) / 2, mbar + (screen.bottom - mbar - (EASY_H + 2)) / 2, 0, 0);
    wr.right = wr.left + EASY_W; wr.bottom = wr.top + EASY_H;
    win = NewCWindow(NULL, &wr, "\p", false, altDBoxProc, (WindowPtr)-1L, false, 0);
    if (win == NULL) return 2;
    ApplyGamePalette(win);
    SetPort(win);
    TextFont(ChicagoFont()); TextSize(12);     /* control titles / popup use the window font */


    presetMenu = NewMenu(240, "\p");                 /* CMNU 70 items */
    AppendMenu(presetMenu, "\pBeginner;Intermediate;Advanced");
    InsertMenu(presetMenu, -1);
    SetRect(&popR, 179 + 16, 132 + 20, 179 + 16 + 132, 132 + 20 + 19);   /* 'popu' */

    SetRect(&editR, 179 + 16, 132 + 49, 179 + 16 + 132, 132 + 49 + 21);
    SetRect(&moreR, 13, 252, 13 + 132, 252 + 21);
    SetRect(&goR, 204, 248, 204 + 140, 248 + 29);
    goBtn = goR; InsetRect(&goBtn, 4, 4);

    ShowWindow(win);
    FlushEvents(everyEvent, 0);

    while (result < 0) {
        EventRecord evt;
        if (!WaitNextEvent(everyEvent, &evt, 30, NULL)) continue;
        if (evt.what == updateEvt && (WindowPtr)evt.message == win) {
            RGBColor black = {0, 0, 0};
            BeginUpdate(win);
            {   /* TPlainPicture: PICT 1001 marble at the origin */
                PicHandle marble = GetPicture(1001);
                if (marble != NULL) {
                    Rect pf = (**marble).picFrame;
                    OffsetRect(&pf, -pf.left, -pf.top);
                    DrawPicture(marble, &pf);
                }
            }
            SetRect(&r, 0, 8, EASY_W, 48);
            DrawSunkenText(&r, ViewString(s, 3010, 20, "\pGame setup"), IlluriaFont(), 36, 1);

            SetRect(&r, 9, 48, 9 + 162, 48 + 166);
            DrawT3DCluster(&r, ViewString(s, 3020, 11, "\pSide to play"));
            SetRect(&r, 179, 48, 179 + 162, 48 + 81);
            DrawT3DCluster(&r, ViewString(s, 3020, 12, "\pComputer Level"));
            SetRect(&r, 179, 132, 179 + 162, 132 + 108);
            DrawT3DCluster(&r, ViewString(s, 3020, 4, "\pOptions"));

            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            for (i = 0; i < factionCount && i < MAX_FACTIONS; i++) {
                Rect sh;
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                short n = 0;
                if (SetupSlotUnused(names, factionCount, i)) {
                    /* a "Not used" side (Isles of Sorcery): no shield, a dimmed
                     * radio and the dim "Not used" label, not selectable */
                    RGBColor frame = {0x8888, 0x8888, 0x8888}, fill = {0xDDDD, 0xDDDD, 0xDDDD};
                    SetRect(&sh, 9 + 22 + 2, 48 + 20 + 17 * i + 2, 9 + 22 + 14, 48 + 20 + 17 * i + 14);
                    RGBForeColor(&fill); PaintOval(&sh);
                    RGBForeColor(&frame); FrameOval(&sh);
                    DrawDimLabel("\pNot used", 9 + 22 + 17, 48 + 20 + 17 * i + 11);
                    continue;
                }
                SetRect(&sh, 9 + 11, 48 + 21 + 17 * i, 9 + 11 + 11, 48 + 21 + 17 * i + 14);
                DrawSmallShieldIcon(i, &sh);           /* TPicCopyView, native 11x14 */
                DrawT3DRadio(9 + 22, 48 + 20 + 17 * i, i == *side);
                while (n < FACTION_NAME_LEN && names[i][n]) n++;
                s[0] = (unsigned char)n; BlockMoveData(names[i], s + 1, n);
                DrawEmbossedString(s, 9 + 22 + 17, 48 + 20 + 17 * i + 11, &cream);
            }
            for (i = 0; i < 3; i++) {
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                DrawT3DRadio(179 + 14, 48 + 20 + 17 * i, i == *skill);
                DrawEmbossedString(ViewString(s, 3020, compStr[i], "\p"), 179 + 14 + 17,
                                   48 + 20 + 17 * i + 11, &cream);
            }
            {
                RGBColor cream = {0xFFFF, 0xFFFF, 0xCCCC};
                DrawT3DCheckBox(179 + 14, 132 + 80, sIAmGreatest);
                DrawEmbossedString(ViewString(s, 3020, 2, "\pI am the Greatest"), 179 + 14 + 17,
                                   132 + 80 + 11, &cream);
            }
            {
                Str255 num, line;
                /* The original rates the game state's AI players: none until a
                 * side / level radio is clicked (SCNs ship without AIs). */
                short rating = aiAssigned ? CalcDifficultyRating(*skill) : CalcDifficultyRatingNoAI();
                NumToString((long)rating, num);
                BlockMoveData("\pDifficulty Rating ", line, 19);
                BlockMoveData(num + 1, line + 1 + line[0], num[0]); line[0] += num[0];
                line[++line[0]] = '%';
                SetRect(&r, 10, 220, 10 + 162, 220 + 19);
                DrawSunkenText(&r, line, IlluriaFont(), 17, 1);
            }
            DrawT3DButton(&editR, ViewString(s, 3010, 9, "\pEdit Options\311"));
            DrawT3DButton(&moreR, ViewString(s, 3010, 21, "\pMore Choices"));
            RGBForeColor(&black);
            PenSize(3, 3); FrameRoundRect(&goR, 16, 16); PenSize(1, 1);
            DrawT3DButton(&goBtn, ViewString(s, 3010, 11, "\pBegin Game"));
            {
                Str255 item;
                SyncPresetMenu(presetMenu);
                GetMenuItemText(presetMenu, PresetMenuItem(), item);
                DrawT3DPopup(popR.left, popR.top, item);
            }
            EndUpdate(win);
        } else if (evt.what == mouseDown) {
            WindowPtr hit;
            Point pt = evt.where;
            if (FindWindow(pt, &hit) != inContent || hit != win) continue;
            GlobalToLocal(&pt);
            {   /* T3DRadio views: the whole 16-tall row is the hit area */
                Rect rr;
                for (i = 0; i < factionCount && i < MAX_FACTIONS; i++) {
                    SetRect(&rr, 9 + 22, 48 + 20 + 17 * i, 9 + 22 + 135, 48 + 20 + 17 * i + 16);
                    if (PtInRect(pt, &rr) && !SetupSlotUnused(names, factionCount, i)) {
                        *side = i; aiAssigned = true; InvalRect(&win->portRect);
                    }
                }
                for (i = 0; i < 3; i++) {
                    SetRect(&rr, 179 + 14, 48 + 20 + 17 * i, 179 + 14 + 140, 48 + 20 + 17 * i + 16);
                    if (PtInRect(pt, &rr)) { *skill = i; aiAssigned = true; InvalRect(&win->portRect); }
                }
                SetRect(&rr, 179 + 14, 132 + 80, 179 + 14 + 138, 132 + 80 + 16);   /* 'grea' */
                if (PtInRect(pt, &rr)) {
                    /* FUN_1005aac8: checking it makes every side a Warlord and
                     * moves the Computer Level radio to Warlord (verified on
                     * the original: the rating jumps to the Warlord value);
                     * unchecking only clears the flag. */
                    sIAmGreatest = !sIAmGreatest;
                    if (sIAmGreatest) { *skill = 2; aiAssigned = true; }
                    InvalRect(&win->portRect);
                }
            }
            if (PtInRect(pt, &popR)) {
                Point g;
                long choice;
                g.h = popR.left; g.v = popR.top;
                LocalToGlobal(&g);
                SyncPresetMenu(presetMenu);
                choice = PopUpMenuSelect(presetMenu, g.v, g.h, PresetMenuItem());
                if ((choice & 0xFFFF) >= 1 && (choice & 0xFFFF) <= 3) {   /* "Custom" is not a choice */
                    sOptionsPreset = (short)(choice & 0xFFFF) - 1;
                    ApplyOptionsPreset(sOptionsPreset);
                }
                InvalRect(&win->portRect);   /* difficulty rating may change */
            } else if (PtInRect(pt, &goR)) {
                result = 0;
            } else if (PtInRect(pt, &moreR)) {
                result = 1;
            } else if (PtInRect(pt, &editR)) {
                ShowEditOptions();
                SetPort(win);
                InvalRect(&win->portRect);
            }
        } else if (evt.what == keyDown) {
            char key = evt.message & charCodeMask;
            if (key == 0x0D || key == 0x03) result = 0;
            else if (key == 0x1B) result = 2;
        }
    }
    DisposeWindow(win);
    DeleteMenu(240);
    DisposeMenu(presetMenu);
    return result;
}

/* ===================================================================
 * RunMoreGameSetup — View 3020 "More Choices", the original's eight-side
 * Game Setup. 507x348 altDBoxProc window (the View's 'wind' record; the
 * 364x510 marble PICT 1001 behind it is clipped), centred like View 3024.
 * Two columns of four T3DClusters 'clu1'..'clu8' (75x161), each framed
 * and titled in the side's colour and holding a T3DIconButton 'icoN'
 * (41x41, the side's portrait), a TRoller 'rolN' (23x84, cycling the
 * 'Roll' 3020 states Knight/Lord/Warlord/Off/Human) and a T3DCheckBox
 * 'chaN' "Character" (the enhanced-AI flag, dimmed unless the side is a
 * computer). Right column: the Options cluster (popup, Edit Options, I am
 * the Greatest), the difficulty rating, E-mail game / Set Addresses /
 * Select Random Characters (dimmed as on the original without an e-mail
 * game or a character set), Fewer Choices and the default Begin Game.
 * Every position below is the View record's (v,h), window-relative.
 * Returns 0 = Begin Game, 1 = Fewer Choices, 2 = cancelled (Escape).
 * =================================================================== */
#define MORE_W 507
#define MORE_H 348

/* 'Roll' 3020 state order Knight, Lord, Warlord, Off, Human <-> sFactionAI */
static short RollerIndexOfAI(short ai)  { return ai == 0 ? 4 : ai - 1; }
static short AIOfRollerIndex(short idx) { return idx == 4 ? 0 : idx + 1; }

/* A side slot the scenario does not use: beyond the named slots, nameless,
 * or carrying the SCN's literal "Not Used". Such a side stays Off. */
static Boolean SetupSlotUnused(char names[][FACTION_NAME_LEN + 1], short factionCount, short i)
{
    const char *n = names[i];
    if (i >= factionCount || n[0] == 0) return true;
    return n[0] == 'N' && n[1] == 'o' && n[2] == 't' && n[3] == ' ' &&
           (n[4] == 'U' || n[4] == 'u') && n[5] == 's' && n[6] == 'e' && n[7] == 'd';
}

/* Side colour code: the SCN colour array (original gs+0xA0 = SCN+0x9F as
 * big-endian shorts; the remake copies the SCN raw, so the code is the low
 * byte at gs+0xA0+slot*2). Every shipped SCN carries 15,7,8,9,10,6,5,0. */
static short SideColourCode(short slot)
{
    unsigned char *gs;
    if (*gGameState == 0) return 15;
    gs = (unsigned char *)*gGameState;
    return gs[0xA0 + slot * 2] & 0x0F;
}

/* Colour code -> RGB as the original frames View 3020's clusters (measured
 * on Mac OS 8.6 with the display gamma removed): 15 white, 7 yellow,
 * 8 orange, 9 red, 10 green, 6 blue, 5 light blue, 0 black; 3 is the grey
 * the original stamps on "Not Used" sides. Other codes: pltt 1000 entries. */
static void SideColourRGB(short code, RGBColor *c)
{
    static const unsigned short tab[16][3] = {
        {0x0000, 0x0000, 0x0000},   /* 0  black */
        {0x8F8F, 0x8F8F, 0x8F8F},   /* 1 */
        {0x8F8F, 0x8F8F, 0x8F8F},   /* 2 */
        {0x6F6F, 0x6F6F, 0x6F6F},   /* 3  grey */
        {0x4F4F, 0x4F4F, 0x4F4F},   /* 4 */
        {0x4242, 0xBDBD, 0xFFFF},   /* 5  light blue */
        {0x0000, 0x5151, 0xCFCF},   /* 6  blue */
        {0xFFFF, 0xFFFF, 0x0000},   /* 7  yellow */
        {0xFFFF, 0x7F7F, 0x0000},   /* 8  orange */
        {0xC2C2, 0x1919, 0x0000},   /* 9  red */
        {0x4F4F, 0xABAB, 0x1919},   /* 10 green */
        {0x0000, 0x8A8A, 0x0202},   /* 11 */
        {0x0000, 0x5454, 0x0000},   /* 12 */
        {0xA3A3, 0x5151, 0x0000},   /* 13 */
        {0x7070, 0x3030, 0x0000},   /* 14 */
        {0xFFFF, 0xFFFF, 0xFFFF},   /* 15 white */
    };
    if (code < 0 || code > 15) code = 15;
    c->red = tab[code][0]; c->green = tab[code][1]; c->blue = tab[code][2];
}

/* 'Roll' 3020: five Str255 records of 258 bytes (Knight, Lord, Warlord,
 * Off, Human). */
static ConstStr255Param RollerString(Str255 buf, short idx)
{
    static const unsigned char *fallback[5] = {
        "\pKnight", "\pLord", "\pWarlord", "\pOff", "\pHuman"
    };
    Handle h;
    if (idx < 0 || idx > 4) idx = 0;
    h = GetResource('Roll', 3020);
    if (h != NULL && GetHandleSize(h) >= (long)(idx + 1) * 258) {
        unsigned char *p = (unsigned char *)*h + idx * 258;
        BlockMoveData(p, buf, p[0] + 1);
        return buf;
    }
    BlockMoveData(fallback[idx], buf, fallback[idx][0] + 1);
    return buf;
}

/* Side portrait of View 3020's 'icoN' (PPC FUN_10057e5c): cicn 3020 +
 * level for a computer side (Knight/Lord/Warlord Macs), 3024 (woman) /
 * 3025 (man) for a human on an even / odd slot; an Off side shows the
 * disabled face with no icon. */
static CIconHandle SidePortraitIcon(short slot, short ai)
{
    static CIconHandle icons[6];
    static Boolean loaded = false;
    short k;
    if (!loaded) {
        for (k = 0; k < 6; k++) icons[k] = GetCIcon(3020 + k);
        loaded = true;
    }
    if (ai == AI_OFF) return NULL;
    if (ai == 0) return icons[(slot & 1) ? 5 : 4];
    return icons[ai - 1];
}

/* TRoller art (23x84), lifted from the original as pltt 1000 indices: the
 * MacApp bevel (dark 0x5555 above/left, light 0xBBBB below/right, 0x8888
 * where they meet) around a black-outlined horizontal cylinder — the body
 * shades 0x6F / 0x8F / 0xBB / white / 0xBB / 0x8F / 0x6F top to bottom, a
 * one- or two-pixel cap band stands at the left end and the right end is
 * stepped. Columns 0-4 are x = 0..4, column 5 fills x = 5..80 and columns
 * 6-8 are x = 81..83. */
#define ROLLER_W 84
#define ROLLER_H 23
static const unsigned char kRollerArt[ROLLER_H][9] = {
    {251, 251, 251, 251, 251,  251,  251, 251, 249},
    {251, 255, 255, 255, 255,  255,  255, 247, 249},
    {251, 255, 255,   3,   3,    3,  255, 247, 249},
    {251, 255, 255,   1,   1,    1,  255, 247, 249},
    {251, 255,   1, 255,   1,    1,    1, 255, 249},
    {251, 255,   1, 255, 247,  247,  247, 255, 249},
    {251, 255,   1, 255, 247,  247,  247, 255, 248},
    {251, 255,   1,   3, 255,  247,  247, 247, 255},
    {251, 255,   3,   3, 255,    0,    0,   0, 255},
    {251, 255,   3,   3, 255,    0,    0,   0, 255},
    {251, 255,   3,   3, 255,  247,  247, 247, 255},
    {251, 255,   3,   3, 255,    0,    0,   0, 255},
    {251, 255,   3,   3, 255,  247,  247, 247, 255},
    {251, 255,   3,   3, 255,  247,  247, 247, 255},
    {251, 255,   3,   3, 255,  247,  247, 247, 255},
    {251, 255,   1,   3, 255,  247,  247, 247, 255},
    {251, 255,   1, 255, 247,  247,  247, 255, 248},
    {251, 255,   1, 255,   1,    1,    1, 255, 249},
    {251, 255,   1, 255,   1,    1,    1, 255, 249},
    {251, 255, 255,   3,   3,    3,  255, 247, 249},
    {251, 255, 255,   3,   3,    3,  255, 247, 249},
    {251, 255, 255, 255, 255,  255,  255, 247, 249},
    {251, 247, 247, 247, 247,  247,  247, 247, 249},
};

/* TRoller: the art above plus the current state in Chicago 12 black,
 * centred like a T3DButton label (cap ink rows top+6..top+14). */
static void DrawTRoller(short left, short top, ConstStr255Param item)
{
    short x, y, w;
    RGBColor c, black = {0, 0, 0};
    if (sGamePal != NULL) {
        for (y = 0; y < ROLLER_H; y++) {
            for (x = 0; x < 5; x++) {
                GetEntryColor(sGamePal, kRollerArt[y][x], &c);
                SetCPixel(left + x, top + y, &c);
            }
            for (x = 0; x < 3; x++) {
                GetEntryColor(sGamePal, kRollerArt[y][6 + x], &c);
                SetCPixel(left + ROLLER_W - 3 + x, top + y, &c);
            }
            GetEntryColor(sGamePal, kRollerArt[y][5], &c);
            RGBForeColor(&c);
            MoveTo(left + 5, top + y); LineTo(left + ROLLER_W - 4, top + y);
        }
    }
    TextFont(ChicagoFont()); TextSize(12); TextFace(0);
    w = StringWidth(item);
    RGBForeColor(&black);
    if (sGamePal != NULL) {   /* smoothed text blends against the back colour: the roller face */
        RGBColor face; GetEntryColor(sGamePal, kRollerArt[ROLLER_H / 2][5], &face);
        RGBBackColor(&face);
    }
    MoveTo((left + left + ROLLER_W - w + 1) / 2, top + 15);
    DrawString(item);
    {   RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF}; RGBBackColor(&white); }
}

/* Dimmed T3DCheckBox (measured on View 3020's 'chaN' / 'mail'): no bevel,
 * a 0x8888 12x12 frame filled 0xDDDD at (left+2, top+2); the label is a
 * single 0xAAAA layer where the embossed label's face would be. */
static void DrawT3DCheckBoxDim(short left, short top, Boolean on)
{
    RGBColor frame = {0x8888, 0x8888, 0x8888}, fill = {0xDDDD, 0xDDDD, 0xDDDD};
    Rect b;
    SetRect(&b, left + 2, top + 2, left + 14, top + 14);
    RGBForeColor(&frame); FrameRect(&b);
    InsetRect(&b, 1, 1);
    RGBForeColor(&fill); PaintRect(&b);
    if (on) {
        RGBForeColor(&frame);
        MoveTo(b.left, b.top); LineTo(b.right - 1, b.bottom - 1);
        MoveTo(b.right - 1, b.top); LineTo(b.left, b.bottom - 1);
    }
}

static void DrawDimLabel(ConstStr255Param s, short x, short baseline)
{
    RGBColor dim = {0xAAAA, 0xAAAA, 0xAAAA};
    RGBForeColor(&dim);
    MoveTo(x + 1, baseline + 1);
    DrawString(s);
}

/* Disabled T3DButton (View 3020 'addr' / 'sele'): the 0x5555 outline and
 * flat 0xCCCC face of DrawT3DDisabledFace, the label 0x7777 over a 0xBBBB
 * highlight (no dark layer). Lines split on '\r' sit 16px apart from the
 * 21px-button baseline (top+13), as the two-line 'sele' shows. */
static void DrawT3DButtonDisabled(const Rect *r, ConstStr255Param label)
{
    RGBColor fg = {0x7777, 0x7777, 0x7777}, light = {0xBBBB, 0xBBBB, 0xBBBB};
    Str255 line;
    short pos = 1, base = r->top + 13, w, x;
    DrawT3DDisabledFace(r);
    TextFont(ChicagoFont()); TextSize(12); TextFace(0);
    while (pos <= label[0]) {
        short n = 0;
        while (pos + n <= label[0] && label[pos + n] != '\r') n++;
        line[0] = (unsigned char)n;
        BlockMoveData(label + pos, line + 1, n);
        w = StringWidth(line);
        x = (r->left + r->right - w + 1) / 2 - 1;
        RGBForeColor(&light); MoveTo(x + 2, base + 2); DrawString(line);
        RGBForeColor(&fg);    MoveTo(x + 1, base + 1); DrawString(line);
        pos += n + 1;
        base += 16;
    }
}

/* Enabled T3DButton with a label split on '\r' (the 37px 'sele'): the
 * same bevel as DrawT3DButton, lines 16px apart from baseline top+13. */
static void DrawT3DButtonLines(const Rect *r, ConstStr255Param label)
{
    RGBColor black = {0, 0, 0};
    Str255 line;
    short pos = 1, base = r->top + 13, w, x;
    DrawT3DBevel(r);
    TextFont(ChicagoFont()); TextSize(12); TextFace(0);
    while (pos <= label[0]) {
        short n = 0;
        while (pos + n <= label[0] && label[pos + n] != '\r') n++;
        line[0] = (unsigned char)n;
        BlockMoveData(label + pos, line + 1, n);
        w = StringWidth(line);
        x = (r->left + r->right - w + 1) / 2;
        DrawEmbossedStringIn(line, x - 1, base, &black, 0x8888, 0xDDDD);
        pos += n + 1;
        base += 16;
    }
}

static short RunMoreGameSetup(char names[][FACTION_NAME_LEN + 1], short factionCount)
{
    /* 'clu1'..'clu8' (v,h): two columns of four */
    static const short kClu[MAX_FACTIONS][2] = {
        {7, 3}, {92, 3}, {177, 3}, {262, 3}, {7, 172}, {92, 172}, {177, 172}, {262, 172}
    };
    WindowPtr win;
    Rect wr, r;
    short i, result = -1, mbar = GetMBarHeight();
    Rect screen = qd.screenBits.bounds;
    MenuHandle presetMenu;
    Rect popR, editR, addrR, seleR, feweR, goR, goBtn;
    Str255 s;
    Boolean unused[MAX_FACTIONS];

    for (i = 0; i < MAX_FACTIONS; i++) {
        unused[i] = SetupSlotUnused(names, factionCount, i);
        if (unused[i]) sFactionAI[i] = AI_OFF;
        else if (sFactionAI[i] < 0 || sFactionAI[i] > AI_OFF) sFactionAI[i] = 1;
    }

    /* MacApp centres the window including altDBoxProc's 2px shadow */
    SetRect(&wr, (screen.right - (MORE_W + 2)) / 2, mbar + (screen.bottom - mbar - (MORE_H + 2)) / 2, 0, 0);
    wr.right = wr.left + MORE_W; wr.bottom = wr.top + MORE_H;
    win = NewCWindow(NULL, &wr, "\p", false, altDBoxProc, (WindowPtr)-1L, false, 0);
    if (win == NULL) return 2;
    ApplyGamePalette(win);
    SetPort(win);
    TextFont(ChicagoFont()); TextSize(12);

    presetMenu = NewMenu(240, "\p");                 /* CMNU 70 items */
    AppendMenu(presetMenu, "\pBeginner;Intermediate;Advanced");
    InsertMenu(presetMenu, -1);

    /* 'opti' (7,340) 108x162: 'popu' (20,16) 19x132, 'edit' (49,16) 21x132 */
    SetRect(&popR,  340 + 16, 7 + 20, 340 + 16 + 132, 7 + 20 + 19);
    SetRect(&editR, 340 + 16, 7 + 49, 340 + 16 + 132, 7 + 49 + 21);
    SetRect(&addrR, 356, 181, 356 + 132, 181 + 20);      /* 'addr' */
    SetRect(&seleR, 356, 218, 356 + 132, 218 + 37);      /* 'sele' */
    SetRect(&feweR, 356, 272, 356 + 132, 272 + 21);      /* 'fewe' */
    SetRect(&goR,   352, 310, 352 + 140, 310 + 29);      /* 'go  ' */
    goBtn = goR; InsetRect(&goBtn, 4, 4);

    ShowWindow(win);
    FlushEvents(everyEvent, 0);

    while (result < 0) {
        EventRecord evt;
        if (!WaitNextEvent(everyEvent, &evt, 30, NULL)) continue;
        if (evt.what == updateEvt && (WindowPtr)evt.message == win) {
            RGBColor black = {0, 0, 0}, cream = {0xFFFF, 0xFFFF, 0xCCCC};
            BeginUpdate(win);
            {   /* TPlainPicture: PICT 1001 marble at the origin */
                PicHandle marble = GetPicture(1001);
                if (marble != NULL) {
                    Rect pf = (**marble).picFrame;
                    OffsetRect(&pf, -pf.left, -pf.top);
                    DrawPicture(marble, &pf);
                }
            }

            for (i = 0; i < MAX_FACTIONS; i++) {
                short v = kClu[i][0], h = kClu[i][1];
                RGBColor col;
                Rect ir;
                Str255 title;
                SideColourRGB(SideColourCode(i), &col);
                if (unused[i]) {
                    BlockMoveData("\pNot used", title, 9);
                } else {
                    short n = 0;
                    while (n < FACTION_NAME_LEN && names[i][n]) n++;
                    title[0] = (unsigned char)n; BlockMoveData(names[i], title + 1, n);
                }
                SetRect(&r, h, v, h + 161, v + 75);
                DrawT3DClusterColor(&r, title, &col);

                SetRect(&ir, h + 14, v + 21, h + 14 + 41, v + 21 + 41);      /* 'icoN' */
                DrawT3DIconButton(&ir, SidePortraitIcon(i, sFactionAI[i]), sFactionAI[i] != AI_OFF);

                DrawTRoller(h + 65, v + 20, RollerString(s, RollerIndexOfAI(sFactionAI[i])));  /* 'rolN' */

                ViewString(s, 3020, 9, "\pCharacter");                        /* 'chaN' */
                TextFont(ChicagoFont()); TextSize(12); TextFace(0);
                if (sFactionAI[i] >= 1 && sFactionAI[i] <= 3) {
                    DrawT3DCheckBox(h + 64, v + 48, sFactionCharacter[i]);
                    DrawEmbossedString(s, h + 64 + 17, v + 48 + 11, &cream);
                } else {
                    DrawT3DCheckBoxDim(h + 64, v + 48, false);
                    DrawDimLabel(s, h + 64 + 17, v + 48 + 11);
                }
            }

            SetRect(&r, 340, 7, 340 + 162, 7 + 108);
            DrawT3DCluster(&r, ViewString(s, 3020, 4, "\pOptions"));
            DrawT3DButton(&editR, ViewString(s, 3010, 9, "\pEdit Options\311"));
            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            DrawT3DCheckBox(340 + 14, 7 + 80, sIAmGreatest);                    /* 'grea' */
            DrawEmbossedString(ViewString(s, 3020, 2, "\pI am the Greatest"), 340 + 14 + 17,
                               7 + 80 + 11, &cream);
            {
                Str255 num, line;
                NumToString((long)CalcDifficultyRatingSides(), num);
                BlockMoveData("\pDifficulty Rating ", line, 19);
                BlockMoveData(num + 1, line + 1 + line[0], num[0]); line[0] += num[0];
                line[++line[0]] = '%';
                SetRect(&r, 340, 128, 340 + 162, 128 + 19);                     /* 'diff' */
                DrawSunkenText(&r, line, IlluriaFont(), 17, 1);
            }
            TextFont(ChicagoFont()); TextSize(12); TextFace(0);
            DrawT3DCheckBoxDim(371, 164, false);                                /* 'mail' */
            DrawDimLabel(ViewString(s, 3020, 10, "\pE-mail game"), 371 + 17, 164 + 11);
            DrawT3DButtonDisabled(&addrR, ViewString(s, 3010, 15, "\pSet Addresses"));
            {   /* 'sele' is live whenever a computer side exists, 'go  ' needs two
                 * playing sides (FUN_100586a0 DimState rules) */
                short nComp = 0, nPlay = 0;
                for (i = 0; i < MAX_FACTIONS; i++) {
                    if (unused[i] || sFactionAI[i] == AI_OFF) continue;
                    nPlay++;
                    if (sFactionAI[i] >= 1 && sFactionAI[i] <= 3) nComp++;
                }
                ViewString(s, 3010, 10, "\pSelect Random\rCharacters");
                if (nComp > 0) DrawT3DButtonLines(&seleR, s); else DrawT3DButtonDisabled(&seleR, s);
                DrawT3DButton(&feweR, ViewString(s, 3010, 22, "\pFewer Choices"));
                RGBForeColor(&black);
                PenSize(3, 3); FrameRoundRect(&goR, 16, 16); PenSize(1, 1);
                ViewString(s, 3010, 11, "\pBegin Game");
                if (nPlay >= 2) DrawT3DButton(&goBtn, s); else DrawT3DButtonDisabled(&goBtn, s);
            }
            {
                Str255 item;
                SyncPresetMenu(presetMenu);
                GetMenuItemText(presetMenu, PresetMenuItem(), item);
                DrawT3DPopup(popR.left, popR.top, item);
            }
            EndUpdate(win);
        } else if (evt.what == mouseDown) {
            WindowPtr hit;
            Point pt = evt.where;
            Rect rr;
            if (FindWindow(pt, &hit) != inContent || hit != win) continue;
            GlobalToLocal(&pt);
            for (i = 0; i < MAX_FACTIONS; i++) {
                short v = kClu[i][0], h = kClu[i][1];
                SetRect(&rr, h + 65, v + 20, h + 65 + ROLLER_W, v + 20 + ROLLER_H);   /* 'rolN' */
                if (PtInRect(pt, &rr) && !unused[i]) {
                    /* PPC FUN_10059b7c: Human -> Knight -> Lord -> Warlord -> Off
                     * -> Human, and the side's Character flag is cleared */
                    sFactionAI[i] = AIOfRollerIndex((RollerIndexOfAI(sFactionAI[i]) + 1) % 5);
                    sFactionCharacter[i] = false;
                    InvalRect(&win->portRect);
                }
                SetRect(&rr, h + 64, v + 48, h + 64 + 90, v + 48 + 16);              /* 'chaN' */
                if (PtInRect(pt, &rr) && sFactionAI[i] >= 1 && sFactionAI[i] <= 3) {
                    sFactionCharacter[i] = !sFactionCharacter[i];
                    InvalRect(&win->portRect);
                }
            }
            SetRect(&rr, 340 + 14, 7 + 80, 340 + 14 + 138, 7 + 80 + 16);   /* 'grea' */
            if (PtInRect(pt, &rr)) {
                sIAmGreatest = !sIAmGreatest;
                if (sIAmGreatest)   /* FUN_1005aac8: EVERY playing side (the human too,
                                     * verified on the original) becomes a Warlord computer;
                                     * a side that was not already a Warlord loses its Character */
                    for (i = 0; i < MAX_FACTIONS; i++)
                        if (!unused[i]) {
                            if (sFactionAI[i] != 3) sFactionCharacter[i] = false;
                            sFactionAI[i] = 3;
                        }
                InvalRect(&win->portRect);
            }
            if (PtInRect(pt, &seleR)) {
                /* 'sele' (FUN_1005b938): sides 0..7, every playing computer
                 * side draws a character of its level's set, Dice(1, count-1,
                 * 0) into gs+0xE0 - never 0, so every Character box ends up
                 * checked.  count = FUN_1003aeb0(7, level): the app's 'DESC'
                 * resources named K000.., L000.., W000.. up to the first
                 * missing one (9 each). */
                for (i = 0; i < MAX_FACTIONS; i++)
                    if (!unused[i] && sFactionAI[i] >= 1 && sFactionAI[i] <= 3) {
                        static const char kLvl[3] = {'K', 'L', 'W'};
                        short cnt = 0;
                        for (cnt = 0; cnt < 30; cnt++) {
                            Str255 nm;
                            Handle h;
                            nm[0] = 4; nm[1] = (unsigned char)kLvl[sFactionAI[i] - 1];
                            nm[2] = (unsigned char)('0' + cnt / 100); nm[3] = (unsigned char)('0' + (cnt / 10) % 10);
                            nm[4] = (unsigned char)('0' + cnt % 10);
                            SetResLoad(false);
                            h = GetNamedResource('DESC', nm);
                            SetResLoad(true);
                            if (h == NULL) break;
                        }
                        if (cnt == 0) cnt = 9;   /* (no DESC: the shipped sets hold 9) */
                        sFactionCharIdx[i] = Dice(1, (short)(cnt - 1), 0);
                        sFactionCharacter[i] = true;
                        InvalRect(&win->portRect);
                    }
            }
            if (PtInRect(pt, &popR)) {
                Point g;
                long choice;
                g.h = popR.left; g.v = popR.top;
                LocalToGlobal(&g);
                SyncPresetMenu(presetMenu);
                choice = PopUpMenuSelect(presetMenu, g.v, g.h, PresetMenuItem());
                if ((choice & 0xFFFF) >= 1 && (choice & 0xFFFF) <= 3) {   /* "Custom" is not a choice */
                    sOptionsPreset = (short)(choice & 0xFFFF) - 1;
                    ApplyOptionsPreset(sOptionsPreset);
                }
                InvalRect(&win->portRect);   /* difficulty rating may change */
            } else if (PtInRect(pt, &goR)) {
                short nPlay = 0;   /* 'go  ' is dimmed under two playing sides */
                for (i = 0; i < MAX_FACTIONS; i++)
                    if (!unused[i] && sFactionAI[i] != AI_OFF) nPlay++;
                if (nPlay >= 2) result = 0;
            } else if (PtInRect(pt, &feweR)) {
                result = 1;
            } else if (PtInRect(pt, &editR)) {
                ShowEditOptions();
                SetPort(win);
                InvalRect(&win->portRect);
            }
        } else if (evt.what == keyDown) {
            char key = evt.message & charCodeMask;
            if (key == 0x0D || key == 0x03) result = 0;
            else if (key == 0x1B) result = 2;
        }
    }
    DisposeWindow(win);
    DeleteMenu(240);
    DisposeMenu(presetMenu);
    return result;
}


/* ===================================================================
 * ShowGameSetup — Display game setup dialog
 *
 * Shows a modal window where the player chooses their faction and
 * the computer AI skill level before starting the game.
 * Faction names are parsed from SCN resource data in gGameState.
 * Returns true if "Begin Game" was clicked, false on Escape.
 * =================================================================== */
static short PathCityIndexAt(short x, short y);   /* defined with the path code below */

static Boolean ShowGameSetup(void)
{
    Boolean    beginGame = false;
    short      selectedSide = 0;
    short      computerSkill = 0;
    char       factionNames[MAX_FACTIONS][FACTION_NAME_LEN + 1];
    short      factionCount = 0;
    short      i;

    /* Parse faction names from SCN resource (offset 0, 8x20 bytes) */
    if (*gGameState != 0) {
        unsigned char *scnData = (unsigned char *)*gGameState;
        for (i = 0; i < MAX_FACTIONS; i++) {
            BlockMoveData(scnData + i * FACTION_NAME_LEN,
                          factionNames[i], FACTION_NAME_LEN);
            factionNames[i][FACTION_NAME_LEN] = 0;
            if (factionNames[i][0] != 0)
                factionCount = i + 1;
        }
    }

    if (factionCount == 0)
        factionCount = MAX_FACTIONS;

    /* The original's default setup is View 3024 (easy); "More Choices"
     * opens View 3020 and "Fewer Choices" comes back, until Begin Game or
     * Escape. Both views work on sFactionAI / sFactionCharacter. */
    {
        Boolean more = false, cameFromMore = false;
        for (;;) {
            short res;
            if (!more) {
                res = RunEasyGameSetup(factionNames, factionCount, &selectedSide, &computerSkill, cameFromMore);
                for (i = 0; i < MAX_FACTIONS; i++) {
                    sFactionAI[i] = SetupSlotUnused(factionNames, factionCount, i) ? AI_OFF :
                                    (i == selectedSide) ? 0 :
                                    (sIAmGreatest ? 3 : computerSkill + 1);   /* "I am the greatest": every AI a Warlord */
                    /* Begin Game from View 3024 clears every Character flag
                     * (FUN_1005a6ac's 'comp' pass writes gs+0xE0 = 0); More
                     * Choices keeps them. */
                    if (res == 0) sFactionCharacter[i] = false;
                }
            } else {
                Boolean haveHuman = false, haveAI = false;
                res = RunMoreGameSetup(factionNames, factionCount);
                cameFromMore = true;
                /* Sync the easy view's radios from the per-side states as
                 * FUN_10057e5c does: 'side' = the first human side, 'comp' =
                 * the level of the first computer side (slot order). */
                for (i = 0; i < MAX_FACTIONS; i++) {
                    if (sFactionAI[i] == 0) {
                        if (!haveHuman) { selectedSide = i; haveHuman = true; }
                    } else if (sFactionAI[i] >= 1 && sFactionAI[i] <= 3) {
                        if (!haveAI) { computerSkill = sFactionAI[i] - 1; haveAI = true; }
                    }
                }
            }
            if (res == 0) { beginGame = true; break; }
            if (res == 2) break;
            more = !more;
        }
    }

    /* Store results */
    sPlayerSide = selectedSide;
    sComputerSkill = computerSkill;

    /* Write game state on Begin Game (Step 6) */
    if (beginGame && *gGameState != 0) {
        unsigned char *gs = (unsigned char *)*gGameState;

        /* Faction count and current player */
        for (i = 0; i < 16; i++) gs[0x100 + i] = 0;   /* advisor state, zero in every SCN */
        /* gs+0x112, the maximum side bonus in battle (FUN_100ac0cc): the
         * original's FUN_1005668c reads it from the SCN header as a
         * little-endian short at the same offset (5 in every scenario and
         * terrain-set SCN); the remake's gs still holds the raw bytes
         * (swapped once: a raw value below 256 has a zero high byte) */
        if (gs[0x112] != 0 && gs[0x113] == 0)
            *(short *)(gs + 0x112) = (short)(unsigned char)gs[0x112];
        *(short *)(gs + 0x110) = selectedSide;

        /* Player types: human vs AI */
        for (i = 0; i < factionCount; i++) {
            *(short *)(gs + 0xd0 + i * 2) = (sFactionAI[i] == 0) ? 0 : 1;
        }

        /* Option words at the original's offsets (FUN_1005a6ac) */
        WriteOptionsToGameState(gs);

        /* Alive flags: the scenario's factions as GameInit found them ("Not
         * Used" slots stay dead: re-enabling them put phantom AIs, heroes and
         * armies at junk capital coords - Isles of Sorcery player 2 in the sea). */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x138 + i * 2) =
                (i < factionCount && gs[i * 0x14] != 0 && sFactionAI[i] != AI_OFF &&
                 !(gs[i * 0x14] == 'N' && gs[i * 0x14 + 1] == 'o' && gs[i * 0x14 + 2] == 't' &&
                   gs[i * 0x14 + 3] == ' ' && gs[i * 0x14 + 4] == 'U')) ? 1 : 0;
        }

        /* Initialize turn management */
        *(short *)(gs + 0x136) = 1;   /* Start at turn 1 */
        *(short *)(gs + 0x118) = 0;   /* Not end-of-round yet */
        *(short *)(gs + 0x174) = 0;   /* Order index starts at 0 */
        for (i = 0; i < 8; i++) {
            *(short *)(gs + 0x164 + i * 2) = i;  /* Sequential turn order */
        }

        /* (Random Turns' 20 swaps, FUN_1003c838, and the first side,
         * FUN_1003d4dc, come after the helmet's 'vbegin': BeginNewGame) */

        /* Re-initialize diplomacy matrix based on actual option setting.
         * GameInit() set all to peace (0x00), but the user may have
         * changed the diplomacy flag in Edit Options.
         * 68k CODE_117 FUN_00000ad2: clears bits 2-3, sets state 2 (war) if
         * diplomacy disabled, then copies bits 2-3 to bits 0-1. */
        {
            short di, dj;
            for (di = 0; di < 8; di++) {
                for (dj = 0; dj < 8; dj++) {
                    unsigned char *dip = gs + 0x1582 + di * 8 + dj;
                    unsigned char state = sOptDiplomacy ? DIPLO_PEACE : DIPLO_WAR;
                    *dip = DIPLO_SET_STATE(0, state) | (state & 3);  /* bits 2-3=state, bits 0-1=copy */
                }
            }
        }

        /* (Per-side notoriety, FUN_1003c368's Dice(1,8,0): BeginNewGame,
         * after the starting armies) */

        /* Per-side level words (PPC FUN_1005a6ac): Knight 0, Lord 1,
         * Warlord 2 for a computer side; a human side carries 2; a side that
         * is dead or switched Off (roller state 3) ends up computer, level 0,
         * not alive, and its capital goes neutral (FUN_1002be50 -> owner 0xF). */
        for (i = 0; i < 8; i++) {
            if (sFactionAI[i] >= 1 && sFactionAI[i] <= 3)
                *(short *)(gs + 0xc0 + i * 2) = sFactionAI[i] - 1;  /* AI level */
            else if (sFactionAI[i] == 0)
                *(short *)(gs + 0xc0 + i * 2) = 2;                  /* human */
            else
                *(short *)(gs + 0xc0 + i * 2) = 0;                  /* Off */
            if (*(short *)(gs + 0x138 + i * 2) == 0) {
                *(short *)(gs + 0xd0 + i * 2) = 1;
                *(short *)(gs + 0xc0 + i * 2) = 0;
            }
        }
        for (i = 0; i < 8; i++) {
            short ci;
            if (*(short *)(gs + 0x138 + i * 2) != 0 || sFactionAI[i] != AI_OFF) continue;
            ci = PathCityIndexAt(*(short *)(gs + 0x18A + i * 0x14), *(short *)(gs + 0x18C + i * 0x14));
            if (ci >= 0) *(short *)(sCityData + ci * 0x20 + 0x04) = 0x0F;
        }

        /* (The fight order, gs+0x60C, is the scenario's: GameInit) */

        /* Additional init from 68k CODE_117 FUN_00001ab6 */
        *(short *)(gs + 0x15E) = 0;   /* endgame/domination flag — blocks hero offers */
        *(short *)(gs + 0x160) = 0;   /* Offer of Peace not yet made */
        *(short *)(gs + 0x158) = 0;   /* special game mode */
        sNoHumanNoticeShown = false;
        for (i = 0; i < 8; i++) {
            /* enhanced-AI flag: View 3020's 'Character' checkbox of a computer side */
            *(short *)(gs + 0x0E0 + i * 2) =
                (sFactionAI[i] >= 1 && sFactionAI[i] <= 3 && sFactionCharacter[i]) ?
                (sFactionCharIdx[i] > 0 ? sFactionCharIdx[i] : 1) : 0;
            *(short *)(gs + 0x148 + i * 2) = sOptHiddenMap ? 1 : 0;  /* fog per player */
        }

        /* Clear per-player hero instance records (gs+0x1422, 0x2C bytes each) */
        for (i = 0; i < 8; i++) {
            short b;
            for (b = 0; b < 0x2C; b++)
                gs[0x1422 + i * 0x2C + b] = 0;
        }

        /* Clear quest records (gs+0x1142, 0x0C bytes per player) */
        for (i = 0; i < 8; i++) {
            short b;
            for (b = 0; b < 0x0C; b++)
                gs[0x1142 + i * 0x0C + b] = 0;
        }
        /* (The sites and their known masks are dealt with the final
         * options at BeginNewGame, FUN_1003956c) */

        /* Item records (gs+0xD12) are NOT cleared here: GameInit already
         * built the Standards and placed the ruin items (FUN_1003956c). */

        /* Set not-playing factions' capitals to neutral army ownership */
        {
            short armyCount = *(short *)(gs + 0x1602);
            if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
            for (i = 0; i < 8; i++) {
                if (*(short *)(gs + 0x138 + i * 2) == 0) {
                    short capX = *(short *)(gs + 0x18A + i * 0x14);
                    short capY = *(short *)(gs + 0x18C + i * 0x14);
                    short ai2;
                    for (ai2 = 0; ai2 < armyCount; ai2++) {
                        unsigned char *army = ARMY_REC(ai2);
                        if (*(short *)(army + 0x00) == capX &&
                            *(short *)(army + 0x02) == capY) {
                            army[0x15] = 0x0F;  /* neutral owner */
                        }
                    }
                }
            }
        }
    }

    return beginGame;
}


/* Terrain type colors for the main strategic map view.
 * 68k terrain types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
 * 5=Hills, 6=Mountains, 7=Plains, 8=Marsh, 9=Sea, 10=City, 11=Ruin */
#define NUM_TERRAIN_COLORS 12
static RGBColor sTerrainColors[NUM_TERRAIN_COLORS] = {
    {0xCFCF,0x8B8B,0x3B3B},  /* 0  road - tan */
    {0x9797,0x4B4B,0x0707},  /* 1  bridge - dark brown */
    {0x4B4B,0xEBEB,0xFFFF},  /* 2  water - light blue */
    {0xFFFF,0xDBDB,0x8B8B},  /* 3  shore - sand */
    {0x0000,0x8B8B,0x1313},  /* 4  forest - dark green */
    {0xAFAF,0x6B6B,0x1B1B},  /* 5  hills - brown */
    {0x8787,0x8787,0x8787},  /* 6  mountains - gray */
    {0x4F4F,0xEFEF,0x4F4F},  /* 7  plains - green */
    {0x6B6B,0x8B8B,0x3B3B},  /* 8  marsh - olive */
    {0x0000,0x6363,0xC3C3},  /* 9  sea/ocean - blue */
    {0xCFCF,0xCFCF,0xCFCF},  /* 10 city - light gray */
    {0x9F9F,0x9F9F,0x9F9F},  /* 11 temple/ruin - medium gray */
};

/* ===================================================================
 * DrawMapInWindow — Draw terrain using sprite sheets at 40x40 per tile
 *
 * Shows a viewport of the map using CopyBits from the terrain GWorlds.
 * Falls back to flat terrain-type colors if sprites aren't loaded.
 * Arrow keys scroll the viewport (handled in event loop).
 * =================================================================== */
static short sDebugShowTileSheet = 0;  /* press 'T' to toggle tile sheet view */

/* Forward declarations for movement cost and item-based movement helpers */
static short GetMovementCost(short mapX, short mapY, short unitClass);
static short GetEffectiveUnitClass(short armyIdx);
static Boolean ArmyHasFlightItem(short armyIdx);
static Boolean ArmyHasDoubleMoveItem(short armyIdx);
static Boolean IsHeroFemale(short armyIdx);
static short ComputeWavefrontPath(short srcX, short srcY, short dstX, short dstY, short armyIdx);
static short ExecutePathSteps(short armyIdx);
static Boolean AskYesNo(ConstStr255Param head, ConstStr255Param l1, ConstStr255Param l2,
                        ConstStr255Param l3, ConstStr255Param l4);
static Boolean UnitTypeFlies(short t);
static Boolean UnitTypeNaval(short t);
static void BuildStackArrays(short leadArmyIdx);
static Boolean CheckAndResolveCombat(short movingArmyIdx);
static void BreakTreaty(short me, short them);
static void FormatTwoStrNum(ConstStr255Param fmt, ConstStr255Param a, ConstStr255Param b, short num, Str255 out);
static void TryTempleBlessing(short armyIdx);
static void CheckGroundItemPickup(short armyIdx);
/* the computer player's hooks into the path core and the record table */
static Boolean AIAttackGate(short armyIdx, short bx, short by);
static void AIAnimateStep(short x, short y);
static void AIOrdOnRemove(short armyIndex, short armyCount);
static void AIResetAll(void);
static void AIBattleMemory(short defOwner, short attOwner, short heroesLeft, short unitsLeft,
                           short attUnits, Boolean cityBattle);
static Boolean sPathForceAI;   /* BuildPathFlagGrid: treat the owner as a computer player */

static void DrawMapInWindow(WindowPtr win)
{
    unsigned char *mapData;
    unsigned char *scnData;
    Rect           winRect;
    short          tx, ty;
    short          tilesWide, tilesHigh;
    Boolean        hasScn;
    short          i;
    GWorldPtr      bufGW = NULL;
    WindowPtr      realWin = win;
    CGrafPtr       bufSavePort = NULL;
    GDHandle       bufSaveDev = NULL;

    if (!sMapLoaded || *gMapTiles == 0)
        return;

    mapData = (unsigned char *)*gMapTiles;
    hasScn  = (*gGameState != 0);
    scnData = hasScn ? (unsigned char *)*gGameState : NULL;
    winRect = win->portRect;

    /* Reserve space for scrollbars and shields at edges */
    winRect.right  -= SCROLLBAR_W;
    winRect.bottom -= SCROLLBAR_H;

    /* How many tiles fit in the window (+1 for the partial tile the
     * sub-tile scroll exposes on the right/bottom) */
    tilesWide = (winRect.right - winRect.left) / TERRAIN_TILE_W + 2;
    tilesHigh = (winRect.bottom - winRect.top) / TERRAIN_TILE_H + 2;

    /* Double buffer the map area (terrain, roads, cities, armies, path):
     * drawn straight to the window the layers showed one after another,
     * which blinked while a path was dragged. */
    {
        static short sBufW = 0, sBufH = 0;
        short bw = win->portRect.right - win->portRect.left;
        short bh = win->portRect.bottom - win->portRect.top;
        if (sMapBufGW != NULL && (bw != sBufW || bh != sBufH)) {
            DisposeGWorld(sMapBufGW); sMapBufGW = NULL;
        }
        if (sMapBufGW == NULL) {
            Rect b;
            Handle ct = (Handle)sGameCTab;
            SetRect(&b, 0, 0, bw, bh);
            if (ct == NULL || HandToHand(&ct) != noErr) ct = NULL;
            if (NewGWorld(&sMapBufGW, 8, &b, (CTabHandle)ct, NULL, 0) != noErr) sMapBufGW = NULL;
            sBufW = bw; sBufH = bh;
        }
        if (sMapBufGW != NULL && LockPixels(GetGWorldPixMap(sMapBufGW))) {
            GetGWorld(&bufSavePort, &bufSaveDev);
            realWin = win;
            SetGWorld(sMapBufGW, NULL);
            win = (WindowPtr)sMapBufGW;
            bufGW = sMapBufGW;
            {   /* a GWorld keeps its last colours: the map's CopyBits colourise
                 * with fore/back, so start from black on white every time */
                RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
                RGBForeColor(&black); RGBBackColor(&white);
                PenNormal(); TextMode(srcOr);
            }
        }
    }

    /* Sub-tile scroll: draw everything in unscrolled coordinates with the
     * port origin moved by the pixel remainder, clipped to the map area. */
    {
        Rect mapClip = winRect;
        SetOrigin(sViewPixX, sViewPixY);
        OffsetRect(&mapClip, sViewPixX, sViewPixY);
        ClipRect(&mapClip);
    }

    /* Lock terrain sheet pixmaps for the draw loop */
    if (sTerrainLoaded) {
        if (sTerrainGW != NULL) LockPixels(GetGWorldPixMap(sTerrainGW));
        if (sTerrainGW2 != NULL) LockPixels(GetGWorldPixMap(sTerrainGW2));
    }

    for (ty = 0; ty < tilesHigh; ty++) {
        for (tx = 0; tx < tilesWide; tx++) {
            short mapX = sViewportX + tx;
            short mapY = sViewportY + ty;
            unsigned short tileOffset;
            unsigned char  terrainIdx;
            short          terrainType;
            Rect           dstRect;

            if (mapX >= sMapWidth || mapY >= sMapHeight)
                continue;

            tileOffset = mapY * 0xE0 + mapX * 2;
            terrainIdx = mapData[tileOffset];

            /* Get terrain category from SCN properties table */
            if (hasScn) {
                terrainType = (short)(unsigned char)scnData[terrainIdx + TERRAIN_TYPE_OFS];
            } else {
                terrainType = (terrainIdx >> 4) & 0x0F;
            }
            if (terrainType >= NUM_TERRAIN_COLORS)
                terrainType = 0;

            SetRect(&dstRect,
                winRect.left + tx * TERRAIN_TILE_W,
                winRect.top  + ty * TERRAIN_TILE_H,
                winRect.left + (tx + 1) * TERRAIN_TILE_W,
                winRect.top  + (ty + 1) * TERRAIN_TILE_H);

            /* Sprite-based rendering from terrain sheets.
             * PICT 30022 = tiles 0-95, PICT 30023 = tiles 96-191.
             * Each sheet: 16 cols x 6 rows of 40x40 tiles.
             * Tile N: sheet=N/96, local=N%96, col=local%16, row=local/16. */
            if (sTerrainLoaded) {
                short local = terrainIdx % TERRAIN_TILES_PER_SHEET;
                short spriteCol = local % TERRAIN_COLS;
                short spriteRow = local / TERRAIN_COLS;
                GWorldPtr sheet = (terrainIdx < TERRAIN_TILES_PER_SHEET)
                    ? sTerrainGW : sTerrainGW2;
                Rect srcRect;

                if (sheet != NULL) {
                    PixMapHandle srcPix = GetGWorldPixMap(sheet);
                    SetRect(&srcRect,
                        spriteCol * TERRAIN_TILE_W, spriteRow * TERRAIN_TILE_H,
                        (spriteCol + 1) * TERRAIN_TILE_W,
                        (spriteRow + 1) * TERRAIN_TILE_H);

                    CopyBits((BitMap *)*srcPix,
                             &((GrafPtr)win)->portBits,
                             &srcRect, &dstRect,
                             srcCopy, NULL);
                    continue;
                }
            }

            /* Fallback: flat terrain-type color */
            RGBForeColor(&sTerrainColors[terrainType]);
            PaintRect(&dstRect);
        }
    }

    /* Unlock terrain sheet pixmaps */
    if (sTerrainLoaded) {
        if (sTerrainGW != NULL) UnlockPixels(GetGWorldPixMap(sTerrainGW));
        if (sTerrainGW2 != NULL) UnlockPixels(GetGWorldPixMap(sTerrainGW2));
    }

    /* --- Road overlay --- */
    /* PICT 30021 (640x80): 17 road sprites, 13 per row, 48px horizontal stride,
     * 40px vertical stride. Each sprite is 40x40 with 8px horizontal padding.
     * RD byte bits 0-4 = road type (0=none, 1-17=road variant).
     * Tile index = rd - 1. srcX = (tileIdx % 13) * 48, srcY = (tileIdx / 13) * 40.
     * Formula from original PPC binary (PPC_0001.c lines 2992-2993). */
    if (*gRoadData != 0 && sMapLoaded && sRoadGW != NULL && sRoadBgColorValid) {
        unsigned char *roadData = (unsigned char *)*gRoadData;
        short rdMapH = sMapHeight;
        PixMapHandle roadPix = GetGWorldPixMap(sRoadGW);
        RGBColor oldBack;

        if (rdMapH > 156) rdMapH = 156;
        LockPixels(roadPix);

        /* Set background color once outside the loop for mode 36 transparency */
        GetBackColor(&oldBack);
        RGBBackColor(&sRoadBgColor);

        for (ty = 0; ty < tilesHigh; ty++) {
            for (tx = 0; tx < tilesWide; tx++) {
                short rMapX = sViewportX + tx;
                short rMapY = sViewportY + ty;
                unsigned char rd;
                Rect srcRect, dstRect;
                short tileIdx, srcX, srcY;

                if (rMapX < 0 || rMapX >= 112 || rMapY < 0 || rMapY >= rdMapH)
                    continue;
                rd = roadData[rMapY * 112 + rMapX] & 0x1F;
                if (rd == 0 || rd > 17) continue;

                tileIdx = rd - 1;
                srcX = (tileIdx % 13) * 48;
                srcY = (tileIdx / 13) * 40;
                SetRect(&srcRect, srcX, srcY, srcX + 40, srcY + 40);

                SetRect(&dstRect,
                    winRect.left + tx * TERRAIN_TILE_W,
                    winRect.top  + ty * TERRAIN_TILE_H,
                    winRect.left + (tx + 1) * TERRAIN_TILE_W,
                    winRect.top  + (ty + 1) * TERRAIN_TILE_H);

                CopyBits((BitMap *)*roadPix,
                         &((GrafPtr)win)->portBits,
                         &srcRect, &dstRect, 36, NULL);
            }
        }

        RGBBackColor(&oldBack);
        UnlockPixels(roadPix);
    }

    /* --- Port anchors (PPC FUN_1000419c / FUN_10005f90): MAP low byte bit 0x80,
     * PICT 30010 (0,0) 32x30 at the tile's top-left, after the roads and
     * before cities and armies. None on the minimap. --- */
    {
        short tx2, ty2;
        for (ty2 = 0; ty2 < tilesHigh; ty2++)
            for (tx2 = 0; tx2 < tilesWide; tx2++) {
                short mx2 = sViewportX + tx2, my2 = sViewportY + ty2;
                Rect ar;
                if (mx2 < 0 || mx2 >= sMapWidth || my2 < 0 || my2 >= sMapHeight) continue;
                if (!(mapData[my2 * 0xE0 + mx2 * 2 + 1] & 0x80)) continue;
                SetRect(&ar, winRect.left + tx2 * TERRAIN_TILE_W, winRect.top + ty2 * TERRAIN_TILE_H,
                        winRect.left + tx2 * TERRAIN_TILE_W + 32, winRect.top + ty2 * TERRAIN_TILE_H + 30);
                DrawPortAnchor(&ar);
            }
    }

    /* --- Fog of war: drawn AFTER all sprites (see block below stack badges) --- */

    /* --- Draw city/ruin/temple icons from SCN data at gs+0x812 --- */
    /* Each site record is 0x20 bytes: +0=x, +2=y, +4=owner, +6=defense, +8=income, +0x17=site_type */
    /* site_type: 0/1=city, 2=temple, 3=library, 4=treasure, 5=ally */
    /* Two passes: ruins first (they're smaller), then cities (80x80, srcCopy covers ruins) */
    if (hasScn) {
        short cityCount = sCityCount;
        short drawPass;
        if (cityCount > 139) cityCount = 139;

        for (drawPass = 0; drawPass < 2; drawPass++)
        for (i = 0; i < cityCount; i++) {
            unsigned char *city = sCityData +i * 0x20;
            short cx = *(short *)(city + 0x00);
            short cy = *(short *)(city + 0x02);
            short owner = *(short *)(city + 0x04);
            short siteType = (short)(unsigned char)city[0x17];
            short screenX, screenY;

            /* Pass 0: ruins only (sType >= 2). Pass 1: cities only (sType < 2). */
            if (drawPass == 0 && siteType < 2) continue;
            if (drawPass == 1 && siteType >= 2) continue;

            screenX = winRect.left + (cx - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (cy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {

                /* Fog of war: hide unexplored cities/ruins */
                if (*(short *)(scnData + 0x124) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    if (curP >= 0 && curP < 8 &&
                        !FogGetBit(sFogExplored[curP], cx, cy))
                        continue;
                }

                if (siteType >= 2 && siteType <= 6) {
                    /* === Ruin / Temple overlay from terrain sprite sheet ===
                     * Tile index 10 = ruin sprite, tile index 11 = temple sprite
                     * in PICT 30022 (16 cols x 6 rows of 40x40 tiles). */
                    if (sTerrainGW != NULL) {
                        /* the site's tile as FUN_10039ec8 set it for the
                         * current player: 11 temple, 12 ruin, 10 hidden
                         * site, 9 an unknown hidden site (plain land) */
                        short tileIdx = (short)mapData[cy * 0xE0 + cx * 2];
                        if (tileIdx < 9 || tileIdx > 12) tileIdx = (siteType == 2) ? 11 : 12;
                        if (tileIdx == 9) continue;
                        short col = tileIdx % 16;
                        short row = tileIdx / 16;
                        Rect srcR, dstR;
                        PixMapHandle srcPix = GetGWorldPixMap(sTerrainGW);
                        SetRect(&srcR, col * 40, row * 40,
                                col * 40 + 40, row * 40 + 40);
                        SetRect(&dstR, screenX, screenY,
                                screenX + 40, screenY + 40);
                        LockPixels(srcPix);
                        CopyBits((BitMap *)*srcPix,
                                 &((GrafPtr)win)->portBits,
                                 &srcR, &dstR,
                                 srcCopy, NULL);
                        UnlockPixels(srcPix);
                    }
                } else {
                    /* === City icon === */
                    if (sTerrainGW2 != NULL) {
                        /* City sprites from PICT 30023 (terrain overlay sheet).
                         * Each city is 80×80 (2×2 of 40×40 tiles), opaque with grass bg.
                         * Layout: 7 per row. Row 0 = neutral + players 0-5 (indices 0-6),
                         *         Row 1 = players 6-7 (indices 7-8).
                         * Position (560,0) is mountain terrain, NOT a city.
                         * Owner mapping: cityIdx = owner+1 (0=neutral, 1-8=players). */
                        short cityIdx;
                        short srcX, srcY;
                        Rect srcRect, dstRect;
                        PixMapHandle srcPix = GetGWorldPixMap(sTerrainGW2);

                        if (owner >= 0 && owner < 8)
                            cityIdx = owner + 1;  /* players 0-7 → indices 1-8 */
                        else
                            cityIdx = 0;           /* neutral → index 0 */

                        /* 7 cities per row: row 0 indices 0-6, row 1 indices 7-8 */
                        srcX = (cityIdx % 7) * 80;
                        srcY = (cityIdx / 7) * 80;

                        SetRect(&srcRect, srcX, srcY, srcX + 80, srcY + 80);
                        SetRect(&dstRect, screenX, screenY,
                            screenX + 80, screenY + 80);

                        LockPixels(srcPix);
                        CopyBits((BitMap *)*srcPix,
                                 &((GrafPtr)win)->portBits,
                                 &srcRect, &dstRect,
                                 srcCopy, NULL);
                        UnlockPixels(srcPix);

                        /* Port anchors removed — terrain tiles handle port visuals */

                        /* (debug owner overlay removed) */
                    } else {
                        /* Fallback: programmatic castle icon */
                        RGBColor black = {0x0000, 0x0000, 0x0000};
                        RGBColor darkGray = {0x4444, 0x4444, 0x4444};
                        RGBColor lightGray = {0xBBBB, 0xBBBB, 0xBBBB};
                        short colorIdx;
                        Rect wallRect, towerL, towerR, gateRect, flagRect;

                        if (owner >= 0 && owner < 8)
                            colorIdx = owner + 1;
                        else
                            colorIdx = 8;

                        SetRect(&wallRect, screenX + 4, screenY + 8,
                                screenX + TERRAIN_TILE_W - 4, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&wallRect);
                        RGBForeColor(&darkGray);
                        FrameRect(&wallRect);

                        SetRect(&towerL, screenX + 2, screenY + 2,
                                screenX + 10, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&towerL);
                        RGBForeColor(&darkGray);
                        FrameRect(&towerL);

                        SetRect(&towerR, screenX + TERRAIN_TILE_W - 10, screenY + 2,
                                screenX + TERRAIN_TILE_W - 2, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&lightGray);
                        PaintRect(&towerR);
                        RGBForeColor(&darkGray);
                        FrameRect(&towerR);

                        {
                            short bx;
                            RGBForeColor(&darkGray);
                            for (bx = screenX + 2; bx < screenX + 10; bx += 4) {
                                Rect cren;
                                SetRect(&cren, bx, screenY + 2, bx + 2, screenY + 4);
                                PaintRect(&cren);
                            }
                            for (bx = screenX + TERRAIN_TILE_W - 10; bx < screenX + TERRAIN_TILE_W - 2; bx += 4) {
                                Rect cren;
                                SetRect(&cren, bx, screenY + 2, bx + 2, screenY + 4);
                                PaintRect(&cren);
                            }
                        }

                        SetRect(&gateRect, screenX + 12, screenY + 16,
                                screenX + 20, screenY + TERRAIN_TILE_H - 2);
                        RGBForeColor(&black);
                        PaintRect(&gateRect);

                        SetRect(&flagRect, screenX + 13, screenY + 6,
                                screenX + 19, screenY + 14);
                        RGBForeColor(&sPlayerColors[colorIdx]);
                        PaintRect(&flagRect);
                        RGBForeColor(&black);
                        FrameRect(&flagRect);
                    }
                }
            }
        }
    }

    /* --- Draw city names below castle icons ---
     * Remake-only overlay: the original map shows no city labels. */
    if (hasScn && sShowCityLabels) {
        short cityCount2 = sCityCount;
        if (cityCount2 > 139) cityCount2 = 139;
        TextFont(3);
        TextSize(9);
        TextFace(0);
        for (i = 0; i < cityCount2; i++) {
            unsigned char *city = sCityData +i * 0x20;
            short cx = *(short *)(city + 0x00);
            short cy = *(short *)(city + 0x02);
            short cityOwner = *(short *)(city + 0x04);
            short siteType = (short)(unsigned char)city[0x17];
            short screenX, screenY;

            if (siteType != 0) continue;  /* only label cities */

            screenX = winRect.left + (cx - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (cy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {
                short colorIdx = (cityOwner >= 0 && cityOwner < 8) ? cityOwner + 1 : 8;
                RGBColor shadowCol = {0x0000, 0x0000, 0x0000};
                Str255 cityPName;

                /* Fog of war: hide city names in unexplored tiles */
                if (*(short *)(scnData + 0x124) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    if (curP >= 0 && curP < 8 &&
                        !FogGetBit(sFogExplored[curP], cx, cy))
                        continue;
                }
                short nameLen = 0;

                /* Get city name from CTY resource data, or fall back to faction name */
                if (i < sCityNameCount && sCityNames[i][0] != '\0') {
                    char *cn = sCityNames[i];
                    while (nameLen < MAX_CITY_NAME - 1 && cn[nameLen] != '\0')
                        nameLen++;
                    {
                        short ni2;
                        for (ni2 = 0; ni2 < nameLen; ni2++)
                            cityPName[ni2 + 1] = cn[ni2];
                    }
                } else if (cityOwner >= 0 && cityOwner < 8) {
                    char *fn = (char *)(scnData + cityOwner * 20);
                    while (nameLen < 12 && fn[nameLen] != 0)
                        nameLen++;
                    {
                        short ni2;
                        for (ni2 = 0; ni2 < nameLen; ni2++)
                            cityPName[ni2 + 1] = fn[ni2];
                    }
                } else {
                    nameLen = 7;
                    BlockMoveData("Neutral", cityPName + 1, 7);
                }
                cityPName[0] = (unsigned char)nameLen;

                /* Append production timer for own cities: " [N]" */
                if (*gExtState != 0 && cityOwner >= 0 && cityOwner < 8 &&
                    cityOwner == *(short *)(scnData + 0x110)) {
                    unsigned char *ext = (unsigned char *)*gExtState;
                    unsigned char *extCity = ext + 0x24c + i * 0x5c;
                    short prodType = *(short *)(extCity + 0x02);
                    short prodTurns = *(short *)(extCity + 0x58);
                    if (prodType >= 0 && nameLen + 4 <= 254) {
                        Str255 tn;
                        short ti2;
                        cityPName[++cityPName[0]] = ' ';
                        cityPName[++cityPName[0]] = '[';
                        NumToString((long)prodTurns, tn);
                        for (ti2 = 1; ti2 <= tn[0]; ti2++)
                            cityPName[++cityPName[0]] = tn[ti2];
                        cityPName[++cityPName[0]] = ']';
                    }
                }

                /* Shadow text */
                RGBForeColor(&shadowCol);
                MoveTo(screenX + 1, screenY + TERRAIN_TILE_H + 9);
                DrawString(cityPName);
                /* Colored text */
                RGBForeColor(&sPlayerColors[colorIdx]);
                MoveTo(screenX, screenY + TERRAIN_TILE_H + 8);
                DrawString(cityPName);
            }
        }
    }

    /* --- Draw army sprites from game state --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;

        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            short ax = *(short *)(army + 0x00);
            short ay = *(short *)(army + 0x02);
            short owner = (short)(unsigned char)army[0x15];
            short screenX, screenY;

            /* Skip invalid/empty army records */
            if (army[0x16] == 0xFF) continue;           /* no units */
            if (ax < 0 || ay < 0) continue;             /* invalid coords */
            if (ax >= sMapWidth || ay >= sMapHeight) continue;

            /* Fog of war: hide enemy armies in non-visible tiles */
            if (*(short *)(scnData + 0x124) != 0) {
                short curPlayer = *(short *)(scnData + 0x110);
                if (curPlayer >= 0 && curPlayer < 8 && owner != curPlayer) {
                    if (!FogGetBit(sFogVisible[curPlayer], ax, ay))
                        continue;
                }
            }

            /* One army sprite per tile, as the original: a hero if the stack
             * has one, else the first army there (Mirea turn 1: the hero
             * stands over the Heavy Cav.) */
            {
                Boolean iHero = ((unsigned char)army[0x16] == 0x1C);
                short aj;
                Boolean hidden = false, selHere = false;
                if (sSelectedArmy >= 0 && sSelectedArmy < armyCount) {
                    unsigned char *sel = ARMY_REC(sSelectedArmy);
                    if (*(short *)(sel + 0) == ax && *(short *)(sel + 2) == ay) {
                        if (i != sSelectedArmy) continue;    /* the selection is drawn on its tile */
                        selHere = true;
                    }
                }
                for (aj = 0; aj < armyCount && !hidden && !selHere; aj++) {
                    unsigned char *a2 = ARMY_REC(aj);
                    Boolean jHero;
                    if (aj == i || a2[0x16] == 0xFF) continue;
                    if (*(short *)(a2 + 0x00) != ax || *(short *)(a2 + 0x02) != ay) continue;
                    jHero = ((unsigned char)a2[0x16] == 0x1C);
                    if ((jHero && !iHero) || (jHero == iHero && aj < i)) hidden = true;
                }
                if (hidden) continue;
            }

            /* Skip naval/boat sprites on land tiles */
            if (*gMapTiles != 0 && ArmyIsNaval(i)) {
                unsigned char *md = (unsigned char *)*gMapTiles;
                short tIdx = (short)(unsigned char)md[ay * 0xE0 + ax * 2];
                short tType = (short)(unsigned char)scnData[tIdx + TERRAIN_TYPE_OFS];
                if (tType != 2 && tType != 9 && tType != 3)
                    continue;  /* not water/sea/shore: don't draw boat */
            }

            screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {

                short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 0;
                /* 68k CODE_067 FUN_000014e2: uses army[0x14] (sprite_index) directly.
                 * This is the authoritative sprite index set by the scenario/game.
                 * Do NOT use army[0x16] (unit type) + table lookup — that gives
                 * wrong results for heroes and loaded scenarios. */
                short spriteIdx = (short)(unsigned char)army[0x14];
                short sheetIdx = (owner >= 0 && owner < 8) ? owner : 8;
                GWorldPtr armyGW;
                short spriteCol, spriteRow;

                /* Hero gender remapping: 68k FUN_000000ae remaps sprite 0x1C
                 * to 0x1D for female heroes (gs+0x594+slot*2 == 1).
                 * Uses IsHeroFemale() which scans hero instance records. */
                if (spriteIdx == 0x1C && IsHeroFemale(i))
                    spriteIdx = 0x1D;
                /* An embarked land stack is drawn as the boat (sprite 5) unless it
                 * stands on an anchor tile (PPC view: unit flag 0x1000, MAP bit 0x80). */
                if ((army[0x2C] & ARMY_EMBARKED_BIT) && !(mapData[ay * 0xE0 + ax * 2 + 1] & 0x80))
                    spriteIdx = 5;
#if DEV_SHIP_PROBE   /* DEV: label armies drawn as a ship that hold no naval unit */
                if (spriteIdx == 5) {
                    char b[64]; Str255 ps; short n;
                    RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0};
                    { unsigned char *md0 = (unsigned char *)*gMapTiles; short ti = md0[ay * 0xE0 + ax * 2];
                      sprintf(b, "#%d o%d t%d,%d,%d,%d tt%d n%d", i, owner, army[0x16], army[0x17], army[0x18], army[0x19],
                              scnData[ti + TERRAIN_TYPE_OFS], ArmyIsNaval(i)); }
                    for (n = 0; b[n] && n < 60; n++) ps[n + 1] = b[n];
                    ps[0] = (unsigned char)n;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    RGBForeColor(&yel); RGBBackColor(&blk);
                    MoveTo(screenX, screenY + 48); DrawString(ps);
                    TextMode(srcOr); RGBForeColor(&blk);
                    { RGBColor w = {0xFFFF,0xFFFF,0xFFFF}; RGBBackColor(&w); }
                }
#endif

                /* Each 512x64 sheet has unit types in a 16x2 grid (32px cells).
                 * Sheet per faction: sArmyGW[owner]. */
                spriteCol = spriteIdx % 16;
                spriteRow = spriteIdx / 16;
                armyGW = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] :
                         (sArmyGW[0] != NULL) ? sArmyGW[0] : NULL;

                if (sArmyLoaded && armyGW != NULL) {
                    /* Blit army sprite from sprite sheet.
                     * 68k CODE_067 FUN_000001c4: srcRect 32×30 cells,
                     *   srcY = (idx/16)*30, srcX = (idx%16)*32.
                     * Dest: tile + 7px offset for centering within 40×40 tile.
                     * Mode 36 transparent blit: bg-colored pixels are not drawn. */
                    Rect srcRect, dstRect;
                    short srcX = spriteCol * 32;
                    short srcY = spriteRow * 30;  /* row stride is 30px, sprite is 29px tall (68k 0x1D) */
                    SetRect(&srcRect, srcX, srcY, srcX + 32, srcY + 29);
                    SetRect(&dstRect, screenX + 8, screenY + 7,
                            screenX + 8 + 32, screenY + 7 + 29);

                    LockPixels(GetGWorldPixMap(armyGW));
                    {
                        RGBColor savedBg;
                        GetBackColor(&savedBg);
                        RGBBackColor(&sArmyBgColor[sheetIdx]);
                        CopyBits((BitMap *)*GetGWorldPixMap(armyGW),
                                 &((GrafPtr)win)->portBits,
                                 &srcRect, &dstRect,
                                 36, NULL);
                        RGBBackColor(&savedBg);
                    }
                    UnlockPixels(GetGWorldPixMap(armyGW));
                } else {
                    /* No army sprites loaded — draw colored oval fallback */
                    Rect markerR;
                    RGBColor black = {0, 0, 0};
                    SetRect(&markerR, screenX + 6, screenY + 2,
                            screenX + TERRAIN_TILE_W - 6, screenY + TERRAIN_TILE_H - 12);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PaintOval(&markerR);
                    RGBForeColor(&black);
                    FrameOval(&markerR);
                }
            }
        }
    }

    /* --- Stack flags ---
     * PPC FUN_10005d2c (68k CODE_067 FUN_000014e2): every occupied tile gets a
     * 40px pole (palette 14 dark brown at x+2 and x+4, 13 light at x+3) and a
     * pennant from the owner's army sheet (srcLeft 464, 48x8, transparent)
     * whose length shows the stack size 1..4; 5..8 add a second, full
     * pennant 8px lower. */
    if (hasScn) {
        static const short kPennantTop[4] = {29, 38, 47, 56};
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            short ax, ay, aOwn, stackN, aj, sheetIdx;
            short screenX, screenY;
            GWorldPtr gw;
            if (army[0x16] == 0xFF) continue;
            ax = *(short *)(army + 0x00);
            ay = *(short *)(army + 0x02);
            aOwn = (short)(unsigned char)army[0x15];
            if (ax < 0 || ay < 0 || ax >= sMapWidth || ay >= sMapHeight) continue;
            /* Fog of war */
            if (*(short *)(scnData + 0x124) != 0) {
                short curP = *(short *)(scnData + 0x110);
                if (curP >= 0 && curP < 8 && aOwn != curP)
                    if (!FogGetBit(sFogVisible[curP], ax, ay)) continue;
            }
            /* One flag per tile: only for the first army there */
            {
                Boolean earlierSameTile = false;
                for (aj = 0; aj < i; aj++) {
                    unsigned char *a2 = ARMY_REC(aj);
                    if (a2[0x16] == 0xFF) continue;
                    if (*(short *)(a2 + 0x00) == ax && *(short *)(a2 + 0x02) == ay) {
                        earlierSameTile = true; break;
                    }
                }
                if (earlierSameTile) continue;
            }
            /* Units on the tile (the original keeps one unit per army) */
            stackN = 0;
            for (aj = 0; aj < armyCount; aj++) {
                unsigned char *a2 = ARMY_REC(aj);
                if (a2[0x16] == 0xFF) continue;
                if (*(short *)(a2 + 0x00) == ax && *(short *)(a2 + 0x02) == ay) {
                    short us;
                    for (us = 0; us < 4; us++)
                        if ((unsigned char)a2[0x16 + us] != 0xFF) stackN++;
                }
            }
            if (stackN < 1) continue;
            screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
            screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;
            if (screenX < winRect.left - TERRAIN_TILE_W || screenX >= winRect.right ||
                screenY < winRect.top - TERRAIN_TILE_H || screenY >= winRect.bottom) continue;
            {
                RGBColor dark = {0x9090, 0x5050, 0x0000}, light = {0xBBBB, 0x7373, 0x0000};
                RGBColor black = {0, 0, 0};
                /* FUN_100479f4(0xe) / (0xd): the colours of pltt 1000's
                 * entries 14 and 13 (the literals only without the palette) */
                if (sGamePal != NULL) {
                    GetEntryColor(sGamePal, 14, &dark);
                    GetEntryColor(sGamePal, 13, &light);
                }
                RGBForeColor(&dark);
                MoveTo(screenX + 2, screenY); Line(0, 39);
                MoveTo(screenX + 4, screenY); Line(0, 39);
                RGBForeColor(&light);
                MoveTo(screenX + 3, screenY); Line(0, 39);
                RGBForeColor(&black);
            }
            sheetIdx = (aOwn >= 0 && aOwn < 8) ? aOwn : 8;
            gw = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] : sArmyGW[0];
            if (sArmyLoaded && gw != NULL) {
                PixMapHandle pm = GetGWorldPixMap(gw);
                RGBColor savedBg;
                short n = stackN, pass;
                LockPixels(pm);
                GetBackColor(&savedBg);
                RGBBackColor(&sArmyBgColor[sheetIdx]);
                for (pass = 0; pass < 2; pass++) {
                    short top, dy;
                    Rect sr, dr;
                    if (pass == 0) {
                        if (n <= 4) continue;
                        top = kPennantTop[0]; dy = 8; n -= 4;
                    } else {
                        if (n > 4) n = 4;
                        top = kPennantTop[n - 1]; dy = 0;
                    }
                    SetRect(&sr, 464, top, 512, top + 8);
                    SetRect(&dr, screenX, screenY + dy, screenX + 48, screenY + dy + 8);
                    CopyBits((BitMap *)*pm, &((GrafPtr)win)->portBits, &sr, &dr, 36, NULL);
                }
                RGBBackColor(&savedBg);
                UnlockPixels(pm);
            }
        }
    }

    /* --- Draw defend mode indicators on defending armies --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
        for (i = 0; i < armyCount; i++) {
            unsigned char *army = ARMY_REC(i);
            /* Skip invalid/empty army records */
            if (army[0x16] == 0xFF) continue;
            {
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                if (ax < 0 || ay < 0 || ax >= sMapWidth || ay >= sMapHeight) continue;
                /* Fog of war: hide enemy defend indicators */
                if (*(short *)(scnData + 0x124) != 0) {
                    short curP = *(short *)(scnData + 0x110);
                    short aOwn = (short)(unsigned char)army[0x15];
                    if (curP >= 0 && curP < 8 && aOwn != curP &&
                        !FogGetBit(sFogVisible[curP], ax, ay))
                        continue;
                }
            }
            if (sArmyState[i] == 7 && ArmyShownOnTile(i)) {
                /* Army is guarding (ext state army_state == 7): draw defend sprite.
                 * 68k CODE_067 FUN_000000ae: uses sprite index 5 as overlay. */
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                short aOwner2 = (short)(unsigned char)army[0x15];
                short screenX = winRect.left + (ax - sViewportX) * TERRAIN_TILE_W;
                short screenY = winRect.top  + (ay - sViewportY) * TERRAIN_TILE_H;

                if (screenX >= winRect.left && screenX < winRect.right &&
                    screenY >= winRect.top && screenY < winRect.bottom &&
                    sArmyLoaded) {
                    short sheetIdx = (aOwner2 >= 0 && aOwner2 < 8) ? aOwner2 : 8;
                    GWorldPtr defGW = (sArmyGW[sheetIdx] != NULL) ? sArmyGW[sheetIdx] :
                                      (sArmyGW[0] != NULL) ? sArmyGW[0] : NULL;
                    if (defGW != NULL) {
                        /* Sprite 5: col=5, row=0 in 32x29 grid (68k FUN_000000ae) */
                        Rect srcR, dstR;
                        SetRect(&srcR, 5 * 32, 0, 5 * 32 + 32, 29);
                        SetRect(&dstR, screenX + 8, screenY + 7,
                                screenX + 8 + 32, screenY + 7 + 29);
                        LockPixels(GetGWorldPixMap(defGW));
                        {
                            RGBColor savedBg;
                            GetBackColor(&savedBg);
                            RGBBackColor(&sArmyBgColor[sheetIdx]);
                            CopyBits((BitMap *)*GetGWorldPixMap(defGW),
                                     &((GrafPtr)win)->portBits,
                                     &srcR, &dstR, 36, NULL);
                            RGBBackColor(&savedBg);
                        }
                        UnlockPixels(GetGWorldPixMap(defGW));
                    }
                }
            }
        }
    }

    /* --- Fog of war overlay (bitmap-based, drawn LAST per 68k CODE_067) --- */
    /* 68k draws fog AFTER all sprites (cities, armies, badges) so that
     * explored-but-not-visible tiles are properly dimmed including any
     * sprites. The selected army is drawn AFTER fog (in selection highlight). */
    if (hasScn && *(short *)(scnData + 0x124) != 0) {
        short curPlayer = *(short *)(scnData + 0x110);
        if (curPlayer >= 0 && curPlayer < 8) {
            for (ty = 0; ty < tilesHigh; ty++) {
                for (tx = 0; tx < tilesWide; tx++) {
                    short mapX = sViewportX + tx;
                    short mapY = sViewportY + ty;
                    Rect fogRect;

                    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight)
                        continue;

                    if (FogGetBit(sFogVisible[curPlayer], mapX, mapY))
                        continue;  /* currently visible: no overlay */

                    SetRect(&fogRect,
                        winRect.left + tx * TERRAIN_TILE_W,
                        winRect.top  + ty * TERRAIN_TILE_H,
                        winRect.left + (tx + 1) * TERRAIN_TILE_W,
                        winRect.top  + (ty + 1) * TERRAIN_TILE_H);

                    if (FogGetBit(sFogExplored[curPlayer], mapX, mapY)) {
                        /* Explored but not currently visible: semi-transparent dim */
                        RGBColor dimColor = {0x6666, 0x6666, 0x6666};
                        RGBForeColor(&dimColor);
                        PenMode(subOver);
                        PaintRect(&fogRect);
                        PenMode(srcCopy);
                    } else {
                        /* Never explored: solid black */
                        RGBColor blackColor = {0x0000, 0x0000, 0x0000};
                        RGBForeColor(&blackColor);
                        PaintRect(&fogRect);
                    }
                }
            }
        }
    }

    /* Movement range overlay removed — original Warlords II does not show
     * movement range with grid outlines. The white FrameRect squares
     * were not aligned with the terrain tile artwork's dither pattern,
     * creating a visual mismatch. */

    /* --- Path preview while dragging (original: the mouse held down with an
     * army selected): each intermediate step gets a 14x14 ring at (+17,+13),
     * plain while affordable this turn, crossed beyond the moves left; the
     * last tile shows the army's ghost. No preview on plain hover. */
    /* A selected army with a pending order shows its remaining path the same
     * way (original turn 3: selecting the hero drew rings to its ghost). */
    if (!sDragPreview && sSelectedArmy >= 0 && hasScn && sAITurnPlayer < 0 &&   /* no path for AI moves */
        sSelectedArmy < *(short *)(scnData + 0x1602)) {
        static long lastSig = -1;
        unsigned char *sa = ARMY_REC(sSelectedArmy);
        long sig = -1;
        if (*(short *)(sa + 0x32) != 0)
            sig = (((long)sSelectedArmy * 160 + *(short *)(sa + 0)) * 160 + *(short *)(sa + 2)) * 160L * 160L +
                  *(short *)(sa + 0x34) * 160L + *(short *)(sa + 0x36);
        if (sig != lastSig || (sig >= 0 && sPreviewPathLen <= 1)) {
            lastSig = sig;
            sPreviewPathLen = 0;
            if (sig >= 0) {
                short ax = *(short *)(sa + 0), ay = *(short *)(sa + 2);
                sPathTargetX = *(short *)(sa + 0x34); sPathTargetY = *(short *)(sa + 0x36);
                ComputePathGridOnly(ax, ay, sSelectedArmy);
                TracePreviewPath(ax, ay, sPathTargetX, sPathTargetY);
                sPreviewGridValid = false;
            }
        }
    }
    if (sAITurnPlayer < 0 && (sDragPreview || (sSelectedArmy >= 0 && hasScn &&
         *(short *)(ARMY_REC(sSelectedArmy) + 0x32) != 0)) &&
        sPreviewPathLen > 1 && sSelectedArmy >= 0 && hasScn) {
        static const char *ringArt[14] = {
            "....######....", "...########...", "..###....###..", ".###......###.",
            "###........###", "##..........##", "##..........##", "##..........##",
            "##..........##", "###........###", ".###......###.", "..###....###..",
            "...########...", "....######...." };
        static const char *crossArt[14] = {
            "....######....", "...########...", "..###....###..", ".####....####.",
            "######..######", "##..######..##", "##...####...##", "##...####...##",
            "##..######..##", "######..######", ".####....####.", "..###....###..",
            "...########...", "....######...." };
        unsigned char *selA = ARMY_REC(sSelectedArmy);
        short mp = (short)(unsigned char)selA[0x2e], cum = 0, pi;
        RGBColor black = {0, 0, 0};
        RGBForeColor(&black);
        for (pi = 1; pi < sPreviewPathLen; pi++) {
            short tx = sPreviewPathX[pi], ty = sPreviewPathY[pi];
            short px = winRect.left + (tx - sViewportX) * TERRAIN_TILE_W;
            short py = winRect.top  + (ty - sViewportY) * TERRAIN_TILE_H;
            cum = (short)sPreviewCum[pi];     /* stack execution costs (TracePreviewPath) */
            if (pi == sPreviewPathLen - 1) {
                short spr = (short)(unsigned char)selA[0x14];
                if (spr == 0x1C && IsHeroFemale(sSelectedArmy)) spr = 0x1D;
                DrawArmyGhostAt((short)(unsigned char)selA[0x15], spr, px + 8, py + 7);
            } else {
                const char **art = (cum <= mp) ? ringArt : crossArt;
                short i, j;
                for (j = 0; j < 14; j++)
                    for (i = 0; i < 14; i++)
                        if (art[j][i] == '#') { MoveTo(px + 17 + i, py + 13 + j); LineTo(px + 17 + i, py + 13 + j); }
            }
        }
    }

    /* --- Draw blinking selection highlight around selected army --- */
    if (sSelectedArmy >= 0 && hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        if (sSelectedArmy < armyCount) {
            unsigned char *selArmy = ARMY_REC(sSelectedArmy);
            short sx = *(short *)(selArmy + 0x00);
            short sy = *(short *)(selArmy + 0x02);
            short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
            short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;

            if (screenX >= winRect.left - TERRAIN_TILE_W &&
                screenX < winRect.right &&
                screenY >= winRect.top - TERRAIN_TILE_H &&
                screenY < winRect.bottom) {
                /* Halo (PPC FUN_10082430/FUN_10082260): four 31x30 frames of
                 * blue rings in PICT 1002 (32 apart), cycled on idle, drawn at
                 * (+8,+7) with the selected army's sprite over it. */
                short selOwner = (short)(unsigned char)selArmy[0x15];
                short selSprite = (short)(unsigned char)selArmy[0x14];
                if (selSprite == 0x1C && IsHeroFemale(sSelectedArmy)) selSprite = 0x1D;
                /* PPC FUN_10004400 (PPC_0001.c:2230): the selected stack is
                 * the boat whenever it is embarked, anchor tile or not. */
                if (selArmy[0x2C] & ARMY_EMBARKED_BIT) selSprite = 5;
                if (sHaloGW == NULL) {
                    sHaloGW = LoadPICTIntoGWorld(1002);
                    if (sHaloGW != NULL) {
                        CGrafPtr sp; GDHandle sd;
                        GetGWorld(&sp, &sd);
                        SetGWorld(sHaloGW, NULL);
                        GetCPixel(0, 0, &sHaloKey);
                        SetGWorld(sp, sd);
                    }
                }
                if (sHaloGW != NULL) {
                    PixMapHandle pm = GetGWorldPixMap(sHaloGW);
                    Rect sr, dr;
                    RGBColor savedBg, black = {0, 0, 0};
                    LockPixels(pm);
                    GetBackColor(&savedBg);
                    RGBForeColor(&black);
                    RGBBackColor(&sHaloKey);
                    SetRect(&sr, (sHaloFrame & 3) * 32, 0, (sHaloFrame & 3) * 32 + 31, 30);
                    SetRect(&dr, screenX + 8, screenY + 7, screenX + 8 + 31, screenY + 7 + 30);
                    CopyBits((BitMap *)*pm, &((GrafPtr)win)->portBits, &sr, &dr, 36, NULL);
                    RGBBackColor(&savedBg);
                    UnlockPixels(pm);
                }
                DrawArmySpriteAt(selOwner, selSprite, screenX + 8, screenY + 7, false);
#if DEV_SHIP_PROBE
                if (selSprite == 5) {
                    char b[64]; Str255 ps; short n;
                    RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0}, w = {0xFFFF,0xFFFF,0xFFFF};
                    sprintf(b, "SEL#%d o%d t%d,%d,%d,%d", sSelectedArmy, selOwner, selArmy[0x16], selArmy[0x17], selArmy[0x18], selArmy[0x19]);
                    for (n = 0; b[n] && n < 60; n++) ps[n + 1] = b[n];
                    ps[0] = (unsigned char)n;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    RGBForeColor(&yel); RGBBackColor(&blk);
                    MoveTo(screenX, screenY + 58); DrawString(ps);
                    TextMode(srcOr); RGBForeColor(&blk); RGBBackColor(&w);
                }
#endif
            }

            /* Destination of a pending order: the original draws a ghost of
             * the army's sprite there (black outline kept, other pixels white
             * on a checkerboard; measured turn 1 at Mirea), no box or line. */
            if (*(short *)(selArmy + 0x32) != 0) {
                short tx = *(short *)(selArmy + 0x34);
                short ty = *(short *)(selArmy + 0x36);
                short tScreenX = winRect.left + (tx - sViewportX) * TERRAIN_TILE_W;
                short tScreenY = winRect.top  + (ty - sViewportY) * TERRAIN_TILE_H;
                short spr = (short)(unsigned char)selArmy[0x14];
                if (spr == 0x1C && IsHeroFemale(sSelectedArmy)) spr = 0x1D;
                if (sPreviewPathLen <= 1 && (tx != sx || ty != sy) &&
                    tScreenX >= winRect.left - TERRAIN_TILE_W && tScreenX < winRect.right &&
                    tScreenY >= winRect.top - TERRAIN_TILE_H && tScreenY < winRect.bottom)
                    DrawArmyGhostAt((short)(unsigned char)selArmy[0x15], spr,
                                    tScreenX + 8, tScreenY + 7);
            }
        }
    }

    /* --- Draw city vectoring lines --- */
    if (hasScn && *gExtState != 0) {
        unsigned char *ext = (unsigned char *)*gExtState;
        short cityCount = sCityCount;
        short curPlayer = *(short *)(scnData + 0x110);
        short ci;
        if (cityCount > 139) cityCount = 139;
        for (ci = 0; ci < cityCount; ci++) {
            unsigned char *city = sCityData +ci * 0x20;
            unsigned char *extCity = ext + 0x24c + ci * 0x5c;
            short vTarget = *(short *)(extCity + 0x3e);
            if (*(short *)(city + 0x04) != curPlayer) continue;
            if (vTarget < 0 || vTarget >= cityCount || vTarget == ci) continue;
            {
                unsigned char *tgtCity = sCityData +vTarget * 0x20;
                short cx1 = *(short *)(city + 0x00);
                short cy1 = *(short *)(city + 0x02);
                short cx2 = *(short *)(tgtCity + 0x00);
                short cy2 = *(short *)(tgtCity + 0x02);
                short sx1 = winRect.left + (cx1 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy1 = winRect.top  + (cy1 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                short sx2 = winRect.left + (cx2 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy2 = winRect.top  + (cy2 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                /* Only draw if at least one endpoint is visible */
                if ((sx1 >= winRect.left && sx1 < winRect.right - SCROLLBAR_W) ||
                    (sx2 >= winRect.left && sx2 < winRect.right - SCROLLBAR_W)) {
                    RGBColor vecColor = {0x8888, 0xFFFF, 0x8888};  /* light green */
                    short vi2, vSteps;
                    short vdx = sx2 - sx1, vdy = sy2 - sy1;
                    vSteps = ((vdx < 0 ? -vdx : vdx) + (vdy < 0 ? -vdy : vdy)) / 8;
                    if (vSteps < 3) vSteps = 3;
                    if (vSteps > 60) vSteps = 60;
                    RGBForeColor(&vecColor);
                    for (vi2 = 0; vi2 <= vSteps; vi2++) {
                        if (vi2 % 2 == 0) {
                            short px = sx1 + (vdx * vi2) / vSteps;
                            short py = sy1 + (vdy * vi2) / vSteps;
                            Rect dot;
                            SetRect(&dot, px - 1, py - 1, px + 1, py + 1);
                            PaintRect(&dot);
                        }
                    }
                    /* Arrow at target end */
                    {
                        Rect arrR;
                        SetRect(&arrR, sx2 - 3, sy2 - 3, sx2 + 3, sy2 + 3);
                        PaintOval(&arrR);
                    }
                }
            }
        }
    }

    /* --- Draw movement order lines for all owned armies with orders --- */
    if (hasScn) {
        short armyCount = *(short *)(scnData + 0x1602);
        short curP = *(short *)(scnData + 0x110);
        short ai4;
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
        for (ai4 = 0; ai4 < armyCount; ai4++) {
            unsigned char *a = ARMY_REC(ai4);
            short aOwner = (short)(unsigned char)a[0x15];
            if (aOwner != curP) continue;
            if (a[0x16] == 0xFF) continue;
            if (ai4 == sSelectedArmy) continue;  /* already drawn above */
            if (*(short *)(a + 0x32) != 0) {
                short ax3 = *(short *)(a + 0x00);
                short ay3 = *(short *)(a + 0x02);
                short tx3 = *(short *)(a + 0x34);
                short ty3 = *(short *)(a + 0x36);
                short sx3 = winRect.left + (ax3 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short sy3 = winRect.top  + (ay3 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                short tx3s = winRect.left + (tx3 - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short ty3s = winRect.top  + (ty3 - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if ((sx3 >= winRect.left && sx3 < winRect.right) ||
                    (tx3s >= winRect.left && tx3s < winRect.right)) {
                    RGBColor ordColor = {0x8888, 0x8888, 0xFFFF};  /* light blue */
                    short odx = tx3s - sx3, ody = ty3s - sy3;
                    short oSteps = ((odx < 0 ? -odx : odx) + (ody < 0 ? -ody : ody)) / 10;
                    short oi;
                    if (oSteps < 2) oSteps = 2;
                    if (oSteps > 40) oSteps = 40;
                    RGBForeColor(&ordColor);
                    for (oi = 0; oi <= oSteps; oi++) {
                        if (oi % 3 == 0) {
                            short px = sx3 + (odx * oi) / oSteps;
                            short py = sy3 + (ody * oi) / oSteps;
                            Rect dot;
                            SetRect(&dot, px, py, px + 2, py + 2);
                            PaintRect(&dot);
                        }
                    }
                }
            }
        }
    }

    /* --- Draw signpost markers on map --- */
    {
        short si;
        RGBColor spColor = {0xFFFF, 0xFFFF, 0x6666};
        RGBColor spBorder = {0x0000, 0x0000, 0x0000};
        TextFont(3);
        TextSize(9);
        TextFace(0);
        for (si = 0; si < sSignpostCount; si++) {
            if (!sSignposts[si].active) continue;
            {
                short sx = sSignposts[si].x;
                short sy = sSignposts[si].y;
                short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
                short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;
                if (screenX >= winRect.left - TERRAIN_TILE_W &&
                    screenX < winRect.right &&
                    screenY >= winRect.top - TERRAIN_TILE_H &&
                    screenY < winRect.bottom) {
                    /* Draw small flag icon */
                    Rect flagR;
                    SetRect(&flagR, screenX + TERRAIN_TILE_W - 10, screenY,
                            screenX + TERRAIN_TILE_W - 2, screenY + 8);
                    RGBForeColor(&spColor);
                    PaintRect(&flagR);
                    RGBForeColor(&spBorder);
                    FrameRect(&flagR);
                    /* Draw text label below */
                    if (sSignposts[si].text[0] != 0) {
                        Str255 pStr;
                        short tl;
                        for (tl = 0; tl < 31 && sSignposts[si].text[tl]; tl++)
                            pStr[tl + 1] = sSignposts[si].text[tl];
                        pStr[0] = (unsigned char)tl;
                        RGBForeColor(&spColor);
                        MoveTo(screenX + 2, screenY + TERRAIN_TILE_H + 8);
                        DrawString(pStr);
                    }
                }
            }
        }

        /* --- Draw SGN scenario signposts (map place-name labels) --- */
        {
            RGBColor sgnColor = {0xDDDD, 0xFFFF, 0xDDDD};  /* pale green */
            TextFont(3);
            TextSize(9);
            TextFace(italic);
            for (si = 0; si < sSgnSignpostCount; si++) {
                if (!sSgnSignposts[si].active) continue;
                {
                    short sx = sSgnSignposts[si].x;
                    short sy = sSgnSignposts[si].y;
                    short screenX = winRect.left + (sx - sViewportX) * TERRAIN_TILE_W;
                    short screenY = winRect.top  + (sy - sViewportY) * TERRAIN_TILE_H;
                    if (screenX >= winRect.left - TERRAIN_TILE_W &&
                        screenX < winRect.right &&
                        screenY >= winRect.top - TERRAIN_TILE_H &&
                        screenY < winRect.bottom) {
                        if (sSgnSignposts[si].text[0] != 0) {
                            Str255 pStr;
                            short tl;
                            for (tl = 0; tl < 31 && sSgnSignposts[si].text[tl]; tl++)
                                pStr[tl + 1] = sSgnSignposts[si].text[tl];
                            pStr[0] = (unsigned char)tl;
                            RGBForeColor(&sgnColor);
                            MoveTo(screenX + 2, screenY + TERRAIN_TILE_H - 2);
                            DrawString(pStr);
                        }
                    }
                }
            }
            TextFace(0);
        }
    }

    SetOrigin(0, 0);
    ClipRect(&win->portRect);

#if DEV_SHIP_PROBE
    {   /* DEV: which army is selected */
        char b[160]; Str255 ps; short n;
        RGBColor yel = {0xFFFF, 0xFFFF, 0}, blk = {0, 0, 0}, w = {0xFFFF, 0xFFFF, 0xFFFF};
        sprintf(b, "sel=%d n=%d", sSelectedArmy, hasScn ? *(short *)(scnData + 0x1602) : -1);
        if (hasScn) {   /* units, records and moving records per player */
            short pl, q, nn = *(short *)(scnData + 0x1602);
            char *o = b; short len = 0;
            while (o[len]) len++;
            for (pl = 0; pl < 8 && len < 140; pl++) {
                short u = 0, recs = 0, ord = 0, kk;
                for (q = 0; q < nn && q < MAX_ARMIES; q++) {
                    unsigned char *qa = ARMY_REC(q);
                    if (qa[0x15] != pl || qa[0x16] == 0xFF) continue;
                    recs++; if (*(short *)(qa + 0x32)) ord++;
                    for (kk = 0; kk < 4; kk++) if (qa[0x16 + kk] != 0xFF) u++;
                }
                {   short pc = 0, tmr = -9, ci;
                    unsigned char *ex = *gExtState ? (unsigned char *)*gExtState : NULL;
                    for (ci = 0; ex && ci < sCityCount && ci < 99; ci++) {
                        unsigned char *c = sCityData + ci * 0x20, *e = ex + 0x24c + ci * 0x5c;
                        if (c[0x17] >= 2 || *(short *)(c + 4) != pl) continue;
                        if (*(short *)(e + 2) >= 0) pc++;
                        tmr = *(short *)(e + 0x58);
                    }
                    {   short bestS = 0, ci2;
                        for (ci2 = 0; ex && ci2 < sCityCount && ci2 < 99; ci2++) {
                            unsigned char *c = sCityData + ci2 * 0x20, *e = ex + 0x24c + ci2 * 0x5c; short kk2;
                            if (c[0x17] >= 2 || *(short *)(c + 4) != pl) continue;
                            for (kk2 = 0; kk2 < 4; kk2++) { short t = *(short *)(e + 6 + kk2 * 2); if (t >= 0 && UnitStatLE(t, 0) > bestS) bestS = UnitStatLE(t, 0); }
                        }
                        len += sprintf(o + len, " %d:%du%dg s%d", pl, u, *(short *)(scnData + 0x186 + pl * 0x14), bestS);
                    }
                }
            }
        }
        if (hasScn) {   /* every army whose sprite is the ship */
            short q, nn = *(short *)(scnData + 0x1602), yy = 24;
            for (q = 0; q < nn && q < MAX_ARMIES; q++) {
                unsigned char *qa = ARMY_REC(q);
                if (qa[0x14] == 5) {
                    char b2[64]; Str255 p2; short m;
                    sprintf(b2, "#%d o%d (%d,%d) t%d,%d,%d,%d nav%d", q, qa[0x15], *(short *)qa, *(short *)(qa + 2),
                            qa[0x16], qa[0x17], qa[0x18], qa[0x19], ArmyIsNaval(q));
                    for (m = 0; b2[m] && m < 60; m++) p2[m + 1] = b2[m];
                    p2[0] = (unsigned char)m;
                    TextFont(4); TextSize(9); TextMode(srcCopy);
                    { RGBColor y2 = {0xFFFF, 0xFFFF, 0}, k2 = {0, 0, 0}; RGBForeColor(&y2); RGBBackColor(&k2); }
                    MoveTo(4, yy); DrawString(p2); yy += 11;
                }
            }
        }
        for (n = 0; b[n] && n < 150; n++) ps[n + 1] = b[n];
        ps[0] = (unsigned char)n;
        TextFont(4); TextSize(9); TextMode(srcCopy);
        RGBForeColor(&yel); RGBBackColor(&blk);
        MoveTo(4, 12); DrawString(ps);
        TextMode(srcOr); RGBForeColor(&blk); RGBBackColor(&w);
    }
#endif
    if (bufGW != NULL) {                    /* copy the finished map to the window */
        RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
        Rect mr = winRect;
        SetGWorld(bufSavePort, bufSaveDev);
        win = realWin;
        SetOrigin(0, 0);
        ClipRect(&win->portRect);
        RGBForeColor(&black); RGBBackColor(&white);
        CopyBits((BitMap *)*GetGWorldPixMap(bufGW), &((GrafPtr)win)->portBits, &mr, &mr, srcCopy, NULL);
        UnlockPixels(GetGWorldPixMap(bufGW));
    }

    /* --- Native Mac scrollbar controls --- */
    {
        /* Only update values, not position/size (those are set on create/resize) */
        if (sVScrollBar != NULL) {
            short maxV = sMapHeight > tilesHigh ? sMapHeight - tilesHigh : 0;
            SetControlMaximum(sVScrollBar, maxV);
            SetControlValue(sVScrollBar, sViewportY);
            Draw1Control(sVScrollBar);
        }
        if (sHScrollBar != NULL) {
            short maxH = sMapWidth > tilesWide ? sMapWidth - tilesWide : 0;
            SetControlMaximum(sHScrollBar, maxH);
            SetControlValue(sHScrollBar, sViewportX);
            /* Draw1Control(sHScrollBar) deferred: the bottom bar PaintRect
             * (drawn further down) would erase the scrollbar.  We call
             * Draw1Control after all bottom-bar painting is finished. */
        }

        /* Standard grow box in the corner (clipped so DrawGrowIcon's
         * scroll-bar lines don't cross the turn strip) */
        {
            Rect corner = win->portRect;
            corner.left = corner.right - SCROLLBAR_W;
            corner.top  = corner.bottom - SCROLLBAR_H;
            ClipRect(&corner);
            DrawGrowIcon(win);
            ClipRect(&win->portRect);
        }
    }

    {
        Rect mapClip = winRect;
        SetOrigin(sViewPixX, sViewPixY);
        OffsetRect(&mapClip, sViewPixX, sViewPixY);
        ClipRect(&mapClip);
    }
    /* --- (remake-only yellow dotted path and red X: the original draws rings
     *      and a ghost instead, see the path preview) --- */
    if (0 && sSelectedArmy >= 0 && hasScn && scnData != NULL) {
        unsigned char *selA = ARMY_REC(sSelectedArmy);
        if (*(short *)(selA + 0x32) != 0) {
            /* Army has movement orders — draw dotted path to target */
            short sx = *(short *)(selA + 0x00);
            short sy = *(short *)(selA + 0x02);
            short tx = *(short *)(selA + 0x34);
            short ty = *(short *)(selA + 0x36);
            short px = sx, py = sy;
            short step;
            RGBColor pathCol = {0xFFFF, 0xFFFF, 0x0000};  /* yellow */
            RGBForeColor(&pathCol);

            for (step = 0; step < 60; step++) {
                short ddx = tx - px, ddy = ty - py;
                short stX = 0, stY = 0;
                short drawX, drawY;
                if (ddx > 0) stX = 1; else if (ddx < 0) stX = -1;
                if (ddy > 0) stY = 1; else if (ddy < 0) stY = -1;
                if (stX == 0 && stY == 0) break;
                px += stX;
                py += stY;

                /* Convert tile to screen coords */
                drawX = (px - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                drawY = (py - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if (drawX < 0 || drawY < 0) continue;
                if (drawX >= win->portRect.right - SCROLLBAR_W) continue;
                if (drawY >= win->portRect.bottom - SCROLLBAR_H) continue;

                /* Draw small dot every tile (alternating for dashes) */
                if (step % 2 == 0) {
                    Rect dot;
                    SetRect(&dot, drawX - 1, drawY - 1, drawX + 2, drawY + 2);
                    PaintRect(&dot);
                }
            }

            /* Draw target marker (X) at destination */
            {
                short dX = (tx - sViewportX) * TERRAIN_TILE_W + TERRAIN_TILE_W / 2;
                short dY = (ty - sViewportY) * TERRAIN_TILE_H + TERRAIN_TILE_H / 2;
                if (dX > 0 && dY > 0 &&
                    dX < win->portRect.right - SCROLLBAR_W &&
                    dY < win->portRect.bottom - SCROLLBAR_H) {
                    RGBColor red = {0xFFFF, 0x3333, 0x3333};
                    RGBForeColor(&red);
                    PenSize(2, 2);
                    MoveTo(dX - 4, dY - 4); LineTo(dX + 4, dY + 4);
                    MoveTo(dX + 4, dY - 4); LineTo(dX - 4, dY + 4);
                    PenSize(1, 1);
                }
            }
        }
    }

    SetOrigin(0, 0);
    ClipRect(&win->portRect);

    /* --- Turn strip (TTurnView) left of the h scroll bar ---
     * Measured on the original (o_map2.png, local coords): white strip
     * x 0..TURN_VIEW_W, black top line at the map's bottom edge; "Turn N" in
     * Chicago 12; shields in turn order (gs+0x164) at x 67+16*slot, y+2;
     * the current player's slot sits in a black box 3px wider each side. */
    if (hasScn && scnData != NULL) {
        Rect fullPort = win->portRect;
        short factionCount = 8;   /* all eight turn-order slots (gs+0x10C is advisor state) */
        short curPlayer = *(short *)(scnData + 0x110);
        short turn = *(short *)(scnData + 0x136);
        short top = fullPort.bottom - SCROLLBAR_H;      /* black line row */
        short slotIdx, aliveSlot = 0;
        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor black = {0x0000, 0x0000, 0x0000};
        Rect strip;
        Str255 numStr;

        if (factionCount < 1) factionCount = 1;
        if (factionCount > 8) factionCount = 8;

        SetRect(&strip, fullPort.left, top + 1, fullPort.left + TURN_VIEW_W, fullPort.bottom);
        RGBForeColor(&white);
        PaintRect(&strip);
        RGBForeColor(&black);
        MoveTo(fullPort.left, top);
        LineTo(fullPort.left + TURN_VIEW_W - 1, top);

        TextFont(0);
        TextSize(12);
        TextFace(0);
        MoveTo(fullPort.left + TURN_TEXT_X, top + 11);
        DrawString(GetCachedString(STR_MISC, 12, "\pTurn "));
        NumToString((long)turn, numStr);
        DrawString(numStr);

        /* 68k CODE_067: x = (i + (8 - alive)) * 16 + base, i.e. the alive sides'
         * shields are right-aligned in 8 slots (4 sides -> slots 4..7, one left
         * -> slot 7).  At 1024x768 the Control Strip covers slots 0-4. */
        {
            short alive = 0, p;
            for (p = 0; p < 8; p++)
                if (*(short *)(scnData + 0x138 + p * 2) != 0) alive++;
            aliveSlot = 8 - alive;
        }
        for (slotIdx = 0; slotIdx < 8; slotIdx++) {
            short factionIdx = *(short *)(scnData + 0x164 + slotIdx * 2);
            short sx;
            Rect sR;
            if (factionIdx < 0 || factionIdx >= 8) continue;
            if (*(short *)(scnData + 0x138 + factionIdx * 2) == 0) continue;
            if (aliveSlot > 7) break;
            sx = fullPort.left + 67 + aliveSlot * SHIELD_SLOT_W;
            if (factionIdx == curPlayer) {
                Rect bR;
                SetRect(&bR, sx - 3, top + 1, sx + SHIELD_ICON_W + 3, fullPort.bottom);
                RGBForeColor(&black);
                PaintRect(&bR);
            }
            SetRect(&sR, sx, top + 2, sx + SHIELD_ICON_W, top + 2 + SHIELD_ICON_H);
            if (sShieldsLoaded && (sShieldIcons[factionIdx] != NULL || sShieldSmallGW != NULL)) {
                DrawSmallShieldIcon(factionIdx, &sR);
            } else {
                RGBForeColor(&sPlayerColors[factionIdx + 1]);
                PaintRect(&sR);
            }
            aliveSlot++;
        }
        RGBForeColor(&black);
    }

    /* --- Horizontal scrollbar drawn LAST so bottom bar PaintRect doesn't erase it --- */
    if (sHScrollBar != NULL) {
        Draw1Control(sHScrollBar);
    }
}


/* ===================================================================
 * Overview map (TOverviewView), 2px per tile.
 *
 * The base image is built once per map like the original's PPC
 * FUN_10063af8 (CODE_128 only copies it and draws the overlays): PICT 1012
 * (ocean gradient) in a 224x312 8-bit GWorld on the game CLUT, then each
 * tile's four pixels from MAPCOLOR (terrain DAT 30020):
 *   +0     4 x 256 bytes, one table per quadrant (TL, TR, BL, BR)
 *   +1024  remap, 16 little-endian shorts (identity here)
 *   +1120  4 x 20 bytes for road tiles (RD & 0x1F, 1-based)
 * Values are pltt 1000 indices; 5 (water) is left out so the gradient shows.
 * Hill/mountain sprites 80..95 take their pixels from a pool of 256 values
 * 2..4 rolled up front (256 x Dice(1,3,1) on the game's Random() stream,
 * once per map: the sage's map refresh reuses the pool); the 4th read can
 * land one past the pool (white).  Validated against the original on
 * Erythea (100% of uncovered pixels) with the pool that run rolled
 * (QuickDraw randSeed 0x2AA0D649 at that point).
 * =================================================================== */
static GWorldPtr sOverviewBaseGW = NULL;

static void BuildOverviewBase(void)
{
    static unsigned char pool[257];
    Rect b;
    PixMapHandle pm;
    unsigned char *base, *mapData, *rdData;
    long rb;
    short x, y, i, c = 0;
    CGrafPtr sp; GDHandle sd;

    if (*gMapTiles == 0) return;
    mapData = (unsigned char *)*gMapTiles;
    rdData = (*gRoadData != 0) ? (unsigned char *)*gRoadData : NULL;

    if (sOverviewBaseFor != (Ptr)*gMapTiles || pool[0] == 0) {   /* FUN_10063af8 */
        for (i = 0; i < 256; i++) pool[i] = (unsigned char)Dice(1, 3, 1);
        pool[256] = 0;
    }

    if (sOverviewBaseGW != NULL) { DisposeGWorld(sOverviewBaseGW); sOverviewBaseGW = NULL; }
    SetRect(&b, 0, 0, sMapWidth * 2, sMapHeight * 2);
    {
        /* Own copy of the game CLUT: the GWorld keeps the handle it is given
         * and disposing the GWorld on a rebuild must not free sGameCTab. */
        Handle ct = (Handle)sGameCTab;
        if (ct == NULL || HandToHand(&ct) != noErr) ct = NULL;
        if (NewGWorld(&sOverviewBaseGW, 8, &b, (CTabHandle)ct, NULL, 0) != noErr ||
            sOverviewBaseGW == NULL) {
            sOverviewBaseGW = NULL;
            return;
        }
    }
    pm = GetGWorldPixMap(sOverviewBaseGW);
    LockPixels(pm);
    GetGWorld(&sp, &sd);
    SetGWorld(sOverviewBaseGW, NULL);
    {
        PicHandle ocean = GetPicture(1012);
        if (ocean != NULL) DrawPicture(ocean, &b);
        else EraseRect(&b);
    }
    SetGWorld(sp, sd);

    base = (unsigned char *)GetPixBaseAddr(pm);
    rb = (**pm).rowBytes & 0x3FFF;
    for (y = 0; y < sMapHeight; y++) {
        for (x = 0; x < sMapWidth; x++) {
            short rd = rdData ? (rdData[y * 112 + x] & 0x1F) : 0;
            short idx = rd ? rd - 1 : mapData[y * 0xE0 + x * 2];
            Boolean hill = (!rd && idx >= 80 && idx <= 95);
            short q;
            for (q = 0; q < 4; q++) {
                unsigned char col;
                if (hill) {
                    col = pool[c + q + 1];
                } else if (sMapColorFullLoaded) {
                    col = rd ? sMapColorFull[1120 + q * 20 + idx] : sMapColorFull[q * 256 + idx];
                    if (col < 16) col = sMapColorFull[1024 + col * 2];   /* little-endian shorts */
                    if (!rd && col == 5) continue;            /* water: keep gradient */
                    /* pltt 1000 #15 is an explicit (pmExplicit) magenta placeholder:
                     * on screen it is device entry 15, white (city window minimap) */
                    if (col == 15) col = 0;
                } else {
                    continue;
                }
                base[(long)(y * 2 + (q >> 1)) * rb + x * 2 + (q & 1)] = col;
            }
            if (hill && (c += 4) > 255) c = 0;
        }
    }
    UnlockPixels(pm);
    sOverviewBaseFor = (Ptr)*gMapTiles;
}


static void DrawOverviewInWindow(WindowPtr win)
{
    DrawOverviewTo((GrafPtr)win, win->portRect, kOvFrame | kOvOverlays);
}

static void DrawOverviewTo(GrafPtr port, Rect r, short flags)
{
    Boolean viewFrame = (flags & kOvFrame) != 0;
    if (!sMapLoaded || *gMapTiles == 0)
        return;

    SetGWorld((CGrafPtr)port, GetMainDevice());

    if (sOverviewBaseGW == NULL || sOverviewBaseFor != (Ptr)*gMapTiles)
        BuildOverviewBase();
    if (sOverviewBaseGW != NULL) {
        PixMapHandle opm = GetGWorldPixMap(sOverviewBaseGW);
        RGBColor black = {0, 0, 0}, white = {0xFFFF, 0xFFFF, 0xFFFF};
        Rect srcR;
        RGBForeColor(&black); RGBBackColor(&white);
        if (LockPixels(opm)) {
            srcR = (**opm).bounds;
            OffsetRect(&srcR, r.left - srcR.left, r.top - srcR.top);
            CopyBits((BitMap *)*opm, &port->portBits, &(**opm).bounds, &srcR, srcCopy, NULL);
            UnlockPixels(opm);
        }
    }

    if (flags & kOvOverlays) {
        short scale = 2;

        /* Fog of war overlay on minimap */
        if (*gGameState != 0 && *(short *)((unsigned char *)*gGameState + 0x124) != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short curP = *(short *)(gs2 + 0x110);
            if (curP >= 0 && curP < 8) {
                RGBColor fogBlack = {0, 0, 0};
                RGBColor fogDim = {0x3333, 0x3333, 0x3333};
                short fx, fy;
                for (fy = 0; fy < sMapHeight; fy++) {
                    for (fx = 0; fx < sMapWidth; fx++) {
                        if (!FogGetBit(sFogExplored[curP], fx, fy)) {
                            /* Unexplored: solid black */
                            RGBForeColor(&fogBlack);
                            if (scale == 1) {
                                MoveTo(r.left + fx, r.top + fy);
                                LineTo(r.left + fx, r.top + fy);
                            } else {
                                Rect fpx;
                                SetRect(&fpx, r.left + fx * scale, r.top + fy * scale,
                                             r.left + fx * scale + scale, r.top + fy * scale + scale);
                                PaintRect(&fpx);
                            }
                        } else if (!FogGetBit(sFogVisible[curP], fx, fy)) {
                            /* Explored but not visible: dimmed */
                            RGBForeColor(&fogDim);
                            PenMode(subOver);
                            if (scale == 1) {
                                MoveTo(r.left + fx, r.top + fy);
                                LineTo(r.left + fx, r.top + fy);
                            } else {
                                Rect fpx;
                                SetRect(&fpx, r.left + fx * scale, r.top + fy * scale,
                                             r.left + fx * scale + scale, r.top + fy * scale + scale);
                                PaintRect(&fpx);
                            }
                            PenMode(srcCopy);
                        }
                    }
                }
            }
        }

        /* Draw army dots on minimap (drawn first, cities go on top).
         * Off: the original's overview showed no marker even for the human's
         * hero outside a city (turn 2, Erythea); kept for the remake's
         * debug overlays. */
        if (*gGameState != 0 && sShowCityLabels) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short armyCount = *(short *)(gs2 + 0x1602);
            short ai;
            RGBColor black2 = {0, 0, 0};
            if (armyCount < 0) armyCount = 0;
            if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;

            for (ai = 0; ai < armyCount; ai++) {
                unsigned char *army = ARMY_REC(ai);
                short ax = *(short *)(army + 0x00);
                short ay = *(short *)(army + 0x02);
                short aOwner = (short)(unsigned char)army[0x15];
                short colorIdx = (aOwner >= 0 && aOwner < 8) ? aOwner + 1 : 8;

                if (army[0x16] == 0xFF) continue;
                if (ax >= 0 && ax < sMapWidth && ay >= 0 && ay < sMapHeight) {
                    /* Fog of war: hide enemy armies on minimap */
                    if (*(short *)(gs2 + 0x124) != 0) {
                        short curP = *(short *)(gs2 + 0x110);
                        if (curP >= 0 && curP < 8 && aOwner != curP &&
                            !FogGetBit(sFogVisible[curP], ax, ay))
                            continue;
                    }
                    /* Armies inside a city are covered by its shield in the
                     * original; the remake's marker peeked out as a dark
                     * shadow on the top/left of the grey shields. */
                    {
                        short cc, ncity = sCityCount > 139 ? 139 : sCityCount;
                        Boolean inCity = false;
                        for (cc = 0; cc < ncity && !inCity; cc++) {
                            unsigned char *ct = sCityData + cc * 0x20;
                            short ddx = ax - *(short *)(ct + 0), ddy = ay - *(short *)(ct + 2);
                            if (ct[0x17] < 2 && ddx >= 0 && ddx <= 1 && ddy >= 0 && ddy <= 1) inCity = true;
                        }
                        if (inCity) continue;
                    }
                    /* Colored dot for army position (68k CODE_128: 7px wide, from -2 to +5) */
                    Rect px;
                    SetRect(&px, r.left + ax * scale - 2, r.top + ay * scale - 2,
                                 r.left + ax * scale + 5, r.top + ay * scale + 5);
                    RGBForeColor(&black2);
                    PaintRect(&px);
                    InsetRect(&px, 1, 1);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PaintRect(&px);
                }
            }
        }

        /* Draw city shields on minimap ON TOP of army dots.
         * CopyBits from PICT 30010 (sMasterSpriteGW):
         *   Grey shield:    (131, 54, 139, 62) for neutral
         *   Colored shields: (faction*16+7, 86, faction*16+15, 94) for factions
         * Uses mode 36 (transparent) with sMasterSpriteBgColor as key. */
        if (*gGameState != 0 && sMasterSpriteGW != NULL) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            PixMapHandle pm = GetGWorldPixMap(sMasterSpriteGW);
            short cityCount = sCityCount;
            short ci;
            if (cityCount > 139) cityCount = 139;

            if (LockPixels(pm)) {
                RGBColor savedBg;
                GetBackColor(&savedBg);
                RGBBackColor(&sMasterSpriteBgColor);

                for (ci = 0; ci < cityCount; ci++) {
                    unsigned char *city = sCityData + ci * 0x20;
                    short cx = *(short *)(city + 0x00);
                    short cy = *(short *)(city + 0x02);
                    short owner = *(short *)(city + 0x04);
                    short siteType = (short)(unsigned char)city[0x17];

                    if (cx >= 0 && cx < sMapWidth && cy >= 0 && cy < sMapHeight) {
                        /* Fog of war: hide unexplored cities on minimap */
                        if (*(short *)(gs2 + 0x124) != 0) {
                            short curP = *(short *)(gs2 + 0x110);
                            if (curP >= 0 && curP < 8 &&
                                !FogGetBit(sFogExplored[curP], cx, cy))
                                continue;
                        }
                        if (siteType >= 2) {
                            /* Ruins/temples: 2x2 white at the site's tile
                             * (Erythea "The Old Cave" 89,20 -> 178,40) */
                            RGBColor ruinCol = {0xFFFF, 0xFFFF, 0xFFFF};
                            Rect dot;
                            SetRect(&dot, r.left + cx * scale, r.top + cy * scale,
                                    r.left + cx * scale + 2, r.top + cy * scale + 2);
                            RGBForeColor(&ruinCol);
                            PaintRect(&dot);
                        } else {
                            /* City: shield sprite from PICT 30010 */
                            Rect srcR, dstR;
                            if (owner >= 0 && owner < 8) {
                                SetRect(&srcR, owner * 16 + 7, 86,
                                               owner * 16 + 15, 94);
                            } else {
                                SetRect(&srcR, 131, 54, 139, 62);
                            }
                            /* CODE_128 FUN_00000d96: 8x8 at (2x-1, 2y-1) */
                            SetRect(&dstR,
                                    r.left + cx * scale - 1,
                                    r.top  + cy * scale - 1,
                                    r.left + cx * scale + 7,
                                    r.top  + cy * scale + 7);
                            CopyBits((BitMap *)*pm,
                                     &port->portBits,
                                     &srcR, &dstR, 36, NULL);
                        }
                    }
                }

                RGBBackColor(&savedBg);
                UnlockPixels(pm);
            }
        }

        /* Highlight selected army with crosshair */
        if (*gGameState != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short armyCount = *(short *)(gs2 + 0x1602);
            if (sSelectedArmy >= 0 && sSelectedArmy < armyCount) {
                unsigned char *selA = ARMY_REC(sSelectedArmy);
                short sx = *(short *)(selA + 0x00);
                short sy = *(short *)(selA + 0x02);
                if (sx >= 0 && sx < sMapWidth && sy >= 0 && sy < sMapHeight) {
                    RGBColor yellow = {0xFFFF, 0xFFFF, 0x0000};
                    short cx2 = r.left + sx * scale + scale / 2;
                    short cy2 = r.top + sy * scale + scale / 2;
                    RGBForeColor(&yellow);
                    /* Crosshair lines */
                    MoveTo(cx2 - 4, cy2);
                    LineTo(cx2 - 2, cy2);
                    MoveTo(cx2 + 2, cy2);
                    LineTo(cx2 + 4, cy2);
                    MoveTo(cx2, cy2 - 4);
                    LineTo(cx2, cy2 - 2);
                    MoveTo(cx2, cy2 + 2);
                    LineTo(cx2, cy2 + 4);
                }
            }
        }

        /* Viewport: 2px white frame around the visible map, measured on the
         * original: inner (px/20, py/20, ceil((px+W)/20)+1, ceil((py+H)/20)+1)
         * in map pixels (origin 3072,0 view 776x710 -> outer 151..196 x ..39) */
        if (viewFrame && gMainGameWindow != NULL && *gMainGameWindow != 0) {
            Rect p = ((WindowPtr)*gMainGameWindow)->portRect, vr;
            long vw = p.right - p.left - SCROLLBAR_W, vh = p.bottom - p.top - SCROLLBAR_H;
            long px = (long)sViewportX * TERRAIN_TILE_W + sViewPixX;
            long py = (long)sViewportY * TERRAIN_TILE_H + sViewPixY;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            SetRect(&vr, r.left + (short)(px / 20), r.top + (short)(py / 20),
                    r.left + (short)((px + vw + 19) / 20) + 1, r.top + (short)((py + vh + 19) / 20) + 1);
            InsetRect(&vr, -2, -2);
            RGBForeColor(&white);
            PenSize(2, 2);
            FrameRect(&vr);
            PenSize(1, 1);
        }
    }
}


/* ===================================================================
 * DrawMinimapInRect — draw a small overview map into any port rect
 *
 * Used by dialogs (hero hire, hero inspect, city info, etc.)
 * to show a minimap inset with an optional highlight marker.
 * highlightX/Y = -1 means no highlight.
 * =================================================================== */
static void DrawMinimapInRect(Rect *destRect, short highlightX, short highlightY)
{
    unsigned char *mapData;
    short x, y;

    if (!sMapLoaded || *gMapTiles == 0)
        return;

    mapData = (unsigned char *)*gMapTiles;

    /* Black background */
    {
        RGBColor bg = {0x0000, 0x0000, 0x3333};
        RGBForeColor(&bg);
        PaintRect(destRect);
    }

    /* 1 pixel per tile, clipped to destRect */
    {
        unsigned char *scnData = (*gGameState != 0) ? (unsigned char *)*gGameState : NULL;
        short destW = destRect->right - destRect->left;
        short destH = destRect->bottom - destRect->top;

        /* Fog check: if hidden map enabled, unexplored tiles rendered darker */
        { short curP = (scnData != NULL) ? *(short *)(scnData + 0x110) : -1;
          Boolean fogActive = (scnData != NULL && *(short *)(scnData + 0x124) != 0 &&
                               curP >= 0 && curP < 8);
          for (y = 0; y < sMapHeight && y < destH; y++) {
            for (x = 0; x < sMapWidth && x < destW; x++) {
                unsigned short tileOffset = y * 0xE0 + x * 2;
                unsigned char terrainIdx = mapData[tileOffset];
                Boolean explored = true;

                if (fogActive && !FogGetBit(sFogExplored[curP], x, y))
                    explored = false;

                if (!explored) {
                    /* Unexplored: dark blue */
                    RGBColor fogCol = {0x0000, 0x0000, 0x2222};
                    RGBForeColor(&fogCol);
                } else if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                    short colorIdx = (short)sMapColor[terrainIdx];
                    if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                    RGBForeColor(&sMinimapPalette[colorIdx]);
                } else if (scnData != NULL) {
                    short terrainType = (short)(unsigned char)scnData[terrainIdx + TERRAIN_TYPE_OFS];
                    if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                    RGBForeColor(&sTerrainColors[terrainType]);
                } else {
                    RGBForeColor(&sMinimapPalette[10]);
                }
                MoveTo(destRect->left + x, destRect->top + y);
                LineTo(destRect->left + x, destRect->top + y);
            }
          }
        }

        /* City dots / shields */
        if (*gGameState != 0) {
            unsigned char *gs2 = (unsigned char *)*gGameState;
            short cityCount = sCityCount;
            short ci;
            short curP2 = *(short *)(gs2 + 0x110);
            Boolean fogActive2 = (*(short *)(gs2 + 0x124) != 0 && curP2 >= 0 && curP2 < 8);
            if (cityCount > 139) cityCount = 139;
            for (ci = 0; ci < cityCount; ci++) {
                unsigned char *city = sCityData +ci * 0x20;
                short cx = *(short *)(city + 0x00);
                short cy = *(short *)(city + 0x02);
                short owner = *(short *)(city + 0x04);
                short sType = (short)(unsigned char)city[0x17];
                /* Fog of war: skip cities in unexplored areas */
                if (fogActive2 && !FogGetBit(sFogExplored[curP2], cx, cy))
                    continue;
                if (cx >= 0 && cx < destW && cy >= 0 && cy < destH) {
                    if (sType >= 2) {
                        /* Ruins/temples: bright dot */
                        RGBColor ruinCol = (sType == 2) ?
                            (RGBColor){0xFFFF, 0xDDDD, 0x3333} :
                            (RGBColor){0xDDDD, 0xDDDD, 0xAAAA};
                        Rect dot;
                        SetRect(&dot, destRect->left + cx - 1, destRect->top + cy - 1,
                                destRect->left + cx + 2, destRect->top + cy + 2);
                        RGBForeColor(&ruinCol);
                        PaintRect(&dot);
                    } else {
                        /* City: colored dot (3x3) */
                        short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                        Rect dot;
                        SetRect(&dot, destRect->left + cx - 1, destRect->top + cy - 1,
                                destRect->left + cx + 2, destRect->top + cy + 2);
                        RGBForeColor(&sPlayerColors[colorIdx]);
                        PaintRect(&dot);
                    }
                }
            }
        }

        /* Highlight marker (crosshair) */
        if (highlightX >= 0 && highlightY >= 0 &&
            highlightX < destW && highlightY < destH) {
            RGBColor yellow = {0xFFFF, 0xFFFF, 0x0000};
            short px = destRect->left + highlightX;
            short py = destRect->top + highlightY;
            RGBForeColor(&yellow);
            MoveTo(px - 5, py); LineTo(px - 2, py);
            MoveTo(px + 2, py); LineTo(px + 5, py);
            MoveTo(px, py - 5); LineTo(px, py - 2);
            MoveTo(px, py + 2); LineTo(px, py + 5);
        }

        /* Border */
        {
            RGBColor border = {0x6666, 0x6666, 0x6666};
            RGBForeColor(&border);
            FrameRect(destRect);
        }
    }
}


/* ===================================================================
 * ToggleMinimapZoom — cycle through 3 minimap zoom levels
 *
 * Small:  124x160, 1px/tile (default)
 * Medium: 180x220, 2px/tile
 * Large:  240x300, 2px/tile (more map visible)
 * =================================================================== */
static void ToggleMinimapZoom(void)
{
    WindowPtr overWin, infoWin;

    if (*gOverviewWindow == 0 || *gInfoWindow == 0)
        return;

    /* Get current overview window position for reference */
    overWin = (WindowPtr)*gOverviewWindow;
    infoWin = (WindowPtr)*gInfoWindow;

    sMinimapZoom = (sMinimapZoom + 1) % 3;

    {
        short newW, newH, infoTop;

        if (sMinimapZoom == 0) {
            /* Small: 2px/tile (drawing always uses 2), compact window */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW < 124) newW = 124;
            if (newH < 100) newH = 100;
            if (newW > 240) newW = 240;
            if (newH > 200) newH = 200;
        } else if (sMinimapZoom == 1) {
            /* Medium: 2px/tile, sized to fit map */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW > 300) newW = 300;
            if (newH > 350) newH = 350;
        } else {
            /* Large: sized to show entire map at 2px/tile */
            newW = sMapWidth * 2;
            newH = sMapHeight * 2;
            if (newW < 240) newW = 240;
            if (newH < 300) newH = 300;
            if (newW > 500) newW = 500;
            if (newH > 680) newH = 680;
        }

        SizeWindow(overWin, newW, newH, true);

        /* Info panel goes below minimap, moderate height */
        infoTop = 40 + newH + 2;
        MoveWindow(infoWin, 514, infoTop, false);
        SizeWindow(infoWin, newW, 160, true);
    }

    /* Force redraw of both windows */
    SetPort(overWin);
    InvalRect(&overWin->portRect);
    SetPort(infoWin);
    InvalRect(&infoWin->portRect);
}


/* ===================================================================
 * ShowHeroHire — Modal hero hire dialog
 *
 * Displays a hero offer with portrait (PICT 3200), name, stats,
 * and Hire / Don't Hire buttons.  Called at start of each human turn.
 * Returns true if the player hired the hero.
 *
 * Hero generation: random name from built-in list, stats scaled by
 * difficulty.  On hire, deducts gold and creates an army record.
 * =================================================================== */

/* ===================================================================
 * ShowSiteInfo — Modal dialog for ruins, temples, and other sites
 *
 * Shows site name and type. Uses PICT 4100 for ruins (crumbling castle)
 * and PICT 4101 for temples (classical temple columns).
 * =================================================================== */
static void ShowSiteInfo(short siteIndex)
{
    WindowPtr  siteWin;
    GWorldPtr  siteGW = NULL;
    Rect       winRect, gwRect, btnR;
    Boolean    done = false;
    unsigned char *site;
    short      siteType, siteX, siteY;
    Str255     siteName;
    short      winW = 460, winH = 340;
    short      panelX = 230;

    if (siteIndex < 0 || siteIndex >= sCityCount) return;
    if (*gGameState == 0) return;

    site = sCityData + siteIndex * 0x20;
    siteType = (short)(unsigned char)site[0x17];
    siteX = *(short *)(site + 0x00);
    siteY = *(short *)(site + 0x02);

    /* Get site name from gs+0x811 ruin records */
    {
        short ri, ruinOrd = 0;
        Boolean foundName = false;
        for (ri = 0; ri < siteIndex; ri++) {
            if ((unsigned char)(sCityData + ri * 0x20)[0x17] >= 2)
                ruinOrd++;
        }
        if (ruinOrd < 40) {
            unsigned char *rec = (unsigned char *)*gGameState + 0x811 + ruinOrd * 0x1F;
            unsigned char *nm = rec + 0x04;
            short ni;
            siteName[0] = 0;
            for (ni = 0; ni < 20 && nm[ni] != 0; ni++) {
                siteName[ni + 1] = nm[ni];
                siteName[0]++;
            }
            foundName = true;
        }
        if (!foundName) {
            siteName[0] = 4;
            siteName[1] = 'S'; siteName[2] = 'i'; siteName[3] = 't'; siteName[4] = 'e';
        }
    }

    /* Centered 460x340 dialog */
    {
        Rect screen = qd.screenBits.bounds;
        short sw = screen.right - screen.left;
        short sh = screen.bottom - screen.top;
        short dl = (sw - winW) / 2;
        short dt = (sh - winH) / 2;
        if (dt < 20) dt = 20;
        SetRect(&winRect, dl, dt, dl + winW, dt + winH);
    }

    siteWin = NewCWindow(NULL, &winRect, "\p", true,
                         dBoxProc, (WindowPtr)-1L, false, 0);
    if (siteWin == NULL) return;

    if (*gMainGameWindow != 0) {
        PaletteHandle gamePal = GetPalette((WindowPtr)*gMainGameWindow);
        if (gamePal != NULL)
            SetPalette(siteWin, gamePal, false);
    }

    SetRect(&gwRect, 0, 0, winW, winH);
    if (NewGWorld(&siteGW, 0, &gwRect, NULL, NULL, 0) != noErr || siteGW == NULL) {
        DisposeWindow(siteWin);
        return;
    }

    /* Done button rect */
    SetRect(&btnR, winW - 60, winH - 32, winW - 8, winH - 8);

    {
        CGrafPtr savePort; GDHandle saveGD;
        unsigned char *gs = (unsigned char *)*gGameState;
        short curPlayer = *(short *)(gs + 0x110);

        GetGWorld(&savePort, &saveGD);
        SetGWorld(siteGW, NULL);
        LockPixels(GetGWorldPixMap(siteGW));

        /* LEFT PANEL: marble + minimap */
        {
            Rect leftPanel;
            SetRect(&leftPanel, 0, 0, panelX, winH);
            DrawMarbleBackground(&leftPanel);
            if (sMapLoaded && *gMapTiles != 0 && sMapWidth > 0 && sMapHeight > 0) {
                unsigned char *mapData = (unsigned char *)*gMapTiles;
                short scaleX = panelX / sMapWidth;
                short scale  = (scaleX > 1) ? scaleX : 1;
                short mmW = sMapWidth * scale;
                short mmH = sMapHeight * scale;
                short mmX = (panelX - mmW) / 2;
                short mmY = (winH - mmH) / 2;
                short mx, my;
                for (my = 0; my < sMapHeight; my++) {
                    for (mx = 0; mx < sMapWidth; mx++) {
                        unsigned short tileOffset = my * 0xE0 + mx * 2;
                        unsigned char terrainIdx = mapData[tileOffset];
                        Rect tileR;
                        SetRect(&tileR,
                            mmX + mx * scale, mmY + my * scale,
                            mmX + mx * scale + scale, mmY + my * scale + scale);
                        if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                            short colorIdx = (short)sMapColor[terrainIdx];
                            if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                            RGBForeColor(&sMinimapPalette[colorIdx]);
                        } else {
                            short terrainType = (short)(unsigned char)gs[terrainIdx + TERRAIN_TYPE_OFS];
                            if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                            RGBForeColor(&sTerrainColors[terrainType]);
                        }
                        PaintRect(&tileR);
                    }
                }
                /* City/site icons on minimap */
                {
                    short ci2, cc2 = sCityCount;
                    if (cc2 > 139) cc2 = 139;
                    for (ci2 = 0; ci2 < cc2; ci2++) {
                        unsigned char *c2 = sCityData + ci2 * 0x20;
                        short cx2 = *(short *)(c2 + 0x00);
                        short cy2 = *(short *)(c2 + 0x02);
                        short st = (short)(unsigned char)c2[0x17];
                        if (st >= 2) {
                            RGBColor ruinGray = {0x9999, 0x9999, 0x7777};
                            Rect rdot;
                            SetRect(&rdot, mmX+cx2*scale, mmY+cy2*scale,
                                           mmX+cx2*scale+3, mmY+cy2*scale+3);
                            RGBForeColor(&ruinGray);
                            PaintRect(&rdot);
                        } else {
                            Rect shR2;
                            SetRect(&shR2,
                                    mmX + cx2 * scale - 3, mmY + cy2 * scale - 3,
                                    mmX + cx2 * scale + 5, mmY + cy2 * scale + 5);
                            DrawMinimapShield(&shR2);
                        }
                    }
                }
                /* Highlight current site */
                {
                    Rect selR;
                    SetRect(&selR,
                            mmX + siteX * scale - 4, mmY + siteY * scale - 4,
                            mmX + siteX * scale + 6, mmY + siteY * scale + 6);
                    DrawMinimapSelectionShield(&selR);
                }
            }
        }

        /* RIGHT PANEL: marble background */
        {
            Rect rightR;
            SetRect(&rightR, panelX, 0, winW, winH);
            DrawMarbleBackground(&rightR);
        }

        /* Site name in gold, centered in right panel */
        {
            RGBColor gold = {0xFFFF, 0xDDDD, 0x4444};
            short tw;
            RGBForeColor(&gold);
            TextFont(2); TextSize(18); TextFace(bold);
            tw = StringWidth(siteName);
            MoveTo(panelX + ((winW - panelX) - tw) / 2, 28);
            DrawString(siteName);
            TextFace(0);
        }

        /* Illustration PICT (4100=ruin, 4101=temple) */
        {
            PicHandle illPic = GetPicture(siteType == 2 ? 4101 : 4100);
            Rect picDst;
            SetRect(&picDst, panelX + 10, 42, panelX + 160, 150);
            if (illPic != NULL) {
                HLock((Handle)illPic);
                DrawPicture(illPic, &picDst);
                HUnlock((Handle)illPic);
            } else {
                RGBColor dk = {0x2222, 0x2222, 0x2222};
                RGBForeColor(&dk);
                PaintRect(&picDst);
            }
            /* Dark border around illustration */
            {
                RGBColor bdr = {0x3333, 0x3333, 0x3333};
                RGBForeColor(&bdr);
                PenSize(2, 2);
                FrameRect(&picDst);
                PenSize(1, 1);
            }
        }

        /* Type and Explored status next to illustration */
        {
            const char *tl;
            Boolean explored;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            /* the original only distinguishes temples and ruins; what a ruin
             * holds (site+0x0C) is unknown until it is searched */
            if (siteType == 2) tl = "Temple";
            else tl = "Ruin";
            explored = (curPlayer >= 0 && curPlayer < 8) ?
                       (site[0x1E] & (1 << curPlayer)) != 0 : false;
            RGBForeColor(&white);
            TextFont(3); TextSize(10); TextFace(0);
            MoveTo(panelX + 170, 70);
            DrawString("\pType: ");
            {
                Str255 ts; short tl2 = 0;
                while (tl[tl2]) tl2++;
                ts[0] = (unsigned char)tl2;
                BlockMoveData(tl, ts + 1, tl2);
                DrawString(ts);
            }
            MoveTo(panelX + 170, 85);
            DrawString(explored ? "\pExplored: Yes" : "\pExplored: No");
        }

        /* Legend box */
        {
            Rect legR;
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBColor grey = {0x8888, 0x8888, 0x8888};
            RGBColor labelC = {0xDDDD, 0xDDDD, 0xDDDD};
            short legX = panelX + 10, legY = 162;
            SetRect(&legR, legX, legY, winW - 10, legY + 62);
            RGBForeColor(&white);
            PaintRect(&legR);
            RGBForeColor(&grey);
            FrameRect(&legR);

            TextFont(3); TextSize(9); TextFace(0);
            RGBForeColor(&labelC);
            /* Row 1: unexplored icon + explored icon */
            if (sRuinIcons[0] != NULL) {
                Rect ir; SetRect(&ir, legX + 6, legY + 6, legX + 22, legY + 22);
                PlotCIcon(&ir, sRuinIcons[0]);
            }
            {
                RGBColor dk = {0x3333, 0x3333, 0x3333};
                RGBForeColor(&dk);
            }
            MoveTo(legX + 26, legY + 18);
            DrawString("\pUnexplored");
            if (sRuinIcons[1] != NULL) {
                Rect ir; SetRect(&ir, legX + 108, legY + 6, legX + 124, legY + 22);
                PlotCIcon(&ir, sRuinIcons[1]);
            }
            MoveTo(legX + 128, legY + 18);
            DrawString("\pExplored");
            /* Row 2: temple + stronghold (colored squares) */
            {
                Rect sq;
                RGBColor tplC = {0x8888, 0x4444, 0xFFFF};
                RGBColor strC = {0xCCCC, 0x6666, 0x2222};
                RGBColor dk2 = {0x3333, 0x3333, 0x3333};
                SetRect(&sq, legX + 6, legY + 32, legX + 22, legY + 48);
                RGBForeColor(&tplC); PaintRect(&sq);
                RGBForeColor(&dk2);
                MoveTo(legX + 26, legY + 44);
                DrawString("\pTemple");
                SetRect(&sq, legX + 108, legY + 32, legX + 124, legY + 48);
                RGBForeColor(&strC); PaintRect(&sq);
                RGBForeColor(&dk2);
                MoveTo(legX + 128, legY + 44);
                DrawString("\pStronghold");
            }
        }

        /* Flavor text from sSiteDescs */
        if (siteIndex < 99 && sSiteDescs[siteIndex][0] != '\0') {
            char *desc = sSiteDescs[siteIndex];
            short descLen = 0, di = 0;
            short lineY = 240;
            RGBColor descC = {0xAAAA, 0xDDDD, 0xAAAA};
            while (desc[descLen]) descLen++;
            RGBForeColor(&descC);
            TextFont(3); TextSize(9); TextFace(italic);
            while (di < descLen && lineY <= 300) {
                short end = di + 38;
                short bp;
                if (end >= descLen) end = descLen;
                else {
                    bp = end;
                    while (bp > di && desc[bp] != ' ') bp--;
                    if (bp > di) end = bp;
                }
                {
                    Str255 ls;
                    short ll = end - di;
                    if (ll > 254) ll = 254;
                    ls[0] = (unsigned char)ll;
                    BlockMoveData(desc + di, ls + 1, ll);
                    MoveTo(panelX + 12, lineY);
                    DrawString(ls);
                }
                di = end;
                if (di < descLen && desc[di] == ' ') di++;
                lineY += 12;
            }
            TextFace(0);
        }

        /* Done button */
        {
            RGBColor grey = {0x9999, 0x9999, 0x9999};
            RGBColor dk = {0x3333, 0x3333, 0x3333};
            RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBForeColor(&grey);
            PaintRoundRect(&btnR, 8, 8);
            RGBForeColor(&dk);
            FrameRoundRect(&btnR, 8, 8);
            TextFont(0); TextSize(12); TextFace(bold);
            RGBForeColor(&white);
            MoveTo(btnR.left + (btnR.right - btnR.left - StringWidth("\pDone")) / 2,
                   btnR.top + 17);
            DrawString("\pDone");
        }

        /* Gold border */
        {
            RGBColor gbdr = {0xCCCC, 0xAAAA, 0x3333};
            RGBForeColor(&gbdr);
            PenSize(2, 2);
            FrameRect(&gwRect);
            PenSize(1, 1);
        }

        UnlockPixels(GetGWorldPixMap(siteGW));
        SetGWorld(savePort, saveGD);

        /* Blit to window */
        SetPort(siteWin);
        {
            Rect dr = siteWin->portRect;
            LockPixels(GetGWorldPixMap(siteGW));
            CopyBits((BitMap *)*GetGWorldPixMap(siteGW),
                     &((GrafPtr)siteWin)->portBits,
                     &gwRect, &dr, srcCopy, NULL);
            UnlockPixels(GetGWorldPixMap(siteGW));
        }
    }

    /* Event loop */
    while (!done) {
        EventRecord ev;
        if (WaitNextEvent(mDownMask | keyDownMask | updateMask, &ev, 10, NULL)) {
            if (ev.what == mouseDown) {
                Point lp = ev.where;
                SetPort(siteWin);
                GlobalToLocal(&lp);
                if (PtInRect(lp, &btnR)) done = true;
            } else if (ev.what == keyDown) {
                char key = ev.message & charCodeMask;
                if (key == '\r' || key == 0x03 || key == 0x1B) done = true;
            } else if (ev.what == updateEvt) {
                BeginUpdate(siteWin);
                SetPort(siteWin);
                {
                    Rect dr = siteWin->portRect;
                    LockPixels(GetGWorldPixMap(siteGW));
                    CopyBits((BitMap *)*GetGWorldPixMap(siteGW),
                             &((GrafPtr)siteWin)->portBits,
                             &gwRect, &dr, srcCopy, NULL);
                    UnlockPixels(GetGWorldPixMap(siteGW));
                }
                EndUpdate(siteWin);
            }
        }
    }

    DisposeGWorld(siteGW);
    DisposeWindow(siteWin);
}

/* ===================================================================
 * ShowCityInfo — Modal city dialog with info, production, and armies
 *
 * Full city management dialog matching original 68k behavior:
 * - Info tab: name, owner, defense, income, production status
 * - Production tab: change production type (own cities only)
 * - Armies at city: list of armies stationed here
 * cityIndex is the index into the SCN city table at gs+0x812.
 * =================================================================== */
static void ShowCityWindow(short cityIndex, short startTab);
static void ShowCityInfo(short cityIndex)
{
    /* the original's city window on its Info pane (View 3301) */
    if (1) { ShowCityWindow(cityIndex, 0); return; }
    WindowPtr  cityWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect;
    Boolean    done = false;
    Rect       screenRect = qd.screenBits.bounds;
    unsigned char *gs;
    unsigned char *city;
    short      cityX, cityY, owner, defense, income;
    short      curTab;  /* 0=Info, 1=Production, 2=Armies */
    Boolean    isOwnCity;
    short      curPlayer;
    #define CITY_WIN_W 460
    #define CITY_WIN_H 340

    if (*gGameState == 0)
        return;

    gs = (unsigned char *)*gGameState;

    {
        short cityCount = sCityCount;
        if (cityIndex < 0 || cityIndex >= cityCount)
            return;
    }

    city = sCityData +cityIndex * 0x20;
    cityX   = *(short *)(city + 0x00);
    cityY   = *(short *)(city + 0x02);
    owner   = *(short *)(city + 0x04);
    defense = *(short *)(city + 0x06);
    income  = *(short *)(city + 0x08);
    curPlayer = *(short *)(gs + 0x110);
    isOwnCity = (owner >= 0 && owner < 8 && owner == curPlayer);
    curTab = isOwnCity ? 0 : 2;  /* Armies tab default for non-owned cities */

    /* Centered window (matches ShowCityBuildSelection layout) */
    {
        short sw = screenRect.right - screenRect.left;
        short sh = screenRect.bottom - screenRect.top;
        short dl = (sw - CITY_WIN_W) / 2;
        short dt = (sh - CITY_WIN_H) / 2;
        if (dt < 20) dt = 20;
        SetRect(&winRect, dl, dt, dl + CITY_WIN_W, dt + CITY_WIN_H);
    }

    cityWin = NewCWindow(NULL, &winRect, "\p", true,
                          dBoxProc, (WindowPtr)-1L, false, 0);
    if (cityWin == NULL)
        return;

    SetPort(cityWin);

    {
        Rect obounds;
        SetRect(&obounds, 0, 0, CITY_WIN_W, CITY_WIN_H);
        NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
    }

    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        unsigned long startTick = TickCount();
        /* Production slot button rects (up to 4) */
        Rect prodBtnR[4];
        short numProdSlots = 0;
        /* Tab button rects */
        Rect tabR[3];

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                RGBColor labelColor = {0xAAAA, 0xAAAA, 0xAAAA};
                RGBColor valueColor = {0xCCCC, 0xDDDD, 0xFFFF};
                RGBColor gold = {0xFFFF, 0xCCCC, 0x3333};
                RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                RGBColor black = {0, 0, 0};
                Str255 numStr;
                SetRect(&r, 0, 0, CITY_WIN_W, CITY_WIN_H);

                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* Background: left panel minimap + right panel marble */
                {
                    short panelX = CITY_WIN_W / 2;  /* 230 */
                    Rect leftPanel, rightPanel;
                    SetRect(&leftPanel, 0, 0, panelX, CITY_WIN_H);
                    SetRect(&rightPanel, panelX, 0, CITY_WIN_W, CITY_WIN_H);
                    DrawMarbleBackground(&leftPanel);
                    DrawMarbleBackground(&rightPanel);

                    /* Left panel: minimap (matches ShowCityBuildSelection) */
                    if (sMapLoaded && *gMapTiles != 0 && sMapWidth > 0 && sMapHeight > 0) {
                        unsigned char *mapData = (unsigned char *)*gMapTiles;
                        unsigned char *scnData2 = gs;
                        short scaleX = panelX / sMapWidth;
                        short scale  = (scaleX > 1) ? scaleX : 1;
                        short mmW = sMapWidth * scale;
                        short mmH = sMapHeight * scale;
                        short mmX = (panelX - mmW) / 2;
                        short mmY = (CITY_WIN_H - mmH) / 2;
                        short mx, my;
                        for (my = 0; my < sMapHeight; my++) {
                            for (mx = 0; mx < sMapWidth; mx++) {
                                unsigned short tileOffset = my * 0xE0 + mx * 2;
                                unsigned char terrainIdx = mapData[tileOffset];
                                Rect tileR;
                                SetRect(&tileR,
                                    mmX + mx * scale, mmY + my * scale,
                                    mmX + mx * scale + scale, mmY + my * scale + scale);
                                if (sMapColorLoaded && terrainIdx < MAPCOLOR_SIZE) {
                                    short colorIdx = (short)sMapColor[terrainIdx];
                                    if (colorIdx >= MINIMAP_PAL_SIZE) colorIdx = 0;
                                    RGBForeColor(&sMinimapPalette[colorIdx]);
                                } else if (scnData2 != NULL) {
                                    short terrainType = (short)(unsigned char)scnData2[terrainIdx + TERRAIN_TYPE_OFS];
                                    if (terrainType >= NUM_TERRAIN_COLORS) terrainType = 0;
                                    RGBForeColor(&sTerrainColors[terrainType]);
                                } else {
                                    RGBColor water = {0x0000, 0x4444, 0xAAAA};
                                    RGBForeColor(&water);
                                }
                                PaintRect(&tileR);
                            }
                        }
                        /* City shield icons on minimap */
                        {
                            short ci2;
                            short cc2 = sCityCount;
                            if (cc2 > 139) cc2 = 139;
                            for (ci2 = 0; ci2 < cc2; ci2++) {
                                unsigned char *c2 = sCityData + ci2 * 0x20;
                                short cx2 = *(short *)(c2 + 0x00);
                                short cy2 = *(short *)(c2 + 0x02);
                                short st = (short)(unsigned char)c2[0x17];
                                if (st >= 2) {
                                    /* Ruins/temples: small gray dot */
                                    RGBColor ruinGray = {0x9999, 0x9999, 0x7777};
                                    Rect rdot;
                                    SetRect(&rdot, mmX+cx2*scale, mmY+cy2*scale,
                                                   mmX+cx2*scale+3, mmY+cy2*scale+3);
                                    RGBForeColor(&ruinGray);
                                    PaintRect(&rdot);
                                } else {
                                    /* City: grey shield from PICT 30010 */
                                    Rect shR2;
                                    SetRect(&shR2,
                                            mmX + cx2 * scale - 3,
                                            mmY + cy2 * scale - 3,
                                            mmX + cx2 * scale + 5,
                                            mmY + cy2 * scale + 5);
                                    DrawMinimapShield(&shR2);
                                }
                            }
                        }
                        /* Selection shield on current city */
                        if (cityX >= 0 && cityY >= 0) {
                            Rect selR2;
                            SetRect(&selR2,
                                    mmX + cityX * scale - 4,
                                    mmY + cityY * scale - 4,
                                    mmX + cityX * scale + 6,
                                    mmY + cityY * scale + 6);
                            DrawMinimapSelectionShield(&selR2);
                        }
                    }
                }

                /* Owner-colored border on right panel */
                {
                    short panelX = CITY_WIN_W / 2;
                    Rect rightR2;
                    short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                    SetRect(&rightR2, panelX, 0, CITY_WIN_W, CITY_WIN_H);
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PenSize(3, 3);
                    FrameRect(&rightR2);
                    PenSize(1, 1);
                }

                /* Owner shield */
                if (owner >= 0 && owner < 8) {
                    short panelX = CITY_WIN_W / 2;
                    Rect shR;
                    SetRect(&shR, panelX + 8, 10,
                            panelX + 8 + BIG_SHIELD_W, 10 + BIG_SHIELD_H);
                    DrawBigShield(owner, &shR);
                }

                /* City name */
                {
                    short panelX = CITY_WIN_W / 2;
                    RGBForeColor(&gold);
                    TextFont(2);
                    TextSize(18);
                    TextFace(bold);
                    MoveTo(panelX + 60, 28);
                    if (cityIndex < sCityNameCount && sCityNames[cityIndex][0] != '\0') {
                        Str255 pName;
                        char *cn = sCityNames[cityIndex];
                        short nlen = 0;
                        while (nlen < MAX_CITY_NAME - 1 && cn[nlen] != '\0') nlen++;
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(cn, pName + 1, nlen);
                        DrawString(pName);
                    } else if (owner >= 0 && owner < 8) {
                        Str255 pName;
                        unsigned char *namePtr = gs + owner * 20;
                        short nlen = 0;
                        while (nlen < 20 && namePtr[nlen] != 0) nlen++;
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(namePtr, pName + 1, nlen);
                        DrawString(pName);
                        DrawString("\p City");
                    } else {
                        DrawString("\pNeutral City");
                    }
                }

                /* Owner name below city name */
                if (owner >= 0 && owner < 8) {
                    short panelX = CITY_WIN_W / 2;
                    Str255 pName;
                    unsigned char *namePtr = gs + owner * 20;
                    short nlen = 0;
                    while (nlen < 20 && namePtr[nlen] != 0) nlen++;
                    pName[0] = (unsigned char)nlen;
                    BlockMoveData(namePtr, pName + 1, nlen);
                    RGBForeColor(&white);
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    MoveTo(panelX + 60, 42);
                    DrawString(pName);
                }

                /* CAPITAL badge if this city is a player's capital */
                {
                    short panelX = CITY_WIN_W / 2;
                    short pp;
                    short factionCount = 8;
                    for (pp = 0; pp < factionCount; pp++) {
                        unsigned char *pstat = gs + 0x186 + pp * 0x14;
                        short capX = *(short *)(pstat + 0x04);
                        short capY = *(short *)(pstat + 0x06);
                        if (capX == cityX && capY == cityY) {
                            RGBColor capCol = {0xFFFF, 0xDDDD, 0x2222};
                            RGBForeColor(&capCol);
                            TextFont(3);
                            TextSize(9);
                            TextFace(bold);
                            MoveTo(panelX + 60, 54);
                            DrawString("\pCAPITAL");
                            TextFace(0);
                            break;
                        }
                    }
                }

                /* Content area (right panel, above bottom buttons) */
                {
                    short panelX = CITY_WIN_W / 2;
                    Rect contentR;
                    RGBColor contentBg = {0x1111, 0x1111, 0x1111};
                    SetRect(&contentR, panelX + 4, 58, CITY_WIN_W - 4, CITY_WIN_H - 46);
                    RGBForeColor(&contentBg);
                    PaintRect(&contentR);
                    {
                        RGBColor contentBdr = {0x5555, 0x5555, 0x5555};
                        RGBForeColor(&contentBdr);
                        FrameRect(&contentR);
                    }
                }

                /* Bottom nav buttons (matches ShowCityBuildSelection layout) */
                {
                    short panelX = CITY_WIN_W / 2;
                    short navBtnW2 = 36, navBtnH2 = 36;
                    short navBtnY2 = CITY_WIN_H - navBtnH2 - 6;
                    short navXs2[3];
                    short navCicnIDs2[3] = {3300, 3301, 3303};  /* ?=Info, tower=Build, arrows=Armies */
                    short ni2;
                    RGBColor navGrey2   = {0x9999, 0x9999, 0x9999};
                    RGBColor navBorder2 = {0x4444, 0x4444, 0x4444};
                    RGBColor navAmber2  = {0xFFFF, 0xAA00, 0x0000};
                    navXs2[0] = panelX + 4;
                    navXs2[1] = navXs2[0] + navBtnW2 + 2;
                    navXs2[2] = navXs2[1] + navBtnW2 + 2;
                    for (ni2 = 0; ni2 < 3; ni2++) {
                        CIconHandle navIcon2;
                        SetRect(&tabR[ni2], navXs2[ni2], navBtnY2,
                                navXs2[ni2] + navBtnW2, navBtnY2 + navBtnH2);
                        /* Grey background */
                        RGBForeColor(&navGrey2);
                        PaintRect(&tabR[ni2]);
                        /* Border: amber for active tab, dark grey otherwise */
                        RGBForeColor(ni2 == curTab ? &navAmber2 : &navBorder2);
                        PenSize(2, 2);
                        FrameRect(&tabR[ni2]);
                        PenSize(1, 1);
                        navIcon2 = GetCIcon(navCicnIDs2[ni2]);
                        if (navIcon2 != NULL) {
                            PlotCIcon(&tabR[ni2], navIcon2);
                            DisposeCIcon(navIcon2);
                        }
                    }
                    /* Done button (black bg, white border+text) */
                    {
                        short dBtnW = 44, dBtnH = navBtnH2;
                        short dBtnX = navXs2[2] + navBtnW2 + 4;
                        Rect doneR2;
                        short tw5;
                        SetRect(&doneR2, dBtnX, navBtnY2, dBtnX + dBtnW, navBtnY2 + dBtnH);
                        RGBForeColor(&black);
                        PaintRoundRect(&doneR2, 8, 8);
                        RGBForeColor(&white);
                        PenSize(2, 2);
                        FrameRoundRect(&doneR2, 8, 8);
                        PenSize(1, 1);
                        TextFont(0);
                        TextSize(10);
                        TextFace(bold);
                        tw5 = StringWidth("\pDone");
                        MoveTo(dBtnX + (dBtnW - tw5) / 2, navBtnY2 + dBtnH / 2 + 4);
                        DrawString("\pDone");
                        TextFace(0);
                    }
                }

                /* ---- Tab content ---- */
                if (curTab == 0) {
                    /* INFO TAB */
                    short xOff = CITY_WIN_W / 2;  /* panel offset */
                    short yBase = 90;
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);

                    /* Defense */
                    RGBForeColor(&labelColor);
                    MoveTo(xOff + 12, yBase);
                    DrawString("\pDefense:");
                    RGBForeColor(&valueColor);
                    MoveTo(xOff + 90, yBase);
                    NumToString((long)defense, numStr);
                    DrawString(numStr);

                    /* Income */
                    RGBForeColor(&labelColor);
                    MoveTo(xOff + 12, yBase + 18);
                    DrawString("\pIncome:");
                    RGBForeColor(&valueColor);
                    MoveTo(xOff + 90, yBase + 18);
                    NumToString((long)income, numStr);
                    DrawString(numStr);
                    DrawString("\p gp/turn");

                    /* Production status (compact: current unit + turns remaining) */
                    if (*gExtState != 0) {
                        unsigned char *ext = (unsigned char *)*gExtState;
                        unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                        short producing = *(short *)(extCity + 0x02);
                        short prodTurns = *(short *)(extCity + 0x58);

                        RGBForeColor(&labelColor);
                        MoveTo(xOff + 12, yBase + 36);
                        DrawString("\pProducing:");
                        RGBForeColor(&valueColor);
                        MoveTo(xOff + 90, yBase + 36);
                        if (producing >= 0) {
                            Str255 prodName;
                            short totalTurns = CitySlotStat(cityIndex, producing, 1);
                            short elapsed = totalTurns - prodTurns;
                            short barW = CITY_WIN_W / 2 - 25;
                            short fillW;
                            Rect trackR2, fillR2;
                            RGBColor trackCol = {0x3333, 0x3333, 0x3333};
                            RGBColor fillCol = {0x3333, 0xBBBB, 0x3333};
                            GetUnitTypeName(producing, prodName);
                            DrawString(prodName);
                            DrawString("\p (");
                            NumToString((long)prodTurns, numStr);
                            DrawString(numStr);
                            DrawString("\p)");
                            /* Compact progress bar */
                            if (elapsed < 0) elapsed = 0;
                            if (elapsed > totalTurns) elapsed = totalTurns;
                            fillW = (totalTurns > 0) ? (elapsed * barW) / totalTurns : 0;
                            SetRect(&trackR2, xOff + 12, yBase + 42, xOff + 12 + barW, yBase + 48);
                            RGBForeColor(&trackCol);
                            PaintRoundRect(&trackR2, 3, 3);
                            if (fillW > 0) {
                                SetRect(&fillR2, xOff + 12, yBase + 42, xOff + 12 + fillW, yBase + 48);
                                RGBForeColor(&fillCol);
                                PaintRoundRect(&fillR2, 3, 3);
                            }
                            {
                                RGBColor bdr = {0x6666, 0x6666, 0x6666};
                                RGBForeColor(&bdr);
                                FrameRoundRect(&trackR2, 3, 3);
                            }
                        } else {
                            DrawString("\pNothing");
                        }

                        /* Available production unit icons (circular, 4 slots)
                         * Info-only: no highlighting, no selection */
                        {
                            short pi3, iconX = xOff + 8;
                            short iconY = yBase + 60;
                            short iconSz = 40;  /* circular icon diameter */
                            short pSheet = (owner >= 0 && owner < ARMY_SHEETS) ? owner : 0;
                            GWorldPtr pGW = sArmyGW[pSheet] ? sArmyGW[pSheet] : sArmyGW[0];
                            /* Only draw circles for valid production types (skip empty -1 slots) */
                            for (pi3 = 3; pi3 >= 0; pi3--) {
                                short pType = *(short *)(extCity + 0x06 + pi3 * 2);
                                Rect iconOval;
                                if (pType < 0 || pType >= MAX_UNIT_TYPES) continue;
                                SetRect(&iconOval, iconX, iconY, iconX + iconSz, iconY + iconSz);
                                {
                                    RGBColor circleBg = {0x2222, 0x2222, 0x2222};
                                    RGBColor circleBdr = {0x5555, 0x5555, 0x5555};
                                    RGBForeColor(&circleBg);
                                    PaintOval(&iconOval);
                                    RGBForeColor(&circleBdr);
                                    FrameOval(&iconOval);
                                }
                                /* Unit sprite centered in circle */
                                if (sArmyLoaded && pGW != NULL) {
                                    short si2 = pType;
                                    Rect srcR3, dstR3;
                                    PixMapHandle pm3;
                                    if (sUnitTypesLoaded && pType < sUnitTypeCount) {
                                        unsigned char *ute = sUnitTypeTable + pType * UNIT_TYPE_ENTRY;
                                        si2 = (short)ute[0x00];
                                    }
                                    SetRect(&srcR3, (si2 % 16) * 32, (si2 / 16) * 30,
                                            (si2 % 16) * 32 + 32, (si2 / 16) * 30 + 29);
                                    SetRect(&dstR3, iconX + 5, iconY + 4,
                                            iconX + iconSz - 5, iconY + iconSz - 4);
                                    pm3 = GetGWorldPixMap(pGW);
                                    if (LockPixels(pm3)) {
                                        RGBColor savedBg3;
                                        GetBackColor(&savedBg3);
                                        RGBBackColor(&sArmyBgColor[pSheet]);
                                        CopyBits((BitMap *)*pm3,
                                                 (BitMap *)*GetGWorldPixMap(offscreen),
                                                 &srcR3, &dstR3, 36, NULL);
                                        RGBBackColor(&savedBg3);
                                        UnlockPixels(pm3);
                                    }
                                }
                                iconX += iconSz + 6;
                            }
                        }
                    }

                    /* City description text from CTY resource */
                    if (cityIndex < sCityNameCount && sCityDescs[cityIndex][0] != '\0') {
                        char descBuf[MAX_CITY_DESC], *desc = descBuf;
                        { short q; for (q = 0; q < MAX_CITY_DESC; q++) {
                              descBuf[q] = sCityDescs[cityIndex][q] == '|' ? ' ' : sCityDescs[cityIndex][q];
                              if (!descBuf[q]) break; } }
                        short di = 0;
                        short descLen = 0;
                        short lineY = CITY_WIN_H - 70;  /* bottom area */
                        RGBColor descColor = {0x9999, 0xBBBB, 0x9999};  /* muted green */
                        while (desc[descLen]) descLen++;
                        RGBForeColor(&descColor);
                        TextFont(3);
                        TextSize(9);
                        TextFace(italic);
                        /* Word-wrap description into lines of ~30 chars each */
                        while (di < descLen && lineY < CITY_WIN_H - 42) {
                            short lineEnd = di;
                            short lastSpace = di;
                            /* Find break point for ~30 chars or at word boundary */
                            while (lineEnd < descLen && lineEnd - di < 32) {
                                if (desc[lineEnd] == ' ') lastSpace = lineEnd;
                                lineEnd++;
                            }
                            if (lineEnd < descLen && lastSpace > di) lineEnd = lastSpace;
                            {
                                Str255 lineStr;
                                short slen = lineEnd - di;
                                if (slen > 30) slen = 30;
                                lineStr[0] = (unsigned char)slen;
                                BlockMoveData(desc + di, lineStr + 1, slen);
                                MoveTo(xOff + 8, lineY);
                                DrawString(lineStr);
                            }
                            di = lineEnd;
                            if (di < descLen && desc[di] == ' ') di++;
                            lineY += 13;
                        }
                        TextFace(0);
                    }

                } else if (curTab == 1) {
                    /* PRODUCTION TAB - show available production types for this city */
                    short xOff = CITY_WIN_W / 2;
                    short yBase = 84;
                    numProdSlots = 0;

                    TextFont(3);
                    TextSize(10);

                    if (!isOwnCity) {
                        RGBForeColor(&labelColor);
                        TextFace(0);
                        MoveTo(xOff + 12, yBase + 20);
                        DrawString("\pYou do not control this city.");
                    } else if (*gExtState != 0) {
                        unsigned char *ext = (unsigned char *)*gExtState;
                        unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                        short producing = *(short *)(extCity + 0x02);
                        short pi2;

                        /* Column headers */
                        RGBForeColor(&labelColor);
                        TextFace(bold);
                        TextSize(9);
                        MoveTo(xOff + 12, yBase);
                        DrawString("\pUnit Type");
                        MoveTo(xOff + 130, yBase);
                        DrawString("\pStr");
                        MoveTo(xOff + 155, yBase);
                        DrawString("\pMov");
                        MoveTo(xOff + 180, yBase);
                        DrawString("\pCost");
                        MoveTo(xOff + 205, yBase);
                        DrawString("\pTrn");
                        {
                            RGBColor lineCol = {0x4444, 0x4444, 0x4444};
                            RGBForeColor(&lineCol);
                            MoveTo(xOff + 8, yBase + 4);
                            LineTo(CITY_WIN_W - 8, yBase + 4);
                        }

                        /* List available production slots (strongest first) */
                        for (pi2 = 3; pi2 >= 0; pi2--) {
                            short pType = *(short *)(extCity + 0x06 + pi2 * 2);
                            if (pType >= 0 && pType < 29) {
                                Str255 uName;
                                short str2, mov, turns;
                                short rowY = yBase + 12 + numProdSlots * 28;
                                Boolean isCurrent = (pType == producing);

                                GetUnitTypeName(pType, uName);
                                str2 = CitySlotStat(cityIndex, pType, 0);
                                mov = CitySlotStat(cityIndex, pType, 3);
                                turns = CitySlotStat(cityIndex, pType, 1);

                                /* Button background */
                                SetRect(&prodBtnR[numProdSlots], xOff + 6, rowY - 8,
                                        CITY_WIN_W - 6, rowY + 16);
                                if (isCurrent) {
                                    RGBColor selBg = {0x2222, 0x3333, 0x5555};
                                    RGBForeColor(&selBg);
                                    PaintRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    {
                                        RGBColor selBdr = {0x6666, 0x8888, 0xFFFF};
                                        RGBForeColor(&selBdr);
                                        FrameRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    }
                                } else {
                                    RGBColor normBg = {0x1A1A, 0x1A1A, 0x2222};
                                    RGBForeColor(&normBg);
                                    PaintRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    {
                                        RGBColor normBdr = {0x4444, 0x4444, 0x4444};
                                        RGBForeColor(&normBdr);
                                        FrameRoundRect(&prodBtnR[numProdSlots], 6, 6);
                                    }
                                }

                                /* Draw army sprite (use city owner's faction sheet) */
                                {
                                    short pSheet = (owner >= 0 && owner < ARMY_SHEETS) ? owner : 0;
                                    GWorldPtr pGW = sArmyGW[pSheet] ? sArmyGW[pSheet] : sArmyGW[0];
                                    if (sArmyLoaded && pGW != NULL) {
                                        short si = pType;  /* sprite index = unit type */
                                        Rect srcR2, dstR2;
                                        PixMapHandle pm;
                                        SetRect(&srcR2, (si % 16) * 32, (si / 16) * 30,
                                                (si % 16) * 32 + 32, (si / 16) * 30 + 29);
                                        SetRect(&dstR2, xOff + 10, rowY - 6, xOff + 36, rowY + 14);
                                        pm = GetGWorldPixMap(pGW);
                                        if (LockPixels(pm)) {
                                            RGBColor savedBg2;
                                            GetBackColor(&savedBg2);
                                            RGBBackColor(&sArmyBgColor[pSheet]);
                                            CopyBits((BitMap *)*pm,
                                                     (BitMap *)*GetGWorldPixMap(offscreen),
                                                     &srcR2, &dstR2, 36, NULL);
                                            RGBBackColor(&savedBg2);
                                            UnlockPixels(pm);
                                        }
                                    }
                                }

                                /* Unit name */
                                RGBForeColor(isCurrent ? &gold : &white);
                                TextFace(isCurrent ? bold : 0);
                                TextSize(10);
                                MoveTo(xOff + 40, rowY + 4);
                                DrawString(uName);
                                if (isCurrent) {
                                    DrawString("\p *");
                                }

                                /* Stats */
                                RGBForeColor(&valueColor);
                                TextFace(0);
                                TextSize(9);
                                MoveTo(xOff + 130, rowY + 4);
                                NumToString((long)str2, numStr);
                                DrawString(numStr);
                                MoveTo(xOff + 155, rowY + 4);
                                NumToString((long)mov, numStr);
                                DrawString(numStr);
                                {
                                    short pCost = GetUnitTypeStat(pType, 4);
                                    if (pCost > 0) {
                                        MoveTo(xOff + 180, rowY + 4);
                                        NumToString((long)pCost, numStr);
                                        DrawString(numStr);
                                    }
                                }
                                MoveTo(xOff + 205, rowY + 4);
                                NumToString((long)turns, numStr);
                                DrawString(numStr);

                                numProdSlots++;
                            }
                        }

                        if (numProdSlots == 0) {
                            RGBForeColor(&labelColor);
                            TextFace(0);
                            MoveTo(xOff + 12, yBase + 20);
                            DrawString("\pNo production available.");
                        }

                        /* Current production timer */
                        if (producing >= 0) {
                            short prodTurns = *(short *)(extCity + 0x58);
                            short totalTurns = CitySlotStat(cityIndex, producing, 1);
                            short timerY = yBase + 16 + numProdSlots * 28 + 10;
                            Rect trackR3, fillR3;
                            short elapsed2, fillW2;
                            short barW2 = CITY_WIN_W - xOff - 24;
                            RGBColor trackCol = {0x3333, 0x3333, 0x3333};
                            RGBColor fillCol = {0x3333, 0xBBBB, 0x3333};

                            RGBForeColor(&labelColor);
                            TextFace(0);
                            TextSize(9);
                            MoveTo(xOff + 12, timerY);
                            DrawString("\pProgress: ");
                            NumToString((long)(totalTurns - prodTurns), numStr);
                            DrawString(numStr);
                            DrawString("\p/");
                            NumToString((long)totalTurns, numStr);
                            DrawString(numStr);
                            DrawString("\p turns");

                            elapsed2 = totalTurns - prodTurns;
                            if (elapsed2 < 0) elapsed2 = 0;
                            if (totalTurns > 0) {
                                fillW2 = (elapsed2 * barW2) / totalTurns;
                                SetRect(&trackR3, xOff + 12, timerY + 4, xOff + 12 + barW2, timerY + 12);
                                RGBForeColor(&trackCol);
                                PaintRoundRect(&trackR3, 4, 4);
                                if (fillW2 > 0) {
                                    SetRect(&fillR3, xOff + 12, timerY + 4, xOff + 12 + fillW2, timerY + 12);
                                    RGBForeColor(&fillCol);
                                    PaintRoundRect(&fillR3, 4, 4);
                                }
                                {
                                    RGBColor bdr = {0x6666, 0x6666, 0x6666};
                                    RGBForeColor(&bdr);
                                    FrameRoundRect(&trackR3, 4, 4);
                                }
                            }
                        }
                    }

                } else if (curTab == 2) {
                    /* ARMIES TAB - detailed list of armies at this city */
                    short xOff = CITY_WIN_W / 2;
                    short armyCount = *(short *)(gs + 0x1602);
                    short ai3, armyY = 84;
                    short armiesHere = 0;
                    if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;

                    /* Column headers */
                    RGBForeColor(&labelColor);
                    TextFont(3);
                    TextSize(9);
                    TextFace(bold);
                    MoveTo(xOff + 12, armyY);
                    DrawString("\pArmy Name");
                    MoveTo(xOff + 130, armyY);
                    DrawString("\pStr");
                    MoveTo(xOff + 155, armyY);
                    DrawString("\pMP");
                    MoveTo(xOff + 180, armyY);
                    DrawString("\pUnits");
                    {
                        RGBColor lineCol = {0x4444, 0x4444, 0x4444};
                        RGBForeColor(&lineCol);
                        MoveTo(xOff + 8, armyY + 4);
                        LineTo(CITY_WIN_W - 8, armyY + 4);
                    }
                    armyY += 16;

                    for (ai3 = 0; ai3 < armyCount && armiesHere < 8; ai3++) {
                        unsigned char *a = ARMY_REC(ai3);
                        short aax = *(short *)(a + 0x00);
                        short aay = *(short *)(a + 0x02);
                        if (a[0x16] == 0xFF) continue;
                        if (aax == cityX && aay == cityY) {
                            Str255 aName;
                            short alen = 0, ui3, unitCount = 0;
                            short aOwner = (short)(unsigned char)a[0x15];
                            short colorIdx2 = (aOwner >= 0 && aOwner < 8) ? aOwner + 1 : 0;

                            /* Army name */
                            while (alen < 16 && a[0x04 + alen] != 0) alen++;
                            if (alen > 0) {
                                aName[0] = (unsigned char)alen;
                                BlockMoveData(a + 0x04, aName + 1, alen);
                            } else {
                                aName[0] = 5;
                                BlockMoveData("Army ", aName + 1, 5);
                            }

                            /* Owner color bar */
                            {
                                Rect ownerBar;
                                SetRect(&ownerBar, xOff + 8, armyY - 8, xOff + 11, armyY + 4);
                                RGBForeColor(&sPlayerColors[colorIdx2]);
                                PaintRect(&ownerBar);
                            }

                            /* Draw army sprite (use per-faction sheet) */
                            {
                                short aSheet = (aOwner >= 0 && aOwner < ARMY_SHEETS) ? aOwner : 0;
                                GWorldPtr aGW = sArmyGW[aSheet] ? sArmyGW[aSheet] : sArmyGW[0];
                                if (sArmyLoaded && aGW != NULL) {
                                    short si2 = (short)(unsigned char)a[0x14];
                                    Rect srcR3, dstR3;
                                    PixMapHandle pm2;
                                    SetRect(&srcR3, (si2 % 16) * 32, (si2 / 16) * 30,
                                            (si2 % 16) * 32 + 32, (si2 / 16) * 30 + 29);
                                    SetRect(&dstR3, xOff + 14, armyY - 8, xOff + 38, armyY + 10);
                                    pm2 = GetGWorldPixMap(aGW);
                                    if (LockPixels(pm2)) {
                                        RGBColor savedBg3;
                                        GetBackColor(&savedBg3);
                                        RGBBackColor(&sArmyBgColor[aSheet]);
                                        CopyBits((BitMap *)*pm2,
                                                 (BitMap *)*GetGWorldPixMap(offscreen),
                                                 &srcR3, &dstR3, 36, NULL);
                                        RGBBackColor(&savedBg3);
                                        UnlockPixels(pm2);
                                    }
                                }
                            }

                            /* Name */
                            RGBForeColor(&white);
                            TextFace(bold);
                            TextSize(10);
                            MoveTo(xOff + 42, armyY + 2);
                            DrawString(aName);

                            /* Strength */
                            RGBForeColor(&valueColor);
                            TextFace(0);
                            TextSize(9);
                            MoveTo(xOff + 130, armyY + 2);
                            NumToString((long)*(short *)(a + 0x2a), numStr);
                            DrawString(numStr);

                            /* Movement points */
                            MoveTo(xOff + 155, armyY + 2);
                            NumToString((long)(unsigned char)a[0x2e], numStr);
                            DrawString(numStr);

                            /* Unit count */
                            for (ui3 = 0; ui3 < 4; ui3++) {
                                if (a[0x16 + ui3] != 0xFF) unitCount++;
                            }
                            MoveTo(xOff + 180, armyY + 2);
                            NumToString((long)unitCount, numStr);
                            DrawString(numStr);
                            DrawString("\p/4");

                            /* Unit types row */
                            {
                                short ux;
                                TextSize(8);
                                RGBForeColor(&labelColor);
                                ux = xOff + 42;
                                for (ui3 = 0; ui3 < 4; ui3++) {
                                    if (a[0x16 + ui3] != 0xFF) {
                                        Str255 utn;
                                        if ((unsigned char)a[0x16 + ui3] == 0x1C) {
                                            unsigned char *hn = a + 0x04; short nl = 0;
                                            while (nl < 15 && hn[nl]) nl++;
                                            utn[0] = (unsigned char)nl;
                                            BlockMoveData(hn, utn + 1, nl);
                                        } else {
                                            GetUnitTypeName((short)(unsigned char)a[0x16 + ui3], utn);
                                        }
                                        MoveTo(ux, armyY + 14);
                                        DrawString(utn);
                                        ux += StringWidth(utn) + 8;
                                    }
                                }
                            }

                            armyY += 28;
                            armiesHere++;
                        }
                    }

                    if (armiesHere == 0) {
                        RGBForeColor(&valueColor);
                        TextFace(0);
                        TextSize(10);
                        MoveTo(xOff + 12, armyY);
                        DrawString("\pNo armies stationed here.");
                    }
                }

                /* Blit to window */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(cityWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)cityWin)->portBits,
                             &r, &cityWin->portRect,
                             srcCopy, NULL);
                }

                needsRedraw = false;
            }

            WaitNextEvent(everyEvent, &evt, 30, NULL);

            if (evt.what == mouseDown) {
                Point localPt = evt.where;
                SetPort(cityWin);
                GlobalToLocal(&localPt);

                /* Done button hit test (matches bottom nav bar layout) */
                {
                    short panelX2 = CITY_WIN_W / 2;
                    short navBW = 36;
                    short dBtnX2 = panelX2 + 4 + (navBW + 2) * 3 + 4;
                    short dBtnY2 = CITY_WIN_H - 36 - 6;
                    Rect doneHit;
                    SetRect(&doneHit, dBtnX2, dBtnY2, dBtnX2 + 44, dBtnY2 + 36);
                    if (PtInRect(localPt, &doneHit)) {
                        done = true;
                        continue;
                    }
                }

                /* Tab buttons */
                {
                    short ti2;
                    for (ti2 = 0; ti2 < 3; ti2++) {
                        if (PtInRect(localPt, &tabR[ti2]) && ti2 != curTab) {
                            curTab = ti2;
                            needsRedraw = true;
                            break;
                        }
                    }
                }

                /* Production slot buttons (Build tab only, own city) */
                if (curTab == 1 && isOwnCity && *gExtState != 0) {
                    short pi3;
                    for (pi3 = 0; pi3 < numProdSlots; pi3++) {
                        if (PtInRect(localPt, &prodBtnR[pi3])) {
                            /* Change production to this slot */
                            unsigned char *ext = (unsigned char *)*gExtState;
                            unsigned char *extCity = ext + 0x24c + cityIndex * 0x5c;
                            short selectedType = *(short *)(extCity + 0x06 + pi3 * 2);
                            short curProd = *(short *)(extCity + 0x02);
                            if (selectedType >= 0 && selectedType != curProd) {
                                *(short *)(extCity + 0x02) = selectedType;
                                *(short *)(extCity + 0x58) = CitySlotStat(cityIndex, selectedType, 1);
                                needsRedraw = true;
                            }
                            break;
                        }
                    }
                }
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;
                if ((TickCount() - startTick) < 30)
                    continue;
                if (key == 0x0D || key == 0x03 || key == 0x1B)
                    done = true;
                else if (key == '1') { curTab = 0; needsRedraw = true; }
                else if (key == '2') { curTab = 1; needsRedraw = true; }
                else if (key == '3') { curTab = 2; needsRedraw = true; }
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeWindow(cityWin);
    #undef CITY_WIN_W
    #undef CITY_WIN_H
}


/* ===================================================================
 * ShowArmyInspect — Modal dialog showing army stack details
 *
 * Shows each unit in the army (up to 4), with type, strength,
 * movement, experience, and bonus.  armyIndex is the index into
 * the army table at gs+0x1604.
 * =================================================================== */
static void ShowArmyInspect(short armyIndex)
{
    WindowPtr  inspWin;
    GWorldPtr  offscreen = NULL;
    Rect       winRect;
    Boolean    done = false;
    Rect       screenRect = qd.screenBits.bounds;
    unsigned char *gs, *army;
    short      armyCount;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyIndex < 0 || armyIndex >= armyCount) return;

    army = ARMY_REC(armyIndex);

    /* Block inspecting enemy armies when View Enemies is off */
    if (!sOptViewEnemies) {
        short armOwner = (short)(unsigned char)army[0x15];
        short curP = *(short *)(gs + 0x110);
        if (armOwner != curP) {
            ShowBriefMessage("\pCannot inspect enemy armies");
            return;
        }
    }

    /* Center 350x340 window (taller to fit hero items section) */
    SetRect(&winRect,
        (screenRect.right - 350) / 2,
        (screenRect.bottom - 340) / 2,
        (screenRect.right - 350) / 2 + 350,
        (screenRect.bottom - 340) / 2 + 340);

    inspWin = NewCWindow(NULL, &winRect, "\p", true,
                          plainDBox, (WindowPtr)-1L, false, 0);
    if (inspWin == NULL) return;

    SetPort(inspWin);
    {
        Rect obounds;
        SetRect(&obounds, 0, 0, 350, 340);
        NewGWorld(&offscreen, 0, &obounds, NULL, NULL, 0);
    }

    FlushEvents(everyEvent, 0);

    {
        Boolean needsRedraw = true;
        unsigned long startTick = TickCount();

        while (!done) {
            EventRecord evt;

            if (needsRedraw) {
                Rect r;
                CGrafPtr savedPort;
                GDHandle savedDevice;
                short ui;
                SetRect(&r, 0, 0, 350, 340);

                if (offscreen != NULL) {
                    GetGWorld(&savedPort, &savedDevice);
                    SetGWorld(offscreen, NULL);
                    LockPixels(GetGWorldPixMap(offscreen));
                }

                /* Dark background */
                {
                    DrawMarbleBackground(&r);
                }

                /* Owner-colored border */
                {
                    short owner = (short)(unsigned char)army[0x15];
                    short colorIdx = (owner >= 0 && owner < 8) ? owner + 1 : 8;
                    RGBForeColor(&sPlayerColors[colorIdx]);
                    PenSize(3, 3);
                    FrameRect(&r);
                    PenSize(1, 1);

                    /* Owner faction shield */
                    if (owner >= 0 && owner < 8) {
                        Rect shR;
                        SetRect(&shR, 300, 8, 300 + BIG_SHIELD_W, 8 + BIG_SHIELD_H);
                        DrawBigShield(owner, &shR);
                    }
                }

                /* Title: army name */
                {
                    RGBColor gold = {0xFFFF, 0xCCCC, 0x3333};
                    Str255 pName;
                    short nlen = 0;
                    RGBForeColor(&gold);
                    TextFont(2);
                    TextSize(16);
                    TextFace(bold);
                    MoveTo(20, 26);
                    while (nlen < 16 && army[0x04 + nlen] != 0) nlen++;
                    if (nlen > 0) {
                        pName[0] = (unsigned char)nlen;
                        BlockMoveData(army + 0x04, pName + 1, nlen);
                        DrawString(pName);
                    } else {
                        DrawString(GetCachedString(STR_STACK_INFO, 0, "\pArmy Stack"));
                    }
                }

                /* Army strength and movement */
                {
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    Str255 numStr;
                    RGBForeColor(&white);
                    TextFont(3);
                    TextSize(10);
                    TextFace(0);
                    MoveTo(20, 42);
                    DrawString("\pStrength: ");
                    NumToString((long)*(short *)(army + 0x2a), numStr);
                    DrawString(numStr);
                    DrawString("\p   Movement: ");
                    NumToString((long)(unsigned char)army[0x2e], numStr);
                    DrawString(numStr);
                    /* Defend status */
                    if (army[0x2d] > 0) {
                        RGBColor defColor = {0x8888, 0xFFFF, 0x8888};
                        RGBForeColor(&defColor);
                        DrawString("\p  [Defending]");
                    }
                    /* Orders status */
                    if (*(short *)(army + 0x32) != 0) {
                        RGBColor ordColor = {0xAAAA, 0xAAAA, 0xFFFF};
                        RGBForeColor(&ordColor);
                        DrawString("\p  [Orders]");
                    }
                }

                /* Separator line */
                {
                    RGBColor gray = {0x6666, 0x6666, 0x6666};
                    RGBForeColor(&gray);
                    MoveTo(15, 52);
                    LineTo(335, 52);
                }

                /* Unit slots (up to 4) with sprites */
                TextFace(0);
                for (ui = 0; ui < 4; ui++) {
                    short yPos = 68 + ui * 40;
                    unsigned char unitType = army[0x16 + ui];
                    unsigned char unitMoves = army[0x1a + ui];
                    unsigned char unitHits = army[0x1e + ui];
                    unsigned char unitExp = army[0x26 + ui];
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    RGBColor dim = {0x5555, 0x5555, 0x5555};
                    Str255 numStr;

                    if (unitType == 0xFF) {
                        /* Empty slot */
                        RGBForeColor(&dim);
                        TextSize(10);
                        MoveTo(50, yPos + 10);
                        DrawString(GetCachedString(STR_STACK_INFO, 9, "\p(empty)"));
                        continue;
                    }

                    /* Row background */
                    {
                        Rect rowBg;
                        RGBColor rowCol = {0x1A1A, 0x1A1A, 0x2222};
                        SetRect(&rowBg, 15, yPos - 6, 335, yPos + 28);
                        RGBForeColor(&rowCol);
                        PaintRoundRect(&rowBg, 4, 4);
                    }

                    /* Draw unit sprite (use army owner's faction sheet) */
                    {
                        short uOwn = (short)(unsigned char)army[0x15];
                        short uSheet = (uOwn >= 0 && uOwn < ARMY_SHEETS) ? uOwn : 0;
                        GWorldPtr uGW = sArmyGW[uSheet] ? sArmyGW[uSheet] : sArmyGW[0];
                        if (sArmyLoaded && uGW != NULL) {
                            short si3 = 0;
                            Rect srcR4, dstR4;
                            PixMapHandle pm3;
                            if (sUnitTypesLoaded && unitType < sUnitTypeCount) {
                                unsigned char *ute = sUnitTypeTable + unitType * UNIT_TYPE_ENTRY;
                                si3 = (short)ute[0x00];
                            }
                            SetRect(&srcR4, (si3 % 16) * 32, (si3 / 16) * 30,
                                    (si3 % 16) * 32 + 32, (si3 / 16) * 30 + 29);
                            SetRect(&dstR4, 18, yPos - 4, 46, yPos + 24);
                            pm3 = GetGWorldPixMap(uGW);
                            if (LockPixels(pm3)) {
                                RGBColor savedBg4;
                                GetBackColor(&savedBg4);
                                RGBBackColor(&sArmyBgColor[uSheet]);
                                CopyBits((BitMap *)*pm3,
                                         (BitMap *)*GetGWorldPixMap(offscreen),
                                         &srcR4, &dstR4, 36, NULL);
                                RGBBackColor(&savedBg4);
                                UnlockPixels(pm3);
                            }
                        }
                    }

                    RGBForeColor(&white);

                    /* Unit type name (large) */
                    TextSize(11);
                    TextFace(bold);
                    MoveTo(52, yPos + 6);
                    {
                        Str255 typeName;
                        GetUnitTypeName((short)unitType, typeName);
                        DrawString(typeName);
                    }

                    /* Stats row below name */
                    {
                        RGBColor statColor = {0xBBBB, 0xBBBB, 0xDDDD};
                        RGBColor labelCol = {0x8888, 0x8888, 0x8888};
                        TextFace(0);
                        TextSize(9);

                        RGBForeColor(&labelCol);
                        MoveTo(52, yPos + 20);
                        DrawString("\pStr:");
                        RGBForeColor(&statColor);
                        /* Base strength from unit type table (not current HP) */
                        {
                            short baseStr = GetUnitTypeStat((short)unitType, 0);
                            NumToString((long)(baseStr > 0 ? baseStr : unitHits), numStr);
                        }
                        DrawString(numStr);

                        RGBForeColor(&labelCol);
                        DrawString("\p  Mov:");
                        RGBForeColor(&statColor);
                        NumToString((long)unitMoves, numStr);
                        DrawString(numStr);

                        RGBForeColor(&labelCol);
                        DrawString("\p  HP:");
                        RGBForeColor(&statColor);
                        NumToString((long)unitHits, numStr);
                        DrawString(numStr);

                        /* (a[0x22+k] is the unit's upkeep, not a bonus) */

                        if (unitExp > 0) {
                            RGBForeColor(&labelCol);
                            DrawString("\p  XP:");
                            RGBForeColor(&statColor);
                            NumToString((long)unitExp, numStr);
                            DrawString(numStr);
                        }
                    }
                }

                /* Hero items display (if army has a hero) */
                {
                    Boolean hasHero = false;
                    short hi;
                    for (hi = 0; hi < 4; hi++) {
                        if ((unsigned char)army[0x16 + hi] == 0x1C) { hasHero = true; break; }
                    }
                    if (hasHero) {
                        short itemY = 232;
                        RGBColor itemLbl = {0x8888, 0x8888, 0x8888};
                        RGBColor itemVal = {0xFFFF, 0xDDDD, 0x6666};
                        RGBColor sepCol = {0x4444, 0x4444, 0x4444};
                        RGBForeColor(&sepCol);
                        MoveTo(15, itemY - 8);
                        LineTo(335, itemY - 8);
                        TextFont(3); TextSize(9); TextFace(bold);
                        RGBForeColor(&itemLbl);
                        MoveTo(20, itemY);
                        DrawString("\pItems:");
                        TextFace(0);
                        {
                            short ii, itemCount = 0, ids_[GAME_ITEM_COUNT], nIds_ = HeroItems(armyIndex, ids_);
                            for (ii = 0; ii < nIds_; ii++) {
                                short itemId = ids_[ii];
                                if (itemId > 0 && itemId <= GAME_ITEM_COUNT) {
                                    ItemDef itemBuf;
                                    const ItemDef *item = GameItemDef(itemId, &itemBuf);
                                    Str255 pn;
                                    short nl = 0;
                                    while (nl < 19 && item->name[nl] != '\0') nl++;
                                    pn[0] = (unsigned char)nl;
                                    BlockMoveData(item->name, pn + 1, nl);
                                    RGBForeColor(&itemVal);
                                    MoveTo(65, itemY + itemCount * 12);
                                    DrawString(pn);
                                    /* Show bonus type */
                                    RGBForeColor(&itemLbl);
                                    if (item->type == ITEM_TYPE_BATTLE) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p str");
                                    } else if (item->type == ITEM_TYPE_COMMAND) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p cmd");
                                    } else if (item->type == ITEM_TYPE_FLYING) {
                                        DrawString("\p (fly)");
                                    } else if (item->type == ITEM_TYPE_MOVEMENT) {
                                        DrawString("\p (move)");
                                    } else if (item->type == ITEM_TYPE_GOLD) {
                                        Str255 vs; DrawString("\p +");
                                        NumToString((long)item->value, vs);
                                        DrawString(vs); DrawString("\p gold");
                                    }
                                    itemCount++;
                                }
                            }
                            if (itemCount == 0) {
                                RGBForeColor(&itemLbl);
                                MoveTo(65, itemY);
                                DrawString("\p(none)");
                            }
                        }
                    }
                }

                /* OK button */
                {
                    RGBColor black = {0, 0, 0};
                    RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
                    Rect okBtn;
                    SetRect(&okBtn, 135, 304, 215, 326);
                    RGBForeColor(&white);
                    PaintRoundRect(&okBtn, 8, 8);
                    RGBForeColor(&black);
                    FrameRoundRect(&okBtn, 8, 8);
                    PenSize(2, 2);
                    FrameRoundRect(&okBtn, 8, 8);
                    PenSize(1, 1);
                    TextFont(3);
                    TextSize(10);
                    TextFace(bold);
                    MoveTo(okBtn.left + 16, okBtn.bottom - 6);
                    DrawString(GetCachedString(STR_COMMON_BUTTONS, 1, "\pOK"));
                }

                /* Blit */
                if (offscreen != NULL) {
                    UnlockPixels(GetGWorldPixMap(offscreen));
                    SetGWorld(savedPort, savedDevice);
                    SetPort(inspWin);
                    CopyBits((BitMap *)*GetGWorldPixMap(offscreen),
                             &((GrafPtr)inspWin)->portBits,
                             &r, &inspWin->portRect,
                             srcCopy, NULL);
                }
                needsRedraw = false;
            }

            WaitNextEvent(everyEvent, &evt, 30, NULL);

            if (evt.what == mouseDown) {
                Point localPt = evt.where;
                Rect okBtn;
                SetPort(inspWin);
                GlobalToLocal(&localPt);
                SetRect(&okBtn, 135, 304, 215, 326);
                if (PtInRect(localPt, &okBtn))
                    done = true;
            }
            else if (evt.what == keyDown) {
                char key = evt.message & charCodeMask;
                if ((TickCount() - startTick) < 30) continue;
                if (key == 0x0D || key == 0x03 || key == 0x1B)
                    done = true;
            }
            else if (evt.what == updateEvt) {
                needsRedraw = true;
            }
        }
    }

    if (offscreen != NULL)
        DisposeGWorld(offscreen);
    DisposeWindow(inspWin);
}


/* Forward declarations for stack grouping and window refresh */
static void BuildStackArrays(short leadArmyIdx);
static void InvalidateAllGameWindows(void);
static void MoveSelectedGroup(void);

/* ===================================================================
 * SelectNextArmy — Next Group (Cmd-N; PPC FUN_10055f30 -> FUN_100559ac)
 *
 * The original measures the Manhattan distance from the position of the
 * stack it picked LAST (at the start of the turn: the player's capital,
 * FUN_100558f8 reads pstat+0x04/06), 0 -> 9000 so the current stack is
 * taken last.  Pass 1 considers stacks not yet visited this turn (unit
 * flag 0x200, set whenever a stack is selected, FUN_10055c64), pass 2 the
 * visited ones and then clears every visited flag.  Fortified units
 * (0x40) are skipped.  The remake keeps the flags per army record index.
 * =================================================================== */
static unsigned char sArmyVisited[MAX_ARMIES];
static unsigned char sArmySkip[MAX_ARMIES];      /* unit flag 0x40 for the turn (FUN_100562e0: Move All stopped short) */
static short sNextRefX = -1, sNextRefY = -1, sNextRefTurn = -1, sNextRefPlayer = -1;
static short sAILastX = 0, sAILastY = 0;  /* FUN_1005619c's last position (computer order loop and Move All) */

/* a new turn (or side): the visited/skip flags go (FUN_100558f8), the
 * reference position is the capital */
static void NextGroupTurnSync(void)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short turnNum, cur, i;
    if (gs == NULL) return;
    turnNum = *(short *)(gs + 0x136); cur = *(short *)(gs + 0x110);
    if (sNextRefTurn != turnNum || sNextRefPlayer != cur) {
        sNextRefTurn = turnNum; sNextRefPlayer = cur;
        for (i = 0; i < MAX_ARMIES; i++) { sArmyVisited[i] = 0; sArmySkip[i] = 0; }
        GetCapitalXY(cur, &sNextRefX, &sNextRefY);
    }
}

/* FUN_10055c64's selection side effects on the group it selects: every
 * member is marked visited (0x200) and FUN_10055ba0(1) sets status bit 1 -
 * the group is no longer defending. */
static void SelectGroupFlags(void)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short k, n;
    if (gs == NULL) return;
    n = *(short *)(gs + 0x1602); if (n > MAX_ARMIES) n = MAX_ARMIES;
    for (k = 0; k < sStackCount; k++) {
        short ai = sStackArmyIdx[k];
        if (!sStackSelected[k] || ai < 0 || ai >= n) continue;
        sArmyVisited[ai] = 1;
        ARMY_REC(ai)[0x2d] = 0;
    }
}

static void SelectNextArmy(void)
{
    unsigned char *gs;
    short currentPlayer, armyCount, i;
    short bestIdx = -1;
    short vpCenterX, vpCenterY;

    if (*gGameState == 0)
        return;

    gs = (unsigned char *)*gGameState;
    currentPlayer = *(short *)(gs + 0x110);
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount <= 0 || armyCount > MAX_ARMIES)
        return;

    /* Viewport center for distance calculation */
    {
        short tilesWide = 10, tilesHigh = 10;
        if (*gMainGameWindow != 0) {
            Rect p = ((WindowPtr)*gMainGameWindow)->portRect;
            tilesWide = (p.right - p.left - SCROLLBAR_W) / TERRAIN_TILE_W;
            tilesHigh = (p.bottom - p.top - SCROLLBAR_H) / TERRAIN_TILE_H;
        }
        vpCenterX = sViewportX + tilesWide / 2;
        vpCenterY = sViewportY + tilesHigh / 2;
    }

    /* FUN_100559ac: the current side's records on the map, skipping only
     * the defending ones (status bit 1 clear: a[0x2d]) and those marked
     * 0x40 (Leave Group, Move All stopped short) - no MP test; nearest by
     * Manhattan distance from the last pick (0 -> 9000), the not-yet-visited
     * first; with only visited ones left, the current side's visited flags
     * are cleared. */
    {
          short bestNew = -1, bestOld = -1;
          short bestNewDist = 10000, bestOldDist = 10000;
          (void)vpCenterX; (void)vpCenterY;
          /* a new turn (or side): forget the visited flags, start from the capital */
          NextGroupTurnSync();
          for (i = armyCount - 1; i >= 0; i--) {
                unsigned char *army = ARMY_REC(i);
                short owner = (short)(unsigned char)army[0x15];
                short ax, ay, dist, dx, dy;

                if (owner != currentPlayer) continue;
                ax = *(short *)(army + 0x00);
                if (ax < 0) continue;  /* not placed */
                if (army[0x16] == 0xFF) continue;  /* dead */
                if (army[0x2d] != 0) continue;  /* defending (status bit 1 clear) */
                if (sArmySkip[i]) continue;     /* 0x40 */

                ay = *(short *)(army + 0x02);
                dx = ax - sNextRefX; if (dx < 0) dx = -dx;
                dy = ay - sNextRefY; if (dy < 0) dy = -dy;
                dist = dx + dy;
                if (dist == 0) dist = 9000;

                if (!sArmyVisited[i]) {
                    if (dist < bestNewDist) { bestNewDist = dist; bestNew = i; }
                } else {
                    if (dist < bestOldDist) { bestOldDist = dist; bestOld = i; }
                }
          }
          if (bestNew >= 0) {
              bestIdx = bestNew;
          } else if (bestOld >= 0) {
              for (i = 0; i < armyCount; i++)   /* the current side's 0x200 flags only */
                  if ((short)(unsigned char)ARMY_REC(i)[0x15] == currentPlayer) sArmyVisited[i] = 0;
              bestIdx = bestOld;
          }
    }

    if (bestIdx < 0) {                   /* FUN_10055f30: none left - nothing selected */
        sSelectedArmy = -1; sStackCount = 0; sPreviewPathLen = 0;
        InvalidateAllGameWindows();
        return;
    }
    sNextRefX = *(short *)(ARMY_REC(bestIdx) + 0x00);
    sNextRefY = *(short *)(ARMY_REC(bestIdx) + 0x02);

    /* Select and center viewport on chosen army */
    {
        unsigned char *army = ARMY_REC(bestIdx);
        sSelectedArmy = bestIdx;
        BuildStackArrays(bestIdx);
        SelectGroupFlags();

        /* Center viewport on selected army */
        CenterViewportOn(*(short *)(army + 0x00), *(short *)(army + 0x02));

        /* Redraw */
        if (*gMainGameWindow != 0) {
            SetPort((WindowPtr)*gMainGameWindow);
            InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        }
        if (*gOverviewWindow != 0) {
            SetPort((WindowPtr)*gOverviewWindow);
            InvalRect(&((WindowPtr)*gOverviewWindow)->portRect);
        }
    }
}


/* ===================================================================
 * BuildStackArrays — Populate parallel arrays for all armies at a tile
 *
 * Called when an army is selected (clicked on map).  Finds all armies
 * at the same tile owned by the same player and builds the stack
 * arrays.  The selected army becomes group 0 and is marked selected.
 * Other armies at the same tile get their own groups.
 *
 * 68k: CODE_123 FUN_00000788 + FUN_000008de
 * =================================================================== */
/* The army whose sprite stands on its tile (one per tile): the selection if
 * it is there, else a hero, else the first army. */
static Boolean ArmyShownOnTile(short i)
{
    unsigned char *gs = (unsigned char *)*gGameState, *a;
    short n, j;
    Boolean iHero;
    if (gs == NULL) return true;
    n = *(short *)(gs + 0x1602);
    a = ARMY_REC(i);
    if (sSelectedArmy >= 0 && sSelectedArmy < n) {
        unsigned char *sel = ARMY_REC(sSelectedArmy);
        if (*(short *)(sel + 0) == *(short *)(a + 0) && *(short *)(sel + 2) == *(short *)(a + 2))
            return i == sSelectedArmy;
    }
    iHero = ((unsigned char)a[0x16] == 0x1C);
    for (j = 0; j < n; j++) {
        unsigned char *b = ARMY_REC(j);
        Boolean jHero;
        if (j == i || b[0x16] == 0xFF) continue;
        if (*(short *)(b + 0) != *(short *)(a + 0) || *(short *)(b + 2) != *(short *)(a + 2)) continue;
        jHero = ((unsigned char)b[0x16] == 0x1C);
        if ((jHero && !iHero) || (jHero == iHero && j < i)) return false;
    }
    return true;
}

/* The army a click on (x,y) selects: the original sorts the stack by group
 * tag (+0x11) then fight order, both descending (hero +50), and takes the
 * first (PPC FUN_10021524 / FUN_10021a3c). */
static short StackLeadAt(short x, short y, short player)
{
    unsigned char *gs, *fo;
    short n, i, best = -1;
    long bestKey = -1;
    if (*gGameState == 0) return -1;
    gs = (unsigned char *)*gGameState;
    n = *(short *)(gs + 0x1602);
    if (n > MAX_ARMIES) n = MAX_ARMIES;
    fo = gs + 0x60C + player * 0x1D;
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        long key;
        if (a[0x16] == 0xFF || (short)(unsigned char)a[0x15] != player) continue;
        if (*(short *)(a + 0) != x || *(short *)(a + 2) != y) continue;
        key = (long)a[0x11] * 1000 + fo[a[0x16] % 0x1D] + (a[0x16] == 0x1C ? 50 : 0);
        if (key > bestKey) { bestKey = key; best = i; }
    }
    return best;
}

static void BuildStackArrays(short leadArmyIdx)
{
    unsigned char *gs;
    unsigned char *lead;
    short ax, ay, owner, armyCount;
    short ai, si;

    sInfoStackBackupSaved = false;

    if (*gGameState == 0 || leadArmyIdx < 0)
        return;

    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (leadArmyIdx >= armyCount)
        return;

    lead = ARMY_REC(leadArmyIdx);
    ax = *(short *)(lead + 0x00);
    ay = *(short *)(lead + 0x02);
    owner = (short)(unsigned char)lead[0x15];

    /* Clear arrays */
    for (si = 0; si < MAX_STACK; si++) {
        sStackArmyIdx[si] = -1;
        sStackGroupId[si] = -1;
        sStackSelected[si] = 0;
        sStackSep[si] = -1;
    }
    sStackCount = 0;

    /* Put the lead army first */
    sStackArmyIdx[0] = leadArmyIdx;
    sStackGroupId[0] = 0;
    sStackSelected[0] = 1;
    sStackSep[0] = 0;
    sStackCount = 1;
    if (leadArmyIdx < MAX_ARMIES) sArmyVisited[leadArmyIdx] = 1;   /* unit flag 0x200 (FUN_10055c64) */

    /* Find all other armies at the same tile with same owner */
    for (ai = 0; ai < armyCount && sStackCount < MAX_STACK; ai++) {
        unsigned char *army = ARMY_REC(ai);
        if (ai == leadArmyIdx)
            continue;
        if (*(short *)(army + 0x00) == ax &&
            *(short *)(army + 0x02) == ay &&
            (short)(unsigned char)army[0x15] == owner) {
            si = sStackCount;
            sStackArmyIdx[si] = ai;
            /* Check group tag (army+0x11): if same tag as lead AND non-zero,
             * put in same group.  Otherwise give own group. */
            if (lead[0x11] != 0 && army[0x11] == lead[0x11]) {
                sStackGroupId[si] = 0;
                sStackSelected[si] = 1;
                sStackSep[si] = -1;
            } else {
                sStackGroupId[si] = sStackCount;
                sStackSelected[si] = 0;
                sStackSep[si] = 0;
            }
            sStackCount++;
        }
    }

    /* Sort by groupId, then by fight order priority within group.
     * 68k CODE_123 FUN_000008de: secondary key = gs[0x60c + player*0x1d + unitType] */
    {
        short i, j;
        short curPlayer = *(short *)(gs + 0x110);
        unsigned char *fightOrder = gs + 0x60C + curPlayer * 0x1D;
        for (i = 1; i < sStackCount; i++) {
            short tmpIdx = sStackArmyIdx[i];
            short tmpGrp = sStackGroupId[i];
            short tmpSel = sStackSelected[i];
            short tmpSep = sStackSep[i];
            /* Get fight order priority for this unit type */
            unsigned char *armyI = ARMY_REC(tmpIdx);
            short prioI = (short)(unsigned char)fightOrder[(unsigned char)armyI[0x16]] +
                          ((unsigned char)armyI[0x16] == 0x1C ? 50 : 0);

            j = i - 1;
            while (j >= 0) {
                unsigned char *armyJ = ARMY_REC(sStackArmyIdx[j]);
                short prioJ = (short)(unsigned char)fightOrder[(unsigned char)armyJ[0x16]] +
                              ((unsigned char)armyJ[0x16] == 0x1C ? 50 : 0);
                /* Sort: groupId ascending, then fight order DESCENDING with the hero
                 * bias, as the original's FUN_10021a3c (hero first) */
                if (sStackGroupId[j] > tmpGrp ||
                    (sStackGroupId[j] == tmpGrp && prioJ < prioI)) {
                    sStackArmyIdx[j + 1] = sStackArmyIdx[j];
                    sStackGroupId[j + 1] = sStackGroupId[j];
                    sStackSelected[j + 1] = sStackSelected[j];
                    sStackSep[j + 1] = sStackSep[j];
                    j--;
                } else {
                    break;
                }
            }
            sStackArmyIdx[j + 1] = tmpIdx;
            sStackGroupId[j + 1] = tmpGrp;
            sStackSelected[j + 1] = tmpSel;
            sStackSep[j + 1] = tmpSep;
        }
    }

    /* Recalculate separators after sort */
    if (sStackCount > 0) {
        sStackSep[0] = 0;
        for (si = 1; si < sStackCount; si++) {
            sStackSep[si] = (sStackGroupId[si] == sStackGroupId[si - 1]) ? -1 : 0;
        }
    }

    /* Renumber groups to be contiguous (0, 1, 2, ...) */
    {
        short remap[MAX_STACK];
        short nextId = 0, ri;
        for (ri = 0; ri < MAX_STACK; ri++) remap[ri] = -1;
        for (si = 0; si < sStackCount; si++) {
            if (remap[sStackGroupId[si]] == -1)
                remap[sStackGroupId[si]] = nextId++;
            sStackGroupId[si] = remap[sStackGroupId[si]];
        }
    }

    /* Find active slot (first selected entry) */
    sActiveSlot = -1;
    for (si = 0; si < sStackCount; si++) {
        if (sStackSelected[si]) {
            sActiveSlot = si;
            break;
        }
    }

    /* Invalidate info window so it switches between stack UI and normal buttons */
    if (gInfoWindow != NULL && *gInfoWindow != 0) {
        GrafPtr savedPort;
        GetPort(&savedPort);
        SetPort((WindowPtr)*gInfoWindow);
        InvalRect(&((WindowPtr)*gInfoWindow)->portRect);
        SetPort(savedPort);
    }
}


/* ===================================================================
 * StackToggleSlot — Toggle army slot in/out of active group.
 * Extracted from ShowStackDialog toggle logic (68k FUN_00001380).
 * =================================================================== */
static void StackToggleSlot(short idx)
{
    short sj;
    if (idx < 0 || idx >= sStackCount) return;

    if (sStackSelected[idx] == 0) {
        /* Join the active group: find groupId of first selected */
        short activeGrp = 0;
        for (sj = 0; sj < sStackCount; sj++) {
            if (sStackSelected[sj]) {
                activeGrp = sStackGroupId[sj];
                break;
            }
        }
        sStackGroupId[idx] = activeGrp;
        sStackSelected[idx] = 1;
    } else {
        /* Leave the group: only if not the last member */
        short memberCount = 0;
        for (sj = 0; sj < sStackCount; sj++) {
            if (sStackGroupId[sj] == sStackGroupId[idx])
                memberCount++;
        }
        if (memberCount > 1) {
            /* Find first unused groupId */
            short newGrp, gj, gUsed;
            for (newGrp = 0; newGrp < MAX_STACK; newGrp++) {
                gUsed = 0;
                for (gj = 0; gj < sStackCount; gj++) {
                    if (sStackGroupId[gj] == newGrp) { gUsed = 1; break; }
                }
                if (!gUsed) break;
            }
            sStackGroupId[idx] = newGrp;
            sStackSelected[idx] = 0;
        }
    }
    /* Recalculate separators */
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++)
        sStackSep[sj] = (sStackGroupId[sj] == sStackGroupId[sj - 1]) ? -1 : 0;
}

/* ===================================================================
 * StackGroupAll — Put all stack members in the same group.
 * =================================================================== */
static void StackGroupAll(void)
{
    short sj;
    for (sj = 0; sj < sStackCount; sj++) {
        sStackGroupId[sj] = 0;
        sStackSelected[sj] = 1;
    }
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++) sStackSep[sj] = -1;
}

/* ===================================================================
 * StackUngroupAll — Give each army its own group.
 * =================================================================== */
static void StackUngroupAll(void)
{
    short sj;
    for (sj = 0; sj < sStackCount; sj++) {
        sStackGroupId[sj] = sj;
        sStackSelected[sj] = 0;
    }
    if (sStackCount > 0) sStackSelected[0] = 1;
    if (sStackCount > 0) sStackSep[0] = 0;
    for (sj = 1; sj < sStackCount; sj++) sStackSep[sj] = 0;
}

/* FUN_10021d50: the first group tag (1..254) no on-map record of the
 * current side carries; 0 when all are taken.  (The original's used-table
 * is cleared from index 2; index 1 counts as used only when a record
 * carries it.) */
static unsigned char NewGroupTag(void)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char used[256];
    short i, n, cur, t;
    if (gs == NULL) return 0;
    for (t = 0; t < 256; t++) used[t] = 0;
    cur = *(short *)(gs + 0x110);
    n = *(short *)(gs + 0x1602); if (n > MAX_ARMIES) n = MAX_ARMIES;
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        if (a[0x16] == 0xFF || (short)(unsigned char)a[0x15] != cur || *(short *)(a + 0) < 0) continue;
        used[a[0x11]] = 1;
    }
    for (t = 1; t < 0xFF; t++) if (!used[t]) return (unsigned char)t;
    return 0;
}

/* ===================================================================
 * StackCommitGroups — the stack window's commit (PPC_0002.c:17000-17124):
 * the selected entries become the selection (status bit 1 set: not
 * defending); then per group, in the window's order: one record -> tag 0;
 * several defending (the first member's status bit 1 clear) -> tag 1;
 * several active -> a tag the stack already used (2..254, popped from the
 * end of the list, whose first entry is never reused) or a new side-unique
 * one (FUN_10021d50).
 * =================================================================== */
static void StackCommitGroups(void)
{
    unsigned char *gs;
    short sj, nOld = 0, g;
    unsigned char oldTags[MAX_STACK];
    short order[MAX_STACK], nGroups = 0;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;

    for (sj = 0; sj < sStackCount; sj++)
        if (sStackSelected[sj] && sStackArmyIdx[sj] >= 0)
            ARMY_REC(sStackArmyIdx[sj])[0x2d] = 0;
    for (sj = 0; sj < sStackCount; sj++) {
        unsigned char t;
        short q;
        Boolean seen = false;
        if (sStackArmyIdx[sj] < 0) continue;
        t = ARMY_REC(sStackArmyIdx[sj])[0x11];
        if (t == 0 || t == 1) continue;
        for (q = 0; q < nOld; q++) if (oldTags[q] == t) seen = true;
        if (!seen) oldTags[nOld++] = t;
    }
    for (sj = 0; sj < sStackCount; sj++) {          /* the groups in window order */
        short q;
        Boolean seen = false;
        for (q = 0; q < nGroups; q++) if (order[q] == sStackGroupId[sj]) seen = true;
        if (!seen) order[nGroups++] = sStackGroupId[sj];
    }
    for (g = 0; g < nGroups; g++) {
        short cnt = 0, first = -1;
        unsigned char tag;
        for (sj = 0; sj < sStackCount; sj++)
            if (sStackGroupId[sj] == order[g] && sStackArmyIdx[sj] >= 0) {
                if (first < 0) first = sStackArmyIdx[sj];
                cnt++;
            }
        if (first < 0) continue;
        if (cnt == 1) tag = 0;
        else if (ARMY_REC(first)[0x2d] != 0) tag = 1;
        else {
            nOld--;
            tag = (nOld < 1) ? NewGroupTag() : oldTags[nOld];
        }
        for (sj = 0; sj < sStackCount; sj++)
            if (sStackGroupId[sj] == order[g] && sStackArmyIdx[sj] >= 0)
                ARMY_REC(sStackArmyIdx[sj])[0x11] = tag;
    }
    /* Update sSelectedArmy to first selected */
    for (sj = 0; sj < sStackCount; sj++) {
        if (sStackSelected[sj] && sStackArmyIdx[sj] >= 0) {
            sSelectedArmy = sStackArmyIdx[sj];
            break;
        }
    }
    sInfoStackBackupSaved = false;
}

/* ===================================================================
 * StackRestoreBackup — Restore backup arrays (Cancel).
 * =================================================================== */
static void StackRestoreBackup(void)
{
    short si;
    sStackCount = sBakStackCount;
    sActiveSlot = sBakActiveSlot;
    for (si = 0; si < MAX_STACK; si++) {
        sStackArmyIdx[si]  = sBakArmyIdx[si];
        sStackGroupId[si]  = sBakGroupId[si];
        sStackSelected[si] = sBakSelected[si];
        sStackSep[si]      = sBakSep[si];
    }
    sInfoStackBackupSaved = false;
}

/* ===================================================================
 * StackTakeBackup — Save current stack state for Cancel.
 * =================================================================== */
static void StackTakeBackup(void)
{
    short si;
    sBakStackCount = sStackCount;
    sBakActiveSlot = sActiveSlot;
    for (si = 0; si < MAX_STACK; si++) {
        sBakArmyIdx[si]  = sStackArmyIdx[si];
        sBakGroupId[si]  = sStackGroupId[si];
        sBakSelected[si] = sStackSelected[si];
        sBakSep[si]      = sStackSep[si];
    }
    sInfoStackBackupSaved = true;
}

