/* ===================================================================
 * RecalcArmyStrength — Recalculate strength display value (army+0x2A).
 *
 * Formula: SUM(HP * 2) for all occupied unit slots.
 * Must be called whenever unit HP or slot occupancy changes.
 * =================================================================== */
static void RecalcArmyStrength(unsigned char *army)
{
    short str = 0, i;
    for (i = 0; i < 4; i++) {
        if ((unsigned char)army[0x16 + i] != 0xFF)
            str += (short)(unsigned char)army[0x1e + i] * 2;
    }
    *(short *)(army + 0x2a) = str;
}

/* (TryMergeArmies, the remake's record auto-merge, was removed: the original
 * never merges unit records - see ExecutePathSteps.) */


/* ===================================================================
 * GetTerrainType — Returns raw terrain type at a map tile (0-11).
 *
 * 68k terrain types: 0=Road, 1=Bridge, 2=Water, 3=Shore, 4=Forest,
 * 5=Hills, 6=Mountains, 7=Plains, 8=Marsh, 9=Sea,
 * 10=City, 11=Ruin/Temple.
 * =================================================================== */
static short GetTerrainType(short mapX, short mapY)
{
    unsigned char *gs, *mapData;
    if (*gGameState == 0 || *gMapTiles == 0) return -1;
    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight) return -1;
    gs = (unsigned char *)*gGameState;
    mapData = (unsigned char *)*gMapTiles;
    return (short)gs[mapData[mapY * 0xE0 + mapX * 2] + TERRAIN_TYPE_OFS];
}


/* ===================================================================
 * IsDiagonalBlocked — 68k CODE_115 FUN_000014c2 diagonal restriction.
 *
 * Ground units cannot move diagonally between terrain categories 2/3
 * (forest/hills in gs+0x711 system) and other terrain. Prevents
 * "cutting corners" through difficult terrain. Flying units exempt.
 * =================================================================== */
static Boolean IsDiagonalBlocked(short srcX, short srcY, short dstX, short dstY, short unitClass)
{
    /* The original has no corner-cutting rule: all 8 neighbours cost the
     * same; 68k FUN_000014c2 is the single-step water/land check, which the
     * cost flags in GetMovementCost already cover. */
    (void)srcX; (void)srcY; (void)dstX; (void)dstY; (void)unitClass;
    return false;
}

static Boolean IsDiagonalBlockedOld(short srcX, short srcY, short dstX, short dstY, short unitClass)
{
    short dx, dy, srcTT, dstTT;
    Boolean srcRestricted, dstRestricted;

    if (unitClass == 0x0E) return false;  /* flying: no restriction */

    dx = dstX - srcX; dy = dstY - srcY;
    if (dx == 0 || dy == 0) return false;  /* cardinal: no restriction */

    srcTT = GetTerrainType(srcX, srcY);
    dstTT = GetTerrainType(dstX, dstY);
    if (srcTT < 0 || dstTT < 0) return false;

    /* 68k CODE_115 FUN_000014c2: terrain categories 2 (Water) and 3 (Shore)
     * from gs+0x711 are the restricted types for diagonal movement (the 68k
     * literal bytes are '\x02'/'\x03'). Prevents cutting corners between
     * water/shore and land. */
    srcRestricted = (srcTT == 2 || srcTT == 3);
    dstRestricted = (dstTT == 2 || dstTT == 3);

    /* Blocked if one is restricted terrain and the other isn't */
    return (srcRestricted != dstRestricted);
}


/* ===================================================================
 * GetMovementCost — Returns movement point cost to enter a map tile.
 *
 * Uses terrain properties table (gs+0x711) and movement cost table
 * (sMoveCostTable, separate from fight order at gs+0x60C).
 * unitClass is the army's primary unit type (0-28).
 * Returns 0 if impassable, otherwise 1-4 movement points.
 * =================================================================== */
static short GetMovementCost(short mapX, short mapY, short unitClass)
{
    /* The original's rules are hard-coded (68k CODE_042 FUN_00001670 cost map,
     * CODE_115 FUN_00001a70 wavefront; table at 68k 0x15cbe / PPC data
     * 0x17576), per terrain type of gs+0x711:
     *   Road 1, Bridge 1, Water 1 (water), Shore 2 (water), Forest 4,
     *   Hills 6, Mountains blocked, Plains 2, Marsh 5, "Sea" 2, City 1, Ruin 2.
     * Road overlay (RD & 0x1F) makes any tile cost 1. Land stacks can't enter
     * water tiles; units with the hills (DAT byte 0x3A) / forest (0x38)
     * ability cross those at 2. Flyers pay 1 on road/bridge/city, else 2.
     * The hero has no abilities and is a land unit (no mountains).
     * (Foreign cities, which the original blocks except as an attack target,
     * stay enterable here so the remake's attack paths keep working.) */
    static const unsigned char kCost[12] = {1, 1, 1, 2, 4, 6, 0, 2, 5, 2, 1, 2};
    static const unsigned char kFlag[12] = {0x10, 0x18, 0x08, 0x08, 0x50, 0x30,
                                            0x10, 0x10, 0x10, 0x10, 0x90, 0x10};
    unsigned char *gs, *mapData, *ute = NULL;
    short type, c, f;
    Boolean road = false, flying, naval;

    if (*gGameState == 0 || *gMapTiles == 0)
        return 1;
    if (mapX < 0 || mapX >= sMapWidth || mapY < 0 || mapY >= sMapHeight)
        return 0;
    gs = (unsigned char *)*gGameState;
    mapData = (unsigned char *)*gMapTiles;
    type = gs[mapData[mapY * 0xE0 + mapX * 2] + TERRAIN_TYPE_OFS];
    if (type > 11) type = 7;
    if (*gRoadData != 0 && mapX < 112 && mapY < 156)
        road = (((unsigned char *)*gRoadData)[mapY * 112 + mapX] & 0x1F) != 0;
    c = kCost[type];
    f = kFlag[type];
    if (road) c = 1;

    if (unitClass >= 0 && unitClass < sUnitTypeCount && sUnitTypesLoaded)
        ute = sUnitTypeTable + unitClass * UNIT_TYPE_ENTRY;
    flying = (unitClass == UNIT_CLASS_FLIGHT) || (ute && ute[UTE_STAT_FLYING] >= 1);
    naval  = (ute && ute[UTE_STAT_NAVAL] >= 1);

    /* Foreign and neutral cities block movement unless the city itself is the
     * destination (the original routes around them: drag past a neutral
     * city on turn 2 stopped beside it; attacking it targets its footprint). */
    if (type == 10) {
        short ci, n = sCityCount > 139 ? 139 : sCityCount, me = *(short *)(gs + 0x110);
        for (ci = 0; ci < n; ci++) {
            unsigned char *ct = sCityData + ci * 0x20;
            short ddx = mapX - *(short *)(ct + 0), ddy = mapY - *(short *)(ct + 2);
            if (ct[0x17] >= 2 || ddx < 0 || ddx > 1 || ddy < 0 || ddy > 1) continue;
            if (*(short *)(ct + 4) != me) {
                short tdx = sPathTargetX - *(short *)(ct + 0), tdy = sPathTargetY - *(short *)(ct + 2);
                if (!(tdx >= 0 && tdx <= 1 && tdy >= 0 && tdy <= 1)) return 0;
            }
            break;
        }
    }

    if (flying)
        return (type == 0 || type == 1 || type == 10 || road) ? 1 : 2;
    if (naval) {
        if (f & 0x08) return c;                     /* water 1, shore 2 */
        if (type == 1 || type == 10) return 1;      /* bridge / port city */
        return 0;
    }
    if (!(f & 0x10)) return 0;                      /* land stack into water */
    if (c == 0) return 0;                           /* mountains */
    if (c > 2 && ute != NULL &&
        ((ute[0x3A] && (f & 0x20)) || (ute[0x38] && (f & 0x40))))
        c = 2;                                      /* hills / forest ability */
    return c;
}


/* ===================================================================
 * Stack movement (PPC 1.0.7, authoritative): the mode and abilities of
 * the moving stack are computed once from ALL its units (PPC_0002.c
 * 5398-5438): naval if any unit is a ship; flying only if every unit
 * flies, or heroes + flyers only, or a hero carries a flight item;
 * ground otherwise, with the hills/forest abilities OR'ed over the units.
 * An embarked stack (a land stack on a boat) is ground mode + flag 8 and
 * has no abilities.  sPathMovers holds the records moving together.
 * =================================================================== */
static short PathDirFromDelta(short dx, short dy)
{
    short d;
    for (d = 0; d < 8; d++)
        if (sPathDX[d] == dx && sPathDY[d] == dy) return d;
    return -1;
}

static void PathBuildStack(short armyIdx, Boolean useSelection)
{
    unsigned char *gs;
    short count, i, s, n = 0;
    Boolean embarked = false, naval = false, anyUnit = false, anyHero = false,
            anyNonHero = false, allFly = true, nonHeroFly = true, flightItem = false,
            hills = false, forest = false;

    sPathMoverCount = 0; sPathMode = PMODE_GROUND; sPathFlags = 0; sPathOwner = -1;
    if (*gGameState == 0 || armyIdx < 0) return;
    gs = (unsigned char *)*gGameState;
    count = *(short *)(gs + 0x1602);
    if (count > MAX_ARMIES) count = MAX_ARMIES;
    if (armyIdx >= count) return;

    if (useSelection && sStackCount > 0) {
        Boolean inStack = false;
        for (i = 0; i < sStackCount; i++)
            if (sStackArmyIdx[i] == armyIdx && sStackSelected[i]) inStack = true;
        if (inStack) {
            sPathMovers[n++] = armyIdx;
            for (i = 0; i < sStackCount && n < 8; i++) {
                short m = sStackArmyIdx[i];
                if (!sStackSelected[i] || m < 0 || m >= count || m == armyIdx) continue;
                sPathMovers[n++] = m;
            }
        }
    }
    if (n == 0) sPathMovers[n++] = armyIdx;
    sPathMoverCount = n;
    sPathOwner = (short)(unsigned char)(ARMY_REC(armyIdx))[0x15];

    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(sPathMovers[i]);
        if (a[0x2C] & ARMY_EMBARKED_BIT) embarked = true;
        if (ArmyHasFlightItem(sPathMovers[i])) flightItem = true;
        for (s = 0; s < 4; s++) {
            short t = (short)(unsigned char)a[0x16 + s];
            Boolean fl;
            if (t == 0xFF) continue;
            anyUnit = true;
            fl = UnitTypeFlies(t);
            if (UnitTypeNaval(t)) naval = true;
            if (t == 0x1C) anyHero = true;
            else { anyNonHero = true; if (!fl) nonHeroFly = false; }
            if (!fl) allFly = false;
            if (sUnitTypesLoaded && t < sUnitTypeCount) {
                unsigned char *ute = sUnitTypeTable + t * UNIT_TYPE_ENTRY;
                if (ute[0x3A]) hills = true;      /* DAT byte 0x3A: hills ability */
                if (ute[0x38]) forest = true;     /* DAT byte 0x38: forest ability */
            }
        }
    }
    if (!anyUnit) return;
    if (embarked) { sPathMode = PMODE_GROUND; sPathFlags = PABIL_EMBARKED; }
    else if (naval) sPathMode = PMODE_NAVAL;
    else if (allFly || (anyHero && anyNonHero && nonHeroFly) || (anyHero && flightItem))
        sPathMode = PMODE_FLYING;
    else sPathFlags = (hills ? PABIL_HILLS : 0) | (forest ? PABIL_FOREST : 0);
}

/* A compact signature of the stack's movement rules (hover preview cache). */
static short PathStackSig(short armyIdx)
{
    PathBuildStack(armyIdx, armyIdx == sSelectedArmy);
    return (short)(sPathMode | (sPathFlags << 2) | (sPathMoverCount << 8));
}

/* Minimum MP over the moving records (the original's stack MP). */
static short PathMoversMinMP(void)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short i, mp = 999;
    for (i = 0; i < sPathMoverCount; i++) {
        short m = (short)(unsigned char)(ARMY_REC(sPathMovers[i]))[0x2e];
        if (m < mp) mp = m;
    }
    return mp == 999 ? 0 : mp;
}

/* A city is coastal when a bridge/water/shore tile touches its 2x2
 * footprint (PPC FUN_10042a24 walks the ring around the city). */
static Boolean CityIsCoastal(short cx, short cy)
{
    short dx, dy;
    for (dy = -1; dy <= 2; dy++)
        for (dx = -1; dx <= 2; dx++) {
            short t;
            if (dx >= 0 && dx <= 1 && dy >= 0 && dy <= 1) continue;
            t = GetTerrainType(cx + dx, cy + dy);
            if (t == 1 || t == 2 || t == 3) return true;
        }
    return false;
}

/* Index of the city (not ruin) whose 2x2 holds (x,y); -1 when none. */
static short PathCityIndexAt(short x, short y)
{
    short ci, n = sCityCount > 139 ? 139 : sCityCount;
    for (ci = 0; ci < n; ci++) {
        unsigned char *ct = sCityData + ci * 0x20;
        short ddx = x - *(short *)(ct + 0), ddy = y - *(short *)(ct + 2);
        if (ct[0x17] >= 2 || ddx < 0 || ddx > 1 || ddy < 0 || ddy > 1) continue;
        return ci;
    }
    return -1;
}

/* ===================================================================
 * BuildPathFlagGrid — PPC FUN_10044110 + FUN_10042d2c/FUN_10042bb4.
 * Per tile (PPC 1.0.7 jump table, read from the code section at
 * 0x1004457c): cost = table[type] (PPC data 0x17576; a road overlay makes
 * it 1; flyers pay 1 on road/bridge/city, else 2) OR'ed with
 *   bridge 0x18, Water/Shore 0x08, forest 0x40, hills 0x20,
 *   road/mountains/plains/marsh/type 9/ruin: nothing,
 *   city: own -> 0x80 | (0x18 when coastal); foreign -> cost 0, 0x80,
 *   anchor tile (MAP flag byte bit 0x80) +0x10.
 * So bit 0x10 marks a PORT: bridges, anchors and coastal cities are the
 * only places where a ground stack may pass between land and water (the
 * search and the trace refuse every other land<->water step).  The city
 * a path is aimed at is opened by FUN_10042d2c(req, 1) with cost 1 and
 * 0x18 when coastal, whoever owns it (that is how a boat attacks a coastal
 * city from any adjacent water tile); here every coastal city gets 0x18,
 * which is equivalent because a foreign city is blocked unless it is the
 * destination.  Own cities cost 1 and are routed through; a neutral city
 * costs 1 in the ground search of a non-human player type (FUN_10042d2c),
 * the execution still stops in front of it.
 * (The 68k CD build, CODE_042 FUN_00001670, differs: there plain land has
 * 0x10 too and cities 0x90, so boats could land anywhere.  The PPC 1.0.7
 * build is the reference.)
 * =================================================================== */
static void BuildPathFlagGrid(void)
{
    static const unsigned char kCost[12]  = {1, 1, 1, 2, 4, 6, 0, 2, 5, 2, 1, 2};
    static const unsigned char kTFlag[12] = {0, 0x18, 0x08, 0x08, 0x40, 0x20, 0, 0, 0, 0, 0x80, 0};
    unsigned char *gs, *mapData, *rd = NULL;
    short x, y, maxX, maxY, me, ci, n;
    Boolean human;

    if (*gGameState == 0 || *gMapTiles == 0) return;
    gs = (unsigned char *)*gGameState;
    mapData = (unsigned char *)*gMapTiles;
    if (*gRoadData != 0) rd = (unsigned char *)*gRoadData;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    me = sPathOwner >= 0 ? sPathOwner : *(short *)(gs + 0x110);
    human = !sPathForceAI && (me >= 0 && me < 8 && *(short *)(gs + 0xd0 + me * 2) == 0);

    for (y = 0; y < maxY; y++) {
        short rowOff = y * PATH_GRID_W;
        for (x = 0; x < maxX; x++) {
            short type = gs[mapData[y * 0xE0 + x * 2] + TERRAIN_TYPE_OFS];
            Boolean road = (rd != NULL && x < 112 && y < 156 && (rd[y * 112 + x] & 0x1F) != 0);
            unsigned char c, f;
            if (type > 11) type = 7;
            c = road ? 1 : kCost[type];
            if (sPathMode == PMODE_FLYING)
                c = (type == 0 || type == 1 || type == 10 || road) ? 1 : 2;
            f = (unsigned char)(kTFlag[type] | c);
            if (mapData[y * 0xE0 + x * 2 + 1] & 0x80) f |= PFLAG_PORT;     /* anchor: +0x10 */
            sPathFlagGrid[rowOff + x] = f;
        }
    }

    n = sCityCount > 139 ? 139 : sCityCount;
    for (ci = 0; ci < n; ci++) {
        unsigned char *ct = sCityData + ci * 0x20;
        short cx = *(short *)(ct + 0), cy = *(short *)(ct + 2);
        short owner = *(short *)(ct + 4);
        Boolean coastal, neutral = (owner < 0 || owner > 7);
        short dx, dy;
        if (ct[0x17] >= 2) continue;                      /* ruin / temple */
        coastal = CityIsCoastal(cx, cy);
        for (dy = 0; dy <= 1; dy++)
            for (dx = 0; dx <= 1; dx++) {
                unsigned char f;
                x = cx + dx; y = cy + dy;
                if (x < 0 || x >= maxX || y < 0 || y >= maxY) continue;
                f = sPathFlagGrid[y * PATH_GRID_W + x];
                /* FUN_10042d2c: a neutral city is opened (cost 1) for a ground
                 * stack of a player whose type is not the human type 0. */
                if (owner != me && !(neutral && !human && sPathMode == PMODE_GROUND))
                    f &= ~7;                              /* blocked unless destination */
                if (coastal) f |= PFLAG_WATER | PFLAG_PORT;
                sPathFlagGrid[y * PATH_GRID_W + x] = (unsigned char)(f | PFLAG_CITY);
            }
    }
}

/* Cost of entering a tile while executing a path (PPC FUN_100445fc).
 * *trans is set when a ground stack steps off a port onto the other
 * element: not embarked and the tile is open water (no 0x10), or embarked
 * and the tile is open land; the steps after that cost 0x80 each, so the
 * move ends on that first tile and the stack boards / lands there
 * (PathBoardOrLand, MP 0).  Leaving a coastal city or an anchor therefore
 * costs the rest of the turn: one tile out and stop. */
static short PathStepCost(short x, short y, short *trans)
{
    unsigned char f;
    short c;
    if (x < 0 || x >= PATH_GRID_W || y < 0 || y >= PATH_GRID_H) return 0x80;
    f = sPathFlagGrid[y * PATH_GRID_W + x];
    c = f & 7;
    if (*trans) return 0x80;
    if (sPathMode == PMODE_FLYING) {
        if ((f & PFLAG_WATER) && !(f & PFLAG_PORT)) return 2;
        if (c == 0) c = 2;
        return c > 2 ? 2 : c;
    }
    if (sPathMode != PMODE_GROUND) return c;
    if (!(f & PFLAG_PORT)) {
        Boolean water = (f & PFLAG_WATER) != 0;
        if ((sPathFlags & PABIL_EMBARKED) ? !water : water) *trans = 1;
    }
    if (sPathFlags && c > 2 &&
        (((sPathFlags & PABIL_HILLS) && (f & PFLAG_HILLS)) ||
         ((sPathFlags & PABIL_FOREST) && (f & PFLAG_FOREST))))
        c = 2;
    return c;
}

/* Relaxation cost in the search (PPC FUN_10043248).  The search expands
 * from the destination: cur is the tile already reached, nbr the tile
 * being labelled (closer to the unit); the cost charged is nbr's.  A
 * ground stack may step between land and water only when one of the two
 * tiles is a port (bit 0x10); the disembark penalty steers the choice. */
static short PathRelaxCost(unsigned char fc, unsigned char fn, Boolean nbrIsSrc)
{
    short c = fn & 7;
    Boolean portOk = (fc & PFLAG_PORT) || (fn & PFLAG_PORT) ||
                     ((fn & PFLAG_WATER) == (fc & PFLAG_WATER));
    if (nbrIsSrc) return (sPathMode != PMODE_GROUND || portOk) ? 1 : -1;
    if (sPathMode == PMODE_FLYING) {
        if (!(fn & PFLAG_WATER) || (fn & PFLAG_PORT)) { if (c == 0) c = 2; if (c > 2) c = 2; }
        else c = 2;
        return c;
    }
    if (sPathMode == PMODE_NAVAL)
        return ((fn & PFLAG_WATER) || (fn & PFLAG_CITY)) ? c : -1;
    if (!portOk) return -1;
    if (sPathFlags && c > 2 &&
        (((sPathFlags & PABIL_HILLS) && (fn & PFLAG_HILLS)) ||
         ((sPathFlags & PABIL_FOREST) && (fn & PFLAG_FOREST))))
        c = 2;
    /* landing from open water onto land / a port: embark penalty (path choice only) */
    if ((!(fc & PFLAG_WATER) || (fc & PFLAG_PORT)) && (fn & PFLAG_WATER) && !(fn & PFLAG_PORT))
        c += sPathPenalty;
    return c;
}

static void PathSetPenalty(short srcX, short srcY, short dstX, short dstY)
{
    sPathPenalty = 0;
    if (sPathMode == PMODE_GROUND) {
        long ddx = dstX - srcX, ddy = dstY - srcY;
        short dt = GetTerrainType(dstX, dstY);
        sPathPenalty = (ddx * ddx + ddy * ddy < 100) ? 30 : 10;   /* FUN_10042ee4 */
        if (dt == 2 || dt == 3) sPathPenalty = 20;
    }
}

/* ===================================================================
 * PathSearch — PPC FUN_10042ee4 (init) + FUN_10043248 (search), exact.
 * The grid holds the cost to the destination: 30000 unlabelled, 30001
 * blocked, a NEGATIVE value for a labelled cell not yet expanded
 * ("open"), positive once expanded.  Each pass scans the cells within
 * Chebyshev distance sPathRadius of the destination (x-major, then y),
 * clamped to bbox(unit,dest) +/- 6 (attempt 0) or +/- 50 (attempt 1,
 * which continues the same grid and radius), expands
 * every open cell and labels its neighbours with the neighbour's cost;
 * the search ends two passes after the unit's tile was expanded, or
 * when a pass changes nothing (failure if the unit was never reached).
 * Ground stacks can't use cost-0 tiles. Ships are blocked only by a
 * missing water bit, so a cost-0 coastal city stays open and the relax
 * step charges 0 to enter it. Flyers are blocked only by cost-0 city
 * tiles. A human's unexplored tiles are impassable except the destination
 * (ground) or the destination's row and column (naval, flying). A blocked
 * destination is opened when it is a city tile (FUN_10043e60).
 * =================================================================== */
static short sPathRadius = 0;

static Boolean PathSearch(short srcX, short srcY, short dstX, short dstY, short attempt)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short bx0, by0, bx1, by1, x, y, maxX, maxY, me = sPathOwner, R, left = 3, passes = 0;
    Boolean changed, reached = false, ok = true;

    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    R = (attempt == 0) ? 6 : 50;   /* the 20 of FUN_10043248 is the road builder's (_DAT_809f0004) */
    bx0 = (srcX < dstX ? srcX : dstX) - R; if (bx0 < 0) bx0 = 0;
    by0 = (srcY < dstY ? srcY : dstY) - R; if (by0 < 0) by0 = 0;
    bx1 = (srcX > dstX ? srcX : dstX) + R; if (bx1 >= maxX) bx1 = maxX - 1;
    by1 = (srcY > dstY ? srcY : dstY) + R; if (by1 >= maxY) by1 = maxY - 1;

    if (attempt == 0) {
        long i, total = (long)PATH_GRID_W * PATH_GRID_H;
        Boolean fog = false;
        for (i = 0; i < total; i++) sPathCostGrid[i] = PATH_COST_MAX;
        if (sOptHiddenMap && me >= 0 && me < 8 && *(short *)(gs + 0xd0 + me * 2) == 0)
            fog = true;                               /* human: fog is impassable */
        for (y = 0; y < maxY; y++) {
            for (x = 0; x < maxX; x++) {
                unsigned char f = sPathFlagGrid[y * PATH_GRID_W + x];
                Boolean blocked;
                if (sPathMode == PMODE_GROUND)      blocked = (f & 7) == 0;
                else if (sPathMode == PMODE_NAVAL)  blocked = !(f & PFLAG_WATER); /* cost-0 coastal cities stay open */
                else                                blocked = (f & PFLAG_CITY) && (f & 7) == 0;
                /* Cities: FUN_10042ee4 blocks only cost-0 tiles, and the flag
                 * grid gives cost 0 to foreign and neutral cities only (68k
                 * CODE_042 FUN_00001670 case 10: owner nibble != player), so
                 * a path runs through the player's own cities and round the
                 * others (Erythea turn 2: the path went round Myre, which was
                 * neutral then).  A city destination is opened below.
                 * Fog: the destination itself is exempt (ground). Naval and
                 * flying exempt every tile of the destination's row or column
                 * (the original test is x != dstX && y != dstY). The source
                 * tile is not exempt. */
                if (fog && !FogGetBit(sFogExplored[me], x, y)) {
                    Boolean exempt = (sPathMode == PMODE_GROUND)
                        ? (x == dstX && y == dstY)
                        : (x == dstX || y == dstY);
                    if (!exempt) blocked = true;
                }
                if (blocked) sPathCostGrid[y * PATH_GRID_W + x] = PATH_COST_BLOCK;
            }
        }
        if (sPathCostGrid[dstY * PATH_GRID_W + dstX] == PATH_COST_BLOCK &&
            (sPathFlagGrid[dstY * PATH_GRID_W + dstX] & PFLAG_CITY))
            sPathCostGrid[dstY * PATH_GRID_W + dstX] = PATH_COST_MAX;
        if (sPathCostGrid[dstY * PATH_GRID_W + dstX] == PATH_COST_BLOCK) return false;
        sPathCostGrid[dstY * PATH_GRID_W + dstX] = -1;     /* open (FUN_10043e60: 0xffff) */
        sPathRadius = 0;
    }

    do {
        short xlo = dstX - sPathRadius, xhi = dstX + sPathRadius;
        short ylo = dstY - sPathRadius, yhi = dstY + sPathRadius;
        if (xlo < bx0) xlo = bx0;  if (xhi > bx1) xhi = bx1;
        if (ylo < by0) ylo = by0;  if (yhi > by1) yhi = by1;
        changed = false;
        for (x = xlo; x <= xhi; x++) {
            for (y = ylo; y <= yhi; y++) {
                short v = sPathCostGrid[y * PATH_GRID_W + x], d;
                unsigned char fc;
                if (v >= 1) continue;             /* expanded, unlabelled or blocked */
                sPathCostGrid[y * PATH_GRID_W + x] = (short)-v;
                changed = true;
                fc = sPathFlagGrid[y * PATH_GRID_W + x];
                for (d = 0; d < 8; d++) {
                    short nx = x + sPathDX[d], ny = y + sPathDY[d], g, c, nv;
                    if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
                    g = sPathCostGrid[ny * PATH_GRID_W + nx];
                    if (g == PATH_COST_BLOCK) continue;
                    c = PathRelaxCost(fc, sPathFlagGrid[ny * PATH_GRID_W + nx],
                                      nx == srcX && ny == srcY);
                    if (c < 0) continue;
                    nv = (short)(-v + c);
                    if (g < 0) g = (short)-g;
                    if (nv < g) sPathCostGrid[ny * PATH_GRID_W + nx] = (short)-nv;
                }
                if (x == srcX && y == srcY) reached = true;
            }
        }
        if (reached && left != 0) left--;
        sPathRadius++;
        if (!changed) { left = 0; if (!reached) ok = false; }
        if (++passes > 400) break;
    } while (left != 0);
    return ok;
}

/* Direction from (x1,y1) toward (x2,y2): PPC FUN_100184dc (0xFF = same). */
static short PathDirToward(short x1, short y1, short x2, short y2)
{
    if (x1 != x2) {
        if (y1 == y2) return x2 < x1 ? 6 : 2;
        if (x1 <= x2) return y2 < y1 ? 1 : 3;
        return y2 < y1 ? 7 : 5;
    }
    if (y1 == y2) return 0xFF;
    return y2 < y1 ? 0 : 4;
}

/* ===================================================================
 * PathTrace — PPC FUN_100439a4: walk forward from the unit toward the
 * destination, taking at each step the lowest-labelled neighbour; ties
 * go to the first in direction order base = dir(cur->dest) then offsets
 * 0,7,1,6,2,5,3,4.  A ground stack never steps land<->water unless one
 * of the two tiles is a port.  Returns the number of directions written.
 * =================================================================== */
static short PathTrace(short srcX, short srcY, short dstX, short dstY,
                       unsigned char *buf, short maxSteps, short *endX, short *endY)
{
    static const short kOff[8] = {0, 7, 1, 6, 2, 5, 3, 4};
    short cx = srcX, cy = srcY, n = 0, maxX, maxY;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    while (n < maxSteps && !(cx == dstX && cy == dstY)) {
        short base = PathDirToward(cx, cy, dstX, dstY), k, bestDir = -1, bestX = cx, bestY = cy;
        short bestV = sPathCostGrid[cy * PATH_GRID_W + cx];
        if (bestV < 0) bestV = (short)-bestV;
        unsigned char fc = sPathFlagGrid[cy * PATH_GRID_W + cx];
        if (base == 0xFF) base = 0;
        for (k = 0; k < 8; k++) {
            short d = (short)((base + kOff[k]) & 7);
            short nx = cx + sPathDX[d], ny = cy + sPathDY[d], v;
            unsigned char fn;
            if (nx < 0 || nx >= maxX || ny < 0 || ny >= maxY) continue;
            v = sPathCostGrid[ny * PATH_GRID_W + nx];
            if (v >= PATH_COST_MAX) continue;     /* unlabelled or blocked */
            if (v < 0) v = (short)-v;             /* open cell (FUN_10003768 abs) */
            fn = sPathFlagGrid[ny * PATH_GRID_W + nx];
            if (sPathMode == PMODE_GROUND && !(fc & PFLAG_PORT) && !(fn & PFLAG_PORT) &&
                ((fc & PFLAG_WATER) != (fn & PFLAG_WATER))) continue;
            if (v < bestV) {          /* strictly lower (the tie rule is the road builder's) */
                bestV = v; bestDir = d; bestX = nx; bestY = ny;
            }
        }
        if (bestDir < 0) break;
        buf[n++] = (unsigned char)bestDir;
        cx = bestX; cy = bestY;
    }
    *endX = cx; *endY = cy;
    return n;
}

/* ===================================================================
 * ComputePathGridOnly — prepare the preview: stack rules + flag grid.
 * (The original searches per destination, so the hover/drag preview
 * runs the bounded search in TracePreviewPath.)
 * =================================================================== */
static void ComputePathGridOnly(short srcX, short srcY, short armyIdx)
{
    sPreviewGridValid = false;
    if (srcX < 0 || srcY < 0 || *gGameState == 0 || *gMapTiles == 0) return;
    PathBuildStack(armyIdx, armyIdx == sSelectedArmy);
    if (sPathMoverCount == 0) return;
    BuildPathFlagGrid();
    sPreviewGridValid = true;
}

/* ===================================================================
 * TracePreviewPath — path from (srcX,srcY) to (dstX,dstY) for the
 * prepared stack into sPreviewPathX/Y[] with cumulative MP in
 * sPreviewCum[] (execution costs, FUN_10044728).
 * =================================================================== */
static void TracePreviewPath(short srcX, short srcY, short dstX, short dstY)
{
    short maxX, maxY, endX, endY, n, i, cx, cy, trans = 0;
    long cum = 0;

    sPreviewPathLen = 0;
    if (!sPreviewGridValid) return;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    if (srcX < 0 || srcY < 0 || srcX >= maxX || srcY >= maxY) return;
    if (dstX < 0 || dstY < 0 || dstX >= maxX || dstY >= maxY) return;
    if (srcX == dstX && srcY == dstY) return;
    sPathTargetX = dstX; sPathTargetY = dstY;
    PathSetPenalty(srcX, srcY, dstX, dstY);
    if (!PathSearch(srcX, srcY, dstX, dstY, 0) &&
        !PathSearch(srcX, srcY, dstX, dstY, 1))
        return;
    n = PathTrace(srcX, srcY, dstX, dstY, sPreviewDirs, PATH_TRACE_MAX, &endX, &endY);
    sPreviewPathX[0] = srcX; sPreviewPathY[0] = srcY; sPreviewCum[0] = 0;
    sPreviewPathLen = 1;
    cx = srcX; cy = srcY;
    for (i = 0; i < n && sPreviewPathLen < PATH_MAX_STEPS; i++) {
        cx += sPathDX[sPreviewDirs[i]]; cy += sPathDY[sPreviewDirs[i]];
        cum += PathStepCost(cx, cy, &trans);
        sPreviewPathX[sPreviewPathLen] = cx;
        sPreviewPathY[sPreviewPathLen] = cy;
        sPreviewCum[sPreviewPathLen] = (unsigned char)(cum > 255 ? 255 : cum);
        sPreviewPathLen++;
    }
}

/* ===================================================================
 * The path cache (PPC FUN_100424e4 / FUN_1004248c / FUN_100427cc /
 * FUN_100426b4 / FUN_100425c0 / FUN_10043c84): 20 entries of 0xd6 bytes
 * {state, mode, flags, src x/y, dest x/y, 200 directions}.  FUN_10043e60
 * looks in slot 0, then (destination more than 14 away) in slots 1-19: a
 * hit needs the same destination, mode and ability flags and the unit's
 * tile on the cached path, whose rest is then used with no search (any
 * side's cached path; map changes since are not seen).  A new path is
 * stored in slot 0 (distance under 15) or in the first free slot 1-19,
 * else over the entry with the shortest span when that is shorter than
 * the new distance.  Cleared only at start-up, save and load.
 * =================================================================== */
#define PATH_CACHE_N 20
typedef struct {
    short state, mode, flags, sx, sy, dx, dy;
    unsigned char dirs[PATH_MAX_STEPS];
} PathCacheEnt;
static PathCacheEnt sPathCache[PATH_CACHE_N];

static void PathCacheClear(void)                  /* FUN_1004248c / FUN_100423a0 */
{
    BlockZero(sPathCache, sizeof(sPathCache));
}

static short PathIntDist(short x1, short y1, short x2, short y2)   /* FUN_1000a884 */
{
    long d2 = (long)(x1 - x2) * (x1 - x2) + (long)(y1 - y2) * (y1 - y2);
    short r = 0;
    while ((long)(r + 1) * (r + 1) <= d2) r++;
    return r;
}

static Boolean PathCacheHit(short slot, short srcX, short srcY, short dstX, short dstY)
{
    PathCacheEnt *e = &sPathCache[slot];
    short cx, cy, i, j, n;
    if (dstX != e->dx || dstY != e->dy || sPathMode != e->mode || (short)sPathFlags != e->flags)
        return false;
    cx = e->sx; cy = e->sy;                         /* FUN_100425c0 */
    for (i = 0; i < PATH_MAX_STEPS; i++) {
        unsigned char d = e->dirs[i];
        if (d == 0xFF) return false;
        if (cx == srcX && cy == srcY) break;
        if (d > 7) return false;
        cx += sPathDX[d]; cy += sPathDY[d];
        if (cx < 0 || cy < 0 || cx == 112 || cy == 156) return false;
    }
    if (i >= PATH_MAX_STEPS) return false;
    for (j = 0; j < PATH_MAX_STEPS; j++) sPathDirBuffer[j] = 0xFF;
    for (j = 0; i < PATH_MAX_STEPS; i++, j++) sPathDirBuffer[j] = e->dirs[i];
    for (n = 0; n < PATH_MAX_STEPS && sPathDirBuffer[n] != 0xFF; n++) ;
    sPathLength = n;
    e->state = 2;
    return true;
}

static void PathCacheStore(short dist, short srcX, short srcY, short dstX, short dstY)
{
    short slot = -1, k, minSlot = -1, minSpan = 10000;
    PathCacheEnt *e;
    if (dist < 15) slot = 0;
    else {
        for (k = 1; k < PATH_CACHE_N; k++) {
            short span;
            if (sPathCache[k].state == 0) { slot = k; break; }
            span = PathIntDist(sPathCache[k].dx, sPathCache[k].dy, sPathCache[k].sx, sPathCache[k].sy);
            if (span < minSpan) { minSpan = span; minSlot = k; }
        }
        if (slot < 0 && minSlot >= 0 && minSpan < dist) slot = minSlot;
        if (slot < 0) return;
    }
    e = &sPathCache[slot];
    for (k = 0; k < PATH_MAX_STEPS; k++) e->dirs[k] = k < sPathLength ? sPathDirBuffer[k] : 0xFF;
    e->state = 2; e->mode = sPathMode; e->flags = (short)sPathFlags;
    e->sx = srcX; e->sy = srcY; e->dx = dstX; e->dy = dstY;
}

/* ===================================================================
 * ComputeWavefrontPath — PPC FUN_10043e60: path for the stack led by
 * armyIdx (its selected group when it is the selected stack) from
 * (srcX,srcY) to (dstX,dstY).  Returns the number of direction steps in
 * sPathDirBuffer[] (0xFF-terminated), 0 when already there, -1 when the
 * destination is unreachable.
 * =================================================================== */
static short ComputeWavefrontPath(short srcX, short srcY,
                                   short dstX, short dstY,
                                   short armyIdx)
{
    short maxX, maxY, endX, endY, dist;

    sPathTargetX = dstX; sPathTargetY = dstY;    /* a foreign city is enterable only as the target */
    sPathLength = 0; sPathDirBuffer[0] = 0xFF;
    if (*gGameState == 0 || *gMapTiles == 0) return -1;
    if (srcX < 0 || srcY < 0 || dstX < 0 || dstY < 0) return -1;
    maxX = sMapWidth;  if (maxX > PATH_GRID_W) maxX = PATH_GRID_W;
    maxY = sMapHeight; if (maxY > PATH_GRID_H) maxY = PATH_GRID_H;
    if (srcX >= maxX || srcY >= maxY || dstX >= maxX || dstY >= maxY) return -1;
    if (srcX == dstX && srcY == dstY) return 0;

    PathBuildStack(armyIdx, armyIdx == sSelectedArmy);
    if (sPathMoverCount == 0) return -1;
    BuildPathFlagGrid();
    dist = PathIntDist(dstX, dstY, srcX, srcY);
    /* the path cache first (FUN_100427cc: slot 0, then slots 1-19 when
     * the destination is more than 14 away) */
    if (PathCacheHit(0, srcX, srcY, dstX, dstY)) return sPathLength;
    if (dist > 14) {
        short k;
        for (k = 1; k < PATH_CACHE_N; k++)
            if (PathCacheHit(k, srcX, srcY, dstX, dstY)) return sPathLength;
    }
    /* An adjacent destination (FUN_10043e60 -> FUN_100428dc): a one-step
     * path without a search when the stack flies, or when both tiles are
     * on the same element (Water/Shore or not) and the tile's terrain cost
     * is not 0; otherwise the full search decides (a land<->water step
     * then needs a port on one side). */
    {
        short ddx = dstX - srcX, ddy = dstY - srcY;
        if (ddx >= -1 && ddx <= 1 && ddy >= -1 && ddy <= 1) {
            static const unsigned char kCost[12] = {1, 1, 1, 2, 4, 6, 0, 2, 5, 2, 1, 2};
            short ts = GetTerrainType(srcX, srcY), td = GetTerrainType(dstX, dstY);
            Boolean ok = true;
            if (td > 11) td = 7;
            if (sPathMode != PMODE_FLYING) {
                if (((ts == 2 || ts == 3) ? 1 : 0) != ((td == 2 || td == 3) ? 1 : 0)) ok = false;
                else if (kCost[td] == 0) ok = false;
            }
            if (ok) {
                sPathDirBuffer[0] = (unsigned char)PathDirFromDelta(ddx, ddy);
                sPathDirBuffer[1] = 0xFF;
                sPathLength = 1;
                return 1;
            }
        }
    }
    PathSetPenalty(srcX, srcY, dstX, dstY);
    if (!PathSearch(srcX, srcY, dstX, dstY, 0) &&
        !PathSearch(srcX, srcY, dstX, dstY, 1))
        return -1;
    sPathLength = PathTrace(srcX, srcY, dstX, dstY, sPathDirBuffer, PATH_TRACE_MAX, &endX, &endY);
    sPathDirBuffer[sPathLength] = 0xFF;
    PathCacheStore(dist, srcX, srcY, dstX, dstY);   /* FUN_10043c84 */
    return sPathLength > 0 ? sPathLength : -1;
}

/* Units (not records) standing on a tile, excluding the moving records. */
static short PathUnitsAt(short x, short y, short *foreignOwner)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short count = *(short *)(gs + 0x1602), i, s, units = 0;
    if (count > MAX_ARMIES) count = MAX_ARMIES;
    *foreignOwner = -1;
    for (i = 0; i < count; i++) {
        unsigned char *a = ARMY_REC(i);
        short k;
        Boolean mover = false;
        if (*(short *)(a + 0x00) != x || *(short *)(a + 0x02) != y) continue;
        if (a[0x16] == 0xFF) continue;
        for (k = 0; k < sPathMoverCount; k++) if (sPathMovers[k] == i) mover = true;
        if (mover) continue;
        if ((short)(unsigned char)a[0x15] != sPathOwner) *foreignOwner = (short)(unsigned char)a[0x15];
        for (s = 0; s < 4; s++) if (a[0x16 + s] != 0xFF) units++;
    }
    return units;
}

/* Owner of the city whose 2x2 holds (x,y); -2 when no city is there. */
static short PathCityOwnerAt(short x, short y)
{
    short ci, n = sCityCount > 139 ? 139 : sCityCount;
    for (ci = 0; ci < n; ci++) {
        unsigned char *ct = sCityData + ci * 0x20;
        short ddx = x - *(short *)(ct + 0), ddy = y - *(short *)(ct + 2);
        if (ct[0x17] >= 2 || ddx < 0 || ddx > 1 || ddy < 0 || ddy > 1) continue;
        return *(short *)(ct + 4);
    }
    return -2;
}

/* FUN_10017844's army test: a tile with a foreign army blocks the path
 * (result 3) only when the mover is not at Peace with its owner (the
 * effective state, bits 0-1; with diplomacy off every pair is at War).
 * Neutral armies always block. */
static Boolean PathArmyBlocks(short owner)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    if (owner < 0 || owner > 7 || sPathOwner < 0 || sPathOwner > 7) return true;
    return (*(gs + 0x1582 + sPathOwner * 8 + owner) & 3) != DIPLO_PEACE;
}

static Boolean RoadAt(short x, short y)
{
    if (*gRoadData == 0 || x < 0 || x >= 112 || y < 0 || y >= 156) return false;
    return (((unsigned char *)*gRoadData)[y * 112 + x] & 0x1F) != 0;
}

/* PPC FUN_10017618(mp): with exactly 1 MP left the stack is not "spent"
 * when it stands on a temple or an unsearched ruin, or a city, a foreign
 * army or a road lies in the 3x3 around it. */
static Boolean PathOneMPUseful(short mp, short x, short y)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short ix, iy, ci, n;
    if (mp != 1) return false;
    if (GetTerrainType(x, y) == 11) {
        n = sCityCount > 139 ? 139 : sCityCount;
        for (ci = 0; ci < n; ci++) {
            unsigned char *st = sCityData + ci * 0x20;
            if (st[0x17] < 2 || *(short *)(st + 0) != x || *(short *)(st + 2) != y) continue;
            if (st[0x17] == 2) return true;                                   /* temple */
            if (st[0x1D] != 0 && SITE_KIND(st) != SITE_EMPTY) return true;     /* not searched */
            break;
        }
    }
    for (ix = x - 1; ix <= x + 1; ix++)
        for (iy = y - 1; iy <= y + 1; iy++) {
            short i, cnt;
            if (ix < 0 || iy < 0 || ix >= 112 || iy >= 156) continue;
            if (GetTerrainType(ix, iy) == 10) return true;
            cnt = *(short *)(gs + 0x1602); if (cnt > MAX_ARMIES) cnt = MAX_ARMIES;
            for (i = 0; i < cnt; i++) {
                unsigned char *a = ARMY_REC(i);
                if (a[0x16] == 0xFF || *(short *)(a + 0) != ix || *(short *)(a + 2) != iy) continue;
                if ((short)(unsigned char)a[0x15] != sPathOwner) return true;
                break;
            }
            if (RoadAt(ix, iy)) return true;
        }
    return false;
}

/* Move every record of the stack to (nx,ny): fortification map bit off
 * on the old tile, fortify cleared, ext guard flag cleared, fog revealed. */
static void PathMoveStackTo(short nx, short ny)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short k;
    short oldXs[8], oldYs[8], nOld = 0, q, n = *(short *)(gs + 0x1602), i;
    for (k = 0; k < sPathMoverCount; k++) {
        unsigned char *a = ARMY_REC(sPathMovers[k]);
        short oldX = *(short *)(a + 0x00), oldY = *(short *)(a + 0x02);
        for (q = 0; q < nOld && (oldXs[q] != oldX || oldYs[q] != oldY); q++) ;
        if (q == nOld && nOld < 8) { oldXs[nOld] = oldX; oldYs[nOld] = oldY; nOld++; }
        *(short *)(a + 0x00) = nx;
        *(short *)(a + 0x02) = ny;
        a[0x2d] = 0;
        sArmyState[sPathMovers[k]] = 0;
    }
    /* PPC FUN_10021364: a tile left EMPTY loses its occupied (0x10) and
     * tower (0x20) bits; a tile where units stay keeps them */
    if (n > MAX_ARMIES) n = MAX_ARMIES;
    for (q = 0; q < nOld; q++) {
        if (*gMapTiles == 0 || oldXs[q] < 0 || oldXs[q] >= sMapWidth || oldYs[q] < 0 || oldYs[q] >= sMapHeight)
            continue;
        for (i = 0; i < n; i++) {
            unsigned char *o = ARMY_REC(i);
            if (*(short *)(o + 0) == oldXs[q] && *(short *)(o + 2) == oldYs[q] && o[0x16] != 0xFF) break;
        }
        if (i == n) ((unsigned char *)*gMapTiles)[oldYs[q] * 0xE0 + oldXs[q] * 2 + 1] &= (unsigned char)~0x30;
    }
    if (sOptHiddenMap)
        FogRevealUnit(sPathOwner, nx, ny, sPathMode == PMODE_FLYING);
}

/* Boarding / landing after a ground stack's move (PPC FUN_100171d4 tail
 * + FUN_10017c28): a non-embarked stack ending on Water/Shore becomes
 * embarked, an embarked stack ending on land (not bridge/water/shore)
 * lands; both set the stack's MP to 0.  Returns 1 boarded, 2 landed, else
 * 0: FUN_10017cb4 turns the move's result into 2 (stop) when either
 * happened, so a stack that boards or lands on its way does NOT go on to
 * attack the city or army in front of it this move. */
static short PathBoardOrLand(short x, short y)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short t = GetTerrainType(x, y), k;
    Boolean board = false, land = false;
    if (sPathMode != PMODE_GROUND) return 0;
    if (!(sPathFlags & PABIL_EMBARKED)) { if (t == 2 || t == 3) board = true; }
    else if (t != 1 && t != 2 && t != 3) land = true;
    if (!board && !land) return 0;
    if (land) {                     /* every unit lands, every unit's MP is 0 */
        for (k = 0; k < sPathMoverCount; k++) {
            unsigned char *a = ARMY_REC(sPathMovers[k]);
            a[0x2C] &= ~ARMY_EMBARKED_BIT;
            a[0x2e] = 0;
        }
        sPathFlags &= ~PABIL_EMBARKED;
        return 2;
    }
    {   /* boarding: fliers never board; a hero boards unless the stack has
         * fliers and no non-flying non-hero unit (it rides with the fliers);
         * only the units that boarded lose their MP (FUN_10017c28) */
        Boolean anyFlier = false, groundNonHero = false, heroStays, any = false;
        short u;
        for (k = 0; k < sPathMoverCount; k++) {
            unsigned char *a = ARMY_REC(sPathMovers[k]);
            for (u = 0; u < 4; u++) {
                short t = (short)(unsigned char)a[0x16 + u];
                if (t == 0xFF) continue;
                if (UnitTypeFlies(t)) anyFlier = true;
                else if (t != 0x1C) groundNonHero = true;
            }
        }
        heroStays = anyFlier && !groundNonHero;
        for (k = 0; k < sPathMoverCount; k++) {
            unsigned char *a = ARMY_REC(sPathMovers[k]);
            Boolean boards = false, hasHero = false;
            for (u = 0; u < 4; u++) {
                short t = (short)(unsigned char)a[0x16 + u];
                if (t == 0xFF || UnitTypeFlies(t)) continue;
                if (t == 0x1C) hasHero = true; else boards = true;
            }
            if (!boards && hasHero && !heroStays) boards = true;
            if (!boards) continue;
            a[0x2C] |= ARMY_EMBARKED_BIT;
            a[0x2e] = 0;
            any = true;
        }
        if (!any) return 0;
        sPathFlags |= PABIL_EMBARKED;
        return 1;
    }
}

/* After a battle the stack advances into the target tile (PPC
 * FUN_1002d3ac): a stack that is not embarked and is not flying BOARDS when
 * that tile is Water/Shore (MP 0); nothing else changes - a stack that took
 * a coastal city from its boats stays embarked in the city (20 + carry MP
 * next turn, and it lands - MP 0 - with its first step onto open land). */
static void PathBoardAfterBattle(short x, short y)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short t = GetTerrainType(x, y), k;
    if (sPathMode == PMODE_FLYING || (sPathFlags & PABIL_EMBARKED)) return;
    if (t != 2 && t != 3) return;
    for (k = 0; k < sPathMoverCount; k++) {
        unsigned char *a = ARMY_REC(sPathMovers[k]);
        short u;
        Boolean boards = false;
        if (ArmyIsNaval(sPathMovers[k])) continue;      /* a ship's record rides on */
        for (u = 0; u < 4; u++) {                       /* fliers and heroes with a */
            short t = (short)(unsigned char)a[0x16 + u];/* flight item (FUN_10039e24) */
            if (t == 0xFF || UnitTypeFlies(t)) continue;/* stay as they are */
            if (t == 0x1C && ArmyHasFlightItem(sPathMovers[k])) continue;
            boards = true;
        }
        if (!boards) continue;
        a[0x2C] |= ARMY_EMBARKED_BIT;
        a[0x2e] = 0;
    }
    sPathFlags |= PABIL_EMBARKED;
}

/* Per-step redraw for a human's stack (the original animates each step). */
static void PathAnimateStep(short x, short y)
{
    if (*gMainGameWindow == 0) return;
    if (sAITurnPlayer >= 0) {
        /* a computer stack's step: shown when AI moves are shown */
        if (AIMovesShown()) AIAnimateStep(x, y);
        return;
    }
    {
        WindowPtr mw = (WindowPtr)*gMainGameWindow;
        GrafPtr sp;
        long dummy;
        RevealTile(x, y);
        GetPort(&sp);
        SetPort(mw);
        DrawMapInWindow(mw);
        SetPort(sp);
        Delay(3, &dummy);
    }
}

/* ===================================================================
 * ExecutePathSteps — PPC FUN_10017844 / FUN_10044728 / FUN_100171d4.
 * Runs sPathDirBuffer[] for the stack led by armyIdx:
 *   budget = steps whose cumulative cost fits the stack's MP (a step onto a
 *     non-port tile that boards/lands ends the move after it);
 *   a foreign city tile (result 5), or a tile with an army of a side the
 *     mover is not at Peace with (result 3), stops the stack in front of it;
 *   a tile is a valid stop point only when its units + the stack's units
 *     are at most 8 and no other side's army stands there: the stack
 *     passes through other tiles and is cut back to the last valid stop.
 * Then every record moves at once and pays the cumulative cost, boards or
 * lands.  A path never attacks: the result and the blocked tile go back to
 * the caller (sPathResult, sPathBlockX/Y) - a human's stack just stops in
 * front and keeps its orders (FUN_100419b0 -> FUN_1003dc28, no battle), the
 * computer's mover (AIMoveStack = FUN_10018180) fights the blocker.
 * Result 2 (FUN_10017844's tail / FUN_10017cb4): the move boarded or
 * landed, or the stack is spent - fewer than 2 MP left (1 MP counts when
 * FUN_10017618 sees something to do next to it) or not enough for the next
 * step of its path; a spent stack does not fight.
 * Returns the number of steps taken.
 * =================================================================== */
static short sPathResult = 0;
static short sPathBlockX = -1, sPathBlockY = -1;
/* FUN_1002da54 stores the attack's MP cost in a global (TOC -0x3d8, in the
 * zeroed bss) that FUN_1002d3ac charges every unit of the advancing stack;
 * only a human's attack sets it, so a computer's battle pays whatever the
 * last human attack cost (0 until a human has attacked this session). */
static short sAttackCost = 0;

static short ExecutePathSteps(short armyIdx)
{
    unsigned char *gs, *army;
    unsigned char cumBuf[PATH_MAX_STEPS];
    short armyCount, mp, i, x, y, trans = 0, budget = 0, committed = 0, pending = 0;
    short result = 0, stackUnits = 0, pathN = 0;
    short stepsTaken = 0, k, s, transEnded = 0;
    long cum = 0;

    sPathResult = 0; sPathBlockX = sPathBlockY = -1;
    if (*gGameState == 0 || *gMapTiles == 0) return 0;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
    if (armyIdx < 0 || armyIdx >= armyCount) return 0;
    if (sPathLength <= 0 || sPathDirBuffer[0] == 0xFF) return 0;

    PathBuildStack(armyIdx, true);
    if (sPathMoverCount == 0) return 0;
    BuildPathFlagGrid();
    army = ARMY_REC(armyIdx);
    x = *(short *)(army + 0x00);
    y = *(short *)(army + 0x02);
    mp = PathMoversMinMP();
    for (k = 0; k < sPathMoverCount; k++) {
        unsigned char *a = ARMY_REC(sPathMovers[k]);
        for (s = 0; s < 4; s++) if (a[0x16 + s] != 0xFF) stackUnits++;
    }

    /* --- budget (FUN_10044728) --- */
    for (i = 0; i < sPathLength && i < PATH_MAX_STEPS && sPathDirBuffer[i] != 0xFF; i++) {
        short d = sPathDirBuffer[i];
        x += sPathDX[d]; y += sPathDY[d];
        if (x < 0 || x >= sMapWidth || y < 0 || y >= sMapHeight) break;
        cum += PathStepCost(x, y, &trans);
        cumBuf[i] = (unsigned char)(cum > 255 ? 255 : cum);
        if (cum <= mp) budget++;
        pathN++;
    }

    /* --- stop rules (FUN_10017844) --- */
    x = *(short *)(army + 0x00);
    y = *(short *)(army + 0x02);
    for (i = 0; i < budget; i++) {
        short d = sPathDirBuffer[i], cityOwner, foreign, tileUnits;
        x += sPathDX[d]; y += sPathDY[d];
        cityOwner = PathCityOwnerAt(x, y);
        if (cityOwner != -2 && cityOwner != sPathOwner) {
            result = 5; sPathBlockX = x; sPathBlockY = y; break;
        }
        tileUnits = PathUnitsAt(x, y, &foreign);
        if (foreign >= 0 && PathArmyBlocks(foreign)) {
            result = 3; sPathBlockX = x; sPathBlockY = y; break;
        }
        if (stackUnits + tileUnits <= 8 && foreign < 0) { committed = (short)(committed + pending + 1); pending = 0; }
        else pending++;
    }

    /* --- move (FUN_100171d4) --- */
    if (committed > 0) {
        sUndoArmyIdx = armyIdx;
        sUndoFromX = *(short *)(army + 0x00);
        sUndoFromY = *(short *)(army + 0x02);
        sUndoMovePts = (short)(unsigned char)army[0x2e];
        sUndoFortify = (short)(unsigned char)army[0x2d];
        x = *(short *)(army + 0x00);
        y = *(short *)(army + 0x02);
        for (i = 0; i < committed; i++) {
            short d = sPathDirBuffer[i];
            x += sPathDX[d]; y += sPathDY[d];
            PathMoveStackTo(x, y);
            /* FUN_100169c0 per step, only for a computer player */
            if (sAITurnPlayer >= 0)
                for (k = 0; k < sPathMoverCount; k++) CheckGroundItemPickup(sPathMovers[k]);
            PathAnimateStep(x, y);
        }
        stepsTaken = committed;
        for (k = 0; k < sPathMoverCount; k++) {
            unsigned char *a = ARMY_REC(sPathMovers[k]);
            short left = (short)(unsigned char)a[0x2e] - (short)cumBuf[committed - 1];
            a[0x2e] = (unsigned char)(left < 0 ? 0 : left);
        }
        transEnded = PathBoardOrLand(x, y);
    }

    /* --- the result (FUN_10017844's tail, FUN_10017cb4) --- */
    {
        short left = PathMoversMinMP();
        short lx = *(short *)(army + 0x00), ly = *(short *)(army + 0x02);
        if ((left < 2 && !PathOneMPUseful(left, lx, ly)) ||
            (committed != 0 && result != 5 && result != 3 && committed < pathN &&
             cumBuf[committed] != 0xFF && left < (short)cumBuf[committed]))
            result = 2;
        if (transEnded) result = 2;
    }
    sPathResult = result;
    if (result != 3 && result != 5) { sPathBlockX = sPathBlockY = -1; }

    if (stepsTaken == 0) return 0;

    /* Reached the stored target: the orders are done (FUN_100419b0 /
     * FUN_10018180 clear the target when the lead stands on it). */
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
    if (armyIdx < armyCount) {
        army = ARMY_REC(armyIdx);
        if (*(short *)(army + 0x00) == *(short *)(army + 0x34) &&
            *(short *)(army + 0x02) == *(short *)(army + 0x36))
            for (k = 0; k < sPathMoverCount; k++)
                if (sPathMovers[k] < armyCount)
                    *(short *)(ARMY_REC(sPathMovers[k]) + 0x32) = 0;
        /* The original never merges unit records: a record arriving on a
         * friendly tile keeps its own MP, orders and embarked state. */
    }

    return stepsTaken;
}

/* The stack (sPathMovers, built by PathBuildStack) advances onto (bx,by)
 * and fights there: FUN_1002d3ac (every unit pays sAttackCost, the stack
 * stands on the target; a non-flying stack boards onto Water/Shore) and the
 * battle (FUN_1002d93c for a human, FUN_10030490 for the computer).
 * Returns true when the attacker's record still stands on the tile. */
static Boolean PathAttack(short armyIdx, short bx, short by)
{
    unsigned char *gs = (unsigned char *)*gGameState, *army;
    short armyCount, k;
    Boolean wasSelected = (armyIdx == sSelectedArmy);
    if (gs == NULL || sPathMoverCount == 0) return false;
    army = ARMY_REC(armyIdx);
    PathMoveStackTo(bx, by);
    for (k = 0; k < sPathMoverCount; k++) {
        unsigned char *a = ARMY_REC(sPathMovers[k]);
        short left = (short)(unsigned char)a[0x2e] - sAttackCost;
        a[0x2e] = (unsigned char)(left < 0 ? 0 : left);
    }
    if (CheckAndResolveCombat(armyIdx)) {
        sUndoArmyIdx = -1;
        armyCount = *(short *)(gs + 0x1602);
        if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
        /* the attacker died: its record is gone (or replaced) */
        if (wasSelected && sSelectedArmy < 0) return false;
        if (armyIdx >= armyCount) return false;
        army = ARMY_REC(armyIdx);
        if ((short)(unsigned char)army[0x15] != sPathOwner ||
            *(short *)(army + 0x00) != bx || *(short *)(army + 0x02) != by)
            return false;
    }
    PathBoardAfterBattle(bx, by);   /* FUN_1002d3ac: board, never land */
    return true;
}

/* Map cursor 8/10 (PPC FUN_1003b4a4): the tile is one step from the stack
 * (FUN_1000a884 < 2) and holds a foreign city or a foreign army.  Both the
 * click dispatch (FUN_1000b3d8 cases 8/10) and the step keys (FUN_100a0b08,
 * when the stack has no stored target) then call the attack FUN_1002da54
 * directly, without a path search. */
static Boolean IsAdjacentAttackTarget(short armyIdx, short tx, short ty)
{
    unsigned char *gs = (unsigned char *)*gGameState, *a;
    short count, owner, ax, ay, dx, dy, i, co;
    if (gs == NULL || armyIdx < 0) return false;
    count = *(short *)(gs + 0x1602);
    if (count > MAX_ARMIES) count = MAX_ARMIES;
    if (armyIdx >= count) return false;
    a = ARMY_REC(armyIdx);
    owner = (short)(unsigned char)a[0x15];
    ax = *(short *)(a + 0x00); ay = *(short *)(a + 0x02);
    dx = tx - ax; dy = ty - ay;
    if (dx < -1 || dx > 1 || dy < -1 || dy > 1 || (dx == 0 && dy == 0)) return false;
    co = PathCityOwnerAt(tx, ty);
    if (co != -2 && co != owner) return true;
    for (i = 0; i < count; i++) {
        unsigned char *o = ARMY_REC(i);
        if (o[0x16] == 0xFF || (short)(unsigned char)o[0x15] == owner) continue;
        if (*(short *)(o + 0x00) == tx && *(short *)(o + 0x02) == ty) return true;
    }
    return false;
}


/* PPC FUN_100300e8 for a broken treaty: the attacker's treachery score
 * (gs+0x1122) grows by Dice(1,100)+100 from Peace, Dice(1,15)+10 from
 * Hostile, and both directions (state and displayed copy) become War. */
static void BreakTreaty(short me, short them)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char *d1, *d2;
    short shown, *rep;
    if (gs == NULL || me < 0 || me > 7 || them < 0 || them > 7 || me == them) return;
    d1 = gs + 0x1582 + me * 8 + them;
    d2 = gs + 0x1582 + them * 8 + me;
    shown = *d1 & 3;
    rep = (short *)(gs + 0x1122 + me * 2);
    if (shown == DIPLO_PEACE) *rep += (short)(Dice(1, 100, 0) + 100);
    else if (shown == DIPLO_HOSTILE) *rep += (short)(Dice(1, 15, 0) + 10);
    *d1 = (unsigned char)(DIPLO_SET_STATE(*d1, DIPLO_WAR) & 0xFC) | DIPLO_WAR;
    *d2 = (unsigned char)(DIPLO_SET_STATE(*d2, DIPLO_WAR) & 0xFC) | DIPLO_WAR;
}

/* PPC FUN_1002da54: the human's attack on the adjacent tile (tx,ty) - map
 * cursor 8/10 clicked, or the step key (FUN_100a0b08) - with no path search:
 *  - a non-flying stack may not attack into a tile whose terrain cost is
 *    below 1 (mountains) unless a road runs there: beep;
 *  - with diplomacy on, a side at Peace (or Hostile, for a city other than
 *    city 0) asks "War! / Milord! Thou art attacking / without first having
 *    declared war! / ..." (View 3410, DAT 0x8d); Yes breaks the treaty
 *    (FUN_100300e8) and attacks, No does nothing;
 *  - no MP left: nothing (no beep);
 *  - the cost max(2, terrain cost) goes to sAttackCost and the battle runs.
 * Returns the number of steps (1 when the battle took place). */
static short DirectAttackStep(short armyIdx, short tx, short ty)
{
    static const unsigned char kCost[12] = {1, 1, 1, 2, 4, 6, 0, 2, 5, 2, 1, 2};
    unsigned char *gs = (unsigned char *)*gGameState, *a;
    short me, owner = 15, type, ci, n, i, c;
    Boolean armyThere = false;
    if (gs == NULL || armyIdx < 0) return 0;
    n = *(short *)(gs + 0x1602); if (n > MAX_ARMIES) n = MAX_ARMIES;
    if (armyIdx >= n) return 0;
    a = ARMY_REC(armyIdx);
    if (PathDirFromDelta(tx - *(short *)(a + 0x00), ty - *(short *)(a + 0x02)) < 0) return 0;
    me = (short)(unsigned char)a[0x15];
    PathBuildStack(armyIdx, true);
    if (sPathMoverCount == 0) return 0;
    type = GetTerrainType(tx, ty);
    if (type < 0 || type > 11) type = 7;
    if (sPathMode != PMODE_FLYING && kCost[type] < 1 && !RoadAt(tx, ty)) {
        PlaySound(SND_CHORD);                               /* FUN_10093928 */
        return 0;
    }
    /* the tile's owner nibble: the army there, else the city */
    for (i = 0; i < n; i++) {
        unsigned char *o = ARMY_REC(i);
        if (o[0x16] == 0xFF || *(short *)(o + 0) != tx || *(short *)(o + 2) != ty) continue;
        armyThere = true; owner = (short)(unsigned char)o[0x15]; break;
    }
    ci = PathCityIndexAt(tx, ty);
    if (!armyThere && ci >= 0) {
        short co = *(short *)(sCityData + ci * 0x20 + 4);
        owner = (co >= 0 && co < 8) ? co : 15;
    }
    if (owner > 15) owner = 15;
    if (*(short *)(gs + 0x11c) != 0 && owner != 15 && owner != me && me >= 0 && me < 8) {
        short st = *(gs + 0x1582 + me * 8 + owner) & 3;
        if (st == DIPLO_PEACE || (ci > 0 && st == DIPLO_HOSTILE)) {
            Str255 h, l1, l2, l3, l4;
            GetDATRawString(738, h);  GetDATRawString(739, l1); GetDATRawString(740, l2);
            GetDATRawString(741, l3); GetDATRawString(742, l4);
            if (!AskYesNo(h, l1, l2, l3, l4)) return 0;
            BreakTreaty(me, owner);                         /* then FUN_1002da54 again */
            PathBuildStack(armyIdx, true);
        }
    }
    if (PathMoversMinMP() <= 0) return 0;                   /* FUN_100219a8 + FUN_1005cc8c */
    c = kCost[type]; if (c < 2) c = 2;
    sAttackCost = c;
    if (owner == me) return 0;
    if (type != 10 && !armyThere) return 0;
    sUndoArmyIdx = armyIdx;
    sUndoFromX = *(short *)(a + 0x00);
    sUndoFromY = *(short *)(a + 0x02);
    sUndoMovePts = (short)(unsigned char)a[0x2e];
    sUndoFortify = (short)(unsigned char)a[0x2d];
    sPathTargetX = tx; sPathTargetY = ty;
    (void)PathAttack(armyIdx, tx, ty);                      /* FUN_1002d93c */
    return 1;
}

/* GetKeys test of one key code (PPC FUN_100efb00): 0x37 Command, 0x38 Shift,
 * 0x3A Option. */
static Boolean KeyCodeDown(short code)
{
    unsigned char km[16];
    GetKeys((void *)km);
    return (km[code >> 3] >> (code & 7)) & 1;
}

/* The map cursor type, PPC FUN_1003b4a4(x, y, 1); the view shows crsr
 * 1000 + type (FUN_10083144, set only when it changes):
 *   0 none, 2 move by sea (boat), 3 foreign/own city info, 4 Option (pan),
 *   5 select own stack, 6 move by land, 7 ruin, 8 attack, 9 advisor
 *   (Shift + 'mili'), 10 attack (breaks a treaty), 11 Command: set path. */
static short MapCursorType(short tx, short ty)
{
    unsigned char *gs, *md, *sel = NULL;
    short cur, terr, owner = 15, i, n, selTerr = 7, dist = 0, mode = PMODE_GROUND;
    Boolean shift, armyBit = false, isCity, embarked = false;
    if (*gGameState == 0 || *gMapTiles == 0) return 0;
    gs = (unsigned char *)*gGameState;
    md = (unsigned char *)*gMapTiles;
    cur = *(short *)(gs + 0x110);
    if (cur < 0 || cur > 7 || *(short *)(gs + 0xd0 + cur * 2) != 0) return 0;
    if (tx < 0 || tx >= sMapWidth || ty < 0 || ty >= sMapHeight) return 0;
    terr = gs[md[ty * 0xE0 + tx * 2] + TERRAIN_TYPE_OFS];
    isCity = (terr == 10);
    n = *(short *)(gs + 0x1602); if (n > MAX_ARMIES) n = MAX_ARMIES;
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        if (a[0x16] == 0xFF) continue;
        if (*(short *)(a + 0) == tx && *(short *)(a + 2) == ty) { armyBit = true; owner = (short)(unsigned char)a[0x15]; break; }
    }
    if (!armyBit && isCity) {
        short co = PathCityOwnerAt(tx, ty);
        owner = (co >= 0 && co < 8) ? co : 15;
    }
    if (owner > 15) owner = 15;
    if (sSelectedArmy >= 0 && sSelectedArmy < n) {
        sel = ARMY_REC(sSelectedArmy);
        if ((short)(unsigned char)sel[0x15] != cur) sel = NULL;
    }
    if (sel != NULL) {
        short sx = *(short *)(sel + 0), sy = *(short *)(sel + 2);
        long d2 = (long)(tx - sx) * (tx - sx) + (long)(ty - sy) * (ty - sy);
        short r = 0;
        while ((long)(r + 1) * (r + 1) <= d2) r++;         /* FUN_1000a884: (int)sqrt */
        dist = r;
        selTerr = gs[md[sy * 0xE0 + sx * 2] + TERRAIN_TYPE_OFS];
        embarked = (sel[0x2C] & ARMY_EMBARKED_BIT) != 0;
        PathBuildStack(sSelectedArmy, true);
        mode = sPathMode;
    }
    shift = KeyCodeDown(0x38);
    if (KeyCodeDown(0x3A)) return 4;
    if (*(short *)(gs + 0x124) != 0 && !FogGetBit(sFogExplored[cur], tx, ty)) return 0;
    if (sel != NULL) {
        if (dist < 2 && owner != cur && (isCity || armyBit)) {
            Boolean attack;
            if (embarked)
                attack = !(mode == PMODE_GROUND && selTerr == 3 && terr != 3 && terr != 2 && terr != 10 && terr != 1);
            else
                attack = !(mode == PMODE_GROUND && terr == 3 &&
                           !(selTerr == 3 || selTerr == 2 || selTerr == 10 || selTerr == 1));
            if (attack) {
                short t = 8;
                if (*(short *)(gs + 0x11c) != 0 && owner != 15) {
                    short shown = *(gs + 0x1582 + cur * 8 + owner) & 3;
                    if (isCity) t = (shown == DIPLO_WAR) ? 8 : 10;
                    else t = (shown == DIPLO_PEACE) ? 10 : 8;
                }
                return (shift && *(short *)(gs + 0x12c) != 0) ? 9 : t;
            }
        }
        if (KeyCodeDown(0x37))
            return ((isCity || armyBit) && owner != cur) ? 0 : 11;
    }
    if (isCity && owner != cur) return shift ? 0 : 3;
    if (sel == NULL || dist < 1) {
        if (!armyBit || owner != cur) {
            if (terr == 11) return shift ? 0 : 7;
            if (isCity) return shift ? 0 : 3;
            return 0;
        }
        return shift ? 0 : 5;
    }
    if (!shift) {
        if (mode == PMODE_FLYING) return 6;
        return (terr == 2 || terr == 3) ? 2 : 6;
    }
    if (!armyBit || owner != cur) {
        if (terr == 11) return 7;
        if (isCity) return 3;
        return 0;
    }
    return 5;
}

/* crsr 1000 + type, set only when it changes (FUN_10083144) */
static void SetCrsrId(short id)
{
    static CCrsrHandle cache[12];
    short k = id - 1000;
    if (id == sShownCrsrId) return;
    if (k < 0 || k >= 12) { InitCursor(); sShownCrsrId = -1; return; }
    if (cache[k] == NULL) cache[k] = GetCCursor(id);
    if (cache[k] == NULL) { InitCursor(); sShownCrsrId = -1; return; }
    SetCCursor(cache[k]);
    sShownCrsrId = id;
}

/* ===================================================================
 * RunStoredPath — run a stack's pending orders (+0x32, target +0x34/36):
 * path + execution.  Unreachable orders stay (FUN_10017cb4 beeps).
 * =================================================================== */
static short RunStoredPath(short armyIdx)
{
    unsigned char *gs, *a;
    short count, tx, ty, len;
    if (*gGameState == 0 || armyIdx < 0) return 0;
    gs = (unsigned char *)*gGameState;
    count = *(short *)(gs + 0x1602);
    if (count > MAX_ARMIES) count = MAX_ARMIES;
    if (armyIdx >= count) return 0;
    a = ARMY_REC(armyIdx);
    if (*(short *)(a + 0x32) == 0) return 0;
    tx = *(short *)(a + 0x34); ty = *(short *)(a + 0x36);
    if (*(short *)(a + 0x00) == tx && *(short *)(a + 0x02) == ty) { *(short *)(a + 0x32) = 0; return 0; }
    len = ComputeWavefrontPath(*(short *)(a + 0x00), *(short *)(a + 0x02), tx, ty, armyIdx);
    if (len < 0) {          /* FUN_10017cb4: no path - a human hears the beep, the orders stay */
        short o = (short)(unsigned char)a[0x15];
        if (o >= 0 && o < 8 && *(short *)(gs + 0xd0 + o * 2) == 0) PlaySound(SND_CHORD);
        return 0;
    }
    if (len == 0) return 0;
    return ExecutePathSteps(armyIdx);
}


/* Road byte bit 0x40 is bit 30 of the big-endian u32 at
 * gRoadData + y*112 + x (FUN_10034074 / FUN_10033e7c / FUN_10033c90). */
static Boolean RoadBit30Set(short x, short y)
{
    unsigned char *rd;
    if (*gRoadData == 0 || x < 0 || y < 0 || x >= 112 || y >= 156) return false;
    rd = (unsigned char *)*gRoadData;
    return (rd[y * 112 + x] & 0x40) != 0;
}
static void SetRoadBit30(short x, short y, Boolean on)
{
    unsigned char *rd;
    if (*gRoadData == 0 || x < 0 || y < 0 || x >= 112 || y >= 156) return;
    rd = (unsigned char *)*gRoadData + y * 112 + x;
    if (on) *rd = (unsigned char)(*rd | 0x40);
    else    *rd = (unsigned char)(*rd & (unsigned char)~0x40);
}
/* FUN_10034074: the side's Standard is planted when item record `player`
 * is on the ground and map bit 30 is set at its ground tile. */
static Boolean StandardPlanted(short player, short *x, short *y)
{
    unsigned char *ir;
    short gx, gy;
    if (player < 0 || player >= 8) return false;
    ir = GameItemRec((short)(player + 1));
    if (ir == NULL || ITEM_STATUS(ir) != ITEM_ST_GROUND) return false;
    gx = *(short *)(ir + 0x1A);
    gy = *(short *)(ir + 0x1C);
    if (!RoadBit30Set(gx, gy)) return false;
    if (x) *x = gx;
    if (y) *y = gy;
    return true;
}
/* Cities vectoring to the Standard (FUN_10047de8(-2)).  The remake keeps
 * that target in ext+0x3e (-1 = not vectoring, -2 = the Standard). */
static void ClearStandardVectors(short player)
{
    short ci, cc;
    if (*gExtState == 0 || player < 0 || player >= 8) return;
    cc = sCityCount;
    if (cc > 139) cc = 139;
    for (ci = 0; ci < cc; ci++) {
        unsigned char *c = sCityData + ci * 0x20;
        unsigned char *ec = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
        if (*(short *)(c + 0x04) != player) continue;
        if (*(short *)(ec + 0x3e) == -2) *(short *)(ec + 0x3e) = -1;
    }
}
/* FUN_10033e7c (menu 0x641): drop the current player's Standard on the
 * selected stack's tile and set map bit 30, unless that terrain is
 * 2/3/10/11 or the bit is already set. */
static void PlantStandard(void)
{
    unsigned char *gs, *army, *ir;
    short ids[GAME_ITEM_COUNT], n, i, x, y, me, tt;
    if (sSelectedArmy < 0 || *gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    army = ARMY_REC(sSelectedArmy);
    x = *(short *)(army + 0);
    y = *(short *)(army + 2);
    if (x < 0 || y < 0) return;
    tt = GetTerrainType(x, y);
    if (tt == 2 || tt == 3 || tt == 10 || tt == 11) return;
    if (RoadBit30Set(x, y)) return;
    me = *(short *)(gs + 0x110);
    n = HeroItems(sSelectedArmy, ids);
    for (i = 0; i < n; i++) {
        if ((short)(ids[i] - 1) != me) continue;
        ir = GameItemRec(ids[i]);
        if (ir == NULL) break;
        ITEM_STATUS(ir) = ITEM_ST_GROUND;
        ITEM_CARRIER(ir) = 0;
        *(short *)(ir + 0x1A) = x;
        *(short *)(ir + 0x1C) = y;
        SetRoadBit30(x, y, true);
        if (*gMainGameWindow != 0) {
            SetPort((WindowPtr)*gMainGameWindow);
            InvalRect(&((WindowPtr)*gMainGameWindow)->portRect);
        }
        break;
    }
}

/* ===================================================================
 * DropHeroItems — the army's hero dies: every carried item drops at the
 * death tile (status 1), or is lost (status 0, "sunk!") on water terrain
 * (68k CODE_042 FUN_00000930).  Clears the army's item slots.
 * =================================================================== */
static void DropHeroItemsAt(short armyIndex, short ax, short ay)
{
    unsigned char *gs;
    short si, ids[GAME_ITEM_COUNT], nIds;
    Boolean onWater = false;
    if (*gGameState == 0 || armyIndex < 0) return;
    gs = (unsigned char *)*gGameState;
    if (*gMapTiles != 0 &&
        ax >= 0 && ax < sMapWidth && ay >= 0 && ay < sMapHeight) {
        unsigned char *md = (unsigned char *)*gMapTiles;
        unsigned char ti = md[ay * 0xE0 + ax * 2];
        unsigned char tt = gs[ti + TERRAIN_TYPE_OFS];
        if (tt == 2) onWater = true;  /* 68k: terrain type 2 (Water) */
    }
    nIds = HeroItems(armyIndex, ids);
    for (si = 0; si < nIds; si++) {
        unsigned char *itemRec = GameItemRec(ids[si]);
        if (itemRec != NULL) {
            if (onWater) {
                ITEM_STATUS(itemRec) = ITEM_ST_NONE;    /* sunk */
                ITEM_CARRIER(itemRec) = -1;
                *(short *)(itemRec + 0x1A) = -1;
                *(short *)(itemRec + 0x1C) = -1;
            } else {
                ITEM_STATUS(itemRec) = ITEM_ST_GROUND;
                ITEM_CARRIER(itemRec) = -1;
                *(short *)(itemRec + 0x1A) = ax;
                *(short *)(itemRec + 0x1C) = ay;
            }
            /* FUN_1002e5c0: a dropped item whose index is the current
             * player (that side's Standard) clears every own city
             * vectoring to the Standard. */
            if ((short)(ids[si] - 1) == *(short *)(gs + 0x110))
                ClearStandardVectors(*(short *)(gs + 0x110));
        }
    }
}
static void DropHeroItems(short armyIndex)
{
    unsigned char *army;
    if (*gGameState == 0 || armyIndex < 0) return;
    army = ARMY_REC(armyIndex);
    DropHeroItemsAt(armyIndex, *(short *)(army + 0x00), *(short *)(army + 0x02));
}

/* PPC FUN_1003357c: n experience points to a hero (slot k of the record),
 * capped at 60. */
static void AddHeroXP(unsigned char *army, short k, short n)
{
    short xp;
    if (army == NULL || k < 0 || k > 3 || (unsigned char)army[0x16 + k] != 0x1C) return;
    xp = (short)(unsigned char)army[0x26 + k] + n;
    if (xp > 60) xp = 60;
    if (xp < 0) xp = 0;
    army[0x26 + k] = (unsigned char)xp;
}

/* ===================================================================
 * RemoveArmy — Remove an army from the army list by shifting later
 * entries down.  Adjusts sSelectedArmy if needed.
 * =================================================================== */
static void BattleOnRemove(short idx);
static void RemoveArmy(short armyIndex)
{
    unsigned char *gs;
    short armyCount, j;

    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyIndex < 0 || armyIndex >= armyCount) return;

    /* If this army contains a hero, drop items and clear hero record */
    {
        unsigned char *army = ARMY_REC(armyIndex);
        short owner = (short)(unsigned char)army[0x15];
        short u;
        for (u = 0; u < 4; u++) {
            if ((short)(unsigned char)army[0x16 + u] == 0x1C && owner < 8) {
                unsigned char *heroRec = gs + 0x1422 + owner * 0x2C;
                /* Drop items on hero death (68k CODE_042 FUN_00000930). */
                DropHeroItems(armyIndex);

                heroRec[0x00] = 0;  /* clear active flag */
                /* Record hero death event (68k CODE_054 event type 3) */
                { short turn = *(short *)(gs + 0x136);
                  char heroName[40];
                  short hn;
                  for (hn = 0; hn < 15 && army[0x04 + hn]; hn++)
                      heroName[hn] = army[0x04 + hn];
                  heroName[hn] = 0;
                  RecordEvent(turn, HIST_EVT_HERO_KILL, owner, heroName);
                  /* free the hero's name slot (gs+0x544 flags, names at gs+0x224) */
                  { short hs;
                    for (hs = 0; hs < 40; hs++) {
                        unsigned char *nm = gs + 0x224 + hs * 20;
                        short q = 0;
                        if (*(short *)(gs + 0x544 + hs * 2) == 0) continue;
                        while (q < 15 && nm[q] && nm[q] == (unsigned char)heroName[q]) q++;
                        if (nm[q] == 0 && heroName[q] == 0) {
                            *(short *)(gs + 0x544 + hs * 2) = 0;
                            break;
                        }
                    }
                  }
                }
                break;
            }
        }
    }

    /* the computer player's per-record orders follow the records */
    AIOrdOnRemove(armyIndex, armyCount);
    /* so do the quest records' heroes and the last battle's attackers */
    QuestRecRemoved(armyIndex);
    /* so do the entries of the battle just fought (the medal reads them) */
    BattleOnRemove(armyIndex);

    /* Shift all armies after this one down by one slot */
    /* visited, Move All skip, and defend state follow the records.
     * ext+0x56 did not, so a removed record's state stuck to the next index. */
    for (j = armyIndex; j < MAX_ARMIES - 1; j++) {
        sArmyVisited[j] = sArmyVisited[j + 1];
        sArmySkip[j] = sArmySkip[j + 1];
        sArmyState[j] = sArmyState[j + 1];
    }
    sArmyVisited[MAX_ARMIES - 1] = 0;
    sArmySkip[MAX_ARMIES - 1] = 0;
    sArmyState[MAX_ARMIES - 1] = 0;
    for (j = armyIndex; j < armyCount - 1; j++) {
        unsigned char *dst = ARMY_REC(j);
        unsigned char *src = ARMY_REC((j + 1));
        short k;
        for (k = 0; k < 0x42; k++)
            dst[k] = src[k];
    }
    *(short *)(gs + 0x1602) = armyCount - 1;
    /* the temple blessing bits (ext+0x3500, a short per record) follow */
    if (*gExtState != 0 && armyCount <= MAX_ARMIES) {
        unsigned char *ext = (unsigned char *)*gExtState;
        for (j = armyIndex; j < armyCount - 1; j++)
            *(unsigned short *)(ext + 0x3500 + j * 2) = *(unsigned short *)(ext + 0x3500 + (j + 1) * 2);
        *(unsigned short *)(ext + 0x3500 + (armyCount - 1) * 2) = 0;
    }

    /* Update hero instance records: decrement army indices above removed slot */
    {
        short p;
        for (p = 0; p < 8; p++) {
            unsigned char *heroRec = gs + 0x1422 + p * 0x2C;
            if (heroRec[0x00] != 0) {
                short heroArmyIdx = *(short *)(heroRec + 0x04);
                if (heroArmyIdx > armyIndex)
                    *(short *)(heroRec + 0x04) = heroArmyIdx - 1;
            }
        }
    }

    /* Update item carrier indices: items referencing armies above removed slot
     * need their carrier index decremented (68k does this in FUN_00000e98). */
    {
        short ii;
        for (ii = 0; ii < 22; ii++) {
            unsigned char *itemRec = gs + 0xD12 + ii * 0x1E;
            if (ITEM_STATUS(itemRec) == ITEM_ST_CARRIED) {  /* status: carried by army */
                short carrierIdx = *(short *)(itemRec + 0x18);
                if (carrierIdx > armyIndex)
                    *(short *)(itemRec + 0x18) = carrierIdx - 1;
            }
        }
    }

    /* Fix selected army reference */
    if (sSelectedArmy == armyIndex) {
        sSelectedArmy = -1; sPreviewPathLen = 0; sPreviewGridValid = false; sInfoStackBackupSaved = false; { GrafPtr _sp; GetPort(&_sp); if (gInfoWindow && *gInfoWindow) { SetPort((WindowPtr)*gInfoWindow); InvalRect(&((WindowPtr)*gInfoWindow)->portRect); } SetPort(_sp); }
    } else if (sSelectedArmy > armyIndex)
        sSelectedArmy--;

    /* Fix stack army indices (shift down those above removed index) */
    {
        short si2;
        for (si2 = 0; si2 < sStackCount; si2++) {
            if (sStackArmyIdx[si2] == armyIndex) {
                /* This stack entry was removed; invalidate it */
                sStackArmyIdx[si2] = -1;
            } else if (sStackArmyIdx[si2] > armyIndex) {
                sStackArmyIdx[si2]--;
            }
        }
    }
}


/* ===================================================================
 * Battle resolution — the original's one battle per attack (PPC 1.0.7
 * FUN_100ac0cc setup, FUN_1002d654 rounds, FUN_1002e7d4 aftermath;
 * 68k CODE_104).
 *
 * Attackers: every unit of the moving stack's tile (at most 8, across
 * the remake's army records).  Defenders: every enemy unit on the target
 * tile, or in all four tiles of a city.  Each side is sorted once by fight
 * order, every unit has combat HP 1 (dies when it goes below 0), and the
 * first live unit of each side fights until one dies.
 *
 * Battle presentation (ShowBattle) replays the kills recorded here:
 * sBattleKill[k] = 0 a defending unit died, 1 an attacking unit died,
 * sBattleKillT[k] = its unit type, in order.
 * =================================================================== */
static Boolean       sBattleQuiet = false;
static unsigned char sBattleKill[128];
static unsigned char sBattleKillT[128];   /* the unit type that died */
static short         sBattleKillN = 0;

#define BATTLE_ATT_MAX 8
#define BATTLE_DEF_MAX 64

typedef struct {
    short   rec;        /* army record index */
    short   slot;       /* unit slot 0..3 */
    short   type;       /* unit type (0x1C hero) */
    short   str;        /* the unit's strength byte */
    short   order;      /* fight order (lower fights first) */
    short   value;      /* battle value (1..15) */
    short   hp;         /* combat HP: 1, dead when < 0 */
    Boolean embarked;   /* carried on water: value 4, no bonuses */
} BattleUnit;

typedef struct {
    short mOwner, defOwner;         /* attacking player; defender (0x0F neutral) */
    short mx, my;                   /* battle tile */
    short cityIdx, cx, cy;          /* city attacked (-1 none) */
    short terr;                     /* terrain type of the battle tile */
    short cls;                      /* terrain class 0 site, 1 open, 2 forest, 3 hills */
    short tileOwner;                /* the battle tile's map owner nibble (DAT_41820040), BattleValues */
    short nAtt, nDef;
    BattleUnit att[BATTLE_ATT_MAX];
    BattleUnit def[BATTLE_DEF_MAX];
} Battle;

static Battle sBattle;      /* the battle being fought */
static void QuestNoteBattle(const Battle *b);   /* the quest module, below */
static Battle sBattleSim;   /* the Military Advisor's rehearsals */

/* a record left the table: sBattle's entries follow (-1: gone) */
static void BattleOnRemove(short idx)
{
    short j;
    for (j = 0; j < sBattle.nAtt + sBattle.nDef; j++) {
        BattleUnit *u = (j < sBattle.nAtt) ? sBattle.att + j : sBattle.def + (j - sBattle.nAtt);
        if (u->rec == idx) u->rec = -1;
        else if (u->rec > idx) u->rec--;
    }
}

/* FUN_100abd8c / 68k FUN_00001592: tower bit (map byte+1 & 0x20) -> 0;
 * forest 4 -> 2; hills 5 / mountains 6 -> 3; city 10 / ruin 11 -> 0; else 1 */
static short BattleTerrainClass(short x, short y, short *terrOut, Boolean *towerOut)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char *md;
    short terr = 7;
    Boolean tower = false;
    if (*gMapTiles != 0 && x >= 0 && x < sMapWidth && y >= 0 && y < sMapHeight) {
        md = (unsigned char *)*gMapTiles;
        terr = gs[md[y * 0xE0 + x * 2] + TERRAIN_TYPE_OFS];
        tower = (md[y * 0xE0 + x * 2 + 1] & 0x20) != 0;
    }
    if (terrOut) *terrOut = terr;
    if (towerOut) *towerOut = tower;
    if (tower) return 0;
    switch (terr) {
        case 4:             return 2;
        case 5: case 6:     return 3;
        case 10: case 11:   return 0;
        default:            return 1;
    }
}

static Boolean UnitTypeFlies(short t)
{
    if (!sUnitTypesLoaded || t < 0 || t >= sUnitTypeCount) return false;
    return sUnitTypeTable[t * UNIT_TYPE_ENTRY + UTE_STAT_FLYING] >= 1;
}

static Boolean UnitTypeNaval(short t)
{
    if (!sUnitTypesLoaded || t < 0 || t >= sUnitTypeCount) return false;
    return sUnitTypeTable[t * UNIT_TYPE_ENTRY + UTE_STAT_NAVAL] >= 1;
}

/* add the live units of record rec to a side (the moving record first) */
static void BattleAddRecord(BattleUnit *side, short *n, short max, short rec, Boolean onWater)
{
    unsigned char *a = ARMY_REC(rec);
    Boolean naval = ArmyIsNaval(rec);
    short k;
    for (k = 0; k < 4 && *n < max; k++) {
        short t = (short)(unsigned char)a[0x16 + k];
        BattleUnit *u;
        if (t == 0xFF || (unsigned char)a[0x1e + k] == 0) continue;
        u = side + (*n)++;
        u->rec = rec; u->slot = k; u->type = t;
        u->str = (short)(unsigned char)a[0x1e + k];
        u->order = 0; u->value = 0; u->hp = 1;
        /* The original's "embarked" unit flag (status 0x1000, PPC
         * FUN_1005d598 / FUN_1005d948).  It fights at value 4 with no
         * bonuses only when the battle tile is water or shore (BattleValues);
         * the flyer test and the medal test read the bit alone.  A ship's
         * record is never embarked (the per-unit bit of the original is never
         * set on a naval type). */
        u->embarked = ((a[0x2C] & ARMY_EMBARKED_BIT) != 0 && !UnitTypeNaval(t));
        (void)onWater; (void)naval;
    }
}

/* Gather both sides.  movingIdx: the moving record (-1: any of mOwner's
 * records on the tile); cityIdx >= 0: the whole city (cx,cy) defends. */
static void BattleGather(Battle *b, short movingIdx, short mOwner, short mx, short my,
                         short cityIdx, short cx, short cy, short defOwner)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short n = *(short *)(gs + 0x1602), i;
    Boolean onWater;
    if (n > MAX_ARMIES) n = MAX_ARMIES;
    b->mOwner = mOwner; b->defOwner = defOwner;
    b->mx = mx; b->my = my;
    b->cityIdx = cityIdx; b->cx = cx; b->cy = cy;
    b->cls = BattleTerrainClass(mx, my, &b->terr, NULL);
    onWater = (b->terr == 2 || b->terr == 3);
    b->nAtt = b->nDef = 0;
    if (movingIdx >= 0 && movingIdx < n)
        BattleAddRecord(b->att, &b->nAtt, BATTLE_ATT_MAX, movingIdx, onWater);
    /* PPC FUN_100ac0cc / FUN_10055c64: the attackers are the SELECTED group -
     * the moving record and the records on its tile that carry the same
     * non-zero group tag (a[0x11]) - never every own army on the tile (a
     * lone hero fought beside a Wizard that merely shared its city). */
    for (i = 0; i < n; i++) {
        unsigned char *a = ARMY_REC(i);
        if (i == movingIdx || (short)(unsigned char)a[0x15] != mOwner) continue;
        if (*(short *)(a + 0x00) != mx || *(short *)(a + 0x02) != my) continue;
        if (movingIdx >= 0 && movingIdx < n) {
            unsigned char *mv = ARMY_REC(movingIdx);
            if (mv[0x11] == 0 || a[0x11] != mv[0x11]) continue;
        }
        BattleAddRecord(b->att, &b->nAtt, BATTLE_ATT_MAX, i, onWater);
    }
    /* the original walks the unit table from the end */
    for (i = n - 1; i >= 0; i--) {
        unsigned char *a = ARMY_REC(i);
        short ox = *(short *)(a + 0x00), oy = *(short *)(a + 0x02);
        if ((short)(unsigned char)a[0x15] == mOwner) continue;
        if (!((ox == mx && oy == my) ||
              (cityIdx >= 0 && ox >= cx && ox <= cx + 1 && oy >= cy && oy <= cy + 1)))
            continue;
        BattleAddRecord(b->def, &b->nDef, BATTLE_DEF_MAX, i, onWater);
    }
}

/* fight order, the flyer's +80, the stable sort of a side */
static void BattleOrderSide(BattleUnit *side, short n, short table, Boolean waterish)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    Boolean hasHero = false;
    short i, j;
    for (i = 0; i < n; i++) {
        side[i].order = (side[i].type < 29) ? (short)(unsigned char)gs[0x60C + table * 0x1D + side[i].type] : 0;
        if (side[i].type == 0x1C) hasHero = true;
    }
    /* on water / shore / mountains a side with a hero sends its first
     * (unembarked) flyer last */
    if (waterish && hasHero) {
        for (i = 0; i < n; i++) {
            if (!side[i].embarked && UnitTypeFlies(side[i].type)) { side[i].order += 80; break; }
        }
    }
    for (i = 1; i < n; i++) {
        for (j = i; j > 0 && side[j].order < side[j - 1].order; j--) {
            BattleUnit t = side[j]; side[j] = side[j - 1]; side[j - 1] = t;
        }
    }
}

/* FUN_100ac0cc: the battle values of both sides */
static void BattleValues(Battle *b)
{
    static const short kLead[10] = {0, 0, 0, 0, 1, 1, 1, 2, 2, 3};
    unsigned char *gs = (unsigned char *)*gGameState;
    short attTable = (b->mOwner >= 0 && b->mOwner < 8) ? b->mOwner : 8;
    short defTable;
    /* gs+0x112: the scenario's maximum side bonus (5 in every SCN), no
     * fallback (PPC_0004.c:12788/12801) */
    short cls = b->cls, maxBonus = *(short *)(gs + 0x112);
    Boolean waterish = (b->terr == 2 || b->terr == 3 || b->terr == 6);
    short attHeroStr = 0, defHeroStr = 0, attCmd = 0, defCmd = 0;
    short attStackTerr = 0, defStackTerr = 0, attPen = 0, defPen = 0;
    Boolean attSp1 = false, attSp2 = false, attSp3 = false, attSp4 = false;
    Boolean defSp1 = false, defSp2 = false, defSp3 = false, defSp4 = false;
    short attLead, defLead, attBonus, defBonus, site = 0, i;

    /* the defenders' fight-order table and the neutral test read the battle
     * tile's map owner nibble (DAT_41820040; 8 for >= 8), not a record */
    b->tileOwner = 0x0F;
    if (*gMapTiles != 0 && b->mx >= 0 && b->mx < sMapWidth && b->my >= 0 && b->my < sMapHeight)
        b->tileOwner = (short)(((unsigned char *)*gMapTiles)[b->my * 0xE0 + b->mx * 2 + 1] & 0x0F);
    defTable = (b->tileOwner < 8) ? b->tileOwner : 8;
    BattleOrderSide(b->att, b->nAtt, attTable, waterish);
    BattleOrderSide(b->def, b->nDef, defTable, waterish);

    for (i = 0; i < b->nAtt; i++) {
        BattleUnit *u = b->att + i;
        short sp = UnitStatLE(u->type, 15), st = UnitStatLE(u->type, 9 + cls), pen = UnitStatLE(u->type, 14);
        if (u->type == 0x1C) {
            short bat, cmd, gold, hs; Boolean fly, dbl;
            GetHeroItemBonus(u->rec, &bat, &cmd, &gold, &fly, &dbl);
            hs = u->str + bat;
            if (hs > 9) hs = 9;
            if (hs > attHeroStr) attHeroStr = hs;
            attCmd += cmd;
        }
        if (sp == 1) attSp1 = true;
        if (sp == 2) attSp2 = true;
        if (sp == 3) attSp3 = true;
        if (sp == 4) attSp4 = true;
        if (pen != 0 && pen < attPen) attPen = pen;
        if (st != 0 && st > attStackTerr) attStackTerr = st;
    }
    for (i = 0; i < b->nDef; i++) {
        BattleUnit *u = b->def + i;
        short sp = UnitStatLE(u->type, 15), st = UnitStatLE(u->type, 9 + cls), pen = UnitStatLE(u->type, 14);
        if (u->type == 0x1C) {
            short bat, cmd, gold, hs; Boolean fly, dbl;
            GetHeroItemBonus(u->rec, &bat, &cmd, &gold, &fly, &dbl);
            hs = u->str + bat;
            if (hs > 9) hs = 9;
            if (hs > defHeroStr) defHeroStr = hs;
            defCmd += cmd;
        }
        if (sp == 1) defSp1 = true;
        if (sp == 2) defSp2 = true;
        if (sp == 3) defSp3 = true;
        if (sp == 4) defSp4 = true;
        if (pen != 0 && pen < defPen) defPen = pen;
        if (st != 0 && st > defStackTerr) defStackTerr = st;
    }
    attLead = kLead[attHeroStr] + attCmd;
    defLead = kLead[defHeroStr] + defCmd;

    /* the defender's site bonus: a tower 1, a ruin 2, a city its defence;
     * special 4 is +1 in the open; the attacker's special 1 cancels it;
     * neutrals get half */
    if (!attSp1 && (cls == 0 || defSp4)) {
        Boolean tower = false;
        unsigned char *md = (*gMapTiles != 0) ? (unsigned char *)*gMapTiles : NULL;
        short tx = (b->cityIdx >= 0) ? b->cx : b->mx, ty = (b->cityIdx >= 0) ? b->cy : b->my;
        if (md && tx >= 0 && tx < sMapWidth && ty >= 0 && ty < sMapHeight)
            tower = (md[ty * 0xE0 + tx * 2 + 1] & 0x20) != 0;
        site = defSp4 ? 1 : 0;
        if (tower) site = 1;
        else if (b->terr == 11) site = 2;
        else if (b->terr == 10) {
            if (b->cityIdx >= 0) site = *(short *)(sCityData + b->cityIdx * 0x20 + 0x06);
            else {
                short ci, cc = sCityCount > 139 ? 139 : sCityCount;
                for (ci = 0; ci < cc; ci++) {
                    unsigned char *c = sCityData + ci * 0x20;
                    short x0 = *(short *)(c + 0x00), y0 = *(short *)(c + 0x02);
                    if (c[0x17] >= 2) continue;
                    if (b->mx >= x0 && b->mx <= x0 + 1 && b->my >= y0 && b->my <= y0 + 1) {
                        site = *(short *)(c + 0x06); break;
                    }
                }
            }
        }
        if (b->tileOwner == 0x0F) site >>= 1;
    }

    /* side bonuses: capped at the scenario maximum, then the enemy penalty */
    attBonus = (defSp2 ? 0 : attLead) + (defSp3 ? 0 : attStackTerr) + ((attSp4 && !defSp1) ? 1 : 0);
    if (attBonus > maxBonus) attBonus = maxBonus;
    attBonus += defPen;
    defBonus = (attSp2 ? 0 : defLead) + (attSp3 ? 0 : defStackTerr) + site;
    if (defBonus > maxBonus) defBonus = maxBonus;
    defBonus += attPen;

    for (i = 0; i < b->nAtt + b->nDef; i++) {
        BattleUnit *u = (i < b->nAtt) ? b->att + i : b->def + (i - b->nAtt);
        short v;
        /* embarked: value 4 only on a water or shore battle tile
         * (PPC_0004.c:12838-12890); an embarked stack attacking a coastal
         * city or a land stack fights at full value */
        if (u->embarked && (b->terr == 2 || b->terr == 3)) { u->value = 4; continue; }
        v = u->str + ((i < b->nAtt) ? attBonus : defBonus);
        if (u->type == 0x1C) {
            short bat, cmd, gold; Boolean fly, dbl;
            GetHeroItemBonus(u->rec, &bat, &cmd, &gold, &fly, &dbl);
            v += bat;
        }
        v += UnitStatLE(u->type, 5 + cls);
        if (v > 15) v = 15;
        u->value = v;
    }
}

/* FUN_1002d654: the rounds.  Returns true when the attacker won.  With
 * record, the kills go to sBattleKill/sBattleKillT. */
static Boolean BattleRounds(Battle *b, Boolean record)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short N = sOptIntenseCombat ? 24 : 20;   /* Intense Combat: a 24-sided die */
    Boolean tutorial = *(short *)(gs + 0x12e) != 0;
    Boolean humanAtt = (b->mOwner >= 0 && b->mOwner < 8 && *(short *)(gs + 0xd0 + b->mOwner * 2) == 0);
    short ai = 0, di = 0;

    /* an empty side: the attacker wins (PPC_0001.c:22785-22788) */
    if (b->nAtt == 0 || b->nDef == 0) return true;
    for (;;) {
        BattleUnit *a = b->att + ai, *d = b->def + di;
        short av = a->value < 1 ? 1 : a->value, dv = d->value < 1 ? 1 : d->value;
        short cnt = 0;
        Boolean died = false;
        while (!died) {
            /* the first die is the defender's, the second the attacker's */
            short rd = Dice(1, N, 0);
            short ra = Dice(1, N, 0);
            Boolean attFail, defFail;
            /* the emergency escape: the attacker takes the hit */
            if (cnt > 10000) { rd = 0; ra = 100; }
            defFail = dv < rd;
            attFail = av < ra;
            if (defFail != attFail) {
                if (defFail) {
                    if (--d->hp < 0) {
                        if (record && sBattleKillN < 128) {
                            sBattleKillT[sBattleKillN] = (unsigned char)((d->type == 0x1C && IsHeroFemale(d->rec)) ? 0x1D : d->type);
                            sBattleKill[sBattleKillN++] = 0;
                        }
                        di++; died = true;
                    }
                } else if (!(tutorial && a->type == 0x1C && humanAtt && b->tileOwner == 0x0F)) {
                    /* (a human's hero is spared against neutrals in the
                     * tutorial - for good: past 10000 rolls the forced roll
                     * does nothing, the 16-bit count wraps and the dice
                     * resume until the defender falls) */
                    if (--a->hp < 0) {
                        if (record && sBattleKillN < 128) {
                            sBattleKillT[sBattleKillN] = (unsigned char)((a->type == 0x1C && IsHeroFemale(a->rec)) ? 0x1D : a->type);
                            sBattleKill[sBattleKillN++] = 1;
                        }
                        ai++; died = true;
                    }
                }
            }
            cnt = (short)(cnt == 32767 ? -32768 : cnt + 1);   /* the original's short counter */
        }
        if (di >= b->nDef || ai >= b->nAtt) return di >= b->nDef;
    }
}

/* PPC FUN_1002e5c0(unit, x, y) as FUN_1002e7d4 calls it for every hero
 * that dies in battle, attacker or defender, whether or not its record
 * survives: the hero-killed history event, the name slot (gs+0x544) freed,
 * the items dropped at the BATTLE tile (lost when its terrain is 2), the
 * player's hero record cleared.  DropHeroItemsAt clears vectoring to
 * the planted standard when the dropped item is the current player's
 * standard (FUN_10047de8(-2)). */
static void BattleHeroFell(short rec, short x, short y, Boolean inBattle)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char *army = ARMY_REC(rec);
    short owner = (short)(unsigned char)army[0x15];
    short turn = *(short *)(gs + 0x136), hn, hs;
    char heroName[40];
    for (hn = 0; hn < 15 && army[0x04 + hn]; hn++) heroName[hn] = army[0x04 + hn];
    heroName[hn] = 0;
    /* FUN_1002e7d4 logs the event before FUN_1002e5c0; a disband
     * (FUN_1000fc38) does not */
    if (inBattle) RecordEvent(turn, HIST_EVT_HERO_KILL, owner, heroName);
    for (hs = 0; hs < 40; hs++) {
        unsigned char *nm = gs + 0x224 + hs * 20;
        short q = 0;
        if (*(short *)(gs + 0x544 + hs * 2) == 0) continue;
        while (q < 15 && nm[q] && nm[q] == (unsigned char)heroName[q]) q++;
        if (nm[q] == 0 && heroName[q] == 0) { *(short *)(gs + 0x544 + hs * 2) = 0; break; }
    }
    DropHeroItemsAt(rec, x, y);
    if (owner >= 0 && owner < 8) (gs + 0x1422 + owner * 0x2C)[0x00] = 0;
}

/* the attackers' types in sorted order (0x40850028), written by every real
 * battle (FUN_100ac0cc) and never cleared: FUN_1002e7d4 reads it for the
 * DEFENDERS' experience */
static unsigned char sBattleAttType[8];

/* FUN_1002e7d4 (the units' part): the dead leave their records (a dead
 * hero first drops its items at the battle tile), surviving attacking
 * heroes gain experience (+2 attacking a city, else +1; cap 60), a
 * surviving defender at sorted index i gains 1 only when the ATTACKER at
 * index i is a hero (the original's index bug), emptied records go.
 * *movingIdx follows the moving record. */
static void BattleApply(Battle *b, short *movingIdx)
{
    unsigned char *gs = (unsigned char *)*gGameState;
    short touched[BATTLE_ATT_MAX + BATTLE_DEF_MAX], nTouched = 0, i, j, k;
    Boolean cityBattle = (b->cityIdx >= 0 || b->terr == 10);

    for (i = 0; i < b->nAtt && i < 8; i++) sBattleAttType[i] = (unsigned char)b->att[i].type;
    for (i = 0; i < b->nAtt + b->nDef; i++) {
        Boolean attacker = i < b->nAtt;
        BattleUnit *u = attacker ? b->att + i : b->def + (i - b->nAtt);
        unsigned char *a = ARMY_REC(u->rec);
        for (j = 0; j < nTouched && touched[j] != u->rec; j++) ;
        if (j == nTouched) touched[nTouched++] = u->rec;
        if (u->hp < 0) {
            if (u->type == 0x1C) BattleHeroFell(u->rec, b->mx, b->my, true);
            k = u->slot;
            a[0x16 + k] = 0xFF; a[0x1a + k] = 0; a[0x1e + k] = 0; a[0x22 + k] = 0; a[0x26 + k] = 0;
            SetMedals(a, k, 0);
        } else if (u->type == 0x1C) {
            short di = i - b->nAtt;
            if (attacker)
                AddHeroXP(a, u->slot, cityBattle ? 2 : 1);
            else if (di < 8 && sBattleAttType[di] == 0x1C)
                AddHeroXP(a, u->slot, 1);
        }
    }
    /* compact the touched records */
    for (i = 0; i < nTouched; i++) {
        unsigned char *a = ARMY_REC(touched[i]);
        short put = 0, live = 0;
        for (k = 0; k < 4; k++) if (a[0x16 + k] != 0xFF) live++;
        if (live == 0) continue;
        for (k = 0; k < 4; k++) {
            if (a[0x16 + k] == 0xFF) continue;
            if (put != k) {
                a[0x16 + put] = a[0x16 + k]; a[0x1a + put] = a[0x1a + k]; a[0x1e + put] = a[0x1e + k];
                a[0x22 + put] = a[0x22 + k]; a[0x26 + put] = a[0x26 + k];
                SetMedals(a, put, GetMedals(a, k));
                a[0x16 + k] = 0xFF; a[0x1a + k] = 0; a[0x1e + k] = 0; a[0x22 + k] = 0; a[0x26 + k] = 0;
                SetMedals(a, k, 0);
                /* the survivors' battle entries follow their slots (the medal
                 * after the battle picks among them) */
                for (j = 0; j < b->nAtt + b->nDef; j++) {
                    BattleUnit *u = (j < b->nAtt) ? b->att + j : b->def + (j - b->nAtt);
                    if (u->rec == touched[i] && u->slot == k && u->hp >= 0) u->slot = put;
                }
            }
            put++;
        }
        a[0x14] = (sUnitTypesLoaded && a[0x16] < sUnitTypeCount) ? sUnitTypeTable[a[0x16] * UNIT_TYPE_ENTRY] : a[0x16];
        RecalcArmyStrength(a);
    }
    /* remove the emptied records, highest index first */
    for (i = 1; i < nTouched; i++)
        for (j = i; j > 0 && touched[j] > touched[j - 1]; j--) { short t = touched[j]; touched[j] = touched[j - 1]; touched[j - 1] = t; }
    for (i = 0; i < nTouched; i++) {
        unsigned char *a = ARMY_REC(touched[i]);
        for (k = 0; k < 4 && a[0x16 + k] == 0xFF; k++) ;
        if (k < 4) continue;
        RemoveArmy(touched[i]);
        if (movingIdx) {
            if (*movingIdx == touched[i]) *movingIdx = -1;
            else if (*movingIdx > touched[i]) (*movingIdx)--;
        }
    }
}

/* FUN_10030e0c: the Military Advisor rehearses the battle 19 times and
 * reports wins/2 (0..9) */
static short BattleAdvisorIndex(const Battle *b)
{
    short wins = 0, i;
    for (i = 0; i < 19; i++) {
        sBattleSim = *b;
        if (BattleRounds(&sBattleSim, false)) wins++;
    }
    return wins / 2;
}


/* ===================================================================
 * ShowCityCaptureNotification — Brief modal showing city capture
 * =================================================================== */
static void ShowCityCaptureNotification(short capturer, short prevOwner,
                                         short cityX, short cityY)
{
    WindowPtr notWin;
    GWorldPtr offGW;
    Rect winRect, gwRect;
    EventRecord evt;
    CGrafPtr savePort;
    PicHandle bgPict;
    short winW = 300, winH = 100;

    PlaySound(SND_CHORD);
    GDHandle saveGD;
    unsigned long ticks;
    unsigned char *gs = (unsigned char *)*gGameState;

    /* Try to load capture scene PICT */
    bgPict = GetPicture(3800);
    if (bgPict) {
        Rect pf = (**bgPict).picFrame;
        winW = pf.right - pf.left;
        winH = pf.bottom - pf.top;
    }

    SetRect(&winRect, 0, 0, winW, winH);
    OffsetRect(&winRect,
        (qd.screenBits.bounds.right - winW) / 2,
        (qd.screenBits.bounds.bottom - winH) / 2);
    notWin = NewCWindow(NULL, &winRect, "\pCity Captured!", true,
                        dBoxProc, (WindowPtr)-1, false, 0);
    SetRect(&gwRect, 0, 0, winW, winH);
    NewGWorld(&offGW, 0, &gwRect, NULL, NULL, 0);
    if (!notWin || !offGW) {
        if (offGW) DisposeGWorld(offGW);
        if (notWin) DisposeWindow(notWin);
        return;
    }

    GetGWorld(&savePort, &saveGD);
    SetGWorld(offGW, NULL);
    LockPixels(GetGWorldPixMap(offGW));

    /* Background: capture PICT or marble fallback, with capturer's color border */
    {
        RGBColor border = sPlayerColors[capturer < 8 ? capturer + 1 : 8];
        if (bgPict) DrawPicture(bgPict, &gwRect);
        else DrawMarbleBackground(&gwRect);
        RGBForeColor(&border);
        PenSize(3, 3);
        FrameRect(&gwRect);
        PenNormal();
    }

    /* Title */
    {
        RGBColor white = {0xFFFF, 0xFFFF, 0xFFFF};
        RGBColor capColor = sPlayerColors[capturer < 8 ? capturer + 1 : 8];
        char factionName[24];
        short len;
        Str255 numStr;

        RGBForeColor(&white);
        TextSize(12);
        TextFace(bold);
        MoveTo(20, 25);
        DrawString(GetCachedString(STR_CITY_CAPTURE, 2, "\pCity Captured!"));
        TextFace(0);
        TextSize(10);

        /* Show capturer name */
        BlockMoveData(gs + capturer * 20, factionName, 20);
        factionName[19] = 0;
        for (len = 0; len < 19 && factionName[len]; len++) {}
        MoveTo(20, 50);
        RGBForeColor(&capColor);
        {
            Str255 pstr;
            pstr[0] = (unsigned char)len;
            BlockMoveData(factionName, &pstr[1], len);
            DrawString(pstr);
        }

        RGBForeColor(&white);
        DrawString(GetCachedString(STR_CITY_CAPTURE, 3, "\p captures city at ("));
        NumToString((long)cityX, numStr);
        DrawString(numStr);
        DrawString("\p, ");
        NumToString((long)cityY, numStr);
        DrawString(numStr);
        DrawString("\p)");

        /* Show previous owner */
        if (prevOwner >= 0 && prevOwner < 8) {
            RGBColor prevColor = sPlayerColors[prevOwner + 1];
            char prevName[24];
            short plen;
            BlockMoveData(gs + prevOwner * 20, prevName, 20);
            prevName[19] = 0;
            for (plen = 0; plen < 19 && prevName[plen]; plen++) {}

            MoveTo(20, 70);
            RGBForeColor(&white);
            DrawString(GetCachedString(STR_MISC, 16, "\pTaken from "));
            RGBForeColor(&prevColor);
            {
                Str255 pstr2;
                pstr2[0] = (unsigned char)plen;
                BlockMoveData(prevName, &pstr2[1], plen);
                DrawString(pstr2);
            }
        }

        RGBForeColor(&white);
        TextSize(9);
        MoveTo(200, 90);
        DrawString(GetCachedString(STR_MISC, 17, "\pClick to continue"));
    }

    UnlockPixels(GetGWorldPixMap(offGW));
    SetGWorld(savePort, saveGD);

    /* Blit to window */
    {
        PixMapHandle srcPM = GetGWorldPixMap(offGW);
        SetPort(notWin);
        LockPixels(srcPM);
        CopyBits((BitMap *)*srcPM,
                 &((GrafPtr)notWin)->portBits,
                 &gwRect, &gwRect, srcCopy, NULL);
        UnlockPixels(srcPM);
    }

    /* Wait for click or 3 seconds */
    ticks = TickCount() + SpeedTicks(180);
    while (TickCount() < ticks) {
        if (WaitNextEvent(mDownMask | keyDownMask, &evt, 5, NULL))
            break;
    }

    DisposeGWorld(offGW);
    DisposeWindow(notWin);
}


/* ===================================================================
 * ShowEliminationNotification — Announce a player has been eliminated
 * =================================================================== */
static void ShowEliminationNotification(short eliminatedPlayer, short byPlayer)
{
    /* View 1020 notice (PPC): "%s, thy empire has fallen!" / "thou art
     * vanquished!" / "thou art no more!" / "thy cities are as dust!"
     * (DAT 207-210, picked at random), shown at the turn change. */
    unsigned char *gs = (unsigned char *)*gGameState;
    unsigned char *fn = gs + eliminatedPlayer * FACTION_NAME_LEN;
    Str255 nm, fmt, line;
    short len = 0;
    WindowPtr win;
    Rect v;
    EventRecord e;
    (void)byPlayer;
    while (len < 14 && fn[len]) len++;
    nm[0] = (unsigned char)len; BlockMoveData(fn, nm + 1, len);
    /* DAT group 0xC has five lines (206-210, "for thee the war is over!"
     * included), picked uniformly (FUN_1005f678(0xc, -1)) */
    GetDATRawString(206 + Dice(1, 5, -1), fmt);
    FormatHeroLine(fmt, nm, 0, line);
    win = NewMacAppWindow(392, 94);
    if (win == NULL) return;
    DrawPictAt(1001, 7, 7);
    DrawPictAt(1004, 0, 0); DrawPictAt(1005, 0, 7); DrawPictAt(1006, 0, 87); DrawPictAt(1009, 385, 0);
    SetRect(&v, 19, 35, 19 + 352, 35 + 19);
    DrawSunkenText(&v, line, IlluriaFont(), 17, 1);
    FlushEvents(mDownMask | keyDownMask, 0);
    for (;;) if (WaitNextEvent(mDownMask | keyDownMask, &e, 5, NULL)) break;
    CloseMacAppWindow(win);
}


/* A capture waiting for its notices/choice (shown after the battle window). */
static Boolean sCapPend = false;
static short   sCapOwner, sCapPrev, sCapX, sCapY, sCapCity;
static short   sCaptureLoot = 0;   /* gold looted by the last capture */
static Str255  sCapWho;            /* hero (or player) named on the Victory screen */

/* ===================================================================
 * CaptureCityAt — the city whose anchor tile is (mx,my) passes to mOwner
 * (gold transfer, production reset, notices, raze choice, elimination).
 * =================================================================== */
static short AIOrdType(short rec);
static void CaptureCityAt(short mOwner, short mx, short my)
{
    unsigned char *gs;
    short armyCount, turnNum;
    if (*gGameState == 0) return;
    gs = (unsigned char *)*gGameState;
    armyCount = *(short *)(gs + 0x1602);
    if (armyCount > MAX_ARMIES) armyCount = MAX_ARMIES;
    turnNum = *(short *)(gs + 0x136);
                {
                    short cityCount = sCityCount;
                    short ci;
                    if (cityCount > 139) cityCount = 139;
                    for (ci = 0; ci < cityCount; ci++) {
                        unsigned char *city = sCityData +ci * 0x20;
                        if (*(short *)(city + 0x00) == mx &&
                            *(short *)(city + 0x02) == my) {
                            short prevOwner = *(short *)(city + 0x04);
                            short prevCities = 0;   /* the loser's cities, this one included */

                            /* PPC FUN_1002e7d4: the loot divides the loser's gold by its
                             * city count as it stands BEFORE the city changes hands */
                            {
                                short ci0;
                                for (ci0 = 0; ci0 < cityCount; ci0++) {
                                    unsigned char *c0 = sCityData + ci0 * 0x20;
                                    if (c0[0x17] < 2 && *(short *)(c0 + 0x04) == prevOwner) prevCities++;
                                }
                            }

                            /* 68k CODE_133: track origin player at city+0x0A.
                             * If capturing player == origin, reset to 0x0F.
                             * Otherwise save previous owner as origin. */
                            if (prevOwner != 0x0F && prevOwner >= 0 && prevOwner < 8) {
                                short curOrigin = *(short *)(city + 0x0A);
                                if (mOwner == curOrigin)
                                    *(short *)(city + 0x0A) = 0x0F;
                                else
                                    *(short *)(city + 0x0A) = prevOwner;
                            }

                            *(short *)(city + 0x04) = mOwner;  /* capture city */

                            /* Update map tiles to new owner (68k CODE_133: only update owner
                             * nibble in byte+1, preserve existing tile type in byte+0). */
                            if (*gMapTiles != 0) {
                                unsigned char *capMap = (unsigned char *)*gMapTiles;
                                short cdx, cdy;
                                for (cdy = 0; cdy < 2; cdy++) {
                                    for (cdx = 0; cdx < 2; cdx++) {
                                        short ctx = mx + cdx, cty = my + cdy;
                                        if (ctx >= 0 && ctx < sMapWidth && cty >= 0 && cty < sMapHeight) {
                                            unsigned short coff = cty * 0xE0 + ctx * 2;
                                            /* Preserve tile type byte, only update owner nibble */
                                            capMap[coff + 1] = (capMap[coff + 1] & 0xF0) | (mOwner & 0x0F);
                                        }
                                    }
                                }
                            }

                            /* Gold transfer on capture (PPC FUN_1002e7d4 / 68k CODE_133):
                             * no gold from neutrals; loot = (cities < 2 ? gold : gold / cities) / 2
                             * with the loser's city count taken before the capture;
                             * the winner gains loot (cap 30000), the loser pays 2*loot (floor 0). */
                            if (prevOwner >= 0 && prevOwner < 8 && prevOwner != 0x0F &&
                                mOwner >= 0 && mOwner < 8) {
                                short defGold = *(short *)(gs + 0x186 + prevOwner * 0x14);
                                short goldPerCity, goldTaken;
                                if (prevCities < 2)
                                    goldPerCity = defGold;
                                else
                                    goldPerCity = defGold / prevCities;
                                goldTaken = goldPerCity / 2;
                                if (goldTaken < 0) goldTaken = 0;
                                sCaptureLoot = goldTaken;
                                {
                                    long newGold = (long)*(short *)(gs + 0x186 + mOwner * 0x14) + goldTaken;
                                    short loserGold;
                                    if (newGold > 30000) newGold = 30000;
                                    *(short *)(gs + 0x186 + mOwner * 0x14) = (short)newGold;
                                    loserGold = *(short *)(gs + 0x186 + prevOwner * 0x14) - (short)(goldTaken * 2);
                                    if (loserGold < 0) loserGold = 0;
                                    *(short *)(gs + 0x186 + prevOwner * 0x14) = loserGold;
                                }
                            }

                            /* PPC FUN_1002e7d4 (PPC_0001.c:23458-23468): the old
                             * owner's units off the map (x == -1) whose order
                             * field is type 1 (status >> 12 & 0xf) with the
                             * captured city in the low 7 bits are destroyed.
                             * A unit in vectoring transit carries its
                             * destination in those bits; the type is the
                             * computer's order type (sAIOrd), 0 unless an
                             * order was given. */
                            if (prevOwner >= 0 && prevOwner < 8) {
                                short ri;
                                for (ri = *(short *)(gs + 0x1602) - 1; ri >= 0; ri--) {
                                    unsigned char *ra;
                                    if (ri >= MAX_ARMIES) continue;
                                    ra = ARMY_REC(ri);
                                    if ((short)(unsigned char)ra[0x15] != prevOwner || *(short *)(ra + 0) != -1) continue;
                                    if (ra[0x30] != 'e' && ra[0x30] != 'f') continue;
                                    if ((short)(unsigned char)ra[0x31] != ci || AIOrdType(ri) != 1) continue;
                                    RemoveArmy(ri);
                                }
                            }

                            /* 68k CODE_133: clear vectoring targets pointing to captured city.
                             * Armies owned by the previous owner that were vectoring to this
                             * city should have their movement orders cleared. */
                            if (prevOwner >= 0 && prevOwner < 8 && *gExtState != 0) {
                                unsigned char *ext = (unsigned char *)*gExtState;
                                short ci3;
                                short cityCount3 = sCityCount;
                                if (cityCount3 > 139) cityCount3 = 139;
                                for (ci3 = 0; ci3 < cityCount3; ci3++) {
                                    unsigned char *extCity3 = ext + 0x24c + ci3 * 0x5c;
                                    short vecTgt = *(short *)(extCity3 + 0x3e);
                                    if (vecTgt == ci) {
                                        /* Clear vectoring: production stays, target cleared */
                                        *(short *)(extCity3 + 0x3e) = -1;
                                    }
                                }
                            }

                            /* 68k CODE_133: clear production and defend state on capture.
                             * New owner must set their own production. */
                            if (*gExtState != 0) {
                                unsigned char *extC = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
                                *(short *)(extC + 0x02) = -1;  /* clear production timer */
                                extC[0x00] = 0;                /* clear current production type */
                            }
                            /* 68k CODE_133: clear army defend state at captured city */
                            {
                                short armyCount2 = *(short *)(gs + 0x1602);
                                short ai2;
                                for (ai2 = 0; ai2 < armyCount2; ai2++) {
                                    unsigned char *ar2 = ARMY_REC(ai2);
                                    if (*(short *)(ar2 + 0x00) == mx &&
                                        *(short *)(ar2 + 0x02) == my) {
                                        ar2[0x2d] = 0;  /* clear defend/fortify */
                                    }
                                }
                            }

                            RecordEvent(turnNum, HIST_EVT_CAPTURE, mOwner,
                                "Captured a city");
                            sCapPend = true; sCapOwner = mOwner; sCapPrev = prevOwner;
                            sCapX = mx; sCapY = my; sCapCity = ci;
                            break;
                        }
                    }
                }
}

/* ===================================================================
 * Victory (View 3800, PPC FUN_100472f4): after a human takes a city.
 *   396x276 on WDEF 128 variant 7 (0x0807), placed like View 3200 (centred
 *   across, a third of the way down); PICT 1016 frame at (0,0), PICT 3800 at
 *   (38,38); 'head' (38,42) 320x39 TxSt 1005 "Victory!"; str1..str4 at
 *   y 88/108/128/148, 320 wide, TxSt 1015: random 370-373 with the hero's
 *   name (else the player's name), random 374-376 with the city name,
 *   "The city is yours!", "Will you...".  T3DButtons (STR# 3800) occu
 *   (51,204) 64x21 default, pill (128,205), sack (205,204), raze (281,204)
 *   64x20, keys o/p/s/r.  Pillage is dimmed when the last production slot
 *   is worth nothing, Sack when fewer than two slots, Raze when razing is
 *   not allowed.
 * =================================================================== */
#define VICT_W 396
#define VICT_H 276

static void CityNameP(short ci, Str255 out)
{
    short n = 0;
    out[0] = 0;
    if (ci < 0 || ci >= sCityNameCount) return;
    while (n < MAX_CITY_NAME && sCityNames[ci][n]) { out[n + 1] = sCityNames[ci][n]; n++; }
    out[0] = (unsigned char)n;
}

/* production slots of a city (ext +0x06), filled ones first */
static short CitySlots(short ci, short *slot)
{
    unsigned char *ext = (unsigned char *)*gExtState + 0x24c + ci * 0x5c;
    short i, n = 0;
    for (i = 0; i < 4; i++) {
        short t = *(short *)(ext + 0x06 + i * 2);
        if (t < 0 || t >= MAX_UNIT_TYPES) break;
        slot[n++] = t;
    }
    return n;
}

/* FUN_1004645c: half the buy price (stat 4) of the last slot */
static short PillageValue(short ci)
{
    short slot[4], n;
    if (*gExtState == 0) return 0;
    n = CitySlots(ci, slot);
    return n > 0 ? GetUnitTypeStat(slot[n - 1], 4) / 2 : 0;
}

/* FUN_1004639c: half the buy price of every slot but the first */
static short SackValue(short ci)
{
    short slot[4], n, i, g = 0;
    if (*gExtState == 0) return 0;
    n = CitySlots(ci, slot);
    if (n < 2) return 0;
    for (i = 1; i < n; i++) g += GetUnitTypeStat(slot[i], 4) / 2;
    return g;
}

static void DrawT3DButtonDim(const Rect *r, ConstStr255Param label)
{
    RGBColor grey = {0x8888, 0x8888, 0x8888};
    short fnum, w;
    DrawT3DBevel(r);
    GetFNum("\pChicago", &fnum);
    TextFont(fnum); TextSize(12); TextFace(0);
    w = StringWidth(label);
    RGBForeColor(&grey);
    MoveTo((r->left + r->right - w + 1) / 2 - 1, (r->top + r->bottom) / 2 + 3);
    DrawString(label);
}

static WindowPtr NewMacAppWindow(short w, short h)
{
    WindowPtr win;
    Rect wr;
    short sw = qd.screenBits.bounds.right, sh = qd.screenBits.bounds.bottom, mb = GetMBarHeight();
    /* a third of the way down, rounded to nearest (measured: 314-high Pillage
     * report at 163, 352-high hero/city at 150, 276-high Victory at 155) */
    short left = (sw - (w + 6)) / 2, top = mb + (sh - mb - (h + 6) + 1) / 3;
    SetRect(&wr, left, top, left + w, top + h);
    win = NewCWindow(NULL, &wr, "\p", false, 0x0807, (WindowPtr)-1L, false, 0);
    if (win == NULL) return NULL;
    ModalMenus(true);   /* MacApp PoseModally: every menu but Help greys */
    {
        Handle wctb = GetResource('wctb', 1000);
        if (wctb != NULL) SetWinColor(win, (CTabHandle)wctb);
    }
    if (*gMainGameWindow != 0) {
        PaletteHandle pal = GetPalette((WindowPtr)*gMainGameWindow);
        if (pal != NULL) SetPalette(win, pal, false);
    }
    /* paint the window's area with the marble before it shows, so it never
     * flashes white while its pictures decode */
    SetPort(win);
    ShowWindow(win);
    {
        PicHandle m = GetPicture(1001);
        if (m != NULL) { Rect pf = (**m).picFrame; OffsetRect(&pf, -pf.left, -pf.top); DrawPicture(m, &pf); }
        ValidRect(&win->portRect);
    }
    return win;
}

static void DrawPictAt(short id, short x, short y)
{
    PicHandle p = GetPicture(id);
    Rect r;
    if (p == NULL) return;
    r = (**p).picFrame;
    OffsetRect(&r, x - r.left, y - r.top);
    DrawPicture(p, &r);
}

/* Close a game dialog without the white flash: the map area it uncovered
 * is refilled at once from the map's offscreen copy, then the rest updates. */
static void DisposeOverMap(WindowPtr win)
{
    Rect gr = win->portRect;
    GrafPtr sp;
    GetPort(&sp);
    SetPort(win); LocalToGlobal((Point *)&gr.top); LocalToGlobal((Point *)&gr.bottom);
    InsetRect(&gr, -8, -8);   /* frame and shadow */
    DisposeWindow(win);
    if (*gMainGameWindow != 0 && sMapBufGW != NULL) {
        WindowPtr mw = (WindowPtr)*gMainGameWindow;
        Rect lr = gr, mr = mw->portRect;
        SetPort(mw);
        GlobalToLocal((Point *)&lr.top); GlobalToLocal((Point *)&lr.bottom);
        mr.right -= SCROLLBAR_W; mr.bottom -= SCROLLBAR_H;
        if (SectRect(&lr, &mr, &lr) && LockPixels(GetGWorldPixMap(sMapBufGW))) {
            RGBColor bk = {0, 0, 0}, wh = {0xFFFF, 0xFFFF, 0xFFFF};
            RGBForeColor(&bk); RGBBackColor(&wh);
            CopyBits((BitMap *)*GetGWorldPixMap(sMapBufGW), &mw->portBits, &lr, &lr, srcCopy, NULL);
            UnlockPixels(GetGWorldPixMap(sMapBufGW));
        }
    }
    SetPort(sp);
}

static void CloseMacAppWindow(WindowPtr win)
{
    DisposeOverMap(win);
    ModalMenus(false);
    if (*gMainGameWindow != 0) {
        HiliteWindow((WindowPtr)*gMainGameWindow, true);
        ActivatePalette((WindowPtr)*gMainGameWindow);
    }
    InvalidateAllGameWindows();
    DrainUpdates();
}

/* MacApp's modal dialogs (the notices, Victory, Congratulations, the medal
 * and promotion screens...) grey the whole menu bar except Help while they
 * are up (the original: wg_elim_druids, wg_r3_c).  Nested dialogs are
 * counted so the bar comes back with the last one. */
static void ModalMenus(Boolean up)
{
    static short depth = 0;
    short id;
    if (up) { if (depth++ > 0) return; }
    else    { if (depth <= 0 || --depth > 0) return; }
    if (!sMapLoaded || *gMainGameWindow == 0) return;   /* the picker keeps its own menu state */
    for (id = 1; id <= 9; id++) {
        MenuHandle m = GetMenuHandle(id);
        if (m == NULL) continue;
        if (up) DisableItem(m, 0); else EnableItem(m, 0);
    }
    DrawMenuBar();
}

/* returns 0 Occupy, 1 Pillage, 2 Sack, 3 Raze */
static short ShowCityVictory(short ci, ConstStr255Param who)
{
    static const short bx[4] = {51, 128, 205, 281}, by[4] = {204, 205, 204, 204}, bh[4] = {21, 20, 20, 20};
    static const char keys[4] = {'o', 'p', 's', 'r'};
    WindowPtr win;
    Rect br[4], v;
    Boolean en[4];
    Str255 s, fmt, cname, label[4];
    short i, choice = -1, def = 0;
    EventRecord e;
    Handle strs;

    /* FUN_100472f4's default button: 'occu', or with quests on and the
     * selected stack's hero on its quest: 'raze' for a raze quest at this
     * city, 'sack' (else 'pill' when only that pays) for a gold quest */
    {
        unsigned char *gs = (unsigned char *)*gGameState;
        short me = *(short *)(gs + 0x110);
        if (*(short *)(gs + 0x11e) != 0 && me >= 0 && me < 8 && QREC(me)[0] != 0 &&
            StackHeroRec(sSelectedArmy) >= 0 && StackHeroRec(sSelectedArmy) == QREC(me)[2]) {
            if (QREC(me)[1] == QUEST_RAZE && QREC(me)[3] == ci) def = 3;
            else if (QREC(me)[1] == QUEST_STEAL_GOLD) {
                if (SackValue(ci) != 0) def = 2;
                else if (PillageValue(ci) != 0) def = 1;
            }
        }
    }
    en[0] = true;
    en[1] = PillageValue(ci) > 0;
    en[2] = SackValue(ci) > 0;
    en[3] = (sRazingCities != 2);
    {   /* FUN_100472f4: in the tutorial, the TFRESULT page once per run */
        static Boolean shownFResult = false;
        if (TutorialActive() && !shownFResult) {
            shownFResult = true;
            ShowTutorialScreen("\pTFRESULT", 0);
        }
    }
    for (i = 0; i < 4; i++) SetRect(&br[i], bx[i], by[i], bx[i] + 64, by[i] + bh[i]);
    strs = GetResource('STR#', 3800);
    for (i = 0; i < 4; i++) {
        if (strs != NULL) GetIndString(label[i], 3800, i + 1); else label[i][0] = 0;
    }
    CityNameP(ci, cname);

    win = NewMacAppWindow(VICT_W, VICT_H);
    if (win == NULL) return 0;
    DrawPictAt(1016, 0, 0);
    DrawPictAt(3800, 38, 38);
    GetDATRawString(367, s);
    SetRect(&v, 38, 42, 38 + 320, 42 + 39);
    DrawSunkenText(&v, s, IlluriaFont(), 36, 1);
    GetDATRawString(370 + Dice(1, 4, -1), fmt);   /* FUN_1005f678(0x43,-1) */
    FormatHeroLine(fmt, who, 0, s);
    SetRect(&v, 38, 88, 358, 107);   DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(374 + Dice(1, 3, -1), fmt);   /* FUN_1005f678(0x44,-1) */
    FormatHeroLine(fmt, cname, 0, s);
    SetRect(&v, 38, 108, 358, 127);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(368, s);
    SetRect(&v, 38, 128, 358, 147);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    GetDATRawString(369, s);
    SetRect(&v, 38, 148, 358, 167);  DrawSunkenText(&v, s, IlluriaFont(), 17, 1);
    {
        RGBColor black = {0, 0, 0};
        Rect ring = br[def];
        InsetRect(&ring, -4, -4);
        RGBForeColor(&black);
        PenSize(3, 3);
        FrameRoundRect(&ring, 16, 16);
        PenSize(1, 1);
    }
    for (i = 0; i < 4; i++) {
        if (en[i]) DrawT3DButton(&br[i], label[i]);
        else DrawT3DButtonDim(&br[i], label[i]);
    }

    FlushEvents(mDownMask | keyDownMask | autoKeyMask, 0);
    while (choice < 0) {
        if (!WaitNextEvent(mDownMask | keyDownMask, &e, 5, NULL)) continue;
        if (e.what == mouseDown) {
            Point pt = e.where;
            SetPort(win);
            GlobalToLocal(&pt);
            for (i = 0; i < 4; i++) if (en[i] && PtInRect(pt, &br[i])) choice = i;
        } else {
            char c = (char)(e.message & charCodeMask);
            if (c == '\r' || c == 0x03) choice = en[def] ? def : 0;
            for (i = 0; i < 4; i++) if (en[i] && (c == keys[i] || c == keys[i] - 32)) choice = i;
        }
    }
    CloseMacAppWindow(win);
    return choice;
}

/* View 1020: 392x94, marble PICT 1001 at (7,7) with edge PICTs 1004 (top),
 * 1005 (left), 1006 (bottom), 1009 (right); '1str' (19,35) 352x19 TxSt 1015. */
